COMPREHENSIVE SECURITY REVIEW OF app.js
========================================

OVERVIEW:
This Express.js application is extremely minimal and exposes two endpoints. While the code
is simple, it contains several significant security vulnerabilities and missing best practices.

VULNERABILITIES FOUND:
======================

1. MISSING AUTHENTICATION & AUTHORIZATION (OWASP #1: Broken Authentication)
   Severity: CRITICAL

   Issue:
   - The /users endpoint exposes sensitive user data (email addresses) without ANY authentication
   - No authentication mechanism exists to verify who is accessing the API
   - No authorization checks to determine if users should have access to this data

   Current Code:
   app.get('/users', (req, res) => {
     res.json([
       { id: 1, name: 'Alice', email: 'alice@example.com' },
       { id: 2, name: 'Bob', email: 'bob@example.com' },
     ]);
   });

   Risk:
   - Unauthenticated users can retrieve all user data
   - This violates data privacy regulations (GDPR, CCPA, etc.)
   - Potential data breach exposure

   Recommended Fix:
   const jwt = require('jsonwebtoken');

   // Middleware to verify JWT token
   const authenticateToken = (req, res, next) => {
     const authHeader = req.headers['authorization'];
     const token = authHeader && authHeader.split(' ')[1]; // Extract Bearer token

     if (!token) {
       return res.status(401).json({ error: 'Access token required' });
     }

     jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
       if (err) {
         return res.status(403).json({ error: 'Invalid token' });
       }
       req.user = user;
       next();
     });
   };

   // Protected endpoint
   app.get('/users', authenticateToken, (req, res) => {
     // Additional check: only allow admins or the user themselves
     if (req.user.role !== 'admin') {
       return res.status(403).json({ error: 'Insufficient permissions' });
     }
     res.json([...]);
   });

---

2. INFORMATION DISCLOSURE / SENSITIVE DATA EXPOSURE (OWASP #3: Sensitive Data Exposure)
   Severity: HIGH

   Issue:
   - Email addresses of users are exposed in the API response
   - Full user information returned without filtering or need-to-know basis
   - No data masking or PII protection

   Risk:
   - Email harvesting for phishing/spam campaigns
   - Social engineering attacks
   - Privacy violations

   Recommended Fix:
   app.get('/users', authenticateToken, (req, res) => {
     // Only return non-sensitive data or filter based on user role
     const sanitizedUsers = [
       { id: 1, name: 'Alice' },  // Remove email
       { id: 2, name: 'Bob' },
     ];
     res.json(sanitizedUsers);
   });

   OR for admin-only detailed view:
   app.get('/users/admin/details', authenticateToken, (req, res) => {
     if (req.user.role !== 'admin') {
       return res.status(403).json({ error: 'Admin access required' });
     }
     res.json([
       { id: 1, name: 'Alice', email: 'alice@example.com' },
       { id: 2, name: 'Bob', email: 'bob@example.com' },
     ]);
   });

---

3. MISSING INPUT VALIDATION (OWASP #1: Injection)
   Severity: HIGH

   Issue:
   - While this endpoint doesn't take parameters, if query parameters or body data were added,
     there is no validation
   - No input sanitization framework in place
   - GET parameters not validated

   Risk:
   - If this grows to accept parameters, it's vulnerable to:
     * SQL Injection (if using databases)
     * NoSQL Injection
     * Command Injection
     * XSS if user input is reflected

   Recommended Fix (for future parameter handling):
   const { query, validationResult } = require('express-validator');

   app.get('/users',
     authenticateToken,
     query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
     query('offset').optional().isInt({ min: 0 }).toInt(),
     (req, res) => {
       const errors = validationResult(req);
       if (!errors.isEmpty()) {
         return res.status(400).json({ errors: errors.array() });
       }

       const limit = req.query.limit || 10;
       const offset = req.query.offset || 0;

       // ... fetch and return paginated results
     }
   );

---

4. MISSING SECURITY HEADERS (OWASP #5: Broken Access Control / General Security)
   Severity: MEDIUM

   Issue:
   - No Content Security Policy (CSP)
   - No X-Frame-Options to prevent clickjacking
   - No X-Content-Type-Options to prevent MIME type sniffing
   - No Strict-Transport-Security for HTTPS
   - No X-XSS-Protection header
   - No Referrer-Policy

   Recommended Fix:
   const helmet = require('helmet');

   app.use(helmet());

   // Or configure manually:
   app.use((req, res, next) => {
     res.setHeader('X-Content-Type-Options', 'nosniff');
     res.setHeader('X-Frame-Options', 'DENY');
     res.setHeader('X-XSS-Protection', '1; mode=block');
     res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
     res.setHeader('Content-Security-Policy', "default-src 'self'");
     res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
     next();
   });

---

5. NO RATE LIMITING (OWASP #4: Broken Access Control / DDOS Prevention)
   Severity: MEDIUM

   Issue:
   - No rate limiting on endpoints
   - Anyone can spam the endpoints
   - Vulnerable to brute force attacks
   - No DDOS protection

   Risk:
   - Denial of Service attacks
   - Resource exhaustion
   - Unauthorized enumeration of user data

   Recommended Fix:
   const rateLimit = require('express-rate-limit');

   const limiter = rateLimit({
     windowMs: 15 * 60 * 1000, // 15 minutes
     max: 100, // limit each IP to 100 requests per windowMs
     message: 'Too many requests from this IP, please try again later.',
     standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
     legacyHeaders: false, // Disable the `X-RateLimit-*` headers
   });

   const strictLimiter = rateLimit({
     windowMs: 15 * 60 * 1000,
     max: 5, // Stricter for sensitive endpoints
     skipSuccessfulRequests: false,
   });

   app.use('/api/', limiter);
   app.use('/users', strictLimiter);

---

6. NO LOGGING & MONITORING (OWASP #9: Insufficient Logging & Monitoring)
   Severity: MEDIUM

   Issue:
   - No logging of API requests
   - No error logging
   - Cannot track security incidents or debug issues
   - No request tracking/correlation IDs

   Risk:
   - Cannot detect security breaches
   - Cannot perform forensics on attacks
   - Compliance violations (audit trails required)

   Recommended Fix:
   const morgan = require('morgan');
   const fs = require('fs');

   // Create write stream for access logs
   const accessLogStream = fs.createWriteStream('access.log', { flags: 'a' });

   app.use(morgan('combined', { stream: accessLogStream }));
   app.use(morgan('combined')); // Also log to console

   // Structured logging for security events
   const logger = require('winston');

   logger.info('Authentication successful', {
     userId: req.user.id,
     timestamp: new Date(),
     ip: req.ip,
   });

---

7. MISSING CORS CONFIGURATION (OWASP #5: Broken Access Control)
   Severity: MEDIUM

   Issue:
   - No explicit CORS configuration
   - Default behavior may be too permissive or incorrectly configured
   - Can lead to unauthorized cross-origin requests

   Recommended Fix:
   const cors = require('cors');

   const corsOptions = {
     origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://example.com'],
     credentials: true,
     methods: ['GET'],
     allowedHeaders: ['Content-Type', 'Authorization'],
     maxAge: 3600,
   };

   app.use(cors(corsOptions));

---

8. NO ERROR HANDLING (OWASP #5: Broken Access Control / Information Disclosure)
   Severity: MEDIUM

   Issue:
   - No try-catch blocks
   - Unhandled promise rejections
   - Stack traces may be exposed to clients
   - No centralized error handling

   Recommended Fix:
   const errorHandler = (err, req, res, next) => {
     // Log error
     console.error('Error:', err);

     // Don't expose internal error details to clients
     const statusCode = err.statusCode || 500;
     const message = process.env.NODE_ENV === 'production' 
       ? 'Internal server error'
       : err.message;

     res.status(statusCode).json({
       error: message,
       ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
     });
   };

   app.use(errorHandler);

   process.on('unhandledRejection', (reason, promise) => {
     console.error('Unhandled Rejection at:', promise, 'reason:', reason);
   });

---

9. NO HTTPS ENFORCEMENT
   Severity: HIGH

   Issue:
   - Application doesn't enforce HTTPS
   - All traffic transmitted in plaintext
   - Vulnerable to man-in-the-middle attacks
   - Authentication tokens can be intercepted

   Recommended Fix:
   // In production, use a reverse proxy (Nginx, HAProxy) or:
   const https = require('https');
   const fs = require('fs');

   const options = {
     key: fs.readFileSync('path/to/private-key.pem'),
     cert: fs.readFileSync('path/to/certificate.pem')
   };

   https.createServer(options, app).listen(443);

   // Enforce HTTPS redirect
   app.use((req, res, next) => {
     if (req.header('x-forwarded-proto') !== 'https') {
       res.redirect(`https://${req.header('host')}${req.url}`);
     } else {
       next();
     }
   });

---

10. MISSING ENVIRONMENT CONFIGURATION
    Severity: MEDIUM

    Issue:
    - Port hardcoded to 3000
    - No environment variable usage
    - Potential for secrets to be committed to code
    - Development vs production settings not separated

    Recommended Fix:
    require('dotenv').config();

    const PORT = process.env.PORT || 3000;
    const NODE_ENV = process.env.NODE_ENV || 'development';
    const JWT_SECRET = process.env.JWT_SECRET;

    if (!JWT_SECRET) {
      throw new Error('JWT_SECRET environment variable is required');
    }

    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
    });

    Create .env file (DO NOT COMMIT):
    PORT=3000
    NODE_ENV=development
    JWT_SECRET=your-secret-key-here
    ALLOWED_ORIGINS=http://localhost:3000

---

11. MISSING HEALTH CHECK SECURITY
    Severity: LOW

    Issue:
    - /health endpoint is public and provides timestamp
    - Can be used for reconnaissance
    - Should be restricted or provide minimal info

    Recommended Fix:
    app.get('/health', (req, res) => {
      // Don't expose timestamp in public health check
      res.json({ status: 'ok' });
    });

    // Separate detailed health check for monitoring
    app.get('/internal/health-detailed', authenticateToken, (req, res) => {
      if (req.user.role !== 'admin') {
        return res.status(403).json({ error: 'Forbidden' });
      }
      res.json({
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        memory: process.memoryUsage(),
      });
    });

---

12. NO DEPENDENCY SECURITY
    Severity: MEDIUM

    Issue:
    - No mention of package-lock.json or dependency verification
    - Vulnerable to supply chain attacks
    - No security auditing of dependencies

    Recommended Fix:
    # In package.json, specify exact versions:
    {
      "dependencies": {
        "express": "4.18.2",
        "jsonwebtoken": "9.0.0",
        "helmet": "7.0.0",
        "express-rate-limit": "6.7.0",
        "express-validator": "7.0.0",
        "cors": "2.8.5",
        "morgan": "1.10.0",
        "winston": "3.8.2",
        "dotenv": "16.0.3"
      }
    }

    # Run regularly:
    npm audit
    npm audit fix
    npm outdated

SUMMARY OF CRITICAL ISSUES:
============================
1. CRITICAL: No authentication/authorization
2. HIGH: Information disclosure (email addresses exposed)
3. HIGH: No HTTPS enforcement
4. HIGH: No input validation framework
5. MEDIUM: Missing security headers
6. MEDIUM: No rate limiting
7. MEDIUM: No logging/monitoring
8. MEDIUM: CORS misconfiguration risk
9. MEDIUM: No error handling
10. MEDIUM: Hardcoded configuration

RECOMMENDED REFACTORED app.js:
==============================

/**
 * SECURE VERSION OF app.js
 * Implements security best practices for production use
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const fs = require('fs');
const path = require('path');

const app = express();

// ============================================================================
// 1. ENVIRONMENT CONFIGURATION
// ============================================================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

// Validate required environment variables
if (!JWT_SECRET && NODE_ENV === 'production') {
  throw new Error('JWT_SECRET environment variable is required in production');
}

// ============================================================================
// 2. SECURITY HEADERS WITH HELMET
// ============================================================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// ============================================================================
// 3. CORS CONFIGURATION
// ============================================================================
const corsOptions = {
  origin: ALLOWED_ORIGINS,
  credentials: true,
  methods: ['GET', 'POST', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// ============================================================================
// 4. BODY PARSER & REQUEST LOGGING
// ============================================================================
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Create logs directory if it doesn't exist
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir);
}

// Morgan logging middleware
const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

// Use 'combined' format for detailed logging
app.use(morgan('combined', { stream: accessLogStream }));

// Log to console in development
if (NODE_ENV === 'development') {
  app.use(morgan('dev'));
}

// ============================================================================
// 5. RATE LIMITING
// ============================================================================
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => NODE_ENV === 'development', // Disable in development
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for auth endpoints
  skipSuccessfulRequests: false,
  message: 'Too many authentication attempts, please try again later.',
});

const userLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20, // Moderate limit for user endpoints
  skipSuccessfulRequests: true,
});

app.use(generalLimiter);

// ============================================================================
// 6. AUTHENTICATION MIDDLEWARE
// ============================================================================
const authenticateToken = (req, res, next) => {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Extract Bearer token

    if (!token) {
      return res.status(401).json({
        error: 'Access token required',
        code: 'MISSING_TOKEN',
      });
    }

    jwt.verify(token, JWT_SECRET || 'dev-secret', (err, user) => {
      if (err) {
        console.warn('Token verification failed:', err.message);
        return res.status(403).json({
          error: 'Invalid or expired token',
          code: 'INVALID_TOKEN',
        });
      }

      req.user = user;
      next();
    });
  } catch (error) {
    console.error('Authentication error:', error);
    return res.status(500).json({
      error: 'Internal server error',
      code: 'AUTH_ERROR',
    });
  }
};

// ============================================================================
// 7. AUTHORIZATION MIDDLEWARE
// ============================================================================
const requireRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        error: 'Authentication required',
        code: 'NOT_AUTHENTICATED',
      });
    }

    if (!allowedRoles.includes(req.user.role)) {
      console.warn(`Unauthorized access attempt by user ${req.user.id} to admin endpoint`);
      return res.status(403).json({
        error: 'Insufficient permissions',
        code: 'INSUFFICIENT_PERMISSIONS',
      });
    }

    next();
  };
};

// ============================================================================
// 8. ENDPOINTS
// ============================================================================

/**
 * Public health check endpoint
 * Minimal information exposure
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

/**
 * Detailed health check (admin only)
 * For monitoring and diagnostics
 */
app.get('/internal/health-detailed',
  authenticateToken,
  requireRole(['admin']),
  (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: NODE_ENV,
    });
  }
);

/**
 * Get all users (admin only)
 * Protected endpoint with full data
 */
app.get('/users',
  userLimiter,
  authenticateToken,
  requireRole(['admin']),
  (req, res) => {
    try {
      // Audit log this access
      console.log(`User ${req.user.id} accessed admin user list`);

      // Return user data (with admin role, show email)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      res.json({
        success: true,
        data: users,
        count: users.length,
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      return res.status(500).json({
        error: 'Failed to fetch users',
        code: 'FETCH_ERROR',
      });
    }
  }
);

/**
 * Get public user profiles (authenticated users)
 * Limited data exposure
 */
app.get('/users/profiles',
  userLimiter,
  authenticateToken,
  (req, res) => {
    try {
      // Return only public profile information
      const profiles = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      res.json({
        success: true,
        data: profiles,
        count: profiles.length,
      });
    } catch (error) {
      console.error('Error fetching profiles:', error);
      return res.status(500).json({
        error: 'Failed to fetch profiles',
        code: 'FETCH_ERROR',
      });
    }
  }
);

/**
 * Get current user info (authenticated users)
 */
app.get('/user/me',
  authenticateToken,
  (req, res) => {
    try {
      res.json({
        success: true,
        data: {
          id: req.user.id,
          role: req.user.role,
        },
      });
    } catch (error) {
      console.error('Error fetching current user:', error);
      return res.status(500).json({
        error: 'Failed to fetch user info',
        code: 'FETCH_ERROR',
      });
    }
  }
);

/**
 * Mock login endpoint for testing
 * In production, integrate with proper authentication provider
 */
app.post('/auth/login',
  authLimiter,
  (req, res) => {
    try {
      // NEVER do this in production - use proper authentication
      // This is just for demonstration purposes
      if (!req.body.username || !req.body.password) {
        return res.status(400).json({
          error: 'Username and password are required',
          code: 'INVALID_INPUT',
        });
      }

      // In production: verify credentials against database with bcrypt
      // This is a dummy check
      if (req.body.username === 'admin' && req.body.password === 'demo-password') {
        const token = jwt.sign(
          { id: 1, username: 'admin', role: 'admin' },
          JWT_SECRET || 'dev-secret',
          { expiresIn: '1h' }
        );

        return res.json({
          success: true,
          token,
          expiresIn: 3600,
        });
      }

      return res.status(401).json({
        error: 'Invalid credentials',
        code: 'INVALID_CREDENTIALS',
      });
    } catch (error) {
      console.error('Login error:', error);
      return res.status(500).json({
        error: 'Login failed',
        code: 'LOGIN_ERROR',
      });
    }
  }
);

// ============================================================================
// 9. CENTRALIZED ERROR HANDLING
// ============================================================================
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    code: 'NOT_FOUND',
    path: req.path,
  });
});

const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

  // Don't expose internal error details to clients in production
  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    error: message,
    code: err.code || 'INTERNAL_ERROR',
    ...(NODE_ENV !== 'production' && { stack: err.stack }),
  });
};

app.use(errorHandler);

// ============================================================================
// 10. UNHANDLED REJECTION HANDLERS
// ============================================================================
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, send alert notification
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Gracefully shutdown after logging
  process.exit(1);
});

// ============================================================================
// 11. HTTPS ENFORCEMENT
// ============================================================================
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(301, `https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// ============================================================================
// 12. START SERVER
// ============================================================================
const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`Environment: ${NODE_ENV}`);
  console.log(`Allowed origins: ${ALLOWED_ORIGINS.join(', ')}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

/**
 * SECURITY TESTING EXAMPLES
 * Tests to verify security measures
 */

const request = require('supertest');
const jwt = require('jsonwebtoken');
const app = require('./app_secure');

describe('Security Tests', () => {
  // Sample valid JWT token for testing
  const generateValidToken = (role = 'user') => {
    return jwt.sign(
      { id: 1, username: 'testuser', role },
      process.env.JWT_SECRET || 'dev-secret',
      { expiresIn: '1h' }
    );
  };

  // ========================================================================
  // AUTHENTICATION TESTS
  // ========================================================================

  describe('Authentication', () => {
    test('Should reject requests without token', async () => {
      const res = await request(app).get('/users');
      expect(res.status).toBe(401);
      expect(res.body.code).toBe('MISSING_TOKEN');
    });

    test('Should reject requests with invalid token', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer invalid-token');

      expect(res.status).toBe(403);
      expect(res.body.code).toBe('INVALID_TOKEN');
    });

    test('Should accept valid token', async () => {
      const token = generateValidToken('admin');
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`);

      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
    });

    test('Should handle malformed auth header', async () => {
      const res = await request(app)
