// Secure Express Application - Best Practices Implementation
// This version includes security hardening for production use

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ============================================================
// LOGGING CONFIGURATION
// ============================================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================
// MIDDLEWARE SETUP
// ============================================================

// Security headers
app.use(helmet());

// CORS configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400,
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim()),
  },
}));

// ============================================================
// RATE LIMITING
// ============================================================

const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Skip health checks from rate limiting
    return req.path === '/health';
  },
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true,
});

const apiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 30,
  message: 'Too many API requests, please try again later.',
});

app.use(globalLimiter);

// ============================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      event: 'UNAUTHORIZED_ACCESS',
      path: req.path,
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'secret', (err, user) => {
    if (err) {
      logger.warn({
        event: 'INVALID_TOKEN',
        path: req.path,
        ip: req.ip,
        error: err.message,
        timestamp: new Date().toISOString(),
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================
// AUTHORIZATION MIDDLEWARE
// ============================================================

const authorizeRole = (roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      logger.warn({
        event: 'FORBIDDEN_ACCESS',
        path: req.path,
        userId: req.user?.id,
        userRole: req.user?.role,
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// ============================================================
// ROUTES
// ============================================================

// Health check (no auth required, excluded from rate limiting)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
  });
});

// Login endpoint (to get token)
app.post('/login', authLimiter, express.json(), (req, res) => {
  const { username, password } = req.body;

  // VALIDATION
  if (!username || !password) {
    logger.warn({
      event: 'LOGIN_FAILED',
      reason: 'missing_credentials',
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });
    return res.status(400).json({ error: 'Username and password required' });
  }

  if (typeof username !== 'string' || username.length > 50) {
    return res.status(400).json({ error: 'Invalid username format' });
  }

  // In production, validate against database with hashed passwords
  // This is a simplified example
  if (username === 'admin' && password === process.env.ADMIN_PASSWORD) {
    const token = jwt.sign(
      {
        id: 1,
        username: 'admin',
        role: 'admin',
      },
      process.env.ACCESS_TOKEN_SECRET || 'secret',
      { expiresIn: '1h' }
    );

    logger.info({
      event: 'LOGIN_SUCCESS',
      username: username,
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });

    return res.json({ token, expiresIn: '1h' });
  }

  logger.warn({
    event: 'LOGIN_FAILED',
    reason: 'invalid_credentials',
    username: username,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  res.status(401).json({ error: 'Invalid credentials' });
});

// Protected endpoint with role-based access and input validation
app.get('/users',
  apiLimiter,
  authenticateToken,
  authorizeRole(['admin']),
  query('id').optional().isInt().toInt(),
  query('search').optional().trim().isLength({ max: 100 }).escape(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt().default(10),
  query('offset').optional().isInt({ min: 0 }).toInt().default(0),
  (req, res) => {
    // VALIDATION
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        event: 'VALIDATION_ERROR',
        path: req.path,
        userId: req.user.id,
        errors: errors.array(),
        timestamp: new Date().toISOString(),
      });
      return res.status(400).json({ errors: errors.array() });
    }

    const { id, search, limit, offset } = req.query;

    logger.info({
      event: 'USERS_FETCHED',
      userId: req.user.id,
      query: { id, search, limit, offset },
      timestamp: new Date().toISOString(),
    });

    // In production, fetch from database with parameterized queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Apply search filter (already escaped by express-validator)
    const filtered = search
      ? users.filter(u => u.name.toLowerCase().includes(search.toLowerCase()))
      : users;

    // Apply pagination
    const paginated = filtered.slice(offset, offset + limit);

    res.json({
      data: paginated,
      total: filtered.length,
      limit,
      offset,
    });
  }
);

// User profile endpoint (can access own data or admin can access any)
app.get('/users/:id',
  apiLimiter,
  authenticateToken,
  query('id').optional().isInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id);

    // Authorization check
    if (req.user.role !== 'admin' && req.user.id !== userId) {
      logger.warn({
        event: 'UNAUTHORIZED_USER_ACCESS',
        userId: req.user.id,
        targetUserId: userId,
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });
      return res.status(403).json({ error: 'Cannot access other user data' });
    }

    // Simulate database fetch
    const user = {
      id: userId,
      name: userId === 1 ? 'Alice' : 'Bob',
      email: userId === 1 ? 'alice@example.com' : 'bob@example.com',
      role: 'user',
    };

    logger.info({
      event: 'USER_PROFILE_ACCESSED',
      userId: req.user.id,
      targetUserId: userId,
      timestamp: new Date().toISOString(),
    });

    res.json(user);
  }
);

// ============================================================
// 404 HANDLER
// ============================================================

app.use((req, res) => {
  logger.warn({
    event: 'NOT_FOUND',
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });
  res.status(404).json({ error: 'Not Found' });
});

// ============================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================

app.use((err, req, res, next) => {
  logger.error({
    event: 'ERROR',
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    userId: req.user?.id,
    timestamp: new Date().toISOString(),
  });

  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================================
// SERVER STARTUP
// ============================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info({
    event: 'SERVER_STARTED',
    port: PORT,
    environment: process.env.NODE_ENV,
    timestamp: new Date().toISOString(),
  });
  console.log(`Server running on port ${PORT} (${process.env.NODE_ENV || 'development'})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info({
    event: 'SIGTERM_RECEIVED',
    timestamp: new Date().toISOString(),
  });
  server.close(() => {
    logger.info({
      event: 'SERVER_CLOSED',
      timestamp: new Date().toISOString(),
    });
    process.exit(0);
  });
});

module.exports = app;

# Security Implementation Guide

## Overview
This guide provides step-by-step instructions for implementing security fixes in the Express.js application.

---

## Phase 1: Installation & Setup

### 1.1 Install Dependencies

```bash
npm install express helmet express-validator express-rate-limit jsonwebtoken cors morgan winston dotenv
npm install --save-dev @types/express @types/node
```

### 1.2 Create Environment File

Create `.env` file in the project root:

