PORT=3000

# Security
ACCESS_TOKEN_SECRET=your-very-long-random-secret-key-min-32-chars
REFRESH_TOKEN_SECRET=another-long-random-secret-key-min-32-chars
ADMIN_PASSWORD=temporary-admin-pass-change-in-production

# CORS
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:3001

# Logging
LOG_LEVEL=info

# HTTPS (Production)
PRIVATE_KEY_PATH=/path/to/private.key
CERT_PATH=/path/to/certificate.crt
```

### 1.3 Create .env.production

```bash
NODE_ENV=production
PORT=443
