    // This should typically be handled by the backend
    // But we provide a helper for local encryption

    if (this.backend === 'encrypted-file') {
      const secretsDir = process.env.SECRETS_DIR || '/etc/app-secrets';
      const secretPath = `${secretsDir}/${secretName}.enc`;
      const encrypted = this.encryptSecret(newValue);

      fs.writeFileSync(secretPath, encrypted, { mode: 0o600 });
      this.clearCache(secretName);
    } else {
      throw new Error(`Secret rotation not supported for ${this.backend} backend`);
    }
  }

  /**
   * Mask secret for logging (prevent accidental exposure)
   */
  static maskSecret(value, visibleChars = 4) {
    if (!value || value.length <= visibleChars) {
      return '***';
    }

    const visible = value.substring(0, visibleChars);
    const masked = '*'.repeat(value.length - visibleChars);
    return visible + masked;
  }
}

/**
 * Secrets configuration loader
 */
class SecretsConfiguration {
  constructor(manager) {
    this.manager = manager;
    this.secrets = {};
  }

  /**
   * Load all required secrets at startup
   */
  async loadSecrets() {
    const requiredSecrets = [
      'ACCESS_TOKEN_SECRET',
      'ADMIN_PASSWORD',
      'SESSION_SECRET',
      'ENCRYPTION_KEY',
    ];

    const optionalSecrets = [
      'DB_PASSWORD',
      'API_KEY',
      'OAUTH_SECRET',
    ];

    // Load required secrets
    for (const secretName of requiredSecrets) {
      try {
        this.secrets[secretName] = await this.manager.getSecret(secretName);
        console.log(`✓ Loaded required secret: ${secretName}`);
      } catch (error) {
        throw new Error(
          `Failed to load required secret ${secretName}: ${error.message}`
        );
      }
    }

    // Load optional secrets
    for (const secretName of optionalSecrets) {
      try {
        this.secrets[secretName] = await this.manager.getSecret(secretName);
        console.log(`✓ Loaded optional secret: ${secretName}`);
      } catch (error) {
        console.warn(`⚠ Optional secret not found: ${secretName}`);
      }
    }

    return this.secrets;
  }

  /**
   * Get secret with type safety
   */
  get(secretName, defaultValue = null) {
    if (!(secretName in this.secrets)) {
      if (defaultValue === null) {
        throw new Error(`Secret not loaded: ${secretName}`);
      }
      return defaultValue;
    }
    return this.secrets[secretName];
  }

  /**
   * Get all loaded secrets (masked for safe display)
   */
  getSummary() {
    const summary = {};
    for (const [name, value] of Object.entries(this.secrets)) {
      summary[name] = SecretsManager.maskSecret(value);
    }
    return summary;
  }
}

module.exports = {
  SecretsManager,
  SecretsConfiguration,
};

