const { SecretsManager } = require('../lib/secrets-manager');

/**
 * Create secrets injection middleware
 * Prevents direct process.env access for secrets
 */
function createSecretsMiddleware(secretsConfig) {
  return (req, res, next) => {
    // Create a safe secrets object for this request
    res.locals.secrets = {
      // Only expose methods, not the actual secrets
      getSecret: (name) => {
        // In production, this would be replaced with async call
        // For now, return from loaded secrets
