          const secret = secretsConfig.get(name);
          // Log access for audit trail
          if (req.user) {
            console.log({
              event: 'SECRET_ACCESS',
              user: req.user.id,
              secret: name,
              timestamp: new Date().toISOString(),
            });
          }
          return secret;
        } catch (error) {
          console.error({
            event: 'SECRET_ACCESS_FAILED',
            user: req.user?.id,
            secret: name,
            error: error.message,
            timestamp: new Date().toISOString(),
          });
          throw error;
        }
      },
    };

    next();
  };
}

/**
 * Prevent direct process.env access middleware
 * Raises errors if code tries to access secrets via process.env
 */
function preventDirectEnvAccess() {
  const secretKeyPatterns = [
    /SECRET/i,
    /PASSWORD/i,
    /TOKEN/i,
    /KEY/i,
    /CREDENTIAL/i,
    /API_KEY/i,
    /DATABASE/i,
  ];

  // Override process.env getter to intercept secret access
  const originalEnv = process.env;
  const handler = {
    get(target, prop) {
      if (secretKeyPatterns.some(pattern => pattern.test(prop))) {
        const stack = new Error().stack;
        console.warn({
          event: 'DIRECT_SECRET_ACCESS_ATTEMPTED',
          secret: prop,
          location: stack,
          timestamp: new Date().toISOString(),
        });

        if (process.env.NODE_ENV === 'production') {
          throw new Error(
            `Direct access to secret '${prop}' via process.env is not allowed. ` +
            'Use SecretsManager instead.'
          );
        }
      }
      return target[prop];
    },

    set(target, prop, value) {
      if (secretKeyPatterns.some(pattern => pattern.test(prop))) {
        console.warn({
          event: 'DIRECT_SECRET_MODIFICATION_ATTEMPTED',
          secret: prop,
          timestamp: new Date().toISOString(),
        });

        if (process.env.NODE_ENV === 'production') {
          throw new Error(
            `Cannot modify secret '${prop}' via process.env in production`
          );
        }
      }
      target[prop] = value;
      return true;
    },
  };

  // This is tricky - process.env can't be proxied directly
  // Instead, use Object.freeze to prevent modification
  Object.freeze(process.env);

  return handler;
}

module.exports = {
  createSecretsMiddleware,
  preventDirectEnvAccess,
};

