```javascript
// lambda/rotate-database-secret.js
const AWS = require('aws-sdk');
const pg = require('pg');

const secretsManager = new AWS.SecretsManager();

exports.handler = async (event) => {
  const SecretId = event.SecretId;
  const ClientRequestToken = event.ClientRequestToken;

  try {
    // Get current secret
    const currentSecret = await secretsManager
      .getSecretValue({ SecretId })
      .promise();

    const current = JSON.parse(currentSecret.SecretString);

    // Generate new password
    const newPassword = generateSecurePassword();

    // Connect to database and update password
    const client = new pg.Client(current);
    await client.connect();
    await client.query('ALTER USER $1 WITH PASSWORD $2', [
      current.username,
      newPassword
    ]);
    await client.end();

    // Update secret
    const newSecret = {
      ...current,
      password: newPassword
    };

    await secretsManager.putSecretValue({
      SecretId,
      ClientRequestToken,
      SecretString: JSON.stringify(newSecret)
    }).promise();

    console.log('✅ Secret rotated successfully');

  } catch (error) {
    console.error('❌ Rotation failed:', error);
    throw error;
  }
};

function generateSecurePassword() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
  let password = '';
  for (let i = 0; i < 32; i++) {
    password += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return password;
}
