.env.*.local
.env.test
secrets/
*.key
*.pem
*.crt
```

### 🟠 STEP 4: Implement Secrets Manager

Choose one based on your infrastructure:
- AWS ecosystem → AWS Secrets Manager
- Multi-cloud → Vault
- Azure → Key Vault
- GCP → Secret Manager
- Local dev → dotenv with .env.local

---

## SECURE APP.JS WITH SECRETS MANAGER

```javascript
require('dotenv').config({ path: '.env.local' });
const express = require('express');
const helmet = require('helmet');
const AWS = require('aws-sdk');

const app = express();
let config = {};

// Load secrets from Secrets Manager
async function initializeApp() {
  try {
    // Production: Load from Secrets Manager
    if (process.env.NODE_ENV === 'production') {
      const secretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const secret = await secretsManager.getSecretValue({
        SecretId: process.env.AWS_SECRET_NAME || 'app/config'
      }).promise();

      config = JSON.parse(secret.SecretString);
    } else {
      // Development: Load from .env.local
      config = {
        JWT_SECRET: process.env.JWT_SECRET,
        DATABASE_URL: process.env.DATABASE_URL,
        API_KEY: process.env.API_KEY
      };
    }

    // Validate required secrets
    const required = ['JWT_SECRET', 'DATABASE_URL'];
    for (const key of required) {
      if (!config[key]) {
        throw new Error(`Missing required secret: ${key}`);
      }
    }

    console.log('✅ Secrets loaded successfully');
    startServer();
  } catch (error) {
    console.error('❌ Failed to initialize:', error.message);
    process.exit(1);
  }
}

app.use(helmet());

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

function startServer() {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

// Initialize on startup
initializeApp();

module.exports = app;
```

---

## SECRETS ROTATION STRATEGY

### Automated Rotation

```javascript
// secrets-rotation.js
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function rotateSecret() {
  try {
    // Generate new secret
    const newSecret = generateRandomSecret(32);

    // Update in Secrets Manager
    await secretsManager.putSecretValue({
      SecretId: 'app/jwt-secret',
      SecretString: JSON.stringify({ JWT_SECRET: newSecret })
    }).promise();

    // Restart application to load new secret
    console.log('Secret rotated, restarting application...');
    process.exit(0); // Container orchestration will restart
  } catch (error) {
    console.error('Failed to rotate secret:', error);
  }
}

// Run weekly
setInterval(rotateSecret, 7 * 24 * 60 * 60 * 1000);
```

---

## MONITORING & AUDITING

### CloudTrail Logging (AWS)

```javascript
// Monitor secret access
async function monitorSecretAccess() {
  const cloudtrail = new AWS.CloudTrail();

  const events = await cloudtrail.lookupEvents({
    LookupAttributes: [
      {
        AttributeKey: 'EventName',
        AttributeValue: 'GetSecretValue'
      }
    ],
    MaxResults: 50
  }).promise();

  // Alert if unauthorized access
  for (const event of events.Events) {
    console.log(`Secret accessed by: ${event.Username} at ${event.EventTime}`);
  }
}
```

---

## COMPLIANCE CHECKLIST

- [ ] All secrets removed from Git history
- [ ] `.env*` files added to `.gitignore`
- [ ] Secrets manager implemented (AWS/Vault/Key Vault/etc)
- [ ] All exposed credentials rotated
- [ ] Audit logging enabled
- [ ] IAM policies follow principle of least privilege
- [ ] Secrets encrypted at rest
- [ ] TLS/HTTPS enforced for secret transmission
- [ ] Secret rotation policy implemented
- [ ] Team trained on secrets management
- [ ] Regular security audits scheduled

---

## REFERENCES

- OWASP: https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html
- AWS Secrets Manager: https://aws.amazon.com/secrets-manager/
- HashiCorp Vault: https://www.vaultproject.io/
- Azure Key Vault: https://azure.microsoft.com/services/key-vault/
- CWE-798: Use of Hard-Coded Credentials: https://cwe.mitre.org/data/definitions/798.html

