// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
require('dotenv').config({ path: `.env.${process.env.NODE_ENV}` });

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

// Cache for secrets (in production, implement with TTL)
const secretsCache = {};
const CACHE_TTL = 3600000; // 1 hour in milliseconds

async function getSecret(secretName) {
  const now = Date.now();

  // Check cache
  if (secretsCache[secretName]) {
    const { value, timestamp } = secretsCache[secretName];
    if (now - timestamp < CACHE_TTL) {
      return value;
    }
  }

  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);

    const secretValue = response.SecretString 
      ? JSON.parse(response.SecretString) 
      : response.SecretBinary;

    // Cache the secret
    secretsCache[secretName] = {
      value: secretValue,
      timestamp: now,
    };

    return secretValue;
  } catch (error) {
    console.error(`[SECURITY] Failed to retrieve secret: ${secretName}`, error);
    throw new Error(`Could not retrieve secret: ${secretName}`);
  }
}

module.exports = { getSecret };
```

