### Step 6: Implement Secret Rotation

**Automated Rotation Strategy:**

```javascript
// config/secret-rotation.js
const { getSecret } = require('./secrets');

class SecretRotationManager {
  constructor(rotationIntervalHours = 24) {
    this.rotationInterval = rotationIntervalHours * 60 * 60 * 1000;
    this.secretsCache = {};
    this.rotationTimers = {};
  }

  async initialize() {
    await this.rotateAllSecrets();
  }

  async rotateAllSecrets() {
    const secretNames = [
      'prod/database',
      'prod/api-keys',
      'prod/stripe',
    ];

    for (const secretName of secretNames) {
      await this.rotateSecret(secretName);
    }
  }

  async rotateSecret(secretName) {
    try {
      const secret = await getSecret(secretName);
      this.secretsCache[secretName] = secret;

      console.log(`[SECURITY] Secret rotated: ${secretName}`);

      // Schedule next rotation
      if (this.rotationTimers[secretName]) {
        clearTimeout(this.rotationTimers[secretName]);
      }

      this.rotationTimers[secretName] = setTimeout(() => {
        this.rotateSecret(secretName);
      }, this.rotationInterval);

    } catch (error) {
      console.error(`[SECURITY] Failed to rotate secret: ${secretName}`, error);
    }
  }

  getSecret(secretName) {
    return this.secretsCache[secretName];
  }

  async shutdown() {
    for (const timer of Object.values(this.rotationTimers)) {
      clearTimeout(timer);
    }
  }
}

module.exports = { SecretRotationManager };
```

