// secrets-manager.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheExpiry = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    const now = Date.now();
    const cached = this.cache.get(secretName);

    // Return cached secret if not expired
    if (cached && cached.expiry > now) {
      return cached.value;
    }

    try {
      const response = await this.client
        .getSecretValue({ SecretId: secretName })
        .promise();

      const secret = response.SecretString || response.SecretBinary;

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        expiry: now + this.cacheExpiry
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  async getAllSecrets(secretNames) {
    return Promise.all(
      secretNames.map(name => this.getSecret(name))
    );
  }
}

module.exports = SecretsManager;
