    } catch (error) {
      console.error(`Failed to rotate secret ${secretPath}:`, error);
      throw error;
    }
  }

  async listSecrets(path) {
    try {
      const response = await vault.list(path);
      return response.data.keys;
    } catch (error) {
      console.error(`Failed to list secrets at ${path}:`, error);
      throw error;
    }
  }
}

module.exports = VaultSecretsManager;
