// gcp-secrets-manager.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GCPSecretsManager {
  constructor(projectId) {
    this.client = new SecretManagerServiceClient();
    this.projectId = projectId;
  }

  async getSecret(secretName) {
    try {
      const name = this.client.secretVersionPath(
        this.projectId,
        secretName,
        'latest'
      );

      const [version] = await this.client.accessSecretVersion({ name });
      return version.payload.data.toString('utf8');
    } catch (error) {
      console.error(`Failed to retrieve GCP secret ${secretName}:`, error);
      throw error;
    }
  }

  async createSecret(secretName, secretValue) {
    try {
      const parent = this.client.projectPath(this.projectId);

      const [secret] = await this.client.createSecret({
        parent,
        secretId: secretName,
        secret: {}
      });

      await this.client.addSecretVersion({
        parent: secret.name,
        payload: { data: Buffer.from(secretValue) }
      });

      return secret;
    } catch (error) {
      console.error(`Failed to create GCP secret ${secretName}:`, error);
      throw error;
    }
  }
}

module.exports = GCPSecretsManager;
