  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Total-Count'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// 3. Body Parser
app.use(express.json({ limit: '10kb' })); // Limit payload size to prevent abuse
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. HTTP Request Logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// 5. Request Logging Middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });
  next();
});

// ============================================
// RATE LIMITING
// ============================================

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV === 'development', // Disable in development
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Strict limit for sensitive operations
  message: 'Too many attempts. Please try again later.',
  skipSuccessfulRequests: true, // Don't count successful requests
});

app.use(generalLimiter);

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn({ event: 'unauthorized_access_attempt', url: req.url, ip: req.ip });
    return res.status(401).json({ error: 'Access denied. Authentication required.' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      logger.warn({ event: 'invalid_token', ip: req.ip, error: err.message });
      return res.status(403).json({ error: 'Invalid or expired token.' });
    }
    req.user = user;
    next();
  });
};

// ============================================
// AUTHORIZATION MIDDLEWARE
// ============================================

const authorize = (requiredRole) => (req, res, next) => {
  if (!req.user || req.user.role !== requiredRole) {
    logger.warn({ event: 'unauthorized_role', user: req.user?.id, requiredRole });
    return res.status(403).json({ error: 'Insufficient permissions.' });
  }
  next();
};

// ============================================
// ROUTES
// ============================================

// Health check (unauthenticated, for monitoring)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

// Get all users (with authentication)
app.get('/users',
  authenticateToken,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      logger.info({ event: 'users_fetched', userId: req.user.id, count: users.length });
      res.json(users);
    } catch (error) {
      logger.error({ event: 'error_fetching_users', error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Get specific user (with authentication and input validation)
app.get('/users/:id',
  authenticateToken,
  param('id').isInt({ min: 1 }).toInt(),
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({ event: 'invalid_input', errors: errors.array() });
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const userId = req.params.id;

      // Mock user lookup (in production, query database with parameterized queries)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      logger.info({ event: 'user_fetched', requestedUserId: userId, authenticatedUser: req.user.id });
      res.json(user);
    } catch (error) {
      logger.error({ event: 'error_fetching_user', error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Login endpoint (rate limited)
