  const cached = secretCache.get(secretId);

  // Return cached if fresh
  if (cached && Date.now() - cached.timestamp < 300000) {
    return cached.value;
  }

  try {
    const secret = await secretsManager
      .getSecretValue({ SecretId: secretId })
      .promise();

