  async getSecret(secretId) {
    const now = Date.now();

    // Return cached if fresh
    const cached = this.cache.get(secretId);
    const expiry = this.cacheExpiry.get(secretId);
    if (cached && expiry && now < expiry) {
      logger.debug(`Using cached secret: ${secretId}`);
      return cached;
    }

    // Fetch from backend
    let secret;
    try {
      switch (this.backend) {
        case 'aws':
          secret = await this.getSecretFromAWS(secretId);
          break;
        case 'vault':
          secret = await this.getSecretFromVault(secretId);
          break;
        case 'azure':
          secret = await this.getSecretFromAzure(secretId);
          break;
        case 'env':
        default:
          secret = this.getSecretFromEnv(secretId);
      }

      // Cache the secret
      this.cache.set(secretId, secret);
      this.cacheExpiry.set(secretId, now + this.cacheTTL);

      logger.info(`Retrieved secret: ${secretId}`);
      return secret;
    } catch (error) {
      logger.error(`Failed to retrieve secret ${secretId}:`, error);

      // Fall back to cached value if available
      if (cached) {
        logger.warn(`Using stale cached secret due to fetch error: ${secretId}`);
        return cached;
      }
      throw error;
    }
  }

