      accessTokenSecret: await this.getSecret('ACCESS_TOKEN_SECRET'),
      adminPassword: await this.getSecret('ADMIN_PASSWORD'),
      dbPassword: await this.getSecret('DB_PASSWORD'),
      dbUser: await this.getSecret('DB_USER'),
      dbHost: await this.getSecret('DB_HOST'),
