/**
 * Secure Secrets Management Module
 * Supports multiple backends: AWS Secrets Manager, Vault, environment variables
 */

const logger = require('winston');

class SecretsManager {
  constructor(backend = 'env') {
    this.backend = backend;
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
    this.cacheExpiry = new Map();
  }

  /**
   * Initialize the appropriate backend
   */
  async initialize() {
    switch (this.backend) {
      case 'aws':
        return this.initializeAWS();
      case 'vault':
        return this.initializeVault();
      case 'azure':
        return this.initializeAzure();
      case 'env':
      default:
        return this.initializeEnv();
    }
  }

  /**
   * AWS Secrets Manager backend
   */
  async initializeAWS() {
    try {
      const AWS = require('aws-sdk');
      this.secretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
      logger.info('AWS Secrets Manager initialized');
    } catch (error) {
      logger.error('Failed to initialize AWS Secrets Manager:', error);
      throw error;
    }
  }

  /**
   * HashiCorp Vault backend
   */
  async initializeVault() {
    try {
      const vault = require('node-vault');
      this.vaultClient = vault({
        endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
        token: process.env.VAULT_TOKEN
      });
      logger.info('HashiCorp Vault initialized');
    } catch (error) {
      logger.error('Failed to initialize Vault:', error);
      throw error;
    }
  }

  /**
   * Azure Key Vault backend
   */
  async initializeAzure() {
    try {
      const { SecretClient } = require('@azure/keyvault-secrets');
      const { DefaultAzureCredential } = require('@azure/identity');

      const credential = new DefaultAzureCredential();
      this.azureClient = new SecretClient(process.env.AZURE_VAULT_URL, credential);
      logger.info('Azure Key Vault initialized');
    } catch (error) {
      logger.error('Failed to initialize Azure Key Vault:', error);
      throw error;
    }
  }

  /**
   * Environment variables backend (for development)
   */
  async initializeEnv() {
    require('dotenv').config({
      path: process.env.NODE_ENV === 'production' ? null : '.env.local'
    });

    // Validate required secrets
    const required = [
      'ACCESS_TOKEN_SECRET',
      'ADMIN_PASSWORD'
    ];

    const missing = required.filter(s => !process.env[s]);
    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}. ` +
        `In production, use a secrets manager instead of .env files.`
      );
    }

    logger.info('Environment variables backend initialized (development mode)');
  }

  /**
   * Retrieve a secret with caching
   */
  async getSecret(secretId) {
    const now = Date.now();

    // Return cached if fresh
    const cached = this.cache.get(secretId);
    const expiry = this.cacheExpiry.get(secretId);
    if (cached && expiry && now < expiry) {
      logger.debug(`Using cached secret: ${secretId}`);
      return cached;
    }

    // Fetch from backend
    let secret;
    try {
      switch (this.backend) {
        case 'aws':
          secret = await this.getSecretFromAWS(secretId);
          break;
        case 'vault':
          secret = await this.getSecretFromVault(secretId);
          break;
        case 'azure':
          secret = await this.getSecretFromAzure(secretId);
          break;
        case 'env':
        default:
          secret = this.getSecretFromEnv(secretId);
      }

      // Cache the secret
      this.cache.set(secretId, secret);
      this.cacheExpiry.set(secretId, now + this.cacheTTL);

      logger.info(`Retrieved secret: ${secretId}`);
      return secret;
    } catch (error) {
      logger.error(`Failed to retrieve secret ${secretId}:`, error);

      // Fall back to cached value if available
      if (cached) {
        logger.warn(`Using stale cached secret due to fetch error: ${secretId}`);
        return cached;
      }
      throw error;
    }
  }

  /**
   * Retrieve all secrets for the application
   */
  async getAllSecrets() {
    const secrets = {
      accessTokenSecret: await this.getSecret('ACCESS_TOKEN_SECRET'),
      adminPassword: await this.getSecret('ADMIN_PASSWORD'),
      dbPassword: await this.getSecret('DB_PASSWORD'),
      dbUser: await this.getSecret('DB_USER'),
      dbHost: await this.getSecret('DB_HOST'),
    };

    // Filter out undefined values (optional secrets)
    return Object.fromEntries(
      Object.entries(secrets).filter(([_, v]) => v !== undefined)
    );
  }

  /**
