      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        logger.warn(`Secret not found in AWS: ${secretId}`);
        return undefined;
      }
      throw error;
    }
  }

  /**
   * Vault implementation
   */
  async getSecretFromVault(secretId) {
    try {
      const response = await this.vaultClient.read(`secret/data/${secretId}`);
      return response.data.data;
    } catch (error) {
      if (error.response?.status === 404) {
        logger.warn(`Secret not found in Vault: ${secretId}`);
        return undefined;
      }
      throw error;
    }
  }

  /**
   * Azure implementation
   */
  async getSecretFromAzure(secretId) {
    try {
      const secret = await this.azureClient.getSecret(secretId);
      return secret.value;
    } catch (error) {
      if (error.code === 'SecretNotFound') {
        logger.warn(`Secret not found in Azure: ${secretId}`);
        return undefined;
      }
      throw error;
    }
  }

  /**
