   */
  getSecretFromEnv(secretId) {
    const value = process.env[secretId];
    if (!value && process.env.NODE_ENV === 'production') {
      throw new Error(
        `Secret '${secretId}' not found in environment. ` +
        'Use a secrets manager in production.'
      );
    }
    return value;
  }

  /**
   * Clear the cache (useful for secret rotation)
   */
  clearCache(secretId = null) {
    if (secretId) {
      this.cache.delete(secretId);
      this.cacheExpiry.delete(secretId);
      logger.info(`Cache cleared for secret: ${secretId}`);
    } else {
      this.cache.clear();
      this.cacheExpiry.clear();
      logger.info('Cache cleared for all secrets');
    }
  }

  /**
   * Check if a secret exists
   */
  async hasSecret(secretId) {
    try {
      const secret = await this.getSecret(secretId);
      return secret !== undefined;
    } catch {
      return false;
    }
  }
}

