/**
 * Secure Express Application with Secure Secrets Management
 * Uses secrets manager (AWS/Vault/Azure or environment variables)
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const winston = require('winston');
const jwt = require('jsonwebtoken');
const { param, validationResult } = require('express-validator');

const { createSecretsManager } = require('./secrets-manager');

// ============================================
// CONFIGURATION
// ============================================

const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = parseInt(process.env.PORT, 10) || 3000;
const SECRETS_BACKEND = process.env.SECRETS_BACKEND || 'env';
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

// ============================================
// LOGGING SETUP
// ============================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================
// SECRETS MANAGER INITIALIZATION
// ============================================

let secretsManager;
let appSecrets = {};

async function initializeSecrets() {
  try {
    secretsManager = createSecretsManager(SECRETS_BACKEND);
    await secretsManager.initialize();

    // Load required secrets at startup
    appSecrets.accessTokenSecret = await secretsManager.getSecret('ACCESS_TOKEN_SECRET');
    appSecrets.adminPassword = await secretsManager.getSecret('ADMIN_PASSWORD');

    // Load optional secrets
    appSecrets.dbPassword = await secretsManager.getSecret('DB_PASSWORD');
    appSecrets.dbUser = await secretsManager.getSecret('DB_USER');
    appSecrets.dbHost = await secretsManager.getSecret('DB_HOST');

    logger.info({
      event: 'secrets_initialized',
      backend: SECRETS_BACKEND,
      secretsLoaded: Object.keys(appSecrets).filter(k => appSecrets[k]).length
    });

    return appSecrets;
  } catch (error) {
    logger.error({ event: 'secrets_initialization_failed', error: error.message });
    throw error;
  }
}

// ============================================
// EXPRESS APP INITIALIZATION
// ============================================

const app = express();

// Security middleware
app.use(helmet());

const corsOptions = {
  origin: ALLOWED_ORIGINS,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Total-Count'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
  });
  next();
});

// Rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests. Please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV === 'development',
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many attempts. Please try again later.',
  skipSuccessfulRequests: true,
});

app.use(generalLimiter);

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({ event: 'unauthorized_access', ip: req.ip });
    return res.status(401).json({ error: 'Authentication required.' });
  }

  jwt.verify(token, appSecrets.accessTokenSecret, (err, user) => {
    if (err) {
      logger.warn({ event: 'invalid_token', ip: req.ip });
      return res.status(403).json({ error: 'Invalid or expired token.' });
    }
    req.user = user;
    next();
  });
};

// ============================================
// ROUTES
// ============================================

// Health check
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

// Get all users
app.get('/users', authenticateToken, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    logger.info({ event: 'users_fetched', userId: req.user.id });
    res.json(users);
  } catch (error) {
    logger.error({ event: 'error_fetching_users', error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get specific user
app.get('/users/:id',
  authenticateToken,
  param('id').isInt({ min: 1 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({ event: 'invalid_input', errors: errors.array() });
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const userId = req.params.id;
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      logger.info({ event: 'user_fetched', userId: req.user.id });
      res.json(user);
    } catch (error) {
      logger.error({ event: 'error_fetching_user', error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Login endpoint
app.post('/login', strictLimiter, (req, res) => {
  try {
    const { username, password } = req.body;

    if (!username || !password) {
      logger.warn({ event: 'login_missing_credentials', ip: req.ip });
      return res.status(400).json({ error: 'Username and password required' });
    }

    if (typeof username !== 'string' || username.length > 100) {
      return res.status(400).json({ error: 'Invalid username format' });
    }

    // Mock authentication
    if (username === 'admin' && password === appSecrets.adminPassword) {
      const user = { id: 1, username: 'admin', role: 'admin' };
      const token = jwt.sign(user, appSecrets.accessTokenSecret, { expiresIn: '1h' });

      logger.info({ event: 'successful_login', username });
      return res.json({ token });
    }

    logger.warn({ event: 'failed_login', username, ip: req.ip });
    res.status(401).json({ error: 'Invalid credentials' });
  } catch (error) {
    logger.error({ event: 'login_error', error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

app.use((req, res) => {
  logger.warn({ event: '404_not_found', url: req.url });
  res.status(404).json({ error: 'Not found' });
});

app.use((err, req, res, next) => {
  const isDevelopment = NODE_ENV === 'development';

  logger.error({
    event: 'unhandled_error',
    message: err.message,
    stack: err.stack,
    url: req.url,
  });

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'An error occurred',
      ...(isDevelopment && { stack: err.stack }),
    },
  });
});

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

process.on('SIGTERM', () => {
  logger.info({ event: 'sigterm_received' });
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info({ event: 'sigint_received' });
  process.exit(0);
});

process.on('uncaughtException', (err) => {
  logger.error({ event: 'uncaught_exception', error: err.message });
  process.exit(1);
});

process.on('unhandledRejection', (reason) => {
  logger.error({ event: 'unhandled_rejection', reason });
  process.exit(1);
});

// ============================================
// STARTUP
// ============================================

async function start() {
  try {
    logger.info({ event: 'initializing_app', environment: NODE_ENV });

    // Initialize secrets before starting server
    await initializeSecrets();

    // Start server
    app.listen(PORT, () => {
      logger.info({
        event: 'server_started',
        port: PORT,
        environment: NODE_ENV,
        secretsBackend: SECRETS_BACKEND,
      });
      console.log(`✓ Server running on port ${PORT} (${NODE_ENV})`);
      console.log(`✓ Secrets backend: ${SECRETS_BACKEND}`);
    });
  } catch (error) {
    logger.error({ event: 'startup_failed', error: error.message });
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

if (require.main === module) {
  start();
}

module.exports = { app, initializeSecrets };
