/**
 * SECURE APP.JS - WITH AWS SECRETS MANAGER INTEGRATION
 * 
 * This demonstrates how to properly load secrets from a secrets manager
 * instead of .env files in production.
 */

const express = require('express');
const AWS = require('aws-sdk');
const winston = require('winston');

// ============================================================================
// LOGGER SETUP (Basic - no secrets)
// ============================================================================
const logger = winston.createLogger({
  level: 'info',
