    new winston.transports.Console(),
    new winston.transports.File({ filename: 'app.log' }),
  ],
});

// ============================================================================
// SECRETS MANAGER CLASS
// ============================================================================
class SecretsManager {
  constructor() {
    this.secrets = null;
    this.cachedAt = null;
    this.cacheTTL = 60 * 60 * 1000; // 1 hour cache

    // Initialize AWS Secrets Manager client
    this.secretsClient = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });
  }

  /**
   * Get secret from AWS Secrets Manager with caching
   */
  async getSecret(secretName) {
    try {
      // Check cache validity
      const now = Date.now();
      if (this.secrets && this.cachedAt && (now - this.cachedAt) < this.cacheTTL) {
        logger.debug('Returning cached secret');
        return this.secrets;
      }

      logger.info(`Fetching secret: ${secretName}`);

      const data = await this.secretsClient.getSecretValue({
        SecretId: secretName,
      }).promise();

      // Parse the secret
      let secretValue;
      if (data.SecretString) {
        secretValue = JSON.parse(data.SecretString);
      } else {
        // Binary secret
        secretValue = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.secrets = secretValue;
      this.cachedAt = now;

      logger.info('Successfully retrieved secret from AWS Secrets Manager');
      return secretValue;

    } catch (error) {
      logger.error(`Failed to retrieve secret: ${error.message}`);
      throw new Error('Failed to load application secrets');
    }
  }

  /**
   * Validate that all required secrets are present
   */
  validateSecrets(secrets, requiredKeys) {
    const missing = requiredKeys.filter(key => !(key in secrets));

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  /**
   * Invalidate cache to force refresh
   */
  invalidateCache() {
    this.secrets = null;
    this.cachedAt = null;
    logger.info('Secret cache invalidated');
  }
}

// ============================================================================
// HASHICORP VAULT ALTERNATIVE
// ============================================================================
class VaultSecretsManager {
  constructor() {
    this.vaultUrl = process.env.VAULT_ADDR;
    this.vaultToken = process.env.VAULT_TOKEN;
    this.secrets = null;
    this.cachedAt = null;
    this.cacheTTL = 60 * 60 * 1000;

    if (!this.vaultUrl || !this.vaultToken) {
      throw new Error('VAULT_ADDR and VAULT_TOKEN environment variables required');
    }
  }

  async getSecret(secretPath) {
    try {
      // Check cache
      const now = Date.now();
      if (this.secrets && this.cachedAt && (now - this.cachedAt) < this.cacheTTL) {
        logger.debug('Returning cached Vault secret');
        return this.secrets;
      }

      const response = await fetch(
        `${this.vaultUrl}/v1/${secretPath}`,
        {
          method: 'GET',
          headers: {
            'X-Vault-Token': this.vaultToken,
          },
        }
      );

      if (!response.ok) {
        throw new Error(`Vault error: ${response.status} ${response.statusText}`);
