/**
 * SECURE SECRETS MANAGEMENT - Production Implementation
 * 
 * DO NOT use .env files for production credentials
 * Use one of these approaches instead
 */

// ============================================
// OPTION 1: AWS Secrets Manager (RECOMMENDED)
// ============================================

const AWS = require('aws-sdk');

const secretsClient = new AWS.SecretsManager({
  region: 'us-east-1'
});

class AWSSecretsConfig {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const response = await secretsClient.getSecretValue({
        SecretId: secretName
      }).promise();

      const secret = response.SecretString 
        ? JSON.parse(response.SecretString)
        : response.SecretBinary;

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretName}`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getAllSecrets() {
    return {
      database: await this.getSecret('prod/database'),
      aws: await this.getSecret('prod/aws'),
      stripe: await this.getSecret('prod/stripe'),
      anthropic: await this.getSecret('prod/anthropic'),
      logfire: await this.getSecret('prod/logfire')
    };
  }
}

// Usage
async function initAWSSecrets() {
  const config = new AWSSecretsConfig();
  const secrets = await config.getAllSecrets();
  return secrets;
}

// ============================================
// OPTION 2: HashiCorp Vault (Enterprise)
// ============================================

const vault = require('node-vault');

class VaultSecretsConfig {
  constructor() {
    this.vaultClient = vault({
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });
    this.cache = new Map();
    this.cacheTTL = 3600000;
  }

  async getSecret(path) {
    const cached = this.cache.get(path);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const response = await this.vaultClient.read(path);
      const secret = response.data.data;

      this.cache.set(path, {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret from Vault: ${path}`, error);
      throw error;
    }
  }

  async getAllSecrets() {
    return {
      database: await this.getSecret('secret/data/prod/database'),
      aws: await this.getSecret('secret/data/prod/aws'),
      stripe: await this.getSecret('secret/data/prod/stripe'),
      anthropic: await this.getSecret('secret/data/prod/anthropic'),
      logfire: await this.getSecret('secret/data/prod/logfire')
    };
  }
}

// ============================================
// OPTION 3: Azure Key Vault
// ============================================

const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

class AzureKeyVaultConfig {
  constructor() {
    const vaultUrl = process.env.AZURE_KEYVAULT_URL;
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(vaultUrl, credential);
    this.cache = new Map();
    this.cacheTTL = 3600000;
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const secret = await this.client.getSecret(secretName);
      const value = JSON.parse(secret.value);

      this.cache.set(secretName, {
        value,
        expiresAt: Date.now() + this.cacheTTL
      });

      return value;
    } catch (error) {
      console.error(`Failed to retrieve secret from Azure Key Vault: ${secretName}`, error);
      throw error;
    }
  }

  async getAllSecrets() {
    return {
      database: await this.getSecret('prod-database'),
      aws: await this.getSecret('prod-aws'),
      stripe: await this.getSecret('prod-stripe'),
      anthropic: await this.getSecret('prod-anthropic'),
      logfire: await this.getSecret('prod-logfire')
    };
  }
}

// ============================================
// OPTION 4: Kubernetes Secrets (K8s Native)
// ============================================

const k8s = require('@kubernetes/client-node');

class KubernetesSecretsConfig {
  constructor() {
    const kc = new k8s.KubeConfig();
    kc.loadFromDefault(); // Uses KUBECONFIG env or in-cluster config
    this.api = kc.makeApiClient(k8s.CoreV1Api);
    this.namespace = process.env.NAMESPACE || 'default';
    this.cache = new Map();
    this.cacheTTL = 3600000;
  }

  async getSecret(secretName) {
    const cacheKey = `${this.namespace}/${secretName}`;
    const cached = this.cache.get(cacheKey);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const response = await this.api.readNamespacedSecret(
        secretName,
        this.namespace
      );

      const secret = {};
      Object.entries(response.body.data || {}).forEach(([key, value]) => {
        secret[key] = Buffer.from(value, 'base64').toString('utf-8');
      });

      this.cache.set(cacheKey, {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret from Kubernetes: ${secretName}`, error);
      throw error;
    }
  }

  async getAllSecrets() {
    return {
      database: await this.getSecret('prod-database-secret'),
      aws: await this.getSecret('prod-aws-secret'),
      stripe: await this.getSecret('prod-stripe-secret'),
      anthropic: await this.getSecret('prod-anthropic-secret'),
      logfire: await this.getSecret('prod-logfire-secret')
    };
  }
}

// ============================================
// SAFE DOTENV USAGE (Development Only)
// ============================================

const dotenv = require('dotenv');
const path = require('path');

class SafeDotenvConfig {
  constructor() {
    // Only load for development
    if (process.env.NODE_ENV !== 'production') {
      const envPath = path.resolve(__dirname, '.env.local');
      dotenv.config({ path: envPath });
    } else {
      // Production MUST use secrets manager
      throw new Error(
        'Cannot use dotenv in production. Use AWS Secrets Manager, Vault, or Azure Key Vault'
      );
    }
  }

  getConfig() {
    const required = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];

    const config = {};
    for (const key of required) {
      if (!process.env[key]) {
        throw new Error(`Missing required environment variable: ${key}`);
      }
      config[key] = process.env[key];
    }

    return config;
  }
}

// ============================================
// UNIVERSAL CONFIG FACTORY
// ============================================

async function initializeSecrets() {
  const environment = process.env.NODE_ENV || 'development';

  switch (environment) {
    case 'production':
      // Use AWS Secrets Manager
      console.log('Loading secrets from AWS Secrets Manager...');
      const awsConfig = new AWSSecretsConfig();
      return await awsConfig.getAllSecrets();

    case 'staging':
      // Use Vault for staging
      console.log('Loading secrets from Vault...');
      const vaultConfig = new VaultSecretsConfig();
      return await vaultConfig.getAllSecrets();

    case 'development':
      // Use safe dotenv
      console.log('Loading secrets from .env.local...');
      const devConfig = new SafeDotenvConfig();
      return devConfig.getConfig();

    default:
      throw new Error(`Unknown environment: ${environment}`);
  }
}

// ============================================
// SECRETS REDACTION FOR LOGS
// ============================================

class SecretsRedactor {
  constructor(secrets) {
    this.secrets = secrets;
    this.redactionPatterns = this._buildPatterns();
  }

  _buildPatterns() {
    const patterns = [];

    // API Keys
    patterns.push(/sk-ant-[a-zA-Z0-9-]+/g);
    patterns.push(/sk_live_[a-zA-Z0-9]+/g);
    patterns.push(/AKIA[0-9A-Z]{16}/g);

    // Database URLs
    patterns.push(/postgres:\/\/[^:]+:[^@]+@[^:]+/g);
    patterns.push(/mongodb:\/\/[^:]+:[^@]+@[^:]+/g);

    // Custom secret patterns
    Object.values(this.secrets).forEach(secret => {
      if (typeof secret === 'string' && secret.length > 8) {
        patterns.push(new RegExp(secret, 'g'));
      }
    });

    return patterns;
  }

  redact(text) {
    let redacted = String(text);
    this.redactionPatterns.forEach(pattern => {
      redacted = redacted.replace(pattern, '[REDACTED]');
    });
    return redacted;
  }
}

// ============================================
// LOGGER WITH SECRET REDACTION
// ============================================

const winston = require('winston');

function createSecureLogger(secrets) {
  const redactor = new SecretsRedactor(secrets);

  const customFormat = winston.format.printf(({ timestamp, level, message, ...meta }) => {
    const redactedMessage = redactor.redact(message);
    const redactedMeta = redactor.redact(JSON.stringify(meta));
    return `${timestamp} [${level}]: ${redactedMessage} ${redactedMeta}`;
  });

  return winston.createLogger({
    format: winston.format.combine(
      winston.format.timestamp(),
      customFormat
    ),
    transports: [
      new winston.transports.File({ filename: 'error.log', level: 'error' }),
      new winston.transports.File({ filename: 'combined.log' })
    ]
  });
}

module.exports = {
  AWSSecretsConfig,
  VaultSecretsConfig,
  AzureKeyVaultConfig,
  KubernetesSecretsConfig,
  SafeDotenvConfig,
  SecretsRedactor,
  createSecureLogger,
  initializeSecrets
};

/**
 * SECURE APP.JS - With Proper Secrets Management
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');

// Import secure secrets config
const { 
  initializeSecrets, 
  createSecureLogger,
  SecretsRedactor 
} = require('./secure-secrets-config');

let app = express();
let config = {};
let logger = null;
let redactor = null;

/**
 * Initialize application with secure secrets
 */
async function bootstrap() {
  try {
    // Load secrets securely
    const secrets = await initializeSecrets();
    config = {
      jwtSecret: secrets.database?.JWT_SECRET || secrets.JWT_SECRET,
      databaseUrl: secrets.database?.URL || secrets.DATABASE_URL,
      stripeKey: secrets.stripe?.secret || secrets.STRIPE_SECRET_KEY,
      anthropicKey: secrets.anthropic?.key || secrets.ANTHROPIC_API_KEY,
      logfireToken: secrets.logfire?.token || secrets.LOGFIRE_TOKEN,
      port: process.env.PORT || 3000,
      environment: process.env.NODE_ENV || 'development'
    };

    // Initialize logger with secret redaction
    redactor = new SecretsRedactor(secrets);
    logger = createSecureLogger(secrets);

    logger.info('Application initialized securely');

  } catch (error) {
    console.error('Failed to initialize secrets:', error.message);
    process.exit(1);
  }
}

// ============================================
// MIDDLEWARE SETUP
// ============================================

// Security headers
app.use(helmet());

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Body parser
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging with secret redaction
app.use((req, res, next) => {
  const startTime = Date.now();
  res.on('finish', () => {
    if (logger) {
      const duration = Date.now() - startTime;
      const logData = {
        method: req.method,
        path: req.path,
        status: res.statusCode,
        duration,
        ip: req.ip,
        userAgent: req.get('user-agent')
      };
      const redactedLog = redactor.redact(JSON.stringify(logData));
      logger.info(redactedLog);
    }
  });
  next();
});

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Unauthorized: No token provided' 
    });
  }

  try {
    // CRITICAL: Use config.jwtSecret from secure storage, not hardcoded
    const decoded = jwt.verify(token, config.jwtSecret);
    req.user = decoded;
    next();
  } catch (error) {
    if (logger) {
      // Log without exposing the secret token
      logger.warn(`Token verification failed: ${error.message}`);
    }
    res.status(403).json({ 
      error: 'Forbidden: Invalid token' 
    });
  }
};

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

app.use((err, req, res, next) => {
  if (logger) {
    // Redact sensitive data from error logs
    const redactedError = redactor.redact(JSON.stringify({
      message: err.message,
      stack: err.stack,
      path: req.path
    }));
    logger.error(redactedError);
  }

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message
  });
});

// ============================================
// ROUTES
// ============================================

// Health check (public endpoint)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.environment 
  });
});

// Protected endpoint - requires authentication
app.get('/users', authMiddleware, (req, res) => {
  try {
    // In production, this would query a secure database
    // using credentials from config.databaseUrl

    // Sanitize response - don't return all sensitive fields
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    // Optional: Filter based on user permissions
    if (req.user.role !== 'admin') {
      // Remove sensitive fields for non-admins
      return res.json(users.map(u => ({
        id: u.id,
        name: u.name
      })));
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Example: Logout endpoint (for token blacklisting)
app.post('/logout', authMiddleware, (req, res) => {
  // In production, add token to blacklist
  // or use token expiration
  res.json({ message: 'Logged out successfully' });
});

// ============================================
// SERVER STARTUP
// ============================================

async function startServer() {
  await bootstrap();

  const server = app.listen(config.port, () => {
    if (logger) {
      logger.info(`Server running on port ${config.port} in ${config.environment} mode`);
    } else {
      console.log(`Server running on port ${config.port}`);
    }
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    if (logger) logger.info('SIGTERM received, shutting down gracefully');
    server.close(() => {
      if (logger) logger.info('Server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    if (logger) logger.info('SIGINT received, shutting down gracefully');
    server.close(() => {
      if (logger) logger.info('Server closed');
      process.exit(0);
    });
  });

  return server;
}

// Only start if running directly (not imported)
if (require.main === module) {
  startServer().catch(error => {
    console.error('Failed to start server:', error);
    process.exit(1);
  });
}

module.exports = app;
module.exports.bootstrap = bootstrap;
module.exports.startServer = startServer;

