/**
 * Secure Configuration & Secrets Manager Module
 * 
 * Implements best practices for handling secrets:
 * - Environment variable validation
 * - Secret masking in logs
 * - Support for multiple secret backends (local .env, AWS Secrets Manager, Vault)
 */

const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');
const winston = require('winston');

// Setup logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

/**
 * Mask sensitive values for logging
 */
function maskSecret(value, prefix = 3, suffix = 3) {
  if (typeof value !== 'string' || value.length <= prefix + suffix) {
    return '***';
  }
  return value.substring(0, prefix) + '*'.repeat(Math.max(0, value.length - prefix - suffix)) + value.substring(value.length - suffix);
}

/**
 * Validate required environment variables
 */
function validateRequiredSecrets(requiredSecrets) {
  const missing = requiredSecrets.filter(secret => !process.env[secret]);

  if (missing.length > 0) {
    const error = `Missing required environment variables: ${missing.join(', ')}`;
    logger.error(error);
    throw new Error(error);
  }

  logger.info('All required secrets validated');
}

/**
 * Load environment variables from .env file (development only)
 */
function loadLocalEnv(envPath = '.env.local') {
  if (process.env.NODE_ENV === 'production') {
    logger.warn('Skipping .env file loading in production - use secrets manager instead');
    return;
  }

  const fullPath = path.resolve(envPath);
  if (fs.existsSync(fullPath)) {
    dotenv.config({ path: fullPath });
    logger.info(`Loaded environment variables from ${fullPath}`);
  } else {
    logger.warn(`No ${envPath} file found`);
  }
}

/**
 * AWS Secrets Manager Integration
 */
class AWSSecretsManager {
  constructor(region = process.env.AWS_REGION || 'us-east-1') {
    this.region = region;
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      logger.debug(`Retrieved secret from cache: ${secretName}`);
      return cached.value;
    }

    try {
      const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
      const client = new SecretsManagerClient({ region: this.region });

      const response = await client.send(new GetSecretValueCommand({
        SecretId: secretName,
      }));

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary).toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, { value: secret, timestamp: Date.now() });

      logger.info(`Successfully retrieved secret: ${secretName}`);
      return secret;
    } catch (error) {
      logger.error(`Failed to retrieve secret from AWS Secrets Manager: ${secretName}`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  clearCache() {
    this.cache.clear();
    logger.info('Cleared secrets cache');
  }
}

/**
 * HashiCorp Vault Integration
 */
class VaultSecretsManager {
  constructor(vaultAddr = process.env.VAULT_ADDR, vaultToken = process.env.VAULT_TOKEN) {
    if (!vaultAddr || !vaultToken) {
      throw new Error('VAULT_ADDR and VAULT_TOKEN are required for Vault integration');
    }

    try {
      this.vault = require('node-vault')({
        endpoint: vaultAddr,
        token: vaultToken,
      });
    } catch (error) {
      logger.error('Failed to initialize Vault client - is node-vault installed?', error);
      throw error;
    }

    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretPath) {
    // Check cache
    const cached = this.cache.get(secretPath);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      logger.debug(`Retrieved secret from cache: ${secretPath}`);
      return cached.value;
    }

    try {
      const response = await this.vault.read(secretPath);
      const secret = response.data.data;

      // Cache the secret
      this.cache.set(secretPath, { value: secret, timestamp: Date.now() });

      logger.info(`Successfully retrieved secret from Vault: ${secretPath}`);
      return secret;
    } catch (error) {
      logger.error(`Failed to retrieve secret from Vault: ${secretPath}`, error);
      throw new Error(`Failed to retrieve secret: ${secretPath}`);
    }
  }

  clearCache() {
    this.cache.clear();
    logger.info('Cleared secrets cache');
  }
}

/**
 * Unified Secrets Manager
 * Tries multiple backends: Vault > AWS Secrets Manager > Local env
 */
class SecretsManager {
  constructor(strategy = 'auto') {
    this.strategy = strategy;
    this.manager = null;
    this.initializeManager();
  }

  initializeManager() {
    if (this.strategy === 'auto') {
      // Auto-detect best strategy
      if (process.env.VAULT_ADDR && process.env.VAULT_TOKEN) {
        logger.info('Using Vault for secrets management');
        this.strategy = 'vault';
        try {
          this.manager = new VaultSecretsManager();
        } catch (error) {
          logger.warn('Vault initialization failed, falling back to AWS Secrets Manager');
          this.strategy = 'aws';
        }
      } else if (process.env.AWS_REGION) {
        logger.info('Using AWS Secrets Manager for secrets management');
        this.strategy = 'aws';
        this.manager = new AWSSecretsManager();
      } else {
        logger.info('Using local environment variables for secrets');
        this.strategy = 'local';
      }
    } else if (this.strategy === 'vault') {
      this.manager = new VaultSecretsManager();
    } else if (this.strategy === 'aws') {
      this.manager = new AWSSecretsManager();
    }
  }

  async getSecret(secretNameOrPath) {
    try {
      if (this.strategy === 'local') {
        // For local strategy, just return from process.env
        const value = process.env[secretNameOrPath];
        if (!value) {
          throw new Error(`Secret not found: ${secretNameOrPath}`);
        }
        return value;
      } else {
        // Use manager (Vault or AWS)
        return await this.manager.getSecret(secretNameOrPath);
      }
    } catch (error) {
      logger.error(`Failed to retrieve secret: ${secretNameOrPath}`, error);
      throw error;
    }
  }

  async getSecrets(secretNames) {
    const secrets = {};

    for (const name of secretNames) {
      try {
        secrets[name] = await this.getSecret(name);
      } catch (error) {
        logger.error(`Failed to retrieve secret: ${name}`);
        throw error;
      }
    }

    return secrets;
  }
}

/**
 * Prevent secrets from being logged
 * Patch console.log to mask common secret patterns
 */
function preventSecretLogging() {
  const originalLog = console.log;
  const secretPatterns = [
    /password\s*[=:]\s*['"]?([^'"\s]+)['"]?/gi,
    /api[_-]?key\s*[=:]\s*['"]?([^'"\s]+)['"]?/gi,
    /secret\s*[=:]\s*['"]?([^'"\s]+)['"]?/gi,
    /token\s*[=:]\s*['"]?([^'"\s]+)['"]?/gi,
    /sk_[a-zA-Z0-9_]+/gi,
    /AKIA[0-9A-Z]{16}/gi,
  ];

  console.log = function(...args) {
    let message = args.join(' ');

    secretPatterns.forEach(pattern => {
      message = message.replace(pattern, (match, secret) => {
        return match.replace(secret, maskSecret(secret));
      });
    });

    originalLog.call(console, message);
  };
}

module.exports = {
  SecretsManager,
  AWSSecretsManager,
  VaultSecretsManager,
  loadLocalEnv,
  validateRequiredSecrets,
  maskSecret,
  preventSecretLogging,
  logger,
};

/**
 * Secure Express Application with Secrets Management
 * 
 * Features:
 * - Secrets loaded from secure manager (Vault/AWS/Local env)
 * - Environment validation on startup
 * - Security headers with Helmet
 * - Rate limiting
 * - CORS protection
 * - Request logging with secret masking
 * - Centralized error handling
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const {
  SecretsManager,
  loadLocalEnv,
  validateRequiredSecrets,
  preventSecretLogging,
  logger,
} = require('./config');

// Prevent secrets from appearing in logs
preventSecretLogging();

// Initialize app
const app = express();

// Load environment variables (development only)
loadLocalEnv();

// Initialize secrets manager
const secretsManager = new SecretsManager(process.env.SECRETS_STRATEGY || 'auto');

// Define required secrets based on environment
const REQUIRED_SECRETS = [
  'NODE_ENV',
  'PORT',
  'JWT_SECRET',
];

// Additional secrets for production
if (process.env.NODE_ENV === 'production') {
  REQUIRED_SECRETS.push('DATABASE_URL');
}

// Validate secrets on startup
try {
  validateRequiredSecrets(REQUIRED_SECRETS);
} catch (error) {
  logger.error('Failed to validate required secrets:', error);
  process.exit(1);
}

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
  },
}));

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true,
});

// Body parser
app.use(express.json());

// HTTPS enforcement (production only)
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logData = {
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      timestamp: new Date().toISOString(),
    };

    if (res.statusCode >= 400) {
      logger.warn(logData);
    } else {
      logger.debug(logData);
    }
  });

  next();
});

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

const authenticate = async (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ 
      error: 'Missing or invalid authorization header' 
    });
  }

  const token = authHeader.substring(7);

  try {
    const jwtSecret = await secretsManager.getSecret('JWT_SECRET');
    const decoded = jwt.verify(token, jwtSecret);
    req.user = decoded;
    next();
  } catch (err) {
    logger.warn({
      event: 'invalid_token_attempt',
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint (public)
 * Does not require authentication
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
  });
});

/**
 * Get users endpoint (protected)
 * Requires valid JWT token
 */
app.get('/users',
  authenticate,
  query('id').optional().isInt().toInt(),
  query('name').optional().trim().isLength({ max: 100 }),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { id, name } = req.query;

    // Sample data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Filter by ID if provided
    if (id) {
      users = users.filter(u => u.id === id);
    }

    // Filter by name if provided
    if (name) {
      users = users.filter(u => u.name.toLowerCase().includes(name.toLowerCase()));
    }

    // Filter sensitive fields based on user role
    const filteredUsers = users.map(user => {
      if (req.user.role === 'admin') {
        return user; // Admins see everything
      }
      // Regular users only see public fields
      const { email, ...publicData } = user;
      return publicData;
    });

    res.json(filteredUsers);
  }
);

/**
 * Login endpoint (protected by rate limiting)
 * Exchanges credentials for JWT token
 */
app.post('/login',
  authLimiter,
  express.json(),
  async (req, res) => {
    try {
      const { username, password } = req.body;

      // Validate input
      if (!username || !password) {
        return res.status(400).json({ error: 'Username and password required' });
      }

      // TODO: Verify credentials against database
      // This is a placeholder - implement actual authentication
      if (username === 'admin' && password === 'password') {
        const jwtSecret = await secretsManager.getSecret('JWT_SECRET');

        const token = jwt.sign(
          { username, role: 'admin' },
          jwtSecret,
          { expiresIn: '24h' }
        );

        return res.json({ token });
      }

      logger.warn({
        event: 'failed_login',
        username,
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });

      res.status(401).json({ error: 'Invalid credentials' });
    } catch (error) {
      logger.error('Login error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

/**
 * Centralized error handler
 * Prevents sensitive information from leaking in error responses
 */
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Prevent exposing stack traces in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;

  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({ 
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

