## BEFORE vs AFTER CODE COMPARISON

### Issue #1: Authentication & Authorization

**BEFORE (VULNERABLE):**
```javascript
app.get('/users', (req, res) => {
  res.json([...userList...]);
});
```

**AFTER (SECURE):**
```javascript
app.get('/users',
  authenticate,              // Verify JWT
  authorize(['user', 'admin']), // Check role
  (req, res) => {
    res.json([...userList...]);
  }
);
```

---

### Issue #2: Input Validation

**BEFORE (VULNERABLE):**
```javascript
app.get('/users', (req, res) => {
  // No validation - accepts any query parameters
  const limit = req.query.limit;
  const sort = req.query.sort;
  // Use directly in query...
});
```

**AFTER (SECURE):**
```javascript
const validateQueryParams = (req, res, next) => {
  const { limit, offset, sort } = req.query;

  if (limit && (isNaN(limit) || limit < 1 || limit > 100)) {
    return res.status(400).json({ error: 'Invalid limit' });
  }

  if (offset && (isNaN(offset) || offset < 0)) {
    return res.status(400).json({ error: 'Invalid offset' });
  }

  const allowedSort = ['id', 'name', 'email'];
  if (sort && !allowedSort.includes(sort)) {
    return res.status(400).json({ error: 'Invalid sort' });
  }

  next();
};

app.get('/users', validateQueryParams, (req, res) => {
  // Safe to use validated parameters
});
```

---

### Issue #3: Rate Limiting

**BEFORE (VULNERABLE):**
```javascript
// No protection - can be hammered with requests
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**AFTER (SECURE):**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // 100 requests per window
  message: 'Too many requests, try again later',
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,  // Stricter for sensitive endpoints
});

app.use(limiter);                    // Apply to all routes
app.get('/users', strictLimiter, ...); // Extra protection for sensitive route
```

---

### Issue #4: Security Headers

**BEFORE (VULNERABLE):**
```javascript
const express = require('express');
const app = express();
// No security headers configured
```

**AFTER (SECURE):**
```javascript
const express = require('express');
const helmet = require('helmet');

const app = express();

// Single line adds all important security headers
app.use(helmet());

// Customize if needed:
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: { maxAge: 31536000 },
  frameguard: { action: 'deny' },
  xssFilter: true,
  noSniff: true,
}));

app.disable('x-powered-by');
```

**Headers Added by Helmet:**
- ✅ X-Frame-Options: DENY (prevents clickjacking)
- ✅ X-Content-Type-Options: nosniff (prevents MIME type sniffing)
- ✅ X-XSS-Protection: 1; mode=block (XSS protection)
- ✅ Strict-Transport-Security: max-age=... (HTTPS enforcement)
- ✅ Content-Security-Policy: default-src 'self' (XSS prevention)
- ✅ Referrer-Policy: no-referrer (reduces data leakage)

---

### Issue #5: CORS Protection

**BEFORE (VULNERABLE):**
```javascript
// No CORS configuration - all origins allowed
app.listen(3000);
```

**AFTER (SECURE):**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') 
    || ['https://app.example.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 600, // Preflight cache
}));
```

