const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const cors = require('cors');
const jwt = require('jsonwebtoken');

const app = express();

// ==================== SECRETS MANAGER CONFIGURATION ====================

let secretsManager;

// Determine which secrets manager to use
async function initializeSecretsManager() {
  const env = process.env.NODE_ENV || 'development';

  switch (process.env.SECRETS_BACKEND || 'env') {
    case 'aws':
      console.log('[Secrets] Using AWS Secrets Manager');
      const AwsSecretsManager = require('./secrets-managers/aws-secrets');
      secretsManager = new AwsSecretsManager();
      break;

    case 'vault':
      console.log('[Secrets] Using HashiCorp Vault');
      const VaultSecretsManager = require('./secrets-managers/vault-secrets');
      secretsManager = new VaultSecretsManager({
        vaultUrl: process.env.VAULT_ADDR,
        vaultToken: process.env.VAULT_TOKEN,
      });
      break;

    case 'gcp':
      console.log('[Secrets] Using Google Cloud Secret Manager');
      const GCPSecretsManager = require('./secrets-managers/gcp-secrets');
      secretsManager = new GCPSecretsManager(process.env.GCP_PROJECT_ID);
      break;

    case 'azure':
      console.log('[Secrets] Using Azure Key Vault');
      const AzureSecretsManager = require('./secrets-managers/azure-secrets');
      secretsManager = new AzureSecretsManager(process.env.AZURE_KEYVAULT_URL);
      break;

    default:
      console.warn('[Secrets] WARNING: Using environment variables (development only)');
      secretsManager = {
        getSecret: async (key) => process.env[key],
        invalidateCache: () => {}
      };
  }

  return secretsManager;
}

// ==================== SECURITY MIDDLEWARE ====================

app.use(helmet());

app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
}));

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);
app.use(express.json({ limit: '10kb' }));
app.use(mongoSanitize());

// ==================== SECRET RETRIEVAL MIDDLEWARE ====================

// Middleware to securely retrieve and cache secrets
app.use(async (req, res, next) => {
  try {
    // Retrieve secrets (cached by the secrets manager)
    req.appSecrets = {
      jwtSecret: await secretsManager.getSecret('JWT_SECRET'),
      sessionSecret: await secretsManager.getSecret('SESSION_SECRET'),
      dbPassword: await secretsManager.getSecret('DB_PASSWORD'),
      redisPassword: await secretsManager.getSecret('REDIS_PASSWORD'),
    };
    next();
  } catch (error) {
    console.error('[Secrets] Failed to retrieve secrets:', error.message);
    res.status(503).json({ error: 'Service unavailable' });
  }
});

// ==================== AUTHENTICATION ====================

const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing authorization' });
  }

  const token = authHeader.slice(7);

  try {
    // Use secret from secrets manager
    const decoded = jwt.verify(token, req.appSecrets.jwtSecret);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// ==================== ENDPOINTS ====================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    secretsBackend: process.env.SECRETS_BACKEND || 'env'
  });
});

app.post('/login', async (req, res) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // TODO: Validate credentials against database
  // For demo purposes only
  if (username === 'demo' && password === 'demo') {
    // Create token using secret from secrets manager
    const token = jwt.sign(
      { id: 1, username, role: 'user' },
      req.appSecrets.jwtSecret,
      { expiresIn: '1h' }
    );

    return res.json({ token });
  }

  res.status(401).json({ error: 'Invalid credentials' });
});

app.get('/users', authenticate, (req, res) => {
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];

  res.json({ data: users });
});

// ==================== SECRET ROTATION ENDPOINT ====================

app.post('/admin/rotate-secret/:secretName', authenticate, async (req, res) => {
  // Only admin can rotate secrets
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const { secretName } = req.params;

  // Validate secret name
  const allowedSecrets = [
    'JWT_SECRET',
    'SESSION_SECRET',
    'DB_PASSWORD',
    'REDIS_PASSWORD'
  ];

  if (!allowedSecrets.includes(secretName)) {
    return res.status(400).json({ error: 'Invalid secret name' });
  }

  try {
    // Invalidate cache to force refresh
    secretsManager.invalidateCache(secretName);

    // Retrieve fresh secret (will get new value from manager)
    const newSecret = await secretsManager.getSecret(secretName);

    console.log(`[Audit] Secret ${secretName} rotated by ${req.user.username}`);

    res.json({
      message: `Secret ${secretName} rotated successfully`,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error(`[Error] Failed to rotate secret: ${error.message}`);
    res.status(500).json({ error: 'Failed to rotate secret' });
  }
});

// ==================== AUDIT LOGGING ====================

app.use((req, res, next) => {
  // Log access with user info (for audit trail)
  const logEntry = {
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    user: req.user?.username || 'anonymous',
    ip: req.ip,
    status: res.statusCode
  };

  // TODO: Send to centralized logging (e.g., CloudWatch, ELK, Datadog)
  console.log('[Audit]', JSON.stringify(logEntry));

  next();
});

// ==================== ERROR HANDLING ====================

app.use((err, req, res, next) => {
  console.error('[Error]', err.message);
  res.status(err.status || 500).json({
    error: 'Internal server error'
  });
});

// ==================== STARTUP ====================

async function start() {
  try {
    // Initialize secrets manager
    await initializeSecretsManager();
    console.log('[Secrets] Manager initialized');

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`[Server] Running on port ${PORT}`);
      console.log(`[Server] Secrets Backend: ${process.env.SECRETS_BACKEND || 'env'}`);
      console.log(`[Server] NODE_ENV: ${process.env.NODE_ENV}`);
    });
  } catch (error) {
    console.error('[Fatal] Failed to start server:', error);
    process.exit(1);
  }
}

if (require.main === module) {
  start();
}

module.exports = app;
