# 🔐 SECRETS MANAGEMENT - COMPREHENSIVE SECURITY GUIDE

## Executive Summary

Your application currently has **CRITICAL SECRETS MANAGEMENT VULNERABILITIES**:

1. ❌ Secrets loaded from plain text `.env` file
2. ❌ No secrets rotation mechanism
3. ❌ Secrets visible in version control history
4. ❌ No audit trail for secret access
5. ❌ Secrets stored unencrypted on disk
6. ❌ No separation between development and production secrets

**Risk Level: CRITICAL** - Database compromises, token theft, API key exposure

---

## Secrets Currently Exposed

| Secret | Usage | Risk | Status |
|--------|-------|------|--------|
| JWT_SECRET | Token signing/verification | High | ❌ Not rotatable |
| SESSION_SECRET | Session encryption | High | ❌ Not rotatable |
| DB_PASSWORD | Database authentication | CRITICAL | ❌ Hardcoded |
| REDIS_PASSWORD | Cache authentication | High | ❌ Hardcoded |
| SMTP_PASSWORD | Email service API key | Medium | ❌ Hardcoded |

---

## SOLUTION 1: AWS Secrets Manager (Recommended)

### Setup Instructions

```bash
# 1. Install AWS SDK
npm install @aws-sdk/client-secrets-manager

# 2. Create secret in AWS
aws secretsmanager create-secret \
  --name prod/app/jwt-secret \
  --secret-string "your-super-secret-key-minimum-32-chars" \
  --region us-east-1

# 3. Create secret for database password
aws secretsmanager create-secret \
  --name prod/app/db-password \
  --secret-string "your-database-password" \
  --region us-east-1

# 4. Enable automatic rotation (for database passwords)
aws secretsmanager rotate-secret \
  --secret-id prod/app/db-password \
  --rotation-rules AutomaticallyAfterDays=30 \
  --region us-east-1
```

### IAM Policy Required

```json
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "secretsmanager:GetSecretValue",
        "secretsmanager:DescribeSecret"
      ],
      "Resource": "arn:aws:secretsmanager:region:account:secret:prod/app/*"
    }
  ]
}
```

### Implementation

```javascript
// secrets-managers/aws-secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = 
  require('@aws-sdk/client-secrets-manager');

class AwsSecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.ttl = 3600000; // 1 hour cache
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      console.log(`[AWS Secrets] Cache hit: ${secretName}`);
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);
      const secret = response.SecretString || response.SecretBinary;

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      console.log(`[AWS Secrets] Retrieved: ${secretName}`);
      return secret;
    } catch (error) {
      console.error(`[AWS Secrets] Error retrieving ${secretName}:`, error.message);
      throw error;
    }
  }

  invalidateCache(secretName) {
    this.cache.delete(secretName);
    console.log(`[AWS Secrets] Cache invalidated: ${secretName}`);
  }
}

module.exports = AwsSecretsManager;
```

---

## SOLUTION 2: HashiCorp Vault

### Docker Setup (Development)

```bash
# Start Vault in dev mode
docker run --cap-add IPC_LOCK \
  -e VAULT_DEV_ROOT_TOKEN_ID="myroot" \
  -p 8200:8200 \
  vault:latest

# Set Vault token
export VAULT_ADDR="http://localhost:8200"
export VAULT_TOKEN="myroot"

# Create secret
vault kv put secret/prod/app \
  jwt_secret="your-jwt-secret" \
  db_password="your-db-password" \
  redis_password="your-redis-password"

# Verify
vault kv get secret/prod/app
```

### Implementation

```javascript
// secrets-managers/vault-secrets.js
const axios = require('axios');

class VaultSecretsManager {
  constructor(config) {
    this.vaultUrl = config.vaultUrl || 'http://localhost:8200';
    this.vaultToken = config.vaultToken;
    this.vaultPath = config.vaultPath || 'secret/data/prod/app';
    this.cache = new Map();
    this.ttl = 3600000;

    this.client = axios.create({
      baseURL: this.vaultUrl,
      headers: {
        'X-Vault-Token': this.vaultToken
      }
    });
  }

  async getSecret(key) {
    const cached = this.cache.get(key);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    try {
      const response = await this.client.get(
        `v1/${this.vaultPath}`
      );

      const secrets = response.data.data.data;
      const value = secrets[key];

      if (!value) {
        throw new Error(`Secret key not found: ${key}`);
      }

      this.cache.set(key, {
        value: value,
        timestamp: Date.now()
      });

      return value;
    } catch (error) {
      console.error(`[Vault] Error: ${error.message}`);
      throw error;
    }
  }

  invalidateCache(key) {
    this.cache.delete(key);
  }
}

module.exports = VaultSecretsManager;
```

---

## SOLUTION 3: Docker Secrets (Swarm)

For Docker Swarm deployment:

```bash
# Create secrets
echo "jwt-secret-value" | docker secret create jwt_secret -
echo "db-password" | docker secret create db_password -

# Use in docker-compose.yml
version: '3.8'
services:
  app:
    image: my-app:latest
    secrets:
      - jwt_secret
      - db_password
    environment:
      - SECRETS_BACKEND=docker

secrets:
  jwt_secret:
    external: true
  db_password:
    external: true
```

### Implementation

```javascript
// secrets-managers/docker-secrets.js
const fs = require('fs');
const path = require('path');

class DockerSecretsManager {
  constructor() {
    this.secretsPath = '/run/secrets';
    this.cache = new Map();
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached) {
      return cached.value;
    }

    try {
      const secretPath = path.join(this.secretsPath, secretName);
      const value = fs.readFileSync(secretPath, 'utf8').trim();

      this.cache.set(secretName, { value });
      return value;
    } catch (error) {
      console.error(`[Docker Secrets] Error: ${error.message}`);
      throw error;
    }
  }

  invalidateCache(secretName) {
    this.cache.delete(secretName);
  }
}

module.exports = DockerSecretsManager;
```

