## SOLUTION 4: Kubernetes Secrets

### Create Kubernetes Secrets

```bash
# Create secret from literals
kubectl create secret generic app-secrets \
  --from-literal=jwt-secret="your-jwt-secret" \
  --from-literal=db-password="your-db-password" \
  --from-literal=redis-password="your-redis-password"

# Or from files
kubectl create secret generic app-secrets \
  --from-file=jwt-secret=./jwt-secret.txt \
  --from-file=db-password=./db-password.txt
```

### Kubernetes Deployment

```yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: app
spec:
  template:
    spec:
      containers:
      - name: app
        image: my-app:latest
        env:
        - name: SECRETS_BACKEND
          value: "kubernetes"
        - name: JWT_SECRET
          valueFrom:
            secretKeyRef:
              name: app-secrets
              key: jwt-secret
        - name: DB_PASSWORD
          valueFrom:
            secretKeyRef:
              name: app-secrets
              key: db-password
        volumeMounts:
        - name: secrets
          mountPath: /run/secrets
          readOnly: true
      volumes:
      - name: secrets
        secret:
          secretName: app-secrets
```

### Implementation

```javascript
// secrets-managers/kubernetes-secrets.js
const fs = require('fs');
const path = require('path');

class KubernetesSecretsManager {
  constructor() {
    this.secretsPath = '/run/secrets';
    this.cache = new Map();
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < 3600000) {
      return cached.value;
    }

    try {
      const secretPath = path.join(this.secretsPath, secretName);
      const value = fs.readFileSync(secretPath, 'utf8').trim();

      this.cache.set(secretName, {
        value,
        timestamp: Date.now()
      });

      return value;
    } catch (error) {
      console.error(`[K8s Secrets] Error: ${error.message}`);
      throw error;
    }
  }

  invalidateCache(secretName) {
    this.cache.delete(secretName);
  }
}

module.exports = KubernetesSecretsManager;
```

