// secrets-managers/aws-secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = 
  require('@aws-sdk/client-secrets-manager');

class AwsSecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.ttl = 3600000; // 1 hour cache
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      console.log(`[AWS Secrets] Cache hit: ${secretName}`);
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);
      const secret = response.SecretString || response.SecretBinary;

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      console.log(`[AWS Secrets] Retrieved: ${secretName}`);
      return secret;
    } catch (error) {
      console.error(`[AWS Secrets] Error retrieving ${secretName}:`, error.message);
      throw error;
    }
  }

  invalidateCache(secretName) {
    this.cache.delete(secretName);
    console.log(`[AWS Secrets] Cache invalidated: ${secretName}`);
  }
}

module.exports = AwsSecretsManager;
```

