// secrets-loader.js
const fs = require('fs');
const crypto = require('crypto');
require('dotenv').config();

class LocalSecretsManager {
  constructor() {
    this.encryptionKey = process.env.ENCRYPTION_KEY;
    if (!this.encryptionKey || this.encryptionKey.length < 32) {
      throw new Error('ENCRYPTION_KEY must be at least 32 characters');
    }
  }

  // Encrypt sensitive data
  encrypt(text) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(
      'aes-256-cbc',
      Buffer.from(this.encryptionKey),
      iv
    );

    let encrypted = cipher.update(text, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    return `${iv.toString('hex')}:${encrypted}`;
  }

  // Decrypt sensitive data
  decrypt(text) {
    const [iv, encrypted] = text.split(':');
    const decipher = crypto.createDecipheriv(
      'aes-256-cbc',
      Buffer.from(this.encryptionKey),
      Buffer.from(iv, 'hex')
    );

    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  // Load and decrypt .env
  loadSecrets() {
    const secrets = {};
    const envPath = process.env.ENCRYPTED_ENV_PATH || '.env.encrypted';

    if (!fs.existsSync(envPath)) {
      throw new Error(`Encrypted env file not found: ${envPath}`);
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      if (!line || line.startsWith('#')) continue;

      const [key, encryptedValue] = line.split('=');
      if (!key || !encryptedValue) continue;

      secrets[key] = this.decrypt(encryptedValue);
    }

