# Security Review Report: app.js

## Executive Summary

This application is a basic Express.js server with significant security vulnerabilities. While the current implementation is relatively simple, it lacks essential security controls that would be critical in a production environment. This review identifies OWASP Top 10 concerns and provides specific recommendations.

---

## Vulnerabilities Found

### 1. **Missing Authentication & Authorization** (OWASP #07 - Identification and Authentication Failures)

**Severity:** CRITICAL

**Issue:** The `/users` endpoint exposes sensitive user data (names and emails) without any authentication mechanism.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risks:**
- Any unauthenticated user can access personal information
- No session management or token validation
- No role-based access control (RBAC)
- Violates GDPR and privacy regulations

**Recommended Fix:**
```javascript
const jwt = require('jsonwebtoken');

// Middleware for authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Verify user has permission to view users
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. **Sensitive Data Exposure** (OWASP #02 - Cryptographic Failures)

**Severity:** HIGH

**Issues:**
- Email addresses exposed without need-to-know basis
- No rate limiting on data access
- No encryption for data in transit (HTTPS not enforced)
- Sensitive data returned in plain text

**Recommended Fix:**
```javascript
const https = require('https');
const fs = require('fs');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

// Apply security headers
app.use(helmet());

// Enable HTTPS
const options = {
  key: fs.readFileSync('./private-key.pem'),
  cert: fs.readFileSync('./certificate.pem')
};

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later'
});

app.use(limiter);

// Mask sensitive data
app.get('/users', authenticateToken, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  const users = [
    { id: 1, name: 'Alice', email: 'a***@example.com' }, // Masked email
    { id: 2, name: 'Bob', email: 'b***@example.com' },
  ];

  res.json(users);
});

// Start HTTPS server
https.createServer(options, app).listen(3000, () => {
  console.log('Secure server running on port 3000');
});
```

---

### 3. **Missing Input Validation & Injection Vulnerabilities** (OWASP #03 - Injection)

**Severity:** HIGH

**Issue:** The application doesn't validate or sanitize any query parameters. If routes were added with user input, they would be vulnerable to:
- SQL Injection (if querying a database)
- NoSQL Injection
- Command Injection
- Path Traversal

**Recommended Fix:**
```javascript
const { body, query, validationResult } = require('express-validator');

// Example for a hypothetical POST endpoint
app.post('/user', 
  // Validation rules
  body('email').isEmail().normalizeEmail(),
  body('name').trim().isLength({ min: 1, max: 100 }).escape(),
  body('age').isInt({ min: 0, max: 150 }).optional(),

  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Process validated data
    const { email, name, age } = req.body;
    // Continue with safe data...
  }
);

// Query parameter validation
app.get('/user/:id', 
  query('id').isInt().toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = req.params.id;
    // Use userId safely
  }
);
```

---

### 4. **Missing Error Handling & Information Disclosure** (OWASP #10 - Broken Logging & Monitoring)

**Severity:** MEDIUM

**Issue:**
- No centralized error handling
- Stack traces could be exposed to clients
- No logging of security events
- No monitoring of suspicious activity

**Recommended Fix:**
```javascript
const winston = require('winston');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Centralized error handler
app.use((err, req, res, next) => {
  // Log error with context
  logger.error({
    message: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method,
    user: req.user?.id
  });

  // Don't expose stack traces to clients
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(status).json({ 
    error: message,
    requestId: req.id // For support tracking
  });
});

// Log all requests
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    user: req.user?.id
  });
  next();
});
```

---

### 5. **Missing Security Headers** (OWASP #01 - Broken Access Control)

**Severity:** MEDIUM

**Issue:** No HTTP security headers configured, leaving application vulnerable to:
- Clickjacking (X-Frame-Options)
- XSS attacks (X-Content-Type-Options, Content-Security-Policy)
- Man-in-the-middle attacks (HSTS)

**Recommended Fix:**
```javascript
const helmet = require('helmet');

// Apply comprehensive security headers
app.use(helmet()); // This adds many headers by default

// Or customize as needed:
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  }
}));

app.use(helmet.hsts({
  maxAge: 31536000, // 1 year in seconds
  includeSubDomains: true,
  preload: true
}));

app.use(helmet.frameguard({ action: 'deny' }));
app.use(helmet.noSniff());
app.use(helmet.xssFilter());
```

---

### 6. **No CORS Configuration** (OWASP #01 - Broken Access Control)

**Severity:** MEDIUM

**Issue:** CORS is not configured, which could lead to:
- Unauthorized cross-origin requests
- Potential for credential theft
- Uncontrolled API access

**Recommended Fix:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://example.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));
```

---

### 7. **Missing Request Size Limits** (OWASP #01 - Broken Access Control)

**Severity:** MEDIUM

**Issue:** No limits on request body/payload size could lead to DoS attacks

**Recommended Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

---

### 8. **No Data Validation/Sanitization for Outputs** (OWASP #07 - XSS)

**Severity:** MEDIUM

**Issue:** If user-controlled data is returned in responses, it could lead to XSS vulnerabilities

**Recommended Fix:**
```javascript
const sanitizeHtml = require('sanitize-html');
const xss = require('xss');

// Sanitize output
app.get('/users', authenticateToken, (req, res) => {
  const users = [
    { id: 1, name: sanitizeHtml('Alice'), email: 'alice@example.com' },
    { id: 2, name: sanitizeHtml('Bob'), email: 'bob@example.com' },
  ];

  res.json(users);
});
```

---

### 9. **Environment Variables Not Used** (OWASP #05 - Security Misconfiguration)

**Severity:** HIGH

**Issue:** Hardcoded configuration and secrets

**Recommended Fix:**
```javascript
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Only run in production
if (NODE_ENV === 'production') {
  // Enforce HTTPS
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

