### Create a User Service with Bcrypt

```javascript
// services/userService.js
const bcrypt = require('bcryptjs');

const SALT_ROUNDS = 12;

class UserService {
  // Hash password
  static async hashPassword(password) {
    if (password.length < 8) {
      throw new Error('Password must be at least 8 characters');
    }
    return bcrypt.hash(password, SALT_ROUNDS);
  }

  // Verify password
  static async verifyPassword(password, hash) {
    return bcrypt.compare(password, hash);
  }

  // Validate email format
  static validateEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  // Mock user database
  static mockUsers = {
    'admin@example.com': {
      id: 1,
      email: 'admin@example.com',
      passwordHash: '$2a$12$...', // bcrypt hash
      role: 'admin'
    }
  };

  static async findByEmail(email) {
    return this.mockUsers[email] || null;
  }
}

module.exports = UserService;
```

### Create Authentication Routes

```javascript
// routes/auth.js
const express = require('express');
const jwt = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');
const UserService = require('../services/userService');

const router = express.Router();

router.post('/login',
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Valid email required'),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters'),
  async (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const { email, password } = req.body;

      // Find user
      const user = await UserService.findByEmail(email);
      if (!user) {
        // Don't reveal if user exists (timing attack prevention)
        return res.status(401).json({
          error: 'Invalid credentials'
        });
      }

      // Verify password
      const isValid = await UserService.verifyPassword(password, user.passwordHash);
      if (!isValid) {
        return res.status(401).json({
          error: 'Invalid credentials'
        });
      }

      // Generate JWT
      const token = jwt.sign(
        {
          id: user.id,
          email: user.email,
          role: user.role
        },
        process.env.JWT_SECRET,
        { expiresIn: '1h' }
      );

      res.json({
        token,
        expiresIn: 3600,
        user: {
          id: user.id,
          email: user.email,
          role: user.role
        }
      });
    } catch (error) {
      res.status(500).json({
        error: process.env.NODE_ENV === 'production'
          ? 'Internal server error'
          : error.message
      });
    }
  }
);

module.exports = router;
```

