## Step 4: Input Validation Patterns

### Validation Middleware Library

```javascript
// middleware/validation.js
const { body, query, param, validationResult } = require('express-validator');

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// User validation rules
const userValidationRules = () => {
  return [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .escape()
      .withMessage('Name must be 1-100 characters'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required'),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be 0-150'),
  ];
};

// Query validation
const paginationValidation = () => {
  return [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('Page must be >= 1'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('Limit must be 1-100'),
  ];
};

// Parameter validation
const idValidation = () => {
  return param('id')
    .isInt({ min: 1 })
    .toInt()
    .withMessage('Invalid ID');
};

module.exports = {
  handleValidationErrors,
  userValidationRules,
  paginationValidation,
  idValidation
};
```

### Using Validation in Routes

```javascript
// routes/users.js
const express = require('express');
const { userValidationRules, idValidation, handleValidationErrors } = require('../middleware/validation');
const { authenticateToken, authorizeRole } = require('../middleware/auth');

const router = express.Router();

// Create user
router.post('/',
  authenticateToken,
  authorizeRole(['admin']),
  userValidationRules(),
  handleValidationErrors,
  async (req, res) => {
    // Data is validated and sanitized
    const { name, email, age } = req.body;

    // Process user creation
    res.status(201).json({ id: 1, ...req.body });
  }
);

// Get user by ID
router.get('/:id',
  authenticateToken,
  idValidation(),
  handleValidationErrors,
  (req, res) => {
    const userId = req.params.id; // Already validated and converted to int
    res.json({ id: userId, name: 'Example User' });
  }
);

module.exports = router;
```

