## Step 6: Security Headers Testing

```javascript
// test/security.test.js
const request = require('supertest');
const app = require('../app-secure');

describe('Security Headers', () => {
  it('should have X-Content-Type-Options header', async () => {
    const res = await request(app).get('/health');
    expect(res.get('X-Content-Type-Options')).toBe('nosniff');
  });

  it('should have X-Frame-Options header', async () => {
    const res = await request(app).get('/health');
    expect(res.get('X-Frame-Options')).toBe('DENY');
  });

  it('should have HSTS header in production', async () => {
    process.env.NODE_ENV = 'production';
    const res = await request(app).get('/health');
    expect(res.get('Strict-Transport-Security')).toBeDefined();
  });

  it('should enforce HTTPS in production', async () => {
    process.env.NODE_ENV = 'production';
    const res = await request(app).get('/users');
    // Should return 403 for non-HTTPS (unless x-forwarded-proto is https)
    expect([403, 401]).toContain(res.status);
  });

  it('should have rate limiting', async () => {
    // Make multiple requests
    for (let i = 0; i < 105; i++) {
      await request(app).get('/health');
    }
    // 105th request should be rate limited
    const res = await request(app).get('/health');
    expect(res.status).toBe(429);
  });

  it('should require authentication for /users', async () => {
    const res = await request(app).get('/users');
    expect(res.status).toBe(401);
  });

  it('should reject invalid tokens', async () => {
    const res = await request(app)
      .get('/users')
      .set('Authorization', 'Bearer invalid-token');
    expect(res.status).toBe(403);
  });
});
```

