# Secure Code Patterns for Express.js

## Pattern 1: Secure Authentication Middleware

```javascript
// middleware/auth.js
const jwt = require('jsonwebtoken');
const logger = require('../services/logger');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    logger.warn({ message: 'Missing token', ip: req.ip, path: req.path });
    return res.status(401).json({ error: 'Token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({ message: 'Invalid token', error: err.message, ip: req.ip });
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

module.exports = { authenticateToken };
```

## Pattern 2: Role-Based Authorization

```javascript
// middleware/authorization.js
const logger = require('../services/logger');

const authorize = (roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!roles.includes(req.user.role)) {
      logger.warn({
        message: 'Unauthorized access',
        userId: req.user.id,
        requiredRoles: roles,
        userRole: req.user.role
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

module.exports = { authorize };
```

## Pattern 3: Input Validation & Sanitization

```javascript
// validators/user.validator.js
const { body, param, query, validationResult } = require('express-validator');

const createUserValidation = () => [
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Valid email required'),
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape()
    .withMessage('Name must be 1-100 characters'),
  body('password')
    .isLength({ min: 8 })
    .matches(/^(?=.*[A-Za-z])(?=.*\d)(?=.*[@$!%*#?&])/)
    .withMessage('Password must contain letters, numbers, and special chars')
];

const updateUserValidation = () => [
  param('id').isInt({ min: 1 }).toInt(),
  body('email').optional().isEmail(),
  body('name').optional().trim().escape()
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      errors: errors.array().map(e => ({
        field: e.param,
        message: e.msg
      }))
    });
  }
  next();
};

module.exports = {
  createUserValidation,
  updateUserValidation,
  handleValidationErrors
};
```

## Pattern 4: Secure Database Query (SQL Injection Prevention)

```javascript
// services/userService.js
const db = require('../db');

class UserService {
  // VULNERABLE - DO NOT USE
  static async getUserByIdVulnerable(id) {
    const query = `SELECT * FROM users WHERE id = ${id}`;
    return db.query(query);
  }

  // SECURE - Use parameterized queries
  static async getUserById(id) {
    const query = 'SELECT * FROM users WHERE id = $1';
    const result = await db.query(query, [id]);
    return result.rows[0];
  }

  // SECURE - Prevent NoSQL injection
  static async getUserByEmailNoSQL(email) {
    // Ensure email is a string, never an object
    if (typeof email !== 'string') {
      throw new Error('Invalid email format');
    }
    return await User.findOne({ email: email });
  }

  // SECURE - Insert with validation
  static async createUser(userData) {
    const { email, name, password } = userData;
    const query = `
      INSERT INTO users (email, name, password_hash)
      VALUES ($1, $2, $3)
      RETURNING id, email, name
    `;
    const result = await db.query(query, [email, name, password]);
    return result.rows[0];
  }
}

module.exports = UserService;
```

## Pattern 5: Secure Error Handling

```javascript
// middleware/errorHandler.js
const logger = require('../services/logger');

class AppError extends Error {
  constructor(message, status = 500) {
    super(message);
    this.status = status;
    this.timestamp = new Date().toISOString();
  }
}

const errorHandler = (err, req, res, next) => {
  const status = err.status || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Log error with context
  logger.error({
    message: err.message,
    stack: err.stack,
    status,
    method: req.method,
    path: req.path,
    userId: req.user?.id,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Safe response - don't expose internals in production
  const response = {
    error: isDevelopment ? err.message : 'Internal server error',
    status,
    requestId: req.id
  };

  // Never expose stack traces or query details in production
  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(status).json(response);
};

module.exports = { AppError, errorHandler };
```

## Pattern 6: Rate Limiting with Redis (Scalable)

```javascript
// middleware/rateLimiter.js
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const redis = require('redis');

const redisClient = redis.createClient({
  host: process.env.REDIS_HOST || 'localhost',
  port: process.env.REDIS_PORT || 6379
});

// General API limiter
const apiLimiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'rate-limit:api:'
  }),
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests, try again later',
  standardHeaders: true,
  legacyHeaders: false
});

// Strict limiter for authentication
const authLimiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'rate-limit:auth:'
  }),
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, try again later'
});

module.exports = { apiLimiter, authLimiter };
```

## Pattern 7: Secure Logging

```javascript
// services/logger.js
const winston = require('winston');
const path = require('path');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: {
    service: 'api',
    environment: process.env.NODE_ENV
  },
  transports: [
    // Error logs
    new winston.transports.File({
      filename: path.join('logs', 'error.log'),
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    }),
    // Combined logs
    new winston.transports.File({
      filename: path.join('logs', 'combined.log'),
      maxsize: 5242880,
      maxFiles: 5
    })
  ]
});

// Console output in development
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    )
  }));
}

module.exports = logger;
```

## Pattern 8: CSRF Protection

```javascript
// middleware/csrf.js
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

const csrfProtection = csrf({
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict'
  }
});

module.exports = { csrfProtection };

// Usage in routes
app.get('/form', csrfProtection, (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

app.post('/form', csrfProtection, (req, res) => {
  // CSRF token automatically validated
  res.json({ success: true });
});
```

## Pattern 9: Secure Session Management

```javascript
// middleware/session.js
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const redis = require('redis');

const redisClient = redis.createClient();

const sessionMiddleware = session({
  store: new RedisStore({ client: redisClient }),
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production', // HTTPS only
    httpOnly: true, // Prevent XSS
    sameSite: 'strict', // CSRF prevention
    maxAge: 30 * 60 * 1000 // 30 minutes
  },
  name: 'sessionId' // Don't use default name
});

module.exports = { sessionMiddleware };
```

## Pattern 10: Secure Data Response Builder

```javascript
// utils/responseBuilder.js
class ResponseBuilder {
  // Mask sensitive data
  static maskEmail(email) {
    const [name, domain] = email.split('@');
    return `${name.charAt(0)}${'*'.repeat(name.length - 1)}@${domain}`;
  }

  // Safe user response (no password hash)
  static safeUser(user) {
    const { passwordHash, ...safe } = user;
    return safe;
  }

  // Paginated response
  static paginated(items, page, limit, total) {
    return {
      data: items,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit)
      }
    };
  }

  // Error response
  static error(message, status = 400) {
    return {
      error: message,
      status,
      timestamp: new Date().toISOString()
    };
  }
}

module.exports = ResponseBuilder;
```

## Pattern 11: Secure Configuration Management

```javascript
// config/config.js
require('dotenv').config();

const config = {
  development: {
    port: 3000,
    nodeEnv: 'development',
    enableHttps: false,
    jwtSecret: process.env.JWT_SECRET || 'dev-secret',
    jwtExpiry: '7d',
    corsOrigins: ['http://localhost:3000', 'http://localhost:3001'],
    rateLimitMax: 1000, // Generous for development
    logLevel: 'debug'
  },

  production: {
    port: process.env.PORT || 3000,
    nodeEnv: 'production',
    enableHttps: true,
    jwtSecret: process.env.JWT_SECRET,
    jwtExpiry: '1h',
    corsOrigins: (process.env.CORS_ORIGINS || '').split(','),
    rateLimitMax: 100,
    logLevel: 'info'
  }
};

// Validate required environment variables
const validateConfig = () => {
  if (process.env.NODE_ENV === 'production') {
    const required = ['JWT_SECRET', 'DATABASE_URL'];
    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }
  }
};

validateConfig();

module.exports = config[process.env.NODE_ENV || 'development'];
```

## Pattern 12: Secure Password Hashing

```javascript
// services/passwordService.js
const bcrypt = require('bcryptjs');

const SALT_ROUNDS = 12;
const MIN_PASSWORD_LENGTH = 8;

class PasswordService {
  static async hash(password) {
    if (!password || password.length < MIN_PASSWORD_LENGTH) {
      throw new Error('Password must be at least 8 characters');
    }

    return bcrypt.hash(password, SALT_ROUNDS);
  }

  static async verify(password, hash) {
    return bcrypt.compare(password, hash);
  }

  static validate(password) {
    const rules = [
      { regex: /.{8,}/, message: 'at least 8 characters' },
      { regex: /[A-Z]/, message: 'uppercase letter' },
      { regex: /[a-z]/, message: 'lowercase letter' },
      { regex: /[0-9]/, message: 'number' },
      { regex: /[@$!%*#?&]/, message: 'special character' }
    ];

    const failed = rules.filter(rule => !rule.regex.test(password));

    if (failed.length > 0) {
      return {
        valid: false,
        message: `Password must contain: ${failed.map(r => r.message).join(', ')}`
      };
    }

    return { valid: true };
  }
}

module.exports = PasswordService;
```

