    status,
    method: req.method,
    path: req.path,
    userId: req.user?.id,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Safe response - don't expose internals in production
  const response = {
    error: isDevelopment ? err.message : 'Internal server error',
    status,
    requestId: req.id
  };

  // Never expose stack traces or query details in production
  if (isDevelopment) {
    response.stack = err.stack;
