 */
class AWSSecretsManager {
  constructor() {
    const AWS = require('aws-sdk');
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = null;
    this.cacheExpiry = null;
  }

  async getSecrets() {
    // Return cached secrets if still valid (1 hour cache)
    if (this.cache && this.cacheExpiry > Date.now()) {
      console.log('[AWS Secrets Manager] Using cached secrets');
      return this.cache;
    }

    try {
      console.log('[AWS Secrets Manager] Retrieving secrets...');
      const data = await this.client
        .getSecretValue({ SecretId: process.env.SECRET_NAME })
        .promise();

      this.cache = JSON.parse(data.SecretString);
      this.cacheExpiry = Date.now() + 3600000; // 1 hour

      console.log('[AWS Secrets Manager] ✓ Secrets retrieved successfully');
      return this.cache;
    } catch (error) {
      console.error('[AWS Secrets Manager] ❌ Failed to retrieve secrets:', error);
      throw new Error('Unable to load secrets from AWS Secrets Manager');
    }
  }
}

/**
 * HashiCorp Vault Implementation
 */
class VaultSecretsManager {
  constructor() {
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN,
    });
    this.vault = vault;
    this.cache = null;
    this.cacheExpiry = null;
  }

  async getSecrets() {
    if (this.cache && this.cacheExpiry > Date.now()) {
      console.log('[Vault] Using cached secrets');
      return this.cache;
    }

    try {
      console.log('[Vault] Retrieving secrets from:', process.env.VAULT_SECRET_PATH);
      const secret = await this.vault.read(
        process.env.VAULT_SECRET_PATH || 'secret/data/my-app'
      );

      // Vault v2 KV engine stores data in nested 'data' field
      this.cache = secret.data.data || secret.data;
      this.cacheExpiry = Date.now() + 3600000; // 1 hour

      console.log('[Vault] ✓ Secrets retrieved successfully');
      return this.cache;
    } catch (error) {
      console.error('[Vault] ❌ Failed to retrieve secrets:', error);
      throw new Error('Unable to load secrets from Vault');
