  }
}

/**
 * Google Cloud Secret Manager Implementation
 */
class GCPSecretsManager {
  constructor() {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    this.client = new SecretManagerServiceClient();
    this.cache = null;
    this.cacheExpiry = null;
  }

  async getSecrets() {
    if (this.cache && this.cacheExpiry > Date.now()) {
      console.log('[GCP Secret Manager] Using cached secrets');
      return this.cache;
    }

    try {
      const projectId = process.env.GCP_PROJECT_ID;
      const secretName = `projects/${projectId}/secrets/${process.env.SECRET_NAME}/versions/latest`;

      console.log('[GCP Secret Manager] Retrieving secrets from:', secretName);
      const [version] = await this.client.accessSecretVersion({ name: secretName });

      const secretString = version.payload.data.toString('utf8');
      this.cache = JSON.parse(secretString);
      this.cacheExpiry = Date.now() + 3600000; // 1 hour

      console.log('[GCP Secret Manager] ✓ Secrets retrieved successfully');
      return this.cache;
    } catch (error) {
      console.error('[GCP Secret Manager] ❌ Failed to retrieve secrets:', error);
      throw new Error('Unable to load secrets from GCP Secret Manager');
    }
  }
}

/**
 * Azure Key Vault Implementation
 */
class AzureSecretsManager {
  constructor() {
    const { DefaultAzureCredential } = require('@azure/identity');
    const { SecretClient } = require('@azure/keyvault-secrets');

    const vaultName = process.env.VAULT_NAME;
    const vaultUrl = `https://${vaultName}.vault.azure.net`;

    this.client = new SecretClient(vaultUrl, new DefaultAzureCredential());
    this.cache = null;
    this.cacheExpiry = null;
  }

  async getSecrets() {
    if (this.cache && this.cacheExpiry > Date.now()) {
      console.log('[Azure Key Vault] Using cached secrets');
      return this.cache;
    }

    try {
      console.log('[Azure Key Vault] Retrieving secrets...');

      const secrets = {};
      const secretNames = [
        'DatabaseUrl',
        'AwsAccessKeyId',
        'AwsSecretAccessKey',
        'AnthropicApiKey',
        'StripeSecretKey',
      ];

      for (const name of secretNames) {
        try {
          const secret = await this.client.getSecret(name);
          secrets[this.camelToSnakeCase(name)] = secret.value;
        } catch (error) {
          console.warn(`[Azure Key Vault] Secret not found: ${name}`);
        }
      }

      this.cache = secrets;
      this.cacheExpiry = Date.now() + 3600000; // 1 hour

      console.log('[Azure Key Vault] ✓ Secrets retrieved successfully');
      return this.cache;
    } catch (error) {
      console.error('[Azure Key Vault] ❌ Failed to retrieve secrets:', error);
      throw new Error('Unable to load secrets from Azure Key Vault');
    }
  }

  camelToSnakeCase(str) {
    return str.replace(/[A-Z]/g, letter => `_${letter}`).toUpperCase();
  }
}

/**
 * Factory function to get the appropriate secrets manager
 */
async function getSecretsManager() {
  const managerType = process.env.SECRETS_MANAGER || 'dotenv';

  console.log(`\n📦 Initializing secrets manager: ${managerType}\n`);

  let manager;

  switch (managerType.toLowerCase()) {
    case 'aws':
      manager = new AWSSecretsManager();
      break;

    case 'vault':
      manager = new VaultSecretsManager();
      break;

    case 'gcp':
      manager = new GCPSecretsManager();
      break;

    case 'azure':
      manager = new AzureSecretsManager();
      break;

    case 'dotenv':
      // Development only - load from .env.local file
      if (process.env.NODE_ENV === 'production') {
        throw new Error(
          'Cannot use dotenv secrets manager in production. Set SECRETS_MANAGER to aws|vault|gcp|azure'
        );
      }
      console.warn(
        '⚠️  WARNING: Using dotenv for secrets. This is development only!\n'
      );
      const dotenv = require('dotenv');
      dotenv.config({ path: '.env.local' });
      return {
        getSecrets: async () => process.env,
      };

    default:
      throw new Error(
        `Unknown secrets manager: ${managerType}. Use: aws, vault, gcp, azure, or dotenv`
      );
  }

  const secrets = await manager.getSecrets();
  return {
    getSecrets: async () => secrets,
  };
}

module.exports = {
  getSecretsManager,
  AWSSecretsManager,
  VaultSecretsManager,
  GCPSecretsManager,
  AzureSecretsManager,
};

