### Solution 3: Use AWS Secrets Manager

Create `config/secrets.js`:
```javascript
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName] && Date.now() - this.cache[secretName].timestamp < this.cacheTTL) {
      return this.cache[secretName].value;
    }

    try {
      const response = await client.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async getDatabaseCredentials() {
    return this.getSecret('prod/database/postgres');
  }

  async getApiKeys() {
    return this.getSecret('prod/api-keys');
  }

  async getJWTSecret() {
    return this.getSecret('prod/jwt-secret');
  }
}

module.exports = new SecretsManager();
```

### Solution 4: Use Google Cloud Secret Manager

Create `config/gcp-secrets.js`:
```javascript
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GCPSecretsManager {
  constructor(projectId) {
    this.client = new SecretManagerServiceClient();
    this.projectId = projectId;
    this.cache = {};
  }

  async getSecret(secretName, version = 'latest') {
    const cacheKey = `${secretName}:${version}`;
    if (this.cache[cacheKey]) {
      return this.cache[cacheKey];
    }

    try {
      const name = this.client.secretVersionPath(this.projectId, secretName, version);
      const [version_resource] = await this.client.accessSecretVersion({ name });

      const payload = version_resource.payload.data.toString('utf8');
      this.cache[cacheKey] = payload;

      return payload;
    } catch (error) {
      console.error(`Failed to retrieve GCP secret ${secretName}:`, error);
      throw error;
    }
  }

  async getSecretJSON(secretName, version = 'latest') {
    const data = await this.getSecret(secretName, version);
    return JSON.parse(data);
  }
}

module.exports = GCPSecretsManager;
```

