const vault = require('node-vault');

class VaultSecretsManager {
  constructor(options = {}) {
    this.client = vault({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN,
      apiVersion: 'v1'
    });
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(path) {
    if (this.cache[path] && Date.now() - this.cache[path].timestamp < this.cacheTTL) {
      return this.cache[path].value;
    }

    try {
      const response = await this.client.read(path);
      const secret = response.data.data;

      this.cache[path] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve Vault secret ${path}:`, error);
      throw error;
    }
  }

  async getDatabaseCredentials() {
    return this.getSecret('secret/data/database');
  }

  async getJWTSecret() {
    return this.getSecret('secret/data/jwt');
  }
}

module.exports = VaultSecretsManager;
```

