```javascript
require('dotenv').config(); // Only for development
const express = require('express');
const aws = require('aws-sdk');

class AppConfig {
  constructor() {
    this.secrets = null;
    this.isProduction = process.env.NODE_ENV === 'production';
  }

  async initialize() {
    if (this.isProduction) {
      await this.loadProductionSecrets();
    } else {
      this.loadDevelopmentSecrets();
    }
    return this;
  }

  async loadProductionSecrets() {
    const secretsManager = new aws.SecretsManager();

    try {
      const response = await secretsManager
        .getSecretValue({ SecretId: 'prod/app-secrets' })
        .promise();

      this.secrets = JSON.parse(response.SecretString);
      console.log('✓ Secrets loaded from AWS Secrets Manager');
    } catch (error) {
      console.error('✗ Failed to load production secrets:', error.message);
      process.exit(1);
    }
  }

  loadDevelopmentSecrets() {
    // Validate required env vars for development
    const required = ['JWT_SECRET', 'DATABASE_URL'];
    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      console.error(`✗ Missing required environment variables: ${missing.join(', ')}`);
      console.error('Create .env file from .env.example');
      process.exit(1);
    }

    this.secrets = {
      jwtSecret: process.env.JWT_SECRET,
      databaseUrl: process.env.DATABASE_URL,
      stripeKey: process.env.STRIPE_SECRET_KEY,
      apiKey: process.env.ANTHROPIC_API_KEY
    };

    console.log('✓ Secrets loaded from .env file (development mode)');
  }

  get(key) {
    if (!this.secrets || !(key in this.secrets)) {
      throw new Error(`Secret not found: ${key}`);
    }
    return this.secrets[key];
  }
}

// Initialize app
const app = express();
const config = new AppConfig();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Start server
(async () => {
  try {
    await config.initialize();

    const port = process.env.PORT || 3000;
    app.listen(port, () => {
      console.log(`✓ Server running on port ${port}`);
      if (process.env.NODE_ENV === 'production') {
        console.log('✓ Running in production mode with secured secret management');
      } else {
        console.log('⚠ Running in development mode');
      }
    });
  } catch (error) {
    console.error('✗ Failed to start server:', error);
    process.exit(1);
  }
})();

module.exports = app;
```

