  const client = new AWS.SecretsManager({ region: 'us-east-1' });

  try {
    // Load database secrets
    const dbSecret = await client.getSecretValue({ 
      SecretId: `${process.env.ENVIRONMENT || 'dev'}/app/database` 
    }).promise();
    secretsCache.database = JSON.parse(dbSecret.SecretString);

    // Load AWS credentials
    const awsSecret = await client.getSecretValue({ 
      SecretId: `${process.env.ENVIRONMENT || 'dev'}/app/aws-credentials` 
    }).promise();
    secretsCache.aws = JSON.parse(awsSecret.SecretString);

    // Load API keys
    const apiKeys = await client.getSecretValue({ 
      SecretId: `${process.env.ENVIRONMENT || 'dev'}/app/api-keys` 
    }).promise();
    secretsCache.apiKeys = JSON.parse(apiKeys.SecretString);

    console.log('Secrets loaded successfully');
  } catch (error) {
    console.error('Failed to load secrets:', error.message);
    throw new Error('Cannot start without secrets');
  }
}

async function connectDatabase() {
