    message: 'Users list accessed',
    userId: req.user.id,
    userRole: req.user.role,
  });

  // Filter user data based on role
  const filteredUsers = users.map(user => 
    filterUserData(user, req.user.role)
  );

  res.json(filteredUsers);
});

/**
 * Get user by ID (requires authentication)
 */
app.get('/users/:id',
  authenticateToken,
  param('id').isInt().toInt(),
  (req, res) => {
    // Validate input
    if (validateRequest(req, res)) return;

    const { id } = req.params;
    const user = users.find(u => u.id === id);

    if (!user) {
      logger.warn({
        message: 'User not found',
        userId: id,
        requesterUserId: req.user.id,
      });
      return res.status(404).json({ error: 'User not found' });
    }

    logger.info({
      message: 'User profile accessed',
      userId: id,
      requesterUserId: req.user.id,
    });

    res.json(filterUserData(user, req.user.role));
  }
);

/**
 * Create user (admin only)
 */
app.post('/users',
  authenticateToken,
  authorize('admin'),
  body('name').trim().isLength({ min: 2, max: 100 }).escape(),
  body('email').isEmail().trim().toLowerCase(),
  (req, res) => {
    // Validate input
    if (validateRequest(req, res)) return;

    const { name, email } = req.body;

    // Check for duplicates
    if (users.some(u => u.email === email)) {
      logger.warn({
        message: 'Duplicate email attempt',
        email,
        requesterUserId: req.user.id,
      });
      return res.status(409).json({ error: 'Email already exists' });
    }

    const newUser = {
      id: Math.max(...users.map(u => u.id)) + 1,
      name,
      email,
      role: 'user',
      createdAt: new Date(),
    };

    users.push(newUser);

    logger.info({
      message: 'New user created',
      newUserId: newUser.id,
      createdBy: req.user.id,
    });

    res.status(201).json(filterUserData(newUser, req.user.role));
  }
);

/**
 * Delete user (admin only)
 */
app.delete('/users/:id',
  authenticateToken,
  authorize('admin'),
  param('id').isInt().toInt(),
  (req, res) => {
    // Validate input
    if (validateRequest(req, res)) return;

    const { id } = req.params;
    const userIndex = users.findIndex(u => u.id === id);

    if (userIndex === -1) {
      return res.status(404).json({ error: 'User not found' });
    }

    const deletedUser = users.splice(userIndex, 1)[0];

    logger.info({
      message: 'User deleted',
      deletedUserId: id,
      deletedBy: req.user.id,
    });

    res.json({ message: 'User deleted', user: deletedUser });
  }
);

// ============================================================================
// 404 HANDLER
// ============================================================================
app.use((req, res) => {
  logger.warn({
    message: '404 Not Found',
    method: req.method,
    path: req.path,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not Found' });
});

// ============================================================================
// GLOBAL ERROR HANDLER (must be last)
// ============================================================================
app.use((err, req, res, next) => {
  logger.error({
    message: 'Unhandled error',
    error: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    userId: req.user?.id,
  });

  // Don't expose stack traces in production
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  const statusCode = err.status || 500;

  res.status(statusCode).json({ 
    error: message,
    ...(NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

