// SERVER STARTUP
// ============================================================================
if (require.main === module) {
  app.listen(PORT, () => {
    logger.info({
      message: 'Server started',
      port: PORT,
      environment: NODE_ENV,
      timestamp: new Date().toISOString(),
    });
  });
}

