### **Step 2: Create Secrets Manager Wrapper**

```javascript
// secrets.js
const AWS = require('aws-sdk');
const logger = require('./logger');

let secretsCache = null;
let cacheTimestamp = null;
const CACHE_TTL = 3600000; // 1 hour

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager();
  }

  async getSecrets() {
    // Return cached secrets if fresh
    if (secretsCache && Date.now() - cacheTimestamp < CACHE_TTL) {
      return secretsCache;
    }

    try {
      const secret = await this.client.getSecretValue({
        SecretId: process.env.SECRETS_ARN
      }).promise();

      secretsCache = JSON.parse(secret.SecretString);
      cacheTimestamp = Date.now();

      logger.info('Secrets loaded successfully');
      return secretsCache;
    } catch (error) {
      logger.error('Failed to load secrets:', {
        error: error.message,
        code: error.code
      });
      throw new Error('Cannot initialize application');
    }
  }

  async getSecret(key) {
    const secrets = await this.getSecrets();
    if (!secrets[key]) {
      throw new Error(`Secret not found: ${key}`);
    }
    return secrets[key];
  }

  // Prevent accidental logging
  toString() {
    return '[SecretsManager]';
  }

  toJSON() {
    return '[SecretsManager]';
  }
}

module.exports = new SecretsManager();
```

