================================================================================
SECURITY AUDIT REPORT - app.js
================================================================================

DATE: 2024
SEVERITY OVERVIEW: 6 Issues Identified (3 High, 3 Medium)

================================================================================
VULNERABILITY FINDINGS
================================================================================

1. MISSING AUTHENTICATION & AUTHORIZATION
   Severity: HIGH
   Category: OWASP A07:2021 - Broken Access Control

   Issue:
   - No authentication mechanism for /users endpoint
   - No authorization checks
   - Sensitive user data (emails) exposed without any access control
   - No rate limiting or DDoS protection

   Current Code:
   ```javascript
   app.get('/users', (req, res) => {
     res.json([
       { id: 1, name: 'Alice', email: 'alice@example.com' },
       { id: 2, name: 'Bob', email: 'bob@example.com' },
     ]);
   });
   ```

   Recommendation:
   Implement authentication middleware and role-based access control.

   ```javascript
   const jwt = require('jsonwebtoken');
   const rateLimit = require('express-rate-limit');

   // Rate limiting middleware
   const limiter = rateLimit({
     windowMs: 15 * 60 * 1000, // 15 minutes
     max: 100, // limit each IP to 100 requests per windowMs
     message: 'Too many requests from this IP, please try again later.'
   });

   // Authentication middleware
   const authenticateToken = (req, res, next) => {
     const authHeader = req.headers['authorization'];
     const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

     if (!token) {
       return res.status(401).json({ error: 'Access token required' });
     }

     jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
       if (err) {
         return res.status(403).json({ error: 'Invalid or expired token' });
       }
       req.user = user;
       next();
     });
   };

   // Authorization middleware
   const authorizeAdmin = (req, res, next) => {
     if (req.user.role !== 'admin') {
       return res.status(403).json({ error: 'Admin role required' });
     }
     next();
   };

   // Protected endpoint with rate limiting
   app.get('/users', limiter, authenticateToken, authorizeAdmin, (req, res) => {
     // Only return necessary fields
     const users = [
       { id: 1, name: 'Alice' },
       { id: 2, name: 'Bob' }
     ];
     res.json(users);
   });
   ```


2. SENSITIVE DATA EXPOSURE
   Severity: HIGH
   Category: OWASP A02:2021 - Cryptographic Failures

   Issue:
   - Email addresses exposed in plain response
   - No data classification or protection
   - Server is likely running over HTTP (not HTTPS)
   - Personal information transmitted unencrypted

   Recommendation:
   - Enable HTTPS/TLS
   - Implement data masking for sensitive fields
   - Use environment-based configuration
   - Consider database-level encryption

   ```javascript
   const express = require('express');
   const https = require('https');
   const fs = require('fs');
   const helmet = require('helmet');

   const app = express();

   // Security headers
   app.use(helmet());

   // HTTPS/TLS Configuration
   const options = {
     key: fs.readFileSync('path/to/private-key.pem'),
     cert: fs.readFileSync('path/to/certificate.pem')
   };

   // Enforce HTTPS redirect (for HTTP server)
   app.use((req, res, next) => {
     if (process.env.NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
       res.redirect(`https://${req.header('host')}${req.url}`);
     }
     next();
   });

   https.createServer(options, app).listen(443);

   // Mask sensitive data
   const maskEmail = (email) => {
     const [localPart, domain] = email.split('@');
     const masked = localPart.charAt(0) + '*'.repeat(localPart.length - 2) + localPart.charAt(localPart.length - 1);
     return `${masked}@${domain}`;
   };

   app.get('/users', authenticateToken, (req, res) => {
     const users = [
       { id: 1, name: 'Alice', email: maskEmail('alice@example.com') },
       { id: 2, name: 'Bob', email: maskEmail('bob@example.com') }
     ];
     res.json(users);
   });
   ```


3. MISSING INPUT VALIDATION & SANITIZATION
   Severity: HIGH
   Category: OWASP A03:2021 - Injection

   Issue:
   - No query parameter validation on any endpoints
   - No input sanitization
   - Vulnerable to query injection attacks
   - No schema validation

   Recommendation:
   Implement input validation using express-validator and joi.

   ```javascript
   const { query, validationResult } = require('express-validator');
   const Joi = require('joi');

   // Schema validation approach
   const userQuerySchema = Joi.object({
     id: Joi.number().integer().positive().optional(),
     limit: Joi.number().integer().min(1).max(100).default(10),
     offset: Joi.number().integer().min(0).default(0)
   });

   // Query validation middleware
   const validateQuery = (schema) => {
     return (req, res, next) => {
       const { error, value } = schema.validate(req.query);
       if (error) {
         return res.status(400).json({
           error: 'Invalid query parameters',
           details: error.details.map(e => e.message)
         });
       }
       req.validatedQuery = value;
       next();
     };
   };

   app.get('/users', 
     limiter, 
     authenticateToken, 
     validateQuery(userQuerySchema), 
     (req, res) => {
       const { limit, offset } = req.validatedQuery;
       // Safely use validated parameters
       const users = [
         { id: 1, name: 'Alice' },
         { id: 2, name: 'Bob' }
       ];
       res.json(users.slice(offset, offset + limit));
     }
   );
   ```


4. MISSING SECURITY HEADERS
   Severity: MEDIUM
   Category: OWASP A05:2021 - Security Misconfiguration

   Issue:
   - No HTTP security headers implemented
   - Vulnerable to XSS, clickjacking, MIME sniffing
   - No Content Security Policy
   - No strict transport security

   Recommendation:
   Use helmet.js to set security headers.

   ```javascript
   const helmet = require('helmet');

   app.use(helmet());

   // Custom header configuration
   app.use(helmet.contentSecurityPolicy({
     directives: {
       defaultSrc: ["'self'"],
       scriptSrc: ["'self'"],
       styleSrc: ["'self'", "'unsafe-inline'"],
       imgSrc: ["'self'", 'data:', 'https:'],
       connectSrc: ["'self'"],
       fontSrc: ["'self'"],
       objectSrc: ["'none'"],
       mediaSrc: ["'self'"],
       frameSrc: ["'none'"],
     },
   }));

   app.use(helmet.hsts({
     maxAge: 31536000, // 1 year in seconds
     includeSubDomains: true,
     preload: true
   }));

   app.use(helmet.noSniff());
   app.use(helmet.xssFilter());
   app.use(helmet.frameguard({ action: 'deny' }));
   app.use(helmet.referrerPolicy({ policy: 'strict-origin-when-cross-origin' }));
   ```


5. NO ERROR HANDLING & INFORMATION DISCLOSURE
   Severity: MEDIUM
   Category: OWASP A01:2021 - Broken Access Control & A05:2021 - Security Misconfiguration

   Issue:
   - No error handling middleware
   - Stack traces exposed to clients
   - No logging for security events
   - Unhandled promise rejections

   Recommendation:
   Implement comprehensive error handling and logging.

   ```javascript
   const winston = require('winston');

   // Configure logging
   const logger = winston.createLogger({
     level: process.env.LOG_LEVEL || 'info',
     format: winston.format.json(),
     transports: [
       new winston.transports.File({ filename: 'error.log', level: 'error' }),
       new winston.transports.File({ filename: 'combined.log' })
     ]
   });

   if (process.env.NODE_ENV !== 'production') {
     logger.add(new winston.transports.Console({
       format: winston.format.simple()
     }));
   }

   // Security event logging
   app.use((req, res, next) => {
     res.on('finish', () => {
       if (res.statusCode >= 400) {
         logger.warn({
           method: req.method,
           path: req.path,
           status: res.statusCode,
           ip: req.ip,
           userAgent: req.get('user-agent')
         });
       }
     });
     next();
   });

   // Global error handler
   app.use((err, req, res, next) => {
     logger.error({
       message: err.message,
       stack: err.stack,
       path: req.path,
       method: req.method
     });

     // Don't expose stack trace to client
     const statusCode = err.statusCode || 500;
     res.status(statusCode).json({
       error: process.env.NODE_ENV === 'production' 
         ? 'Internal server error' 
         : err.message
     });
   });

   // Handle unhandled promise rejections
   process.on('unhandledRejection', (reason, promise) => {
     logger.error({
       message: 'Unhandled Rejection',
       reason: reason,
       promise: promise
     });
   });
   ```


6. MISSING ENVIRONMENT CONFIGURATION
   Severity: MEDIUM
   Category: OWASP A05:2021 - Security Misconfiguration

   Issue:
   - Hardcoded port (3000)
   - No environment variable support
   - No configuration for different environments
   - Secrets potentially exposed in code

   Recommendation:
   Use environment variables for configuration.

   ```javascript
   require('dotenv').config();
   const express = require('express');
   const helmet = require('helmet');

   const app = express();

