  async loadFromKubernetes() {
    const fs = require('fs').promises;
    const path = '/var/run/secrets/kubernetes.io/serviceaccount';

    return {
      JWT_SECRET: await fs.readFile(
        `${path}/jwt-secret`,
        'utf8'
      ),
      DATABASE_URL: await fs.readFile(
        `${path}/database-url`,
        'utf8'
      )
    };
  }

  validate() {
    const required = ['JWT_SECRET', 'DATABASE_URL'];

    required.forEach(secret => {
      if (!this.secrets[secret]) {
        throw new Error(`Missing required secret: ${secret}`);
      }
    });

    // Validate JWT_SECRET strength
    if (this.secrets.JWT_SECRET.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    // Validate DATABASE_URL format
    if (!this.secrets.DATABASE_URL.match(/^(postgres|mysql|mongodb):\/\//)) {
      throw new Error('Invalid DATABASE_URL format');
    }
  }

  get(key) {
    const secret = this.secrets[key];
    if (!secret) {
      throw new Error(`Secret not found: ${key}`);
    }
    return secret;
  }
}

module.exports = SecretsManager;
