// config/secrets.js
const dotenv = require('dotenv');
const path = require('path');
const fs = require('fs');
const AWS = require('aws-sdk');

/**
 * Load secrets based on environment
 * Development: Use .env.development (not committed)
 * Production: Use AWS Secrets Manager
 * Staging: Use AWS Secrets Manager or .env.staging
 */
async function loadSecrets() {
  const env = process.env.NODE_ENV || 'development';

  if (env === 'production') {
    // Production: Load from AWS Secrets Manager
    return await loadFromAWSSecretsManager();
  } else if (env === 'staging') {
    // Staging: Load from AWS or environment
    return await loadFromAWSSecretsManager();
  } else {
    // Development: Load from local .env file (not in repo)
    return loadFromDotenv();
  }
}

/**
 * Load from AWS Secrets Manager
 */
async function loadFromAWSSecretsManager() {
  const secretsManager = new AWS.SecretsManager({
    region: process.env.AWS_REGION || 'us-east-1'
  });

  try {
    const secretName = `${process.env.NODE_ENV}/app/secrets`;

    console.log(`[Secrets] Loading from AWS Secrets Manager: ${secretName}`);

    const data = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    let secrets;
    if ('SecretString' in data) {
      secrets = JSON.parse(data.SecretString);
    } else {
      // Binary secrets (less common)
      secrets = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    console.log('[Secrets] Successfully loaded from AWS Secrets Manager');

    // Set as environment variables
    Object.entries(secrets).forEach(([key, value]) => {
      if (!process.env[key]) {
        process.env[key] = value;
      }
    });

    return secrets;
  } catch (err) {
    console.error('[Secrets] Failed to load from AWS Secrets Manager:', err.message);

    // Fail fast in production
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Failed to load production secrets. Cannot start server.');
    }

    // Fall back to .env in non-production
    return loadFromDotenv();
  }
}

/**
 * Load from local .env file
 */
function loadFromDotenv() {
  const env = process.env.NODE_ENV || 'development';
  const envFile = path.resolve(`.env.${env}`);

  if (!fs.existsSync(envFile)) {
    console.warn(`[Secrets] .env.${env} file not found at ${envFile}`);
    return {};
  }

  console.log(`[Secrets] Loading from .env.${env}`);

  const result = dotenv.config({ path: envFile });

  if (result.error) {
    console.error('[Secrets] Error loading .env file:', result.error);
    throw result.error;
  }

  console.log('[Secrets] Successfully loaded from .env file');
  return result.parsed;
}

module.exports = { loadSecrets };
```

