/**
 * Load secrets from AWS Secrets Manager
 * This is the RECOMMENDED approach for production environments
 */
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;

async function getSecretsFromAWS() {
  try {
    if (cachedSecrets) {
      return cachedSecrets;
    }

    const secretName = process.env.SECRET_ARN || 'prod/app/secrets';

    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    let secrets;
    if ('SecretString' in data) {
      secrets = JSON.parse(data.SecretString);
    } else {
      // Handle binary secrets
      const buff = Buffer.from(data.SecretBinary, 'base64');
      secrets = JSON.parse(buff.toString('ascii'));
    }

    // Cache for performance (consider TTL in production)
    cachedSecrets = secrets;
    return secrets;
  } catch (error) {
    console.error('Failed to retrieve secrets from AWS:', error);
    throw error;
  }
}

// ===================================================================
// OPTION 2: HASHICORP VAULT (RECOMMENDED FOR ENTERPRISE)
// ===================================================================

const vault = require('node-vault');

const vaultClient = new vault({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN
});

async function getSecretsFromVault() {
  try {
    const path = process.env.VAULT_PATH || 'secret/data/app';
    const secret = await vaultClient.read(path);
    return secret.data.data;
  } catch (error) {
    console.error('Failed to retrieve secrets from Vault:', error);
    throw error;
  }
}

// ===================================================================
// OPTION 3: ENVIRONMENT VARIABLES (WITH VALIDATION)
// ===================================================================

function getSecretsFromEnvironment() {
  // Define required secrets
  const requiredSecrets = [
    'DATABASE_URL',
    'JWT_SECRET',
    'API_KEY'
  ];

  const secrets = {};

  // Validate all required secrets exist
  const missing = [];
  requiredSecrets.forEach(secret => {
    if (!process.env[secret]) {
      missing.push(secret);
    } else {
      secrets[secret] = process.env[secret];
    }
  });

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}\n` +
      `These must be injected at runtime, not committed to code.`
    );
  }

  return secrets;
}

// ===================================================================
// OPTION 4: DOTENV WITH STRICT CONTROLS (DEVELOPMENT ONLY)
// ===================================================================

function getSecretsFromDotenv() {
  // ONLY load .env files in development
  if (process.env.NODE_ENV !== 'development') {
    console.error('ERROR: .env files should not be used in production!');
    process.exit(1);
  }

  const path = require('path');
  const dotenv = require('dotenv');

  // Only load .env.local (which should be .gitignored)
  // NEVER load .env.test or .env.production
  const envPath = path.resolve(process.cwd(), '.env.local');

  const result = dotenv.config({ path: envPath });

  if (result.error && result.error.code !== 'ENOENT') {
    throw new Error(`Failed to load .env.local: ${result.error}`);
  }

  return process.env;
}

// ===================================================================
// UNIFIED SECRETS LOADER
// ===================================================================

async function loadSecrets() {
  const environment = process.env.NODE_ENV || 'development';

  console.log(`Loading secrets for environment: ${environment}`);

  let secrets;

  switch (environment) {
    case 'production':
      // Use AWS Secrets Manager in production
      console.log('Using AWS Secrets Manager...');
      secrets = await getSecretsFromAWS();
      break;

    case 'staging':
      // Use Vault in staging
      console.log('Using HashiCorp Vault...');
      secrets = await getSecretsFromVault();
      break;

    case 'development':
      // Use environment variables, with optional .env.local fallback
      console.log('Using environment variables + .env.local...');
      try {
        getSecretsFromDotenv();
        secrets = getSecretsFromEnvironment();
      } catch (error) {
        console.warn(`Could not load .env.local: ${error.message}`);
        secrets = getSecretsFromEnvironment();
      }
      break;

    default:
      throw new Error(`Unknown environment: ${environment}`);
  }

  return secrets;
}

