    this.databaseUrl = this.validateSecret(rawSecrets.DATABASE_URL, 'DATABASE_URL', 'string');
    this.jwtSecret = this.validateSecret(rawSecrets.JWT_SECRET, 'JWT_SECRET', 'string');
    this.apiKey = this.validateSecret(rawSecrets.API_KEY, 'API_KEY', 'string');
