      this.validateSecret(rawSecrets.AWS_SECRET_ACCESS_KEY, 'AWS_SECRET_ACCESS_KEY', 'string') : null;
  }

  validateSecret(value, name, type) {
    if (!value) {
      throw new Error(`Missing secret: ${name}`);
    }

    if (typeof value !== type) {
      throw new Error(`Invalid type for secret ${name}: expected ${type}, got ${typeof value}`);
    }

    // Additional validation for known secret formats
    if (name === 'JWT_SECRET' && value.length < 32) {
      throw new Error(`JWT_SECRET must be at least 32 characters long`);
    }

    if (name === 'DATABASE_URL' && !value.startsWith('postgres://')) {
      throw new Error(`DATABASE_URL must start with postgres://`);
    }

    if (name === 'STRIPE_SECRET_KEY' && !value.startsWith('sk_')) {
      throw new Error(`STRIPE_SECRET_KEY must start with sk_`);
    }

    // Ensure production secrets don't contain test patterns
    if (process.env.NODE_ENV === 'production' && value.includes('CANARY')) {
      throw new Error(`SECURITY ALERT: Test secret "${name}" found in production!`);
    }

    if (process.env.NODE_ENV === 'production' && value.includes('test')) {
      console.warn(`WARNING: Secret "${name}" contains 'test' pattern`);
    }

    return value;
  }

