    this.loadedFrom = null;
    this.secretKeys = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'JWT_SECRET',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];

    this.requireKeys = [
      'NODE_ENV',
      'JWT_SECRET'
    ];

    this.validateEnvironment();
  }

  /**
   * Validate that required environment variables are set
   */
  validateEnvironment() {
    const missing = this.requireKeys.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required environment variables: ${missing.join(', ')}\n` +
        `Please ensure these are set before starting the application.`
      );
    }

    console.log(`✓ All required environment variables present`);
    console.log(`✓ Running in ${process.env.NODE_ENV} environment`);
  }

  /**
   * Safely retrieve a configuration value
   * @param {string} key - Environment variable key
   * @param {*} defaultValue - Default value if not found
   * @returns {*} Configuration value
   */
  get(key, defaultValue = undefined) {
    const value = process.env[key];

    if (!value && defaultValue === undefined) {
      throw new Error(
        `Configuration key "${key}" is required but not set. ` +
        `Please set the ${key} environment variable.`
      );
    }

    return value || defaultValue;
  }

  /**
   * Get a secret with redaction for logging
   * @param {string} key - Secret key
   * @returns {object} { value, redacted }
   */
  getSecret(key) {
    const value = this.get(key);
    const redacted = this.redactSecret(value);
    return { value, redacted };
  }

  /**
   * Redact sensitive information for safe logging
   * @param {string} secret - Secret value to redact
   * @returns {string} Redacted version
   */
  redactSecret(secret) {
    if (!secret || typeof secret !== 'string') return '[REDACTED]';

    if (secret.length <= 4) return '****';
    if (secret.startsWith('sk_')) return `${secret.substring(0, 10)}...****`;
    if (secret.startsWith('AKIA')) return `${secret.substring(0, 8)}...****`;

    // For URLs and connection strings
    if (secret.includes('://')) {
      return secret.replace(/:[^@]*@/, ':****@');
    }

    return `${secret.substring(0, 6)}...${secret.substring(secret.length - 4)}`;
  }

  /**
   * Validate secret format
   * @param {string} key - Secret key name
   * @param {string} value - Secret value
   * @returns {boolean} True if valid format
   */
  validateSecretFormat(key, value) {
    const validators = {
      'AWS_ACCESS_KEY_ID': (v) => /^AKIA[0-9A-Z]{16}$/.test(v),
      'AWS_SECRET_ACCESS_KEY': (v) => v.length >= 40,
      'STRIPE_SECRET_KEY': (v) => v.startsWith('sk_live_') || v.startsWith('sk_test_'),
      'ANTHROPIC_API_KEY': (v) => v.startsWith('sk-ant-'),
      'JWT_SECRET': (v) => v.length >= 32,
      'DATABASE_URL': (v) => v.includes('://'),
    };

    if (validators[key]) {
      return validators[key](value);
    }

    return true; // Other keys pass by default
  }

  /**
   * Load and validate all critical secrets
   * @returns {object} Configuration object
   */
  loadSecrets() {
    const secrets = {};

    this.secretKeys.forEach(key => {
      const value = process.env[key];

      if (value) {
        if (this.validateSecretFormat(key, value)) {
          secrets[key] = value;
          const { redacted } = this.getSecret(key);
          console.log(`✓ ${key}: ${redacted}`);
        } else {
          console.warn(`⚠ ${key}: Invalid format detected`);
        }
      }
    });

    return secrets;
  }

  /**
   * Prevent accidental logging of secrets
   */
  toString() {
    return '[ConfigManager - Secrets Hidden]';
  }

  toJSON() {
    return { _: 'ConfigManager - Secrets Hidden' };
  }

  /**
   * Inspect method for debugging (still redacts secrets)
   */
  [Symbol.for('nodejs.util.inspect.custom')]() {
    return '[ConfigManager - Secrets Hidden]';
  }
}

// Create singleton instance
const config = new ConfigManager();

module.exports = config;

