/**
 * AWS Secrets Manager Loader
 * Production-grade secrets management using AWS Secrets Manager
 */

const AWS = require('aws-sdk');

class AWSSecretsLoader {
  constructor(options = {}) {
    this.client = new AWS.SecretsManager({
      region: options.region || process.env.AWS_REGION || 'us-east-1',
      maxRetries: options.maxRetries || 3,
    });

    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 3600000; // 1 hour
    this.secretName = options.secretName || `${process.env.NODE_ENV}/app/secrets`;
  }

  /**
   * Load secrets from AWS Secrets Manager
   * @returns {Promise<object>} Loaded secrets
   */
  async loadSecrets() {
    // Check cache first
    if (this.cache.has(this.secretName)) {
      const cached = this.cache.get(this.secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        console.log('✓ Secrets loaded from cache');
        return cached.data;
      }
    }

    try {
      console.log(`Loading secrets from AWS Secrets Manager: ${this.secretName}`);

      const data = await this.client.getSecretValue({
        SecretId: this.secretName,
      }).promise();

      let secret;

      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else if ('SecretBinary' in data) {
        secret = JSON.parse(Buffer.from(data.SecretBinary, 'base64').toString('ascii'));
      } else {
        throw new Error('Invalid secret format');
      }

      // Validate loaded secrets
      this.validateSecrets(secret);

      // Cache the secrets
      this.cache.set(this.secretName, {
        data: secret,
        timestamp: Date.now(),
      });

      console.log('✓ Secrets successfully loaded from AWS Secrets Manager');
      this.logSecretStatus(secret);

      return secret;
    } catch (error) {
      console.error('Failed to load secrets from AWS Secrets Manager:', error.message);

      // If development, try falling back to environment variables
      if (process.env.NODE_ENV === 'development') {
        console.warn('⚠ Falling back to environment variables');
        return this.loadFromEnvironment();
      }

      // In production, fail fast
      throw new Error('Failed to load secrets from AWS Secrets Manager');
    }
  }

  /**
   * Load secrets from environment variables (fallback)
   * @returns {object} Secrets from environment
   */
  loadFromEnvironment() {
    const secrets = {
      database_url: process.env.DATABASE_URL,
      aws_access_key_id: process.env.AWS_ACCESS_KEY_ID,
      aws_secret_access_key: process.env.AWS_SECRET_ACCESS_KEY,
      jwt_secret: process.env.JWT_SECRET,
      stripe_secret_key: process.env.STRIPE_SECRET_KEY,
      anthropic_api_key: process.env.ANTHROPIC_API_KEY,
      logfire_token: process.env.LOGFIRE_TOKEN,
    };

    this.validateSecrets(secrets);
    console.log('✓ Secrets loaded from environment variables');
    return secrets;
  }

  /**
   * Validate that all required secrets are present
   * @param {object} secrets - Secrets object to validate
   */
  validateSecrets(secrets) {
    const required = [
      'jwt_secret',
      'database_url',
    ];

    const missing = required.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  /**
   * Log secret status without exposing values
   * @param {object} secrets - Secrets object
   */
  logSecretStatus(secrets) {
    Object.entries(secrets).forEach(([key, value]) => {
      if (value) {
        const redacted = this.redactSecret(value);
        console.log(`  ✓ ${key}: ${redacted}`);
      }
    });
  }

  /**
   * Redact secret for safe logging
   * @param {string} secret - Secret to redact
   * @returns {string} Redacted secret
   */
  redactSecret(secret) {
    if (!secret || typeof secret !== 'string') return '[REDACTED]';
    if (secret.length <= 4) return '****';
    if (secret.startsWith('sk_')) return `${secret.substring(0, 10)}...****`;
    if (secret.includes('://')) return secret.replace(/:[^@]*@/, ':****@');
    return `${secret.substring(0, 6)}...${secret.substring(secret.length - 4)}`;
  }

  /**
   * Rotate secrets (updates cache)
   */
  async rotateSecrets() {
    console.log('Rotating secrets...');
    this.cache.delete(this.secretName);
    return this.loadSecrets();
  }

  /**
   * Set up automatic secret rotation (recommended every 30 days)
   * @param {number} intervalMs - Rotation interval in milliseconds
   */
  startAutoRotation(intervalMs = 2592000000) { // 30 days
    this.rotationInterval = setInterval(async () => {
      try {
        await this.rotateSecrets();
      } catch (error) {
        console.error('Failed to rotate secrets:', error);
      }
    }, intervalMs);

    console.log(`✓ Automatic secret rotation enabled (every ${intervalMs / 1000 / 60 / 60 / 24} days)`);
  }

  /**
   * Stop automatic rotation
   */
  stopAutoRotation() {
    if (this.rotationInterval) {
      clearInterval(this.rotationInterval);
      this.rotationInterval = null;
      console.log('✓ Automatic secret rotation disabled');
    }
  }
}

module.exports = AWSSecretsLoader;
