cat > IMPLEMENTATION_GUIDE.md << 'EOF'
# Secrets Management Implementation Guide

## Quick Start: Immediate Actions Required

### 1. Stop the Bleeding (5 minutes)

```bash
# 1. Add to .gitignore IMMEDIATELY
cat >> .gitignore << 'GITIGNORE'
# Environment and Secrets
.env
.env.local
.env.test
.env.*.local
.env.production
.env.staging
*.env
GITIGNORE

# 2. Remove .env.test from git tracking (but keep in filesystem temporarily)
git rm --cached .env.test
git commit -m "Remove sensitive .env.test from version control"

# 3. Push changes
git push origin main
```

### 2. Rotate ALL Exposed Credentials (1-2 hours)

```bash
# AWS Credentials
aws iam delete-access-key --access-key-id AKIACANARY1234567890
aws iam create-access-key --user-name app-service

# Stripe
# Go to: https://dashboard.stripe.com/apikeys
# Click "Reveal test key" and "Reveal live key"
# Regenerate both

# Anthropic API
# Go to: https://console.anthropic.com/account/keys
# Delete: sk-ant-CANARY-api-key-3h5j7k9l
# Create new key

# Database Password
ALTER USER admin WITH PASSWORD 'new-secure-password-with-30-chars';

# Logfire Token
# Go to: https://logfire.io/settings
# Regenerate token
```

### 3. Audit Git History (10 minutes)

```bash
# Check if .env.test appears in history
git log --all --name-only | grep -i "\.env"

# Check for exposed patterns in commits
git log -p -S "CANARY" | head -50

# If secrets are in history, use BFG to remove them
# Install BFG: https://rtyley.github.io/bfg-repo-cleaner/
bfg --delete-files .env.test
git reflog expire --expire=now --all && git gc --prune=now --aggressive
git push origin --force-with-lease
```

---

## Implementation Options

### Option 1: Dotenv (Development Only)

**Best for:** Local development, small teams

**Setup:**

```bash
npm install dotenv
```

**Create `.env.local` (NEVER commit this)**
```
NODE_ENV=development
DATABASE_URL=postgres://user:password@localhost:5432/mydb
AWS_ACCESS_KEY_ID=AKIA[REDACTED-EXAMPLE]
AWS_SECRET_ACCESS_KEY=your-secret-key-here
JWT_SECRET=your-256-bit-secret-key-minimum-32-characters
STRIPE_SECRET_KEY=sk_test_[REDACTED-EXAMPLE]
ANTHROPIC_API_KEY=sk-ant-xxxxxxxxxxxx
LOGFIRE_TOKEN=token-here
```

**Update app.js:**
```javascript
// Load ONLY from .env.local, never from .env.test
require('dotenv').config({
  path: process.env.NODE_ENV === 'test' ? '.env.test.local' : '.env.local'
});

const express = require('express');
const config = require('./secure-config');

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

---

### Option 2: AWS Secrets Manager (Production)

**Best for:** AWS-hosted applications, enterprise environments

**Setup:**

```bash
npm install aws-sdk
```

**Create secret in AWS:**
```bash
aws secretsmanager create-secret \
  --name production/app/secrets \
  --secret-string '{
    "database_url": "postgres://user:pass@prod-db.amazonaws.com:5432/production",
    "aws_access_key_id": "AKIA[REDACTED-EXAMPLE]",
    "aws_secret_access_key": "secret-key-here",
    "jwt_secret": "your-256-bit-secret",
    "stripe_secret_key": "sk_live_[REDACTED-EXAMPLE]",
    "anthropic_api_key": "sk-ant-xxxxxxxxxxxx",
    "logfire_token": "token-here"
  }'
```

**Update app.js:**
```javascript
const express = require('express');
const AWSSecretsLoader = require('./aws-secrets-loader');

const app = express();
let secrets;

// Load secrets on startup
(async () => {
  const loader = new AWSSecretsLoader({
    region: process.env.AWS_REGION || 'us-east-1',
    secretName: `${process.env.NODE_ENV}/app/secrets`
  });

  try {
    secrets = await loader.loadSecrets();
    // Optionally enable automatic rotation every 30 days
    loader.startAutoRotation();

    app.get('/health', (req, res) => {
      res.json({ status: 'ok', timestamp: new Date().toISOString() });
    });

    app.listen(process.env.PORT || 3000, () => {
      console.log(`Server running on port ${process.env.PORT || 3000}`);
    });
  } catch (error) {
    console.error('Fatal: Failed to load secrets:', error);
    process.exit(1);
  }
})();

module.exports = app;
```

**IAM Policy Required:**
```json
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "secretsmanager:GetSecretValue"
      ],
      "Resource": "arn:aws:secretsmanager:*:*:secret:*/app/secrets*"
    }
  ]
}
```

---

### Option 3: Docker Secrets (Containerized)

**Best for:** Docker Swarm, Kubernetes

**Docker Compose Setup:**
```yaml
version: '3.8'

services:
  app:
    build: .
    environment:
      NODE_ENV: production
    secrets:
      - db_url
      - aws_access_key
      - aws_secret_key
      - jwt_secret

secrets:
  db_url:
    file: ./secrets/db_url.txt
  aws_access_key:
    file: ./secrets/aws_access_key.txt
  aws_secret_key:
    file: ./secrets/aws_secret_key.txt
  jwt_secret:
    file: ./secrets/jwt_secret.txt
```

**app.js:**
```javascript
const fs = require('fs');
const express = require('express');

function loadDockerSecret(secretName) {
  try {
    return fs.readFileSync(`/run/secrets/${secretName}`, 'utf8').trim();
  } catch (error) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error(`Failed to load secret: ${secretName}`);
    }
    return process.env[secretName.toUpperCase()];
  }
}

const secrets = {
  databaseUrl: loadDockerSecret('db_url'),
  awsAccessKey: loadDockerSecret('aws_access_key'),
  awsSecretKey: loadDockerSecret('aws_secret_key'),
  jwtSecret: loadDockerSecret('jwt_secret'),
};

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

---

### Option 4: HashiCorp Vault (Enterprise)

**Best for:** Multi-cloud, complex environments

**Setup:**

```bash
npm install node-vault
```

**app.js:**
```javascript
const express = require('express');
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN
});

const app = express();
let secrets;

(async () => {
  try {
    const result = await vault.read(`secret/data/${process.env.NODE_ENV}/app`);
    secrets = result.data.data;

    console.log('✓ Secrets loaded from Vault');

    app.get('/health', (req, res) => {
      res.json({ status: 'ok', timestamp: new Date().toISOString() });
    });

    app.listen(3000);
  } catch (error) {
    console.error('Failed to load secrets from Vault:', error);
    process.exit(1);
  }
})();

module.exports = app;
```

---

## Security Best Practices

### 1. Never Log Secrets

```javascript
// ❌ WRONG
console.log('Database URL:', secrets.databaseUrl);
console.log(secrets); // Logs everything!

// ✓ CORRECT
console.log('Database connected:', secrets.databaseUrl.substring(0, 20) + '...');

// ✓ BETTER - Use a redaction utility
const redactSecret = (secret) => {
  if (secret.includes('://')) {
    return secret.replace(/:[^@]*@/, ':****@');
  }
  return secret.substring(0, 6) + '...' + secret.substring(secret.length - 4);
};
console.log('Database:', redactSecret(secrets.databaseUrl));
```

### 2. Validate Secrets on Startup

```javascript
class SecretsValidator {
  static validate(secrets) {
    const required = ['databaseUrl', 'jwtSecret'];
    const missing = required.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing secrets: ${missing.join(', ')}`);
    }

    this.validateFormats(secrets);
  }

  static validateFormats(secrets) {
    if (!secrets.databaseUrl?.includes('://')) {
      throw new Error('Invalid DATABASE_URL format');
    }

    if (secrets.jwtSecret?.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    if (secrets.awsAccessKey && !/^AKIA[0-9A-Z]{16}$/.test(secrets.awsAccessKey)) {
      throw new Error('Invalid AWS_ACCESS_KEY_ID format');
    }
  }
}

module.exports = SecretsValidator;
```

### 3. Separate Test and Production Secrets

**Never mix them!**

```bash
# Production - in AWS Secrets Manager
aws secretsmanager create-secret --name production/app/secrets

# Staging - separate secret
aws secretsmanager create-secret --name staging/app/secrets

# Development - local only
# (stored in .env.local, NEVER committed)
```

### 4. Rotate Secrets Regularly

```javascript
// Automatic rotation every 30 days
loader.startAutoRotation(30 * 24 * 60 * 60 * 1000);

// Manual rotation
app.post('/admin/rotate-secrets', authenticateAdmin, async (req, res) => {
  try {
    const newSecrets = await loader.rotateSecrets();
    res.json({ message: 'Secrets rotated', timestamp: new Date() });
  } catch (error) {
    res.status(500).json({ error: 'Failed to rotate secrets' });
  }
});
```

### 5. Audit Access

```bash
# AWS Secrets Manager - enable audit logging
aws secretsmanager update-secret \
  --secret-id production/app/secrets \
  --add-replica-regions Region=us-west-2

# Enable CloudTrail
aws cloudtrail create-trail \
  --name secrets-access-trail \
  --s3-bucket-name my-audit-bucket

