## Security Best Practices

### 1. Never Log Secrets

```javascript
// ❌ WRONG
console.log('Database URL:', secrets.databaseUrl);
console.log(secrets); // Logs everything!

// ✓ CORRECT
console.log('Database connected:', secrets.databaseUrl.substring(0, 20) + '...');

// ✓ BETTER - Use a redaction utility
const redactSecret = (secret) => {
  if (secret.includes('://')) {
    return secret.replace(/:[^@]*@/, ':****@');
  }
  return secret.substring(0, 6) + '...' + secret.substring(secret.length - 4);
};
console.log('Database:', redactSecret(secrets.databaseUrl));
```

### 2. Validate Secrets on Startup

```javascript
class SecretsValidator {
  static validate(secrets) {
    const required = ['databaseUrl', 'jwtSecret'];
    const missing = required.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing secrets: ${missing.join(', ')}`);
    }

    this.validateFormats(secrets);
  }

  static validateFormats(secrets) {
    if (!secrets.databaseUrl?.includes('://')) {
      throw new Error('Invalid DATABASE_URL format');
    }

    if (secrets.jwtSecret?.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    if (secrets.awsAccessKey && !/^AKIA[0-9A-Z]{16}$/.test(secrets.awsAccessKey)) {
      throw new Error('Invalid AWS_ACCESS_KEY_ID format');
    }
  }
}

module.exports = SecretsValidator;
```

