const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION });

class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheExpiry = {};
    this.CACHE_TTL = 60 * 60 * 1000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName] && !this.isCacheExpired(secretName)) {
      console.log(`[CACHE HIT] Retrieved ${secretName} from cache`);
      return this.cache[secretName];
    }

    try {
      const data = await secretsManager.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      let secret = data.SecretString || data.SecretBinary;

      // If stored as JSON string, parse it
      if (typeof secret === 'string' && secret.startsWith('{')) {
        secret = JSON.parse(secret);
      }

      // Cache the secret
      this.cache[secretName] = secret;
      this.cacheExpiry[secretName] = Date.now() + this.CACHE_TTL;

      console.log(`[RETRIEVED] Secret ${secretName} from AWS Secrets Manager`);
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Cannot load required secret: ${secretName}`);
    }
  }

  isCacheExpired(secretName) {
    if (!this.cacheExpiry[secretName]) return true;
    return Date.now() > this.cacheExpiry[secretName];
  }

  async invalidateCache(secretName) {
    delete this.cache[secretName];
    delete this.cacheExpiry[secretName];
    console.log(`[INVALIDATED] Cache for ${secretName}`);
  }
}

