/**
 * Secure Express.js Application
 * Implements OWASP Top 10 security best practices
 */

require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const winston = require('winston');
const { body, param, validationResult } = require('express-validator');

// ==================== CONFIGURATION ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

// Validate required environment variables
if (!JWT_SECRET && NODE_ENV === 'production') {
  console.error('FATAL: JWT_SECRET environment variable not set in production');
  process.exit(1);
}

// ==================== LOGGING ====================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ==================== EXPRESS APP INITIALIZATION ====================

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Helmet.js - Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: {
    action: 'deny',
  },
  referrerPolicy: {
    policy: 'strict-origin-when-cross-origin',
  },
}));

// 2. CORS - Configure allowed origins
const corsOptions = {
  origin: (origin, callback) => {
    if (!origin || ALLOWED_ORIGINS.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));

// 3. Body Parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data Sanitization
app.use(mongoSanitize()); // Prevents NoSQL injection
app.use(xss()); // Prevents XSS attacks

// 5. HTTP Request Logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim()),
  },
  skip: (req, res) => res.statusCode >= 500, // Skip 5xx errors
}));

// 6. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests, please try again later.',
    });
  },
});

app.use(limiter);

// Stricter rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 requests per 15 minutes
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

// ==================== AUTHENTICATION MIDDLEWARE ====================

/**
 * Verify JWT token from Authorization header
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn(`Missing token for ${req.method} ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token for ${req.method} ${req.path} from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

/**
 * Authorization middleware - Check user role
 */
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logger.warn(`Unauthorized access attempt by user ${req.user.id} to ${req.path}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ==================== VALIDATION HELPERS ====================

/**
 * Validation result handler middleware
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn(`Validation error for ${req.method} ${req.path}: ${JSON.stringify(errors.array())}`);
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array(),
    });
  }
  next();
};

// ==================== ROUTES ====================

/**
 * Health check endpoint (public)
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime(),
  });
});

/**
 * Login endpoint - Issue JWT token
 */
app.post('/login', authLimiter, [
  body('username')
    .trim()
    .isLength({ min: 3, max: 50 })
    .withMessage('Username must be 3-50 characters'),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters'),
], handleValidationErrors, (req, res) => {
  // In production, verify against database with bcrypt
  // This is a mock implementation
  const mockUser = {
    id: 1,
    username: 'alice',
    role: 'admin',
  };

  // Verify credentials (simplified for demo)
  if (req.body.username === 'alice' && req.body.password === 'password123') {
    const token = jwt.sign(mockUser, JWT_SECRET, { 
      expiresIn: '24h',
      issuer: 'secure-app',
    });

    logger.info(`User ${req.body.username} logged in successfully`);
    res.json({ token, user: mockUser });
  } else {
    logger.warn(`Failed login attempt for username: ${req.body.username}`);
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

/**
 * Get all users (protected, admin only)
 * Sanitized to not expose sensitive data to regular users
 */
app.get('/users', authenticateToken, authorize('admin'), (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ];

  logger.info(`User ${req.user.id} accessed /users endpoint`);
  res.json(users);
});

/**
 * Get current user's profile (protected)
 */
app.get('/me', authenticateToken, (req, res) => {
  const user = {
    id: req.user.id,
    username: req.user.username,
    role: req.user.role,
  };

  res.json(user);
});

/**
 * Get specific user by ID (protected)
 */
app.get('/users/:id', 
  authenticateToken,
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer'),
  ],
  handleValidationErrors,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    const user = mockUsers.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Sanitize response based on permissions
    const sanitizedUser = {
      id: user.id,
      name: user.name,
      role: user.role,
    };

    // Only admins or the user themselves can see email
    if (req.user.role === 'admin' || req.user.id === userId) {
      sanitizedUser.email = user.email;
    }

    logger.info(`User ${req.user.id} accessed profile for user ${userId}`);
    res.json(sanitizedUser);
  }
);

// ==================== ERROR HANDLING ====================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  const statusCode = err.status || 500;
  const isDevelopment = NODE_ENV !== 'production';

  logger.error(`${err.status || 500} - ${err.message}`, {
    error: err.stack,
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  // Don't expose stack trace in production
  const response = {
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  };

  res.status(statusCode).json(response);
});

// ==================== SERVER STARTUP ====================

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// ==================== GRACEFUL SHUTDOWN ====================

process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

// ==================== UNHANDLED REJECTION HANDLER ====================

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', { promise, reason });
  process.exit(1);
});

module.exports = app;

