/**
 * IMPROVED SECRETS MANAGEMENT
 * Using AWS Secrets Manager instead of .env files
 * 
 * This is a DROP-IN replacement for the secrets loading
 * in app.secure.js
 */

const AWS = require('aws-sdk');
const winston = require('winston');

// Create logger for startup diagnostics
const startupLogger = winston.createLogger({
  level: 'info',
  format: winston.format.simple(),
  transports: [new winston.transports.Console()],
});

/**
 * Load secrets from AWS Secrets Manager
 * 
 * PRODUCTION: Secrets from AWS Secrets Manager
 * DEVELOPMENT: Fallback to dotenv with warnings
 * TESTING: Mock secrets for unit tests
 */
async function loadSecrets() {
  const NODE_ENV = process.env.NODE_ENV || 'development';

  try {
    if (NODE_ENV === 'production') {
      return await loadSecretsFromAWS();
    } else if (NODE_ENV === 'test') {
      return loadMockSecrets();
    } else {
      return loadSecretsFromDotenv();
    }
  } catch (error) {
    startupLogger.error('FATAL: Failed to load secrets', error);
    process.exit(1);
  }
}

/**
 * Load secrets from AWS Secrets Manager
 * @returns {Object} Secrets object
 */
async function loadSecretsFromAWS() {
  const NODE_ENV = process.env.NODE_ENV || 'production';
  const secretName = process.env.AWS_SECRETS_NAME || `${NODE_ENV}/app/secrets`;
  const region = process.env.AWS_REGION || 'us-east-1';

  startupLogger.info(`Loading secrets from AWS Secrets Manager: ${secretName}`);

  try {
    const client = new AWS.SecretsManager({ region });

    const secret = await client.getSecretValue({
      SecretId: secretName,
    }).promise();

    let secretsObject;

    if (secret.SecretString) {
      secretsObject = JSON.parse(secret.SecretString);
    } else {
      // Binary secret
      const buff = Buffer.from(secret.SecretBinary, 'base64');
      secretsObject = JSON.parse(buff.toString('ascii'));
    }

    // Validate required secrets are present
    validateSecrets(secretsObject, NODE_ENV);

    startupLogger.info('✅ Secrets loaded from AWS Secrets Manager');

    return secretsObject;
  } catch (error) {
    if (error.code === 'ResourceNotFoundException') {
      startupLogger.error(`Secret not found: ${secretName}`);
    } else if (error.code === 'InvalidClientTokenId') {
      startupLogger.error('Invalid AWS credentials');
    } else if (error.code === 'AccessDeniedException') {
      startupLogger.error('IAM role lacks permission to access secrets');
    }
    throw error;
  }
}

/**
 * Load secrets from .env file (Development fallback)
 * @returns {Object} Secrets object
 */
function loadSecretsFromDotenv() {
  startupLogger.warn('⚠️  Loading secrets from .env file (DEVELOPMENT ONLY)');
  startupLogger.warn('⚠️  This is NOT suitable for production');

  try {
    require('dotenv').config();

    const secrets = {
      JWT_SECRET: process.env.JWT_SECRET,
      DB_PASSWORD: process.env.DB_PASSWORD,
      API_KEY: process.env.API_KEY,
      SENTRY_DSN: process.env.SENTRY_DSN,
      SMTP_PASSWORD: process.env.SMTP_PASSWORD,
    };

    validateSecrets(secrets, 'development');

    startupLogger.info('✅ Secrets loaded from .env file');

    return secrets;
  } catch (error) {
    startupLogger.error('Failed to load .env file', error);
    throw error;
  }
}

/**
 * Load mock secrets for testing
 * @returns {Object} Mock secrets
 */
function loadMockSecrets() {
  startupLogger.info('Using mock secrets for testing');

  return {
    JWT_SECRET: 'test-secret-key-do-not-use-in-production-' + Math.random(),
    DB_PASSWORD: 'test-db-password',
    API_KEY: 'test-api-key',
    SENTRY_DSN: 'https://test@sentry.io/test',
    SMTP_PASSWORD: 'test-smtp-password',
  };
}

/**
 * Validate that all required secrets are present and valid
 * @param {Object} secrets - Secrets object
 * @param {string} environment - Current environment
 */
function validateSecrets(secrets, environment) {
  const required = ['JWT_SECRET', 'DB_PASSWORD', 'API_KEY'];

  for (const key of required) {
    if (!secrets[key]) {
      throw new Error(`FATAL: Required secret missing: ${key}`);
    }

    if (typeof secrets[key] !== 'string') {
      throw new Error(`FATAL: Secret ${key} must be a string`);
    }

    if (secrets[key].length === 0) {
      throw new Error(`FATAL: Secret ${key} cannot be empty`);
    }
  }

  // Production-specific validation
  if (environment === 'production') {
    if (secrets.JWT_SECRET.length < 32) {
      throw new Error('FATAL: JWT_SECRET must be at least 32 characters in production');
    }

    if (secrets.JWT_SECRET.includes('test-') || secrets.JWT_SECRET.includes('dev-')) {
      throw new Error('FATAL: Cannot use development secrets in production');
    }
  }

  startupLogger.info(`✅ All ${required.length} required secrets validated`);
}

/**
 * Setup secret rotation (optional)
 * For long-running processes, periodically refresh secrets
 */
function setupSecretRotation(rotationIntervalHours = 24) {
  const intervalMs = rotationIntervalHours * 60 * 60 * 1000;

  setInterval(async () => {
    try {
      const newSecrets = await loadSecrets();

      // Update process.env with new secrets
      Object.assign(process.env, newSecrets);

      startupLogger.info('✅ Secrets rotated successfully');
    } catch (error) {
      startupLogger.error('Failed to rotate secrets', error);
      // Don't exit - keep using old secrets
      // Alert should be triggered instead
    }
  }, intervalMs);

  startupLogger.info(`Secret rotation scheduled every ${rotationIntervalHours} hours`);
}

/**
 * Setup monitoring for secret access failures
 */
function setupSecretAccessMonitoring() {
  process.on('uncaughtException', (error) => {
    if (error.message && error.message.includes('JWT_SECRET')) {
      startupLogger.error('🚨 ALERT: Possible secret access failure', error);
      // Send alert to monitoring system
    }
  });
}

/**
 * Export secrets as read-only object
 * Prevents accidental modification
 */
function createImmutableSecrets(secrets) {
  return Object.freeze({
    JWT_SECRET: secrets.JWT_SECRET,
    DB_PASSWORD: secrets.DB_PASSWORD,
    API_KEY: secrets.API_KEY,
    SENTRY_DSN: secrets.SENTRY_DSN,
    SMTP_PASSWORD: secrets.SMTP_PASSWORD,

    // Prevent modification
    [Symbol.setPrototypeOf]: undefined,
  });
}

// Export for use in app
module.exports = {
  loadSecrets,
  loadSecretsFromAWS,
  loadSecretsFromDotenv,
  loadMockSecrets,
  validateSecrets,
  setupSecretRotation,
  setupSecretAccessMonitoring,
  createImmutableSecrets,
};
