      // Update process.env with new secrets
      Object.assign(process.env, newSecrets);

      startupLogger.info('✅ Secrets rotated successfully');
    } catch (error) {
      startupLogger.error('Failed to rotate secrets', error);
      // Don't exit - keep using old secrets
      // Alert should be triggered instead
    }
  }, intervalMs);

  startupLogger.info(`Secret rotation scheduled every ${rotationIntervalHours} hours`);
}

/**
 * Setup monitoring for secret access failures
 */
function setupSecretAccessMonitoring() {
  process.on('uncaughtException', (error) => {
    if (error.message && error.message.includes('JWT_SECRET')) {
      startupLogger.error('🚨 ALERT: Possible secret access failure', error);
      // Send alert to monitoring system
    }
  });
}

/**
 * Export secrets as read-only object
 * Prevents accidental modification
 */
function createImmutableSecrets(secrets) {
  return Object.freeze({
    JWT_SECRET: secrets.JWT_SECRET,
    DB_PASSWORD: secrets.DB_PASSWORD,
    API_KEY: secrets.API_KEY,
    SENTRY_DSN: secrets.SENTRY_DSN,
    SMTP_PASSWORD: secrets.SMTP_PASSWORD,

    // Prevent modification
    [Symbol.setPrototypeOf]: undefined,
  });
}

// Export for use in app
module.exports = {
  loadSecrets,
  loadSecretsFromAWS,
  loadSecretsFromDotenv,
  loadMockSecrets,
  validateSecrets,
  setupSecretRotation,
  setupSecretAccessMonitoring,
  createImmutableSecrets,
};

