# Security Review of app.js

## Executive Summary
This application is a basic Express.js server with minimal functionality. While the current code is relatively simple, there are several security best practices that should be implemented to make it production-ready. Below is a detailed analysis of potential vulnerabilities and recommendations.

---

## OWASP Top 10 & Vulnerability Analysis

### 1. **MISSING SECURITY HEADERS** ⚠️ HIGH PRIORITY
**Issue:** No security headers are configured.

**Risk:** The application is vulnerable to:
- Clickjacking attacks
- XSS vulnerabilities
- MIME type sniffing
- Missing HTTPS enforcement

**Current Code:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Recommended Fix:**
```javascript
const helmet = require('helmet');
const express = require('express');
const app = express();

// Apply security headers middleware
app.use(helmet());

// Additional HSTS configuration
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

---

### 2. **MISSING INPUT VALIDATION** ⚠️ HIGH PRIORITY
**Issue:** No query parameters, path parameters, or request body validation.

**Risk:** 
- Query injection attacks
- Unexpected behavior from malformed requests
- Information disclosure

**Vulnerable Pattern:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
// What if someone sends: /users?malicious_param=<script>alert('xss')</script>
```

**Recommended Fix:**
```javascript
const { query, validationResult } = require('express-validator');

// Validate query parameters
app.get('/users', 
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);
```

---

### 3. **MISSING AUTHENTICATION & AUTHORIZATION** ⚠️ CRITICAL (if sensitive data)
**Issue:** All endpoints are publicly accessible without any authentication.

**Risk:**
- Unauthorized access to user data
- No accountability for API calls
- Data exposure

**Recommended Fix:**
```javascript
const jwt = require('jsonwebtoken');

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Protected route
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 4. **MISSING RATE LIMITING** ⚠️ MEDIUM PRIORITY
**Issue:** No rate limiting protection against brute force or DoS attacks.

**Risk:**
- Brute force attacks on authentication endpoints
- Denial of service (DoS)
- Resource exhaustion

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');

// Create different rate limiters for different purposes
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5, // Limit each IP to 5 requests per hour
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true,
});

// Apply rate limiting
app.use(generalLimiter);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([...]);
});
```

---

### 5. **NO LOGGING & MONITORING** ⚠️ MEDIUM PRIORITY
**Issue:** No request logging or security event monitoring.

**Risk:**
- Cannot detect or investigate security incidents
- No audit trail for compliance
- Difficult troubleshooting

**Recommended Fix:**
```javascript
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Create a write stream for logging
const accessLogStream = fs.createWriteStream(
  path.join(__dirname, 'logs', 'access.log'),
  { flags: 'a' }
);

// Use morgan for HTTP request logging
app.use(morgan('combined', { stream: accessLogStream }));

// Custom security event logger
const logger = {
  logSecurityEvent: (event, details) => {
    const timestamp = new Date().toISOString();
    console.log(`[SECURITY] ${timestamp} - ${event}:`, details);
  }
};

app.get('/users', (req, res) => {
  logger.logSecurityEvent('USER_LIST_ACCESSED', { 
    ip: req.ip, 
    user: req.user 
  });
  res.json([...]);
});
```

---

### 6. **MISSING CORS CONFIGURATION** ⚠️ MEDIUM PRIORITY
**Issue:** No CORS (Cross-Origin Resource Sharing) policy defined.

**Risk:**
- Unintended cross-origin requests
- Potential for CSRF attacks
- Unauthorized API consumption

**Recommended Fix:**
```javascript
const cors = require('cors');

// Configure CORS with whitelist
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};

app.use(cors(corsOptions));
```

---

### 7. **UNENCRYPTED SENSITIVE DATA** ⚠️ HIGH PRIORITY
**Issue:** User emails are returned in plaintext without encryption consideration.

**Risk:**
- Email addresses exposed if database is compromised
- Privacy violations (GDPR, CCPA)

**Recommended Fix:**
```javascript
const crypto = require('crypto');

app.get('/users', authenticateToken, (req, res) => {
  // Only expose email to authorized users
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter sensitive data based on authorization
  const filteredUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    // Only include email for authenticated admin users
    ...(req.user?.role === 'admin' && { email: user.email })
  }));

  res.json(filteredUsers);
});
```

---

### 8. **NO ERROR HANDLING** ⚠️ MEDIUM PRIORITY
**Issue:** No centralized error handling or try-catch blocks.

**Risk:**
- Information disclosure through stack traces
- Unhandled exceptions crash the application
- Poor user experience

**Recommended Fix:**
```javascript
// Global error handling middleware
app.use((err, req, res, next) => {
  logger.logSecurityEvent('ERROR', { 
    message: err.message, 
    ip: req.ip,
    path: req.path 
  });

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

### 9. **NO DEPENDENCY VULNERABILITY SCANNING** ⚠️ MEDIUM PRIORITY
**Issue:** No verification that dependencies are secure.

**Risk:**
- Known vulnerabilities in dependencies
- Supply chain attacks

**Recommended Fix:**
```bash
# Add to package.json scripts
npm audit
npm audit fix
npm install --save snyk
npx snyk test
```

---

### 10. **MISSING ENVIRONMENT CONFIGURATION** ⚠️ HIGH PRIORITY
**Issue:** Hardcoded values and no environment-based configuration.

**Risk:**
- Secrets exposed in version control
- Configuration not separated by environment
- Port exposed directly in code

**Recommended Fix:**
```javascript
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const app = express();

// Use environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const ACCESS_TOKEN_SECRET = process.env.ACCESS_TOKEN_SECRET;

if (!ACCESS_TOKEN_SECRET) {
  console.error('ERROR: ACCESS_TOKEN_SECRET is not set');
  process.exit(1);
}

app.use(helmet());

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV 
  });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

**.env file (NEVER commit this to git):**
```
PORT=3000
NODE_ENV=development
ACCESS_TOKEN_SECRET=your_secret_key_here
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:3001
```

**.gitignore (ensure .env is ignored):**
```
.env
.env.local
.env.*.local
node_modules/
logs/
```

---

## Recommended package.json Dependencies

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^7.0.0",
    "express-validator": "^7.0.0",
    "cors": "^2.8.5",
    "morgan": "^1.10.0",
    "jsonwebtoken": "^9.0.0",
    "dotenv": "^16.0.0"
  },
  "devDependencies": {
    "nodemon": "^3.0.0"
  }
}
```

---

## Complete Secure Example

See `app_secure.js` for a complete implementation with all recommendations applied.

---

## Security Checklist

- [ ] Install `helmet` for security headers
- [ ] Add input validation with `express-validator`
- [ ] Implement JWT authentication
- [ ] Add rate limiting
- [ ] Set up logging with Morgan
- [ ] Configure CORS properly
- [ ] Add error handling middleware
- [ ] Use environment variables (.env)
- [ ] Run `npm audit` and fix vulnerabilities
- [ ] Use HTTPS in production
- [ ] Set secure cookie flags (if using cookies)
- [ ] Implement CSP (Content Security Policy)
- [ ] Regular security audits and dependency updates
- [ ] Add API documentation with security notes
- [ ] Implement request/response validation
- [ ] Set up monitoring and alerting

---

## Deployment Recommendations

1. **Use HTTPS Only**: Install SSL/TLS certificates
2. **Run Behind Reverse Proxy**: Use nginx/HAProxy
3. **Container Security**: Use secure Docker image
4. **CI/CD Security**: Scan images and dependencies
5. **WAF**: Consider Web Application Firewall
6. **DDoS Protection**: Use CDN or DDoS mitigation service
7. **Secrets Management**: Use AWS Secrets Manager, HashiCorp Vault
8. **Regular Updates**: Keep dependencies updated
9. **Penetration Testing**: Conduct regular security testing

/**
 * Secure Express Application
 * This file demonstrates best practices for security
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const fs = require('fs');
const path = require('path');

// ============================================================================
// CONFIGURATION
// ============================================================================

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const ACCESS_TOKEN_SECRET = process.env.ACCESS_TOKEN_SECRET;

// Validate required environment variables
if (!ACCESS_TOKEN_SECRET) {
  console.error('ERROR: ACCESS_TOKEN_SECRET is not set in environment');
  process.exit(1);
}

// ============================================================================
// LOGGING SETUP
// ============================================================================

// Create logs directory if it doesn't exist
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

const errorLogger = (event, details) => {
  const timestamp = new Date().toISOString();
  const logMessage = `[${timestamp}] ${event}: ${JSON.stringify(details)}\n`;
  fs.appendFileSync(path.join(logsDir, 'security.log'), logMessage);
};

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));

// 2. CORS configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// 3. HTTP request logging
app.use(morgan('combined', { stream: accessLogStream }));

// 4. Body parser middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 5. HTTPS redirect (in production)
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// 6. Rate limiting - General
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV !== 'production', // Disabled in development
});

// 7. Rate limiting - Authentication
const authLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5,
  message: 'Too many authentication attempts, please try again later.',
  skipSuccessfulRequests: true,
});

app.use(generalLimiter);

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    errorLogger('UNAUTHORIZED_ACCESS', { path: req.path, ip: req.ip });
    return res.status(401).json({ 
      error: 'Access token required',
      code: 'MISSING_TOKEN'
    });
  }

  jwt.verify(token, ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      errorLogger('INVALID_TOKEN', { path: req.path, ip: req.ip, error: err.message });
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        code: 'INVALID_TOKEN'
      });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check (no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime(),
  });
});

// Authentication endpoint
app.post('/auth/login', authLimiter, (req, res) => {
  try {
    const { username, password } = req.body;

    // Input validation
    if (!username || !password) {
      return res.status(400).json({ 
        error: 'Username and password required',
        code: 'MISSING_CREDENTIALS'
      });
    }

    // In production, validate against database with bcrypt
    // This is a simple mock example
    if (username === 'demo' && password === 'password') {
      const token = jwt.sign(
        { id: 1, username, role: 'user' },
        ACCESS_TOKEN_SECRET,
        { expiresIn: '1h' }
      );

      errorLogger('USER_LOGIN_SUCCESS', { username, ip: req.ip });
      return res.json({ token, expiresIn: '1h' });
    }

    errorLogger('LOGIN_FAILED', { username, ip: req.ip });
    res.status(401).json({ 
      error: 'Invalid credentials',
      code: 'INVALID_CREDENTIALS'
    });
  } catch (err) {
    errorLogger('LOGIN_ERROR', { error: err.message, ip: req.ip });
    res.status(500).json({ 
      error: 'Authentication error',
      code: 'AUTH_ERROR'
    });
  }
});

// Protected endpoint - Get users
app.get('/users',
  authenticateToken,
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    try {
      // Validate query parameters
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array(),
          code: 'VALIDATION_ERROR'
        });
      }

      const page = req.query.page || 1;
      const limit = req.query.limit || 10;

      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com', created_at: '2024-01-01' },
        { id: 2, name: 'Bob', email: 'bob@example.com', created_at: '2024-01-02' },
      ];

      // Filter sensitive data based on authorization
      const users = allUsers.map(user => {
        const userData = {
          id: user.id,
          name: user.name,
        };

        // Only admin users can see emails
        if (req.user?.role === 'admin') {
          userData.email = user.email;
        }

        return userData;
      });

      // Pagination
      const start = (page - 1) * limit;
      const paginatedUsers = users.slice(start, start + limit);

      errorLogger('USERS_LIST_ACCESSED', { 
        user: req.user?.username,
        ip: req.ip,
        page,
        limit,
        returned: paginatedUsers.length
      });

      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          pages: Math.ceil(users.length / limit),
        }
      });
    } catch (err) {
      errorLogger('GET_USERS_ERROR', { error: err.message, user: req.user?.username });
      res.status(500).json({ 
        error: NODE_ENV === 'production' ? 'Internal server error' : err.message,
        code: 'SERVER_ERROR'
      });
    }
  }
);

// Protected endpoint - Get single user (with parameter validation)
app.get('/users/:id',
  authenticateToken,
  (req, res) => {
    try {
      const { id } = req.params;

      // Input validation
      if (!/^\d+$/.test(id)) {
        return res.status(400).json({ 
          error: 'Invalid user ID format',
          code: 'INVALID_ID'
        });
      }

      const userId = parseInt(id, 10);

      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = allUsers.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found',
          code: 'NOT_FOUND'
        });
      }

      // Filter sensitive data
      const userData = { id: user.id, name: user.name };
      if (req.user?.role === 'admin' || req.user?.id === userId) {
        userData.email = user.email;
      }

      errorLogger('USER_ACCESSED', { 
        userId,
        requestingUser: req.user?.username,
        ip: req.ip
      });

      res.json(userData);
    } catch (err) {
      errorLogger('GET_USER_ERROR', { error: err.message, user: req.user?.username });
      res.status(500).json({ 
        error: NODE_ENV === 'production' ? 'Internal server error' : err.message,
        code: 'SERVER_ERROR'
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  errorLogger('ROUTE_NOT_FOUND', { path: req.path, method: req.method, ip: req.ip });
  res.status(404).json({ 
    error: 'Not found',
    code: 'NOT_FOUND',
    path: req.path
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  errorLogger('UNHANDLED_ERROR', { 
    message: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    ip: req.ip
  });

  const isDevelopment = NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      code: err.code || 'INTERNAL_ERROR',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`✓ Server running on port ${PORT}`);
  console.log(`✓ Environment: ${NODE_ENV}`);
  console.log(`✓ Logs directory: ${logsDir}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

