     res.json([
       { id: 1, name: 'Alice', email: 'alice@example.com' },
       { id: 2, name: 'Bob', email: 'bob@example.com' },
     ]);
   });
   ```

   RISK: 
   - Sensitive user data (names, emails) is exposed to anyone without access control
   - No session management or user verification
   - Violates principle of least privilege

   RECOMMENDED FIX:
   ```javascript
   const jwt = require('jsonwebtoken');

   // Middleware to verify JWT token
   const authenticateToken = (req, res, next) => {
     const authHeader = req.headers['authorization'];
     const token = authHeader && authHeader.split(' ')[1];

     if (!token) {
       return res.status(401).json({ error: 'Access token required' });
     }

     jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
       if (err) return res.status(403).json({ error: 'Invalid token' });
       req.user = user;
       next();
     });
   };

   app.get('/users', authenticateToken, (req, res) => {
     res.json([
       { id: 1, name: 'Alice', email: 'alice@example.com' },
       { id: 2, name: 'Bob', email: 'bob@example.com' },
     ]);
   });
   ```

================================================================================
2. SENSITIVE DATA EXPOSURE (OWASP A02:2021 - Cryptographic Failures)
   ---
   ISSUE: User data returned without encryption or data protection

   Location: /users endpoint response

   RISK:
   - Email addresses exposed without protection
   - User IDs sequential (predictable enumeration attack)
   - No HTTPS enforcement mentioned
   - Data sent in plaintext over HTTP
   - User-Identifiable Information (PII) exposed

   RECOMMENDED FIX:
   ```javascript
   const helmet = require('helmet');
   const rateLimit = require('express-rate-limit');

   // Enable security headers
   app.use(helmet());

   // Enforce HTTPS
   app.use((req, res, next) => {
     if (req.header('x-forwarded-proto') !== 'https') {
       res.redirect(`https://${req.header('host')}${req.url}`);
     } else {
       next();
     }
   });

   // Don't expose sensitive fields in responses
   app.get('/users', authenticateToken, (req, res) => {
     // Only return necessary fields, mask or exclude sensitive data
     res.json([
       { id: 'usr_1', name: 'Alice' }, // No email, hashed/masked ID
       { id: 'usr_2', name: 'Bob' },
