/**
 * SECURE APPLICATION EXAMPLE
 * This demonstrates the fixes for all identified vulnerabilities
 */

const express = require('express');
const jwt = require('jsonwebtoken');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// MIDDLEWARE - SECURITY & PARSING
// ============================================================================

// 1. Security headers via Helmet
app.use(helmet());

// 2. Custom HTTPS enforcement (for production)
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production') {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
  }
  next();
});

// 3. CORS Configuration
const corsOptions = {
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || 
                           ['http://localhost:3000'];

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 3600,
};

app.use(cors(corsOptions));

// 4. Body parser with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: false }));

// 5. Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });
  next();
});

// ============================================================================
// RATE LIMITING
// ============================================================================

const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => process.env.NODE_ENV === 'development', // Skip in dev
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 requests per 15 minutes for auth endpoints
  skipSuccessfulRequests: true, // Don't count successful attempts
  message: 'Too many authentication attempts, please try again later.',
});

app.use(globalLimiter);

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      event: 'missing_auth_token',
      path: req.path,
      ip: req.ip,
    });
    return res.status(401).json({ 
      error: 'Access token required',
      code: 'MISSING_TOKEN',
    });
  }

  try {
    const user = jwt.verify(token, process.env.ACCESS_TOKEN_SECRET);
    req.user = user;
    next();
  } catch (err) {
    logger.warn({
      event: 'invalid_auth_token',
      path: req.path,
      ip: req.ip,
      error: err.message,
    });
    return res.status(403).json({ 
      error: 'Invalid or expired token',
      code: 'INVALID_TOKEN',
    });
  }
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint - no auth required
 * Safe for load balancers and monitoring
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0',
  });
});

/**
 * GET /users - Retrieve user list with validation and auth
 * 
 * Query parameters:
 *   - limit: (1-100) Number of results (default: 10)
 *   - offset: (>=0) Pagination offset (default: 0)
 */
app.get('/users',
  authenticateToken,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be >= 0')
    .toInt(),
  (req, res, next) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    try {
      const limit = req.query.limit || 10;
      const offset = req.query.offset || 0;

      // Log data access
      logger.info({
        event: 'users_accessed',
        userId: req.user.id,
        limit,
        offset,
      });

      // Return minimal user data (no PII exposure)
      // In production, fetch from database with proper permissions
      const users = [
        { id: 'usr_1', name: 'Alice' },
        { id: 'usr_2', name: 'Bob' },
      ];

      res.json({
        data: users.slice(offset, offset + limit),
        pagination: {
          limit,
          offset,
          total: users.length,
        },
      });
    } catch (err) {
      next(err);
    }
  }
);

/**
 * POST /auth/login - Authentication endpoint
 * Input validation required
 */
app.post('/auth/login',
  authLimiter,
  query('username')
    .trim()
    .isLength({ min: 3, max: 30 })
    .withMessage('Username must be 3-30 characters')
    .matches(/^[a-zA-Z0-9_-]+$/)
    .withMessage('Username can only contain alphanumeric characters, -, and _'),
  query('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        event: 'login_validation_failed',
        ip: req.ip,
        details: errors.array(),
      });
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    try {
      // This is a placeholder - in production:
      // 1. Verify credentials against database
      // 2. Use bcrypt for password comparison
      // 3. Implement MFA
      // 4. Check account status/locks

      const { username } = req.query;

      // Generate JWT token
      const token = jwt.sign(
        { id: username, iat: Math.floor(Date.now() / 1000) },
        process.env.ACCESS_TOKEN_SECRET,
        { expiresIn: '1h' }
      );

      logger.info({
        event: 'login_success',
        username,
        ip: req.ip,
      });

      res.json({
        token,
        expiresIn: 3600,
        type: 'Bearer',
      });
    } catch (err) {
      next(err);
    }
  }
);

// ============================================================================
// 404 HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
  });
});

// ============================================================================
// GLOBAL ERROR HANDLER (must be last)
// ============================================================================

app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't expose internal error details in production
  const statusCode = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    error: message,
    code: err.code || 'INTERNAL_ERROR',
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Validate required environment variables
const requiredEnvVars = ['ACCESS_TOKEN_SECRET'];
for (const envVar of requiredEnvVars) {
  if (!process.env[envVar]) {
    logger.error(`Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
}

const server = app.listen(PORT, HOST, () => {
  logger.info(`Server running on ${HOST}:${PORT} (${process.env.NODE_ENV || 'development'})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

