/**
 * Secure Secrets Manager - Abstracts secrets retrieval based on environment
 * Supports: .env (development), AWS Secrets Manager (production), Vault, Azure Key Vault
 */

class SecretsManager {
  static instance = null;
  static backend = null;

  /**
   * Get or initialize the secrets manager
   */
  static async getInstance() {
    if (this.instance) return this.instance;

    const env = process.env.NODE_ENV || 'development';

    try {
      if (env === 'production') {
        // Determine which backend to use
        if (process.env.USE_VAULT === 'true') {
          this.backend = new VaultSecretsBackend();
        } else if (process.env.USE_AZURE_KEYVAULT === 'true') {
          this.backend = new AzureKeyVaultBackend();
        } else {
          // Default to AWS Secrets Manager for production
          this.backend = new AWSSecretsManagerBackend();
        }
      } else {
        // Use environment variables for development
        this.backend = new DotenvSecretsBackend();
      }

      await this.backend.initialize();
      this.instance = this;
      return this.instance;
    } catch (error) {
      console.error('❌ Failed to initialize secrets manager:', error);
      throw error;
    }
  }

  /**
   * Retrieve a secret by name/path
   * @param {string} secretName - Name of the secret to retrieve
   * @returns {Promise<object>} - The secret value
   */
  static async getSecret(secretName) {
    if (!this.backend) {
      await this.getInstance();
    }

    console.log(`📂 Retrieving secret: ${secretName} from ${this.backend.constructor.name}`);
    return this.backend.getSecret(secretName);
  }

  /**
   * Retrieve multiple secrets
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<object>} - Object with all secrets
   */
  static async getSecrets(secretNames) {
    const secrets = {};
    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }
    return secrets;
  }

  /**
   * Get secret with fallback value
   * @param {string} secretName - Name of the secret
   * @param {*} fallback - Fallback value if secret not found
   * @returns {Promise<*>}
   */
  static async getSecretOrDefault(secretName, fallback) {
    try {
      return await this.getSecret(secretName);
    } catch (error) {
      console.warn(`⚠️  Secret '${secretName}' not found, using fallback`);
      return fallback;
    }
  }
}

/**
 * AWS Secrets Manager Backend
 */
class AWSSecretsManagerBackend {
  constructor() {
    this.client = null;
  }

  async initialize() {
    // Install: npm install @aws-sdk/client-secrets-manager
    const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    console.log(`✅ AWS Secrets Manager initialized (region: ${process.env.AWS_REGION || 'us-east-1'})`);
  }

  async getSecret(secretName) {
    try {
      const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      if ('SecretString' in response) {
        return JSON.parse(response.SecretString);
      } else if ('SecretBinary' in response) {
        const buff = Buffer.from(response.SecretBinary, 'base64');
        return buff.toString('ascii');
      }
    } catch (error) {
      console.error(`❌ Error retrieving secret ${secretName} from AWS:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }
}

/**
 * HashiCorp Vault Backend
 */
class VaultSecretsBackend {
  constructor() {
    this.vault = null;
  }

  async initialize() {
    // Install: npm install node-vault
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN,
      apiVersion: 'v1'
    });

    this.vault = vault;

    // Test connection
    try {
      await this.vault.health();
      console.log(`✅ HashiCorp Vault initialized (${process.env.VAULT_ADDR})`);
    } catch (error) {
      throw new Error(`Failed to connect to Vault: ${error.message}`);
    }
  }

  async getSecret(secretPath) {
    try {
      const response = await this.vault.read(secretPath);
      return response.data.data || response.data;
    } catch (error) {
      console.error(`❌ Error retrieving secret ${secretPath} from Vault:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretPath}`);
    }
  }
}

/**
 * Azure Key Vault Backend
 */
class AzureKeyVaultBackend {
  constructor() {
    this.client = null;
  }

  async initialize() {
    // Install: npm install @azure/identity @azure/keyvault-secrets
    const { DefaultAzureCredential } = require('@azure/identity');
    const { SecretClient } = require('@azure/keyvault-secrets');

    const credential = new DefaultAzureCredential();
