      const secret = await this.client.getSecret(secretName);
      return secret.value;
    } catch (error) {
      console.error(`❌ Error retrieving secret ${secretName} from Azure Key Vault:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }
}

/**
 * Dotenv Backend (Development only)
 */
class DotenvSecretsBackend {
  async initialize() {
    // Install: npm install dotenv
    require('dotenv').config();

    // Verify required secrets are present
    const requiredSecrets = (process.env.REQUIRED_SECRETS || '').split(',').filter(s => s);
    const missing = requiredSecrets.filter(s => !process.env[s]);

    if (missing.length > 0) {
      console.warn(`⚠️  Missing environment variables: ${missing.join(', ')}`);
      console.warn(`    Update your .env file or set these as environment variables`);
    }

    console.log('✅ Environment variables loaded from .env (Development mode)');
  }

  async getSecret(secretName) {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Environment variable ${secretName} not found`);
    }
    return value;
  }
}

