        anthropic: { configured: !!config.services.anthropic?.apiKey },
        aws: { configured: !!config.services.aws?.accessKeyId }
      }
    });
  });

  return app;
}

/**
 * Start the application
 */
async function start() {
  try {
    // Initialize secrets and config
