```javascript
// config/secrets.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

const cache = new Map();
const CACHE_TTL = 3600000; // 1 hour

async function getSecret(secretName) {
  // Check cache first
  if (cache.has(secretName)) {
    const { value, timestamp } = cache.get(secretName);
    if (Date.now() - timestamp < CACHE_TTL) {
      return value;
    }
    cache.delete(secretName);
  }

  try {
    const secretValue = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    let secret;
    if ('SecretString' in secretValue) {
      secret = JSON.parse(secretValue.SecretString);
    } else {
      secret = Buffer.from(secretValue.SecretBinary, 'base64').toString('ascii');
    }

    // Cache the secret
    cache.set(secretName, {
      value: secret,
      timestamp: Date.now()
    });

    return secret;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw error;
  }
}

async function initializeSecrets() {
  const secrets = [
    'prod/database/url',
    'prod/aws/credentials',
    'prod/stripe/key',
    'prod/anthropic/key',
    'prod/logfire/token'
  ];

