      const secretValue = await this.secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secret;
      if ('SecretString' in secretValue) {
        secret = JSON.parse(secretValue.SecretString);
      } else {
        // Binary secret
        secret = Buffer.from(secretValue.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      console.log(`[AWS] Successfully cached ${secretName}`);
      return secret;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret ${secretName}:`, error.message);
      throw error;
    }
  }

  /**
   * Clear all cached secrets
   */
  clearCache() {
    this.cache.clear();
    console.log('[INFO] Cleared secrets cache');
  }
}

