  anthropic: null,
  jwt: null
};

/**
 * Initialize application secrets on startup
 * Fails fast if any required secret is missing
 */
async function initializeSecrets() {
  console.log('[STARTUP] Initializing secrets...');

  const requiredSecrets = [
    { key: 'database', path: 'prod/database/url' },
    { key: 'stripe', path: 'prod/stripe/key' },
    { key: 'anthropic', path: 'prod/anthropic/key' },
    { key: 'jwt', path: 'prod/jwt/secret' }
  ];

  for (const { key, path } of requiredSecrets) {
    try {
      secrets[key] = await secretsManager.getSecret(path);
      console.log(`✓ Loaded secret: ${key}`);
    } catch (error) {
      console.error(`✗ Failed to load required secret: ${key}`);
      console.error(`  Path: ${path}`);
      console.error(`  Error: ${error.message}`);
      process.exit(1);
    }
  }

  console.log('[STARTUP] All secrets initialized successfully');
}

// ============================================================================
// MIDDLEWARE
// ============================================================================

/**
 * Validate that secrets are loaded before handling requests
 */
function ensureSecretsLoaded(req, res, next) {
  if (!secrets.database || !secrets.jwt) {
    return res.status(503).json({
      error: 'Service unavailable: secrets not initialized'
    });
  }
  next();
}

/**
 * Add security headers
 */
function addSecurityHeaders(req, res, next) {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.removeHeader('X-Powered-By');
  next();
}

/**
 * Log secret access attempts (with security considerations)
 */
function logSecretAccess(action, success) {
  return (req, res, next) => {
    res.on('finish', () => {
      // Log successful secret access, but never log the actual secrets
      if (success) {
        console.log(JSON.stringify({
          timestamp: new Date().toISOString(),
          action,
          status: res.statusCode,
          ip: req.ip,
          path: req.path
        }));
      }
    });
    next();
  };
}

