app.use(helmet());

// Rate Limiting - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// CORS Configuration - Only allow trusted origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Middleware to validate and sanitize request data
const validateInput = (req, res, next) => {
  // Remove any potentially dangerous properties
  delete req.body.__proto__;
  delete req.body.constructor;
  delete req.body.prototype;
  next();
};
app.use(validateInput);

// Health check endpoint - No sensitive data
app.get('/health', (req, res) => {
  res.set('X-Content-Type-Options', 'nosniff');
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation and authentication
// Authentication middleware - MUST be implemented based on your auth strategy
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: 'Missing authorization header' });
  }

  // Validate Bearer token format
  const tokenMatch = authHeader.match(/^Bearer\s+([a-zA-Z0-9\-_]+)$/);
  if (!tokenMatch) {
    return res.status(401).json({ error: 'Invalid authorization format' });
  }

  // TODO: Validate token against your auth provider (JWT verification, etc.)
  // For now, just ensure it's present
  req.token = tokenMatch[1];
  next();
};

// GET /users - Protected endpoint with input validation
app.get('/users', authenticate, (req, res) => {
  try {
    // Validate query parameters
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

    // Validate input constraints
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter. Must be integer between 1 and 100.' 
      });
    }

