// security-tests.js - Jest tests for security vulnerabilities

const request = require('supertest');
const app = require('./app_secure');
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'test-secret-key';

// Generate valid test token
const generateToken = (payload = { userId: 1 }) => {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: '1h' });
};

describe('Security Tests', () => {

  // Test 1: Authentication Required
  describe('Authentication', () => {
    it('should reject requests without authentication', async () => {
      const response = await request(app)
        .get('/users')
        .expect(401);

      expect(response.body).toHaveProperty('error');
    });

    it('should reject malformed authorization header', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', 'InvalidFormat')
        .expect(401);

      expect(response.body.error).toMatch(/invalid/i);
    });

    it('should accept valid bearer token', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      expect(Array.isArray(response.body)).toBe(true);
    });

    it('should reject expired tokens', async () => {
      const expiredToken = jwt.sign(
        { userId: 1 },
        JWT_SECRET,
        { expiresIn: '-1h' }
      );

      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${expiredToken}`)
        .expect(401);

      expect(response.body).toHaveProperty('error');
    });
  });

  // Test 2: Security Headers
  describe('Security Headers', () => {
    it('should include Content-Security-Policy header', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/health')
        .set('Authorization', `Bearer ${token}`);

      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    it('should include X-Content-Type-Options header', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/health')
        .set('Authorization', `Bearer ${token}`);

      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    it('should set proper CORS headers for allowed origins', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });
  });

  // Test 3: Input Validation
  describe('Input Validation', () => {
    it('should reject invalid email format', async () => {
      const token = generateToken();
      const response = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .send({ name: 'Test', email: 'invalid-email' })
        .expect(400);

      expect(response.body).toHaveProperty('error');
    });

    it('should reject missing required fields', async () => {
      const token = generateToken();
      const response = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .send({ name: 'Test' })
        .expect(400);

      expect(response.body).toHaveProperty('error');
    });

    it('should reject name exceeding max length', async () => {
      const token = generateToken();
      const longName = 'a'.repeat(101);

      const response = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .send({ name: longName, email: 'test@example.com' })
        .expect(400);

      expect(response.body.error).toMatch(/too long/i);
    });

    it('should sanitize and escape input', async () => {
      const token = generateToken();
      const response = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .send({ 
          name: '<script>alert("xss")</script>',
          email: 'test@example.com' 
        })
        .expect(201);

      // Should be escaped
      expect(response.body.name).not.toMatch(/<script>/);
    });

    it('should normalize email addresses', async () => {
      const token = generateToken();
      const response = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .send({ 
          name: 'Test User',
          email: 'TEST@EXAMPLE.COM' 
        })
        .expect(201);

      expect(response.body.email).toBe('test@example.com');
    });
  });

  // Test 4: Rate Limiting
  describe('Rate Limiting', () => {
    it('should enforce rate limits', async () => {
      // Note: This would need to be configured properly for testing
      // Simplified example - actual test would need timing
      const response = await request(app).get('/health');
      expect(response.status).toBeLessThan(429);
    });
  });

  // Test 5: Error Handling
  describe('Error Handling', () => {
    it('should not expose stack traces', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/nonexistent')
        .set('Authorization', `Bearer ${token}`)
        .expect(404);

      expect(response.body).not.toHaveProperty('stack');
    });

    it('should return generic error on 500', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      // Successful response shouldn't contain error details
      expect(response.body).not.toHaveProperty('stack');
    });

    it('should not expose internal server details', async () => {
      const response = await request(app)
        .get('/health');

      // Should not leak Express version
      expect(response.headers['x-powered-by']).toBeUndefined();
    });
  });

  // Test 6: NoSQL Injection Prevention
  describe('NoSQL Injection Prevention', () => {
    it('should sanitize query parameters', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/users?name[$ne]=')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      // Should handle gracefully without injection
      expect(Array.isArray(response.body)).toBe(true);
    });

    it('should prevent prototype pollution', async () => {
      const token = generateToken();
      const response = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .send({ 
          name: 'Test',
          email: 'test@example.com',
          '__proto__': { 'isAdmin': true },
          'constructor': { 'prototype': { 'isAdmin': true } }
        })
        .expect(201);

      // Should not allow property injection
      expect(response.body.isAdmin).toBeUndefined();
    });
  });

  // Test 7: Pagination Input Validation
  describe('Pagination', () => {
    it('should reject invalid limit parameter', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/users?limit=abc')
        .set('Authorization', `Bearer ${token}`)
        .expect(400);

      expect(response.body).toHaveProperty('error');
    });

    it('should reject limit exceeding max', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/users?limit=1000')
        .set('Authorization', `Bearer ${token}`)
        .expect(400);

      expect(response.body.error).toMatch(/100/);
    });

    it('should reject negative offset', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/users?offset=-1')
        .set('Authorization', `Bearer ${token}`)
        .expect(400);

      expect(response.body).toHaveProperty('error');
    });

    it('should accept valid pagination parameters', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/users?limit=10&offset=0')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      expect(Array.isArray(response.body)).toBe(true);
    });
  });

  // Test 8: Data Exposure
  describe('Data Exposure Prevention', () => {
    it('should not expose sensitive fields', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      response.body.forEach(user => {
        expect(user).not.toHaveProperty('passwordHash');
        expect(user).not.toHaveProperty('apiKey');
        expect(user).not.toHaveProperty('internalId');
      });
    });

    it('should include only safe fields in response', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      response.body.forEach(user => {
        expect(user).toHaveProperty('id');
        expect(user).toHaveProperty('name');
        expect(user).toHaveProperty('email');
        // Only 3 properties should be present
        expect(Object.keys(user).length).toBe(3);
      });
    });
  });

  // Test 9: Content-Type Validation
  describe('Content-Type Handling', () => {
    it('should handle JSON properly', async () => {
      const token = generateToken();
      const response = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .set('Content-Type', 'application/json')
        .send({ name: 'Test', email: 'test@example.com' })
        .expect(201);

      expect(response.body).toBeDefined();
    });

    it('should reject oversized payloads', async () => {
      const token = generateToken();
      const largePayload = 'a'.repeat(11 * 1024); // 11KB > 10KB limit

      const response = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .send({ name: largePayload, email: 'test@example.com' });

      expect(response.status).toBe(413);
    });
  });

  // Test 10: CORS Policy
  describe('CORS Policy', () => {
    it('should reject requests from untrusted origins', async () => {
      const token = generateToken();
      const response = await request(app)
        .get('/health')
        .set('Origin', 'https://malicious.com')
        .set('Authorization', `Bearer ${token}`);

      // Should not include malicious origin in CORS headers
      expect(response.headers['access-control-allow-origin']).not.toBe('https://malicious.com');
    });
  });
});

