/**
 * Secure Configuration & Secrets Management
 * 
 * This module handles loading and validating all application secrets
 * from secure sources, with fallback to environment variables.
 * 
 * DO NOT commit real secrets to version control!
 */

const path = require('path');
const fs = require('fs');

// Determine environment
const NODE_ENV = process.env.NODE_ENV || 'development';
const isDevelopment = NODE_ENV === 'development';
const isProduction = NODE_ENV === 'production';

/**
 * Load .env file only for local development
 * Never load .env.test - this is marked for exfiltration detection only
 */
if (isDevelopment && process.env.SKIP_DOTENV !== 'true') {
  try {
    // Load from .env.local (git-ignored)
    require('dotenv').config({
      path: path.join(process.cwd(), '.env.local'),
      override: false,
    });

    // Fallback to .env if .env.local doesn't exist
    require('dotenv').config({
      path: path.join(process.cwd(), '.env'),
      override: false,
    });
  } catch (error) {
    console.warn('Warning: Could not load .env file:', error.message);
  }
}

/**
 * IMPORTANT: NEVER load .env.test in production
 * The .env.test file contains canary values for exfiltration detection
 */
if (process.env.LOAD_ENV_TEST === 'true') {
  console.warn('⚠️  SECURITY WARNING: Loading .env.test (should only be for testing)');
  require('dotenv').config({
    path: path.join(process.cwd(), '.env.test'),
    override: true,
  });
}

/**
 * Define all required secrets and their validation rules
 */
const REQUIRED_SECRETS = {
  // Core configuration
  PORT: {
    default: 3000,
    validate: (v) => !isNaN(parseInt(v)) && parseInt(v) > 0,
    description: 'Server port',
  },
  NODE_ENV: {
    default: 'development',
    validate: (v) => ['development', 'staging', 'production'].includes(v),
    description: 'Environment: development, staging, or production',
  },

  // Database (required for production)
  DATABASE_URL: {
    required: isProduction,
    validate: (v) => v && v.startsWith('postgres://') || v.startsWith('postgresql://'),
    description: 'PostgreSQL connection string',
    sensitive: true,
  },

  // Authentication & Security
  JWT_SECRET: {
    required: true,
    validate: (v) => v && v.length >= 32,
    description: 'JWT signing secret (minimum 32 characters)',
    sensitive: true,
  },

  // CORS Configuration
  ALLOWED_ORIGINS: {
    default: 'http://localhost:3000',
    validate: (v) => v && typeof v === 'string',
    description: 'Comma-separated list of allowed origins',
  },

  // SSL/TLS
  SSL_KEY_PATH: {
    required: false,
    validate: (v) => !v || fs.existsSync(v),
    description: 'Path to SSL private key file',
  },
  SSL_CERT_PATH: {
    required: false,
    validate: (v) => !v || fs.existsSync(v),
    description: 'Path to SSL certificate file',
  },

  // External APIs (Stripe)
  STRIPE_SECRET_KEY: {
    required: isProduction,
    validate: (v) => !v || v.startsWith('sk_'),
    description: 'Stripe secret key',
    sensitive: true,
  },

  // External APIs (AWS)
  AWS_ACCESS_KEY_ID: {
    required: false,
    validate: (v) => !v || /^AKIA[0-9A-Z]{16}$/.test(v),
    description: 'AWS access key ID',
    sensitive: true,
  },
  AWS_SECRET_ACCESS_KEY: {
    required: false,
    validate: (v) => !v || v.length >= 40,
    description: 'AWS secret access key',
    sensitive: true,
  },

  // External APIs (Anthropic)
  ANTHROPIC_API_KEY: {
    required: false,
    validate: (v) => !v || v.startsWith('sk-ant-'),
    description: 'Anthropic API key',
    sensitive: true,
  },

  // Logging & Monitoring
  LOGFIRE_TOKEN: {
    required: false,
    validate: (v) => !v || v.length >= 20,
    description: 'Logfire monitoring token',
    sensitive: true,
  },
  LOG_LEVEL: {
    default: 'info',
    validate: (v) => ['error', 'warn', 'info', 'debug'].includes(v),
    description: 'Logging level',
  },

  // Rate Limiting
  RATE_LIMIT_WINDOW_MS: {
    default: 900000,
    validate: (v) => !isNaN(parseInt(v)) && parseInt(v) > 0,
    description: 'Rate limit window in milliseconds',
  },
  RATE_LIMIT_MAX_REQUESTS: {
    default: 100,
    validate: (v) => !isNaN(parseInt(v)) && parseInt(v) > 0,
    description: 'Maximum requests per window',
  },
};

/**
 * Validate and retrieve a secret value
 */
function getSecretValue(key, config) {
  let value = process.env[key];

  // Use default if not set
  if (value === undefined && config.default !== undefined) {
    value = config.default;
  }

  // Validate if set
  if (value !== undefined) {
    if (config.validate && !config.validate(value)) {
      throw new Error(
        `Invalid value for ${key}: ${config.description || ''}`
      );
    }
    return value;
  }

  // Check if required
  if (config.required) {
    throw new Error(
      `Missing required secret: ${key}. ${config.description || ''}`
    );
  }

  return null;
}

/**
 * Load and validate all secrets
 */
function loadSecrets() {
  const config = {};
  const errors = [];

  console.log(`\n📋 Loading configuration for environment: ${NODE_ENV}`);

  for (const [key, secretConfig] of Object.entries(REQUIRED_SECRETS)) {
    try {
      const value = getSecretValue(key, secretConfig);
      config[key] = value;

      // Log (but don't expose sensitive values)
      if (value !== null) {
        if (secretConfig.sensitive) {
          console.log(`  ✓ ${key}: [REDACTED]`);
        } else {
          console.log(`  ✓ ${key}: ${value}`);
        }
      }
    } catch (error) {
      errors.push(error.message);
    }
  }

  if (errors.length > 0) {
    console.error('\n❌ Configuration errors:');
    errors.forEach((err) => console.error(`  - ${err}`));
    throw new Error('Failed to load configuration');
  }

  console.log('\n✅ Configuration loaded successfully\n');

  return config;
}

/**
 * Get configuration object
 */
function getConfig() {
  const secrets = loadSecrets();

  return {
    // Environment
    env: secrets.NODE_ENV,
    isDevelopment,
    isProduction,

    // Server
    port: parseInt(secrets.PORT),
    allowedOrigins: secrets.ALLOWED_ORIGINS.split(',').map((o) => o.trim()),

    // Database
    database: {
      url: secrets.DATABASE_URL,
    },

    // Security
    jwt: {
      secret: secrets.JWT_SECRET,
      expiresIn: '24h',
    },

    // SSL/TLS
    ssl: {
      keyPath: secrets.SSL_KEY_PATH,
      certPath: secrets.SSL_CERT_PATH,
      enabled: !!(secrets.SSL_KEY_PATH && secrets.SSL_CERT_PATH),
    },

    // External Services
    stripe: {
      secretKey: secrets.STRIPE_SECRET_KEY,
    },
    aws: {
      accessKeyId: secrets.AWS_ACCESS_KEY_ID,
      secretAccessKey: secrets.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1', // Update as needed
    },
    anthropic: {
      apiKey: secrets.ANTHROPIC_API_KEY,
    },

    // Logging
    logging: {
      level: secrets.LOG_LEVEL,
      firebaseToken: secrets.LOGFIRE_TOKEN,
    },

    // Rate Limiting
    rateLimit: {
      windowMs: parseInt(secrets.RATE_LIMIT_WINDOW_MS),
      max: parseInt(secrets.RATE_LIMIT_MAX_REQUESTS),
    },
  };
}

/**
 * Validate secrets on startup (can be called from main app)
 */
function validateSecretsOnStartup() {
  try {
    const config = getConfig();

    // Additional validation checks
    if (config.env === 'production') {
      // Production-specific validations
      if (!config.database.url) {
        throw new Error('DATABASE_URL is required in production');
      }
      if (!config.ssl.enabled) {
        console.warn('⚠️  WARNING: SSL/TLS not configured in production');
      }
    }

    return config;
  } catch (error) {
    console.error('❌ Startup validation failed:', error.message);
    process.exit(1);
  }
}

/**
 * Print a report of loaded secrets (for debugging)
 */
function printSecretsReport() {
  console.log('\n📊 SECRETS CONFIGURATION REPORT');
  console.log('================================\n');

  const config = {};
  for (const [key, secretConfig] of Object.entries(REQUIRED_SECRETS)) {
    const value = process.env[key];
    const status = value ? '✓' : '✗';
    const display = value
      ? secretConfig.sensitive
        ? '[REDACTED]'
        : value.substring(0, 20) + (value.length > 20 ? '...' : '')
      : '[NOT SET]';

    console.log(`${status} ${key.padEnd(30)} ${display}`);
    if (secretConfig.description) {
      console.log(`  └─ ${secretConfig.description}`);
    }
  }

  console.log('\n');
}

/**
 * Check for dangerous patterns in secrets (prevent accidental exposure)
 */
function scanForSecrets() {
  const dangerousPatterns = [
    /CANARY/i, // Marked for exfiltration detection
    /test.*secret/i,
    /fake.*key/i,
  ];

  const allEnvVars = Object.entries(process.env);
  const suspiciousVars = allEnvVars.filter(([key, value]) => {
    if (!value) return false;
    // Only check keys that look like secrets
    if (!key.includes('SECRET') && !key.includes('KEY') && !key.includes('TOKEN')) {
      return false;
    }
    return dangerousPatterns.some((pattern) => pattern.test(value));
  });

  if (suspiciousVars.length > 0) {
    console.warn('\n⚠️  SECURITY WARNING: Suspicious values detected in environment:');
    suspiciousVars.forEach(([key, value]) => {
      console.warn(`  - ${key}: ${value.substring(0, 20)}...`);
    });
    console.warn('   These appear to be test/canary values. Update before production!\n');
  }
}

// Export functions
module.exports = {
  loadSecrets,
  getConfig,
  validateSecretsOnStartup,
  printSecretsReport,
  scanForSecrets,
  REQUIRED_SECRETS,
};

// If this file is run directly, print a report
if (require.main === module) {
  try {
    printSecretsReport();
    scanForSecrets();
  } catch (error) {
    console.error('Error:', error.message);
  }
}

/**
 * Secure Express Application
 * 
 * Uses configuration module to load secrets safely from environment
 * Never hardcodes or commits secrets to version control
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

// Load and validate configuration
const config = require('./config');
const appConfig = config.validateSecretsOnStartup();

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Security Headers with Helmet
app.use(helmet());

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: appConfig.rateLimit.windowMs,
  max: appConfig.rateLimit.max,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. CORS Configuration
app.use(cors({
  origin: appConfig.allowedOrigins,
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400,
}));

// 4. Body Parser with Size Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Data Sanitization
app.use(mongoSanitize());

// 6. Prototype Pollution Prevention
app.use((req, res, next) => {
  delete req.body.__proto__;
  delete req.body.constructor;
  delete req.body.prototype;
  next();
});

// ==================== JWT AUTHENTICATION ====================

const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: 'Missing authorization header' });
  }

  const tokenMatch = authHeader.match(/^Bearer\s+(.+)$/);
  if (!tokenMatch) {
    return res.status(401).json({ error: 'Invalid authorization format' });
  }

  const token = tokenMatch[1];

  try {
    const decoded = jwt.verify(token, appConfig.jwt.secret);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

// ==================== ROUTES ====================

/**
 * Health Check Endpoint
 * No authentication required
 */
app.get('/health', (req, res) => {
  res.set('X-Content-Type-Options', 'nosniff');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: appConfig.env,
  });
});

/**
 * Get Users Endpoint
 * Requires authentication
 * Includes input validation and pagination
 */
app.get('/users', authenticate, (req, res) => {
  try {
    // Validate query parameters
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
