 */
function startServer() {
  const PORT = appConfig.port;

  if (appConfig.ssl.enabled) {
    // HTTPS with TLS
    const https = require('https');
    const fs = require('fs');

    try {
      const key = fs.readFileSync(appConfig.ssl.keyPath);
      const cert = fs.readFileSync(appConfig.ssl.certPath);
