const AWS = require('aws-sdk');

/**
 * APPROACH 1: AWS Secrets Manager (RECOMMENDED FOR AWS)
 */
class AWSSecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    try {
      // Check cache first
      const cached = this.cache.get(secretName);
      if (cached && cached.expiresAt > Date.now()) {
        console.log(`[CACHE HIT] Secret: ${secretName}`);
        return cached.value;
      }

      // Fetch from Secrets Manager
      console.log(`[FETCHING] Secret from AWS Secrets Manager: ${secretName}`);
      const response = await this.client.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secret;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getSecrets(secretNames) {
    return Promise.all(secretNames.map(name => this.getSecret(name)));
  }

  clearCache() {
    this.cache.clear();
  }
}

/**
 * APPROACH 2: HashiCorp Vault (RECOMMENDED FOR ENTERPRISE)
 */
class VaultSecretsManager {
  constructor() {
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN
    });
    this.vault = vault;
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretPath) {
    try {
      // Check cache
      const cached = this.cache.get(secretPath);
      if (cached && cached.expiresAt > Date.now()) {
        console.log(`[CACHE HIT] Secret: ${secretPath}`);
        return cached.value;
      }

      // Fetch from Vault
      console.log(`[FETCHING] Secret from Vault: ${secretPath}`);
      const response = await this.vault.read(secretPath);

      const secret = response.data.data;

      // Cache
      this.cache.set(secretPath, {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secret;
    } catch (error) {
      console.error(`Error fetching secret from Vault ${secretPath}:`, error.message);
      throw new Error(`Failed to retrieve secret from Vault: ${secretPath}`);
    }
  }

  async getSecrets(secretPaths) {
    return Promise.all(secretPaths.map(path => this.getSecret(path)));
  }

  clearCache() {
    this.cache.clear();
  }
}

/**
 * APPROACH 3: Azure Key Vault (FOR AZURE USERS)
 */
class AzureKeyVaultManager {
  constructor() {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(
      process.env.AZURE_KEYVAULT_URL,
      credential
    );
    this.cache = new Map();
    this.cacheTTL = 3600000;
  }

  async getSecret(secretName) {
    try {
      const cached = this.cache.get(secretName);
      if (cached && cached.expiresAt > Date.now()) {
        console.log(`[CACHE HIT] Secret: ${secretName}`);
        return cached.value;
      }

      console.log(`[FETCHING] Secret from Azure Key Vault: ${secretName}`);
      const secret = await this.client.getSecret(secretName);

      this.cache.set(secretName, {
        value: secret.value,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secret.value;
    } catch (error) {
      console.error(`Error fetching secret from Azure Key Vault ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getSecrets(secretNames) {
    return Promise.all(secretNames.map(name => this.getSecret(name)));
  }

  clearCache() {
    this.cache.clear();
  }
}

/**
 * APPROACH 4: Secure Environment Variables (DEVELOPMENT ONLY)
 * 
 * Only use this for development and local testing!
 * Never use this in production.
 */
class SecureEnvManager {
  constructor() {
    require('dotenv').config({ path: this.getEnvFilePath() });
    this.validateRequired();
  }

  getEnvFilePath() {
    const env = process.env.NODE_ENV || 'development';
    return `.env.${env}.local`;
  }

  validateRequired() {
    const required = [
      'DATABASE_URL',
      'JWT_SECRET',
      'API_KEY'
    ];

    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }
  }

  getSecret(key) {
    const value = process.env[key];
    if (!value) {
      throw new Error(`Secret ${key} not found in environment`);
    }
    return value;
  }

  getSecrets(keys) {
    return keys.map(key => this.getSecret(key));
  }
}

/**
 * MAIN SECRETS MANAGER (Chooses appropriate implementation)
 */
class SecretsManager {
  static instance = null;

  static getInstance() {
    if (!SecretsManager.instance) {
      SecretsManager.instance = SecretsManager.createManager();
    }
    return SecretsManager.instance;
  }

  static createManager() {
    const env = process.env.NODE_ENV || 'development';
    const secretsBackend = process.env.SECRETS_BACKEND || 'env';

    console.log(`[INIT] Initializing ${secretsBackend} secrets manager for ${env} environment`);

    switch (secretsBackend) {
      case 'aws':
        return new AWSSecretsManager();
      case 'vault':
        return new VaultSecretsManager();
      case 'azure':
        return new AzureKeyVaultManager();
      case 'env':
        if (env === 'production') {
          throw new Error('Cannot use environment variables for production. Use AWS Secrets Manager, Vault, or Azure Key Vault.');
        }
        return new SecureEnvManager();
      default:
        throw new Error(`Unknown secrets backend: ${secretsBackend}`);
    }
  }
}

module.exports = {
  SecretsManager,
  AWSSecretsManager,
  VaultSecretsManager,
  AzureKeyVaultManager,
  SecureEnvManager
};

