/**
 * Secret Scanner - Detects hardcoded secrets in source code
 * Usage: node scan-secrets.js
 */

const fs = require('fs');
const path = require('path');

class SecretScanner {
  constructor() {
    // Patterns for common secrets
    this.patterns = {
      AWS_KEY: /AKIA[0-9A-Z]{16}/g,
      AWS_SECRET: /aws_secret_access_key\s*=\s*[^\s]+/gi,
      STRIPE_KEY: /(sk_live_|sk_test_)[0-9a-z]{16,}/g,
      JWT: /eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g,
      PASSWORD: /password\s*[=:]\s*["\']([^"\']+)["\']/gi,
      API_KEY: /api[_-]?key\s*[=:]\s*["\']?([^\s"\']+)["\']?/gi,
      PRIVATE_KEY: /-----BEGIN PRIVATE KEY-----/g,
      DATABASE_URL: /postgres:\/\/[^@]+@[^\s]+/gi,
      AUTH_TOKEN: /Authorization:\s*Bearer\s+[^\s]+/gi,
      ANTHROPIC_KEY: /sk-ant-[A-Za-z0-9_-]{20,}/g,
      GITHUB_TOKEN: /gh[pousr]{1}_[A-Za-z0-9_-]{36,255}/g,
    };

    this.findings = [];
    this.ignoredFiles = [
      'node_modules',
      '.git',
      'dist',
      'build',
      '.next',
      'SECRETS_MANAGEMENT_GUIDE.md',
      'scan-secrets.js'
    ];
  }

  isIgnored(filePath) {
    return this.ignoredFiles.some(ignored => filePath.includes(ignored));
  }

  getFiles(dir, fileList = []) {
    const files = fs.readdirSync(dir);

    files.forEach(file => {
      const filePath = path.join(dir, file);
      const stat = fs.statSync(filePath);

      if (this.isIgnored(filePath)) {
        return;
      }

      if (stat.isDirectory()) {
        this.getFiles(filePath, fileList);
      } else if (!filePath.includes('node_modules')) {
        fileList.push(filePath);
      }
    });

    return fileList;
  }

  scanFile(filePath) {
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      const lines = content.split('\n');

      Object.entries(this.patterns).forEach(([patternName, pattern]) => {
        lines.forEach((line, lineNum) => {
          if (pattern.test(line)) {
            // Skip comments and examples
            if (line.trim().startsWith('#') || line.includes('EXAMPLE') || line.includes('example')) {
              return;
            }

            this.findings.push({
              file: filePath,
              line: lineNum + 1,
              type: patternName,
              content: line.substring(0, 80) + (line.length > 80 ? '...' : ''),
              severity: this.getSeverity(patternName)
            });
          }
        });
      });
    } catch (error) {
      console.warn(`Warning: Could not read file ${filePath}`);
    }
  }

  getSeverity(patternName) {
    const critical = ['AWS_KEY', 'AWS_SECRET', 'STRIPE_KEY', 'PRIVATE_KEY', 'DATABASE_URL', 'ANTHROPIC_KEY'];
    const high = ['JWT', 'AUTH_TOKEN', 'GITHUB_TOKEN', 'API_KEY'];

    if (critical.includes(patternName)) return '🔴 CRITICAL';
    if (high.includes(patternName)) return '🟠 HIGH';
    return '🟡 MEDIUM';
  }

  scan(dir = '.') {
    console.log(`\n🔍 Scanning for secrets in: ${path.resolve(dir)}\n`);

    const files = this.getFiles(dir);
    console.log(`📁 Found ${files.length} files to scan\n`);

    files.forEach(file => {
      this.scanFile(file);
    });

    return this.findings;
  }

  report() {
    if (this.findings.length === 0) {
      console.log('✅ No secrets found!\n');
      return;
    }

    console.log(`\n⚠️  Found ${this.findings.length} potential secrets:\n`);
    console.log('┌' + '─'.repeat(118) + '┐');
    console.log('│ File │ Line │ Type │ Severity │ Preview');
    console.log('├' + '─'.repeat(118) + '┤');

    this.findings.forEach(finding => {
      const fileCol = finding.file.padEnd(30);
      const lineCol = `${finding.line}`.padEnd(5);
      const typeCol = finding.type.padEnd(15);
      const severityCol = finding.severity.padEnd(20);

      console.log(`│ ${fileCol} │ ${lineCol} │ ${typeCol} │ ${severityCol} │ ${finding.content}`);
    });

    console.log('└' + '─'.repeat(118) + '┘\n');

    // Summary
    const critical = this.findings.filter(f => f.severity.includes('CRITICAL')).length;
    const high = this.findings.filter(f => f.severity.includes('HIGH')).length;
    const medium = this.findings.filter(f => f.severity.includes('MEDIUM')).length;

    console.log('Summary:');
    console.log(`  🔴 CRITICAL: ${critical}`);
    console.log(`  🟠 HIGH: ${high}`);
    console.log(`  🟡 MEDIUM: ${medium}\n`);

    if (critical > 0) {
      console.log('🚨 CRITICAL SECRETS FOUND - IMMEDIATE ACTION REQUIRED!\n');
      process.exit(1);
    }
  }
}

// Run scanner
const scanner = new SecretScanner();
scanner.scan('.');
scanner.report();

