  });
}

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Now only authenticated users can access this
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. **NO INPUT VALIDATION** (OWASP #3: Injection, #5: Broken Access Control)
**Severity: HIGH**

**Issue:** No validation or sanitization of query parameters or request bodies. This could lead to injection attacks if the app is extended.

**Risk:** 
- SQL Injection (if database queries are added)
- NoSQL Injection
- Command Injection
- Path Traversal

**Recommended Fix:**
```javascript
const { body, query, validationResult } = require('express-validator');

// Validate and sanitize inputs
app.get('/users/:id', [
  // Validate and sanitize the id parameter
  query('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const userId = req.query.id;
  // Safe to use userId now
  res.json({ id: userId, name: 'User Name' });
});

// For POST requests
app.post('/users', [
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape() // Escape HTML characters
    .withMessage('Name must be 1-100 characters'),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process validated data
  res.json({ success: true });
});
```

---

### 3. **MISSING SECURITY HEADERS** (OWASP #6: Security Misconfiguration)
**Severity: HIGH**

**Issue:** No HTTP security headers to protect against common attacks (XSS, Clickjacking, etc.).

**Risk:** 
- Cross-Site Scripting (XSS)
- Clickjacking attacks
- Man-in-the-middle attacks
- MIME-type sniffing

**Recommended Fix:**
```javascript
const helmet = require('helmet');

// Apply Helmet middleware - sets various HTTP headers
app.use(helmet());

// Or configure more specifically:
app.use(
  helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'", "'unsafe-inline'"], // Restrict scripts
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", 'data:', 'https:'],
      },
    },
    hsts: {
      maxAge: 31536000, // 1 year
      includeSubDomains: true,
      preload: true,
    },
    frameguard: {
      action: 'deny', // Prevent clickjacking
    },
    noSniff: true, // Prevent MIME sniffing
    xssFilter: true, // Enable XSS protection
    referrerPolicy: {
      policy: 'strict-origin-when-cross-origin',
    },
  })
);
```

---

### 4. **NO RATE LIMITING** (OWASP #4: Broken Access Control)
**Severity: HIGH**

**Issue:** No protection against brute force or DoS attacks.

**Risk:** 
- Denial of Service (DoS)
- Brute force attacks
- Resource exhaustion

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 login attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful requests
});

app.post('/login', authLimiter, (req, res) => {
  // Login logic
});
```

---

### 5. **SENSITIVE DATA EXPOSURE** (OWASP #3: Sensitive Data Exposure)
**Severity: HIGH**

**Issue:** 
- User emails exposed in plain response
- Hardcoded values (should use environment variables)
- No data classification

**Risk:** Privacy violations, data breaches.

**Recommended Fix:**
```javascript
// Use environment variables
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Filter sensitive data based on user roles
app.get('/users', authenticateToken, (req, res) => {
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ];

  // Only return full email if user is admin or viewing own data
  users = users.map(user => {
    if (req.user.role === 'admin' || req.user.id === user.id) {
      return user;
    }
    // Hide email for non-admin users viewing other users
    return {
      id: user.id,
      name: user.name,
      // email intentionally omitted
    };
  });

  res.json(users);
});
```

---

### 6. **NO HTTPS ENFORCEMENT** (OWASP #2: Broken Authentication, #3: Sensitive Data Exposure)
**Severity: HIGH**

**Issue:** Application doesn't enforce HTTPS in production.

**Risk:** Man-in-the-middle attacks, credential interception.

**Recommended Fix:**
```javascript
// Enforce HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Or use helmet
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true,
}));
```

---

## 🟡 MEDIUM-RISK ISSUES

### 7. **NO CORS CONFIGURATION** (OWASP #1: Broken Access Control)
**Severity: MEDIUM**

**Issue:** No CORS policy defined; defaults allow any origin.

**Risk:** Unauthorized cross-origin requests.

**Recommended Fix:**
```javascript
const cors = require('cors');

// Restrict CORS to specific origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600, // 1 hour
};

app.use(cors(corsOptions));

// Or disable CORS entirely if not needed
app.use(cors({ origin: false }));
```

---

### 8. **NO ERROR HANDLING** (OWASP #6: Security Misconfiguration)
**Severity: MEDIUM**

**Issue:** No centralized error handling; could leak sensitive information in stack traces.

**Risk:** Information disclosure of system details, stack traces, file paths.

**Recommended Fix:**
```javascript
// Global error handler (add at the end of routes)
app.use((err, req, res, next) => {
  console.error(err); // Log full error server-side

  // Don't expose sensitive error details to client
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: {
      message: message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    },
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

### 9. **NO LOGGING/MONITORING** (OWASP #9: Insufficient Logging & Monitoring)
**Severity: MEDIUM**

**Issue:** No audit logging for security events.

**Risk:** Unable to detect or respond to security incidents.

**Recommended Fix:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Create logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'api-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Log HTTP requests
app.use(morgan('combined', { stream: { write: message => logger.info(message) } }));

// Log authentication events
app.post('/login', (req, res) => {
  try {
    // Login logic...
    logger.info(`User login successful: ${req.body.email}`);
  } catch (error) {
    logger.error(`Login failed: ${req.body.email} - ${error.message}`);
  }
});
```

---

### 10. **NO REQUEST SIZE LIMITS** (OWASP #4: Broken Access Control)
**Severity: MEDIUM**

**Issue:** No limits on request payload size.

**Risk:** DoS attacks via large payloads, memory exhaustion.

**Recommended Fix:**
```javascript
// Limit request size
app.use(express.json({ limit: '10kb' })); // 10KB limit for JSON
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Or per-route
app.post('/upload', express.json({ limit: '100kb' }), (req, res) => {
  // Handle upload
});
```

---

