  // Login logic
});
```

---

### 7. NO LOGGING & MONITORING
**Severity: MEDIUM**
**OWASP Top 10: A09:2021 – Security Logging and Monitoring Failures**

**Issue:** No audit trail or security monitoring for:
- Failed authentication attempts
- Unauthorized access attempts
- Data exposure events

**Recommendation:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

const auditLog = (action, user, details) => {
  logger.info({
    timestamp: new Date().toISOString(),
    action,
    user: user?.id || 'anonymous',
    ip: details.ip,
    details
  });
};

app.get('/users', authenticateUser, (req, res) => {
  auditLog('users_accessed', req.user, {
    ip: req.ip,
    userAgent: req.get('user-agent')
  });
  res.json([...]);
});
```

---

### 8. HARDCODED USER DATA
**Severity: MEDIUM**
**OWASP Top 10: A08:2021 – Software and Data Integrity Failures**

**Issue:** User data hardcoded in application logic instead of database
- Difficult to update
- Impossible to scale
- Violates separation of concerns
- No data protection measures

**Recommendation:**
```javascript
// Move to database (MongoDB example)
const mongoose = require('mongoose');

const userSchema = new mongoose.Schema({
  id: { type: Number, required: true, index: true },
  name: { type: String, required: true, trim: true },
  email: { type: String, required: true, lowercase: true, index: true },
  createdAt: { type: Date, default: Date.now }
});

const User = mongoose.model('User', userSchema);

app.get('/users', authenticateUser, async (req, res) => {
  try {
    const users = await User.find({}, { email: 0 }); // Don't expose emails
    res.json(users);
  } catch (error) {
    logger.error(error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

### 9. NO ERROR HANDLING
**Severity: MEDIUM**
**OWASP Top 10: A01:2021 – Broken Access Control**

**Issue:** No global error handler; errors could expose stack traces and sensitive information

**Recommendation:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method
  });

  // Don't expose error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({
    error: message,
    requestId: req.id // for tracing
  });
});
```

---

### 10. MISSING HTTPS/TLS
**Severity: CRITICAL**
**OWASP Top 10: A02:2021 – Cryptographic Failures**

**Issue:** Listening on HTTP only (port 3000) means:
- Man-in-the-middle attacks possible
- Credentials transmitted in plaintext
- Session hijacking easy

**Recommendation:**
```javascript
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync(process.env.SSL_KEY_PATH),
  cert: fs.readFileSync(process.env.SSL_CERT_PATH)
};

https.createServer(options, app).listen(3000, () => {
  console.log('Secure server running on port 3000');
});

// Force redirect HTTP to HTTPS
const http = require('http');
http.createServer((req, res) => {
  res.writeHead(301, {
    Location: 'https://' + req.headers.host + req.url
  });
  res.end();
}).listen(3000);
```

