    test('POST /login should reject non-string credentials', async () => {
      const res = await request(app)
        .post('/login')
        .send({ username: 123, password: [] })
        .expect(400);

      expect(res.body.error).toContain('Invalid');
    });
  });

  // ========================================================================
  // SECURITY HEADERS TESTS
  // ========================================================================
  describe('Security Headers', () => {

    test('Should set X-Content-Type-Options header', async () => {
      const res = await request(app).get('/health');
      expect(res.get('X-Content-Type-Options')).toBe('nosniff');
    });

    test('Should set X-Frame-Options header', async () => {
      const res = await request(app).get('/health');
      expect(res.get('X-Frame-Options')).toBeDefined();
    });

    test('Should set Strict-Transport-Security header', async () => {
      const res = await request(app).get('/health');
      expect(res.get('Strict-Transport-Security')).toBeDefined();
    });

    test('Should set Content-Security-Policy header', async () => {
      const res = await request(app).get('/health');
      expect(res.get('Content-Security-Policy')).toBeDefined();
    });

    test('Should set secure CORS headers when appropriate', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(res.get('Access-Control-Allow-Origin')).toBeDefined();
    });
  });

  // ========================================================================
  // RATE LIMITING TESTS
  // ========================================================================
  describe('Rate Limiting', () => {

    test('Should rate limit excessive requests', async () => {
      // Make multiple requests rapidly
      let rateLimited = false;

      for (let i = 0; i < 5; i++) {
        const res = await request(app).get('/health');
        const remaining = res.get('RateLimit-Remaining');

        if (remaining === '0') {
          rateLimited = true;
          break;
        }
      }

      // Should show rate limit info in headers
      const res = await request(app).get('/health');
      expect(res.get('RateLimit-Limit')).toBeDefined();
      expect(res.get('RateLimit-Remaining')).toBeDefined();
      expect(res.get('RateLimit-Reset')).toBeDefined();
    });

    test('POST /login should have stricter rate limits', async () => {
      // Attempt multiple login failures
      const attempts = [];
      for (let i = 0; i < 6; i++) {
        const res = await request(app)
          .post('/login')
          .send({ username: 'test', password: 'wrong' });
        attempts.push(res.status);
      }

      // Should eventually return 429 (Too Many Requests)
      expect(attempts).toContain(429);
    });
  });

  // ========================================================================
  // ERROR HANDLING TESTS
  // ========================================================================
  describe('Error Handling & Information Disclosure', () => {

    test('404 errors should not expose sensitive information', async () => {
      const res = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(res.body.error).toBe('Not Found');
      expect(res.body.stack).toBeUndefined();
    });

    test('500 errors should not expose stack traces in production', async () => {
      process.env.NODE_ENV = 'production';

      // Trigger error (implementation-specific)
      const res = await request(app)
        .get('/health')
        .expect(200);

      // In production, stack traces shouldn't be exposed
      if (res.status === 500) {
        expect(res.body.stack).toBeUndefined();
      }

      process.env.NODE_ENV = 'test';
    });

    test('Error responses should include requestId for tracking', async () => {
      const res = await request(app)
        .get('/users') // No auth
        .expect(401);

      expect(res.body.requestId).toBeDefined();
      expect(res.get('X-Request-ID')).toBeDefined();
    });
  });

  // ========================================================================
  // DATA EXPOSURE TESTS
  // ========================================================================
  describe('Sensitive Data Protection', () => {

    let validToken;

    beforeAll(async () => {
      const res = await request(app)
        .post('/login')
        .send({ username: 'demo', password: 'password123' });
      validToken = res.body.token;
    });

    test('GET /users should not expose email addresses', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${validToken}`)
        .expect(200);

      const users = res.body.data;
      users.forEach(user => {
        expect(user.email).toBeUndefined();
        expect(user.password).toBeUndefined();
      });
    });

    test('Login response should not expose sensitive user data', async () => {
      const res = await request(app)
        .post('/login')
        .send({ username: 'demo', password: 'password123' })
        .expect(200);

      expect(res.body.token).toBeDefined();
      expect(res.body.password).toBeUndefined();
      expect(res.body.email).toBeUndefined();
    });

    test('Credentials should not be logged in responses', async () => {
      const res = await request(app)
        .post('/login')
        .send({ username: 'demo', password: 'password123' })
        .expect(200);

      const responseJson = JSON.stringify(res.body);
      expect(responseJson).not.toContain('password123');
    });
  });

  // ========================================================================
  // INJECTION ATTACK TESTS
  // ========================================================================
  describe('Injection Attack Prevention', () => {

    let validToken;

    beforeAll(async () => {
      const res = await request(app)
        .post('/login')
        .send({ username: 'demo', password: 'password123' });
      validToken = res.body.token;
    });

    test('Should reject SQL injection attempt in query parameters', async () => {
      const res = await request(app)
        .get('/users?id=1; DROP TABLE users;--')
        .set('Authorization', `Bearer ${validToken}`)
        .expect(400); // Should fail validation
    });

    test('Should reject NoSQL injection attempt', async () => {
      const res = await request(app)
        .get('/users?id[$ne]=')
        .set('Authorization', `Bearer ${validToken}`)
        .expect(400);
    });

    test('Should reject command injection attempt', async () => {
      const res = await request(app)
        .get('/users?search=`rm -rf /`')
        .set('Authorization', `Bearer ${validToken}`)
        .expect(200); // Should sanitize

      const responseJson = JSON.stringify(res.body);
      expect(responseJson).not.toContain('`rm -rf');
    });
  });

  // ========================================================================
  // CORS TESTS
  // ========================================================================
  describe('CORS Security', () => {

    test('Should allow requests from whitelisted origins', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(res.get('Access-Control-Allow-Origin')).toBeDefined();
    });

    test('Should deny requests from unauthorized origins', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'https://evil.com');

      // Either blocked or returns undefined
      const corsHeader = res.get('Access-Control-Allow-Origin');
      if (corsHeader) {
        expect(corsHeader).not.toBe('https://evil.com');
      }
    });

    test('Should restrict preflight requests properly', async () => {
      const res = await request(app)
        .options('/users')
        .set('Origin', 'http://localhost:3000')
        .set('Access-Control-Request-Method', 'POST')
        .expect(200);

      expect(res.get('Access-Control-Allow-Methods')).toBeDefined();
    });
  });

  // ========================================================================
  // REQUEST ID TRACKING
  // ========================================================================
  describe('Request ID & Audit Trail', () => {

    test('Every response should include X-Request-ID header', async () => {
      const res = await request(app).get('/health');
      expect(res.get('X-Request-ID')).toBeDefined();
      expect(res.get('X-Request-ID')).toMatch(/^[0-9a-f-]{36}$/); // UUID format
    });

    test('Request ID should be included in error responses', async () => {
      const res = await request(app)
        .get('/users')
        .expect(401);

      expect(res.body.requestId).toBeDefined();
      expect(res.get('X-Request-ID')).toBe(res.body.requestId);
    });
  });

});

