/**
 * SECURE VERSION OF app.js
 * Implements security best practices and OWASP Top 10 protections
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const fs = require('fs');
const path = require('path');

const app = express();

// ============================================================================
// 1. SECURITY HEADERS (OWASP A01:2021 - Broken Access Control)
// ============================================================================
app.use(helmet());

// ============================================================================
// 2. CORS CONFIGURATION (OWASP A01:2021 - Broken Access Control)
// ============================================================================
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
  maxAge: 3600
};
app.use(cors(corsOptions));

// ============================================================================
// 3. BODY PARSER MIDDLEWARE
// ============================================================================
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// 4. RATE LIMITING (OWASP A04:2021 - Insecure Design)
// ============================================================================
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  store: new (require('rate-limit-memory-store'))() // Use memory store for demo
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for auth endpoints
  skipSuccessfulRequests: true,
  message: 'Too many failed attempts, please try again later.'
});

app.use(generalLimiter);

// ============================================================================
// 5. REQUEST LOGGING (OWASP A09:2021 - Logging and Monitoring Failures)
// ============================================================================
const requestLogger = (req, res, next) => {
  const timestamp = new Date().toISOString();
  const logEntry = {
    timestamp,
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    statusCode: res.statusCode
  };

  // Log to console and file in production
  console.log(JSON.stringify(logEntry));

  if (process.env.NODE_ENV === 'production') {
    // In production, write to file (consider using winston in real app)
    fs.appendFileSync(
      path.join(__dirname, 'logs', 'access.log'),
      JSON.stringify(logEntry) + '\n',
      { flag: 'a' }
    );
  }

  next();
};
app.use(requestLogger);

// ============================================================================
// 6. AUTHENTICATION MIDDLEWARE (OWASP A07:2021 - Identification and Authentication)
// ============================================================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Extract token from "Bearer TOKEN"

  if (!token) {
    return res.status(401).json({ 
      error: 'Access denied. No authentication token provided.' 
    });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key');
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token has expired.' });
    }
    return res.status(403).json({ error: 'Invalid token.' });
  }
