    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (err) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * Users Endpoint - Protected with authentication
 * GET /users - Retrieve all users
 * Query parameters: id (optional, integer), limit (optional, max 100)
 */
app.get('/users',
  authenticateToken,
  query('id').optional().isInt().toInt(),
  query('limit').optional().isInt().toInt().isIn([1, 10, 50, 100]),
  (req, res) => {
