    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid query parameters',
        details: errors.array() 
      });
    }

    try {
      const limit = req.query.limit || 100;
      const id = req.query.id;

      // Mock data (in production, fetch from database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter by ID if provided
      const filteredUsers = id ? users.filter(u => u.id === id) : users;

      // Apply limit
      const paginatedUsers = filteredUsers.slice(0, limit);

      res.json({
        success: true,
        data: paginatedUsers,
        count: paginatedUsers.length,
        total: filteredUsers.length
      });
    } catch (err) {
      res.status(500).json({ 
        error: process.env.NODE_ENV === 'production' 
          ? 'Internal server error' 
          : err.message 
      });
    }
  }
);

/**
 * Authentication Endpoint - Generate JWT token
 * POST /auth/login - Login with credentials
 * Body: { username: string, password: string }
 */
app.post('/auth/login',
  authLimiter,
  (req, res) => {
    try {
      const { username, password } = req.body;

      // Validate input
      if (!username || !password) {
        return res.status(400).json({ 
          error: 'Username and password are required' 
        });
      }

      // Validate length
      if (username.length > 50 || password.length > 255) {
        return res.status(400).json({ 
          error: 'Invalid username or password format' 
        });
      }

      // Simple mock authentication (in production, verify against database with hashed passwords)
      if (username === 'admin' && password === 'password123') {
        const token = jwt.sign(
          { 
            id: 1, 
            username: username,
            iat: Math.floor(Date.now() / 1000)
          },
          process.env.JWT_SECRET || 'your-secret-key',
          { expiresIn: '1h' }
        );

        return res.json({
          success: true,
          token: token,
          expiresIn: 3600
        });
      }

      res.status(401).json({ 
        error: 'Invalid credentials' 
      });
    } catch (err) {
      res.status(500).json({ 
        error: process.env.NODE_ENV === 'production' 
          ? 'Authentication failed' 
          : err.message 
      });
    }
  }
);

// ============================================================================
// 8. ERROR HANDLING MIDDLEWARE (OWASP A09:2021 - Logging and Monitoring)
// ============================================================================
app.use((err, req, res, next) => {
  const timestamp = new Date().toISOString();

  // Log error details internally
  console.error(JSON.stringify({
    timestamp,
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  }));

  // Send generic error to client (don't expose stack traces)
  const status = err.status || 500;
  res.status(status).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message,
    timestamp
  });
});

// ============================================================================
// 9. 404 HANDLER
// ============================================================================
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.url 
  });
});

// ============================================================================
// 10. SERVER STARTUP (OWASP A05:2021 - Security Misconfiguration)
// ============================================================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Create logs directory if it doesn't exist
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

const server = app.listen(PORT, () => {
  console.log(`
    ========================================
    Server running on port ${PORT}
    Environment: ${NODE_ENV}
    ========================================
  `);
});

// Handle server errors
server.on('error', (err) => {
  console.error('Server error:', err);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

