/**
 * secrets.js - Centralized secrets management
 */

const AWS = require('aws-sdk');

class SecretManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
    this.lastFetch = {};
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache[secretName] && 
        Date.now() - this.lastFetch[secretName] < this.cacheTTL) {
      return this.cache[secretName];
    }

    // Fetch from secrets manager
    if (process.env.NODE_ENV === 'production') {
      return this.fetchFromSecretsManager(secretName);
    } else {
      return this.fetchFromEnv(secretName);
    }
  }

  async fetchFromSecretsManager(secretName) {
    try {
      const secretsManager = new AWS.SecretsManager();
      const result = await secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      const secret = JSON.parse(result.SecretString);

      // Cache the secret
      this.cache[secretName] = secret;
      this.lastFetch[secretName] = Date.now();

      return secret;
    } catch (error) {
      console.error(`Failed to fetch secret ${secretName}:`, error);
      throw new Error('Failed to retrieve secrets');
    }
  }

  fetchFromEnv(secretName) {
    const secret = process.env[secretName];

    if (!secret) {
      throw new Error(`Secret ${secretName} not found in environment`);
    }

    if (secret.length < 32) {
      throw new Error(`Secret ${secretName} is too short (< 32 chars)`);
    }

    return secret;
  }
}

module.exports = new SecretManager();
```

