// config/secrets.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets with TTL
const secretsCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

const getSecret = async (secretName) => {
  // Return from cache if fresh
  const cached = secretsCache.get(secretName);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    return cached.value;
  }

  try {
    const result = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    const secretValue = result.SecretString 
      ? JSON.parse(result.SecretString) 
      : result.SecretBinary;

    // Cache the result
    secretsCache.set(secretName, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  } catch (error) {
    console.error(`Failed to retrieve secret: ${secretName}`, error);

    // Use emergency fallback if secret retrieval fails
    if (process.env.FALLBACK_SECRETS === 'true') {
      console.warn('Using fallback secrets - DEVELOPMENT ONLY');
      return getFallbackSecret(secretName);
    }

    throw error;
  }
};

// Usage in app.js
app.use(async (req, res, next) => {
  try {
    const dbCredentials = await getSecret('prod/database');
    const apiKeys = await getSecret('prod/api-keys');

    req.secrets = {
      database: dbCredentials,
      apis: apiKeys
    };

    next();
  } catch (error) {
    res.status(500).json({ error: 'Configuration error' });
