const express = require('express');
const axios = require('axios');
const helmet = require('helmet');

const app = express();

class VaultClient {
  constructor(vaultAddr, vaultToken) {
    this.vaultAddr = vaultAddr || process.env.VAULT_ADDR;
    this.vaultToken = vaultToken || process.env.VAULT_TOKEN;
    this.secretsCache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  /**
   * Retrieve secret from Vault
   */
  async getSecret(secretPath) {
    // Check cache
    if (this.secretsCache[secretPath]) {
      const { data, expiry } = this.secretsCache[secretPath];
      if (Date.now() < expiry) {
        return data;
      }
    }

    try {
      const response = await axios.get(
        `${this.vaultAddr}/v1/${secretPath}`,
        {
          headers: {
            'X-Vault-Token': this.vaultToken
          }
        }
      );

      const secretData = response.data.data.data;

      // Cache the secret
      this.secretsCache[secretPath] = {
        data: secretData,
        expiry: Date.now() + this.cacheTTL
      };

      return secretData;
    } catch (error) {
      console.error(`Failed to retrieve secret from Vault: ${error.message}`);
      throw new Error(`Vault secret retrieval failed: ${secretPath}`);
    }
  }

  /**
   * Revoke token on shutdown
   */
  async revokeToken() {
    try {
      await axios.post(
        `${this.vaultAddr}/v1/auth/token/revoke-self`,
        {},
        {
          headers: {
            'X-Vault-Token': this.vaultToken
          }
        }
      );
      console.log('Vault token revoked');
    } catch (error) {
      console.error('Failed to revoke Vault token:', error.message);
    }
  }

  /**
   * Validate Vault connectivity
   */
  async health() {
    try {
      const response = await axios.get(`${this.vaultAddr}/v1/sys/health`);
      return response.data;
    } catch (error) {
      console.error('Vault health check failed:', error.message);
      return null;
    }
  }
}

// Initialize Vault client
const vault = new VaultClient();

/**
 * Initialize application with Vault
 */
async function initializeApp() {
  try {
    // Verify Vault connectivity
    const health = await vault.health();
    if (!health) {
      throw new Error('Vault is not accessible');
    }

    // Load secrets
    const appSecrets = await vault.getSecret('secret/data/production/app');
    const dbSecrets = await vault.getSecret('secret/data/production/database');
    const externalApis = await vault.getSecret('secret/data/production/external-apis');

    // Validate required secrets
    const required = ['JWT_SECRET', 'DATABASE_URL', 'STRIPE_SECRET_KEY'];
    const allSecrets = { ...appSecrets, ...dbSecrets, ...externalApis };

    const missing = required.filter(key => !allSecrets[key]);
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    app.use(helmet());

    app.get('/health', (req, res) => {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        vault: 'connected'
      });
    });

    const PORT = process.env.PORT || 3000;

    const server = app.listen(PORT, () => {
      console.log(`🔒 Secure server running on port ${PORT} with Vault`);
    });

    // Graceful shutdown
    process.on('SIGTERM', async () => {
      console.log('Shutting down gracefully...');
      server.close(async () => {
        await vault.revokeToken();
        process.exit(0);
      });
    });

    return app;
  } catch (error) {
    console.error('Failed to initialize application:', error.message);
    process.exit(1);
  }
}

// Start application
if (require.main === module) {
  initializeApp();
}

module.exports = { app, VaultClient };
