  }

  res.json(users);
});

// Ensure HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

---

### 8. **NO ERROR HANDLING / INFORMATION DISCLOSURE** ⚠️ MEDIUM
**Issue:** No proper error handling; stack traces might be exposed.
**OWASP Top 10:** A05:2021 – Security Misconfiguration

**Current Risk:** Detailed error messages can leak system information to attackers.

**Recommendation:** Implement proper error handling.

**Fixed Code Example:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't expose internal errors in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ 
    error: message,
    requestId: req.id // For debugging/tracking
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

### 9. **NO LOGGING / MONITORING** ⚠️ MEDIUM
**Issue:** No request logging or security event monitoring.
**OWASP Top 10:** A09:2021 – Security Logging and Monitoring Failures

**Current Risk:** Unable to detect or investigate security incidents.

**Recommendation:** Implement logging.

**Fixed Code Example:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Setup Winston logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
