### **Solution 7: Environment Variable (With Best Practices)**
**Best for**: Small apps, CI/CD with secret injection

```javascript
// app-secure-env.js
require('dotenv').config();

// NEVER use fallbacks for production secrets
const getRequiredSecret = (name) => {
  const value = process.env[name];
  if (!value && process.env.NODE_ENV === 'production') {
    throw new Error(`Required secret missing: ${name}`);
  }
  return value;
