```javascript
// config/secrets.js
const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.validate();
  }

  validate() {
    const required = ['JWT_SECRET'];
    const optional = ['DB_PASSWORD', 'DATABASE_URL', 'SESSION_SECRET', 'REDIS_URL'];

    // Always required
    for (const secret of required) {
      if (!process.env[secret]) {
        const msg = `FATAL: Required secret '${secret}' not set`;
        logger.error(msg);
        throw new Error(msg);
      }
      // In production, reject weak secrets
      if (process.env.NODE_ENV === 'production') {
        if (process.env[secret].length < 32) {
          throw new Error(`${secret} must be at least 32 characters in production`);
        }
        if (process.env[secret].includes('dev') || process.env[secret].includes('test')) {
          throw new Error(`${secret} appears to be a development secret in production`);
        }
      }
    }

    logger.info(`Loaded ${required.length} required secrets`);
  }

  get(key) {
    const value = process.env[key];
    if (!value) {
      throw new Error(`Secret '${key}' not found`);
    }
    return value;
  }

  mask(secret) {
    if (!secret || secret.length < 8) return '***';
    return secret.substring(0, 4) + '*'.repeat(Math.max(8, secret.length - 8));
  }
}

module.exports = new SecretsManager();
```

