const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const { query, validationResult } = require('express-validator');

// ============================================================================
// ENVIRONMENT VALIDATION
// ============================================================================

const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
const missingVars = requiredEnvVars.filter(env => !process.env[env]);
if (missingVars.length > 0) {
  console.error(`FATAL: Missing required environment variables: ${missingVars.join(', ')}`);
  process.exit(1);
}

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Add console output in development
if (NODE_ENV === 'development') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// EXPRESS APP SETUP
// ============================================================================

const app = express();

// ============================================================================
// MIDDLEWARE: SECURITY HEADERS
// ============================================================================

// Use helmet to set various HTTP headers
app.use(helmet());

// Set additional security policies
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

// ============================================================================
// MIDDLEWARE: HTTPS ENFORCEMENT (Production)
// ============================================================================

if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// ============================================================================
// MIDDLEWARE: CORS CONFIGURATION
// ============================================================================

const corsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin || ALLOWED_ORIGINS.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS policy violation'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));

// ============================================================================
// MIDDLEWARE: BODY PARSING (with size limits to prevent DoS)
// ============================================================================

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// MIDDLEWARE: REQUEST LOGGING
// ============================================================================

app.use((req, res, next) => {
  const start = Date.now();

  // Log request
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });

  // Log response
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      userId: req.user?.id || 'anonymous',
    });
  });

  next();
});

// ============================================================================
// MIDDLEWARE: RATE LIMITING
// ============================================================================

// Global rate limiter
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV !== 'production',
});

app.use(globalLimiter);

// Stricter limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 requests per 15 minutes
  skipSuccessfulRequests: true,
  message: 'Too many authentication attempts, please try again later.',
});

// ============================================================================
// MIDDLEWARE: AUTHENTICATION
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn({
      event: 'unauthorized_access',
      path: req.path,
      ip: req.ip,
      reason: 'missing_token',
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({
        event: 'invalid_token',
        path: req.path,
        ip: req.ip,
        error: err.message,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    req.user = user;
    next();
  });
};

// ============================================================================
// MIDDLEWARE: AUTHORIZATION (Role-based Access Control)
// ============================================================================

const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'User not authenticated' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logger.warn({
        event: 'unauthorized_access',
        userId: req.user.id,
        requiredRole: allowedRoles,
        userRole: req.user.role,
        path: req.path,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ============================================================================
// ROUTES: PUBLIC
// ============================================================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// ============================================================================
// ROUTES: PROTECTED
// ============================================================================

// Get all users (admin only)
app.get('/users', 
  authenticateToken, 
  authorize('admin'),
  (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    logger.info({
      event: 'users_retrieved',
      userId: req.user.id,
      count: users.length,
    });

    res.json(users);
  }
);

// Get current user profile
app.get('/profile',
  authenticateToken,
  (req, res) => {
    const userProfile = {
      id: req.user.id,
      name: req.user.name,
      role: req.user.role,
      email: req.user.email,
    };

    res.json(userProfile);
  }
);

// Search with input validation
app.get('/search',
  authenticateToken,
  query('q')
    .trim()
    .notEmpty().withMessage('Search query cannot be empty')
    .isLength({ max: 100 }).withMessage('Search query must be less than 100 characters')
    .escape(), // Prevent XSS
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const searchTerm = req.query.q;

    logger.info({
      event: 'search_performed',
      userId: req.user.id,
      searchTerm,
    });

    // Simulated search results
    res.json({
      results: [],
      query: searchTerm,
      totalResults: 0,
    });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn({
    event: '404_not_found',
    path: req.path,
    method: req.method,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id || 'anonymous',
  });

  // Don't expose internal error details in production
  const isDevelopment = NODE_ENV === 'development';
  const statusCode = err.status || err.statusCode || 500;

  const errorResponse = {
    error: 'Internal server error',
    ...(isDevelopment && {
      message: err.message,
      stack: err.stack,
    }),
  };

  res.status(statusCode).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info({
    event: 'server_started',
    port: PORT,
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

// Unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    event: 'unhandled_rejection',
    reason: reason?.message || reason,
    promise: promise.toString(),
  });
});

module.exports = app;
