// Secure Application with AWS Secrets Manager Integration
// Implements production-grade secrets management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const AWS = require('aws-sdk');

// ============================================================================
// SECRETS MANAGER INITIALIZATION
// ============================================================================

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache for secrets (with TTL)
const secretsCache = new Map();
const SECRET_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

/**
 * Retrieve secret from AWS Secrets Manager with caching
 * @param {string} secretName - Name of the secret
 * @returns {Promise<Object>} - Secret value
 */
async function getSecret(secretName) {
  // Check cache first
  const cached = secretsCache.get(secretName);
  if (cached && cached.timestamp > Date.now() - SECRET_CACHE_TTL) {
    logger.debug('Using cached secret', { secret: secretName });
    return cached.value;
  }

  try {
    logger.info('Fetching secret from AWS Secrets Manager', { secret: secretName });

    const data = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    let secret;
    if ('SecretString' in data) {
      secret = JSON.parse(data.SecretString);
    } else {
      secret = Buffer.from(data.SecretBinary, 'base64');
    }

    // Cache the secret
    secretsCache.set(secretName, {
      value: secret,
      timestamp: Date.now(),
      version: data.VersionId
    });

    logger.info('Secret retrieved successfully', { 
      secret: secretName,
      version: data.VersionId 
    });

    return secret;
  } catch (error) {
    logger.error('Failed to retrieve secret', {
      secret: secretName,
      error: error.message,
      code: error.code
    });

    // Fail securely - do not allow application to continue without secrets
    throw new Error(`Cannot start without secret: ${secretName}`);
  }
}

/**
 * Handle secret change notifications (for rotation)
 */
secretsManager.on('error', (error) => {
  logger.error('Secrets Manager error', { error: error.message });
});

/**
 * Monitor for secret rotation events
 */
function setupSecretRotationListener() {
  // Set up CloudWatch Events to trigger on secret rotation
  logger.info('Secret rotation listener configured');
}

// ============================================================================
// ENVIRONMENT & BOOTSTRAP
// ============================================================================

const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'app', environment: NODE_ENV },
  transports: [
    new winston.transports.File({ 
      filename: 'error.log', 
      level: 'error',
      maxsize: 10485760, // 10MB
      maxFiles: 5
    }),
    new winston.transports.File({ 
      filename: 'combined.log',
      maxsize: 10485760,
      maxFiles: 5
    }),
  ],
});

// Add console output in development
if (NODE_ENV === 'development') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// APPLICATION BOOTSTRAP
// ============================================================================

let app;
let jwtSecret;
let dbUrl;
let apiKeys = {};

/**
 * Initialize application with secrets
 */
async function initializeApp() {
  logger.info('Initializing application with secrets manager');

  try {
    // Retrieve required secrets from AWS Secrets Manager
    logger.info('Retrieving secrets from manager...');

    // Get JWT secret
    const jwtSecretData = await getSecret(`${NODE_ENV}/jwt-secret`);
    jwtSecret = jwtSecretData.secret;

    // Get database URL
    const dbData = await getSecret(`${NODE_ENV}/database-connection`);
    dbUrl = dbData.url;

    // Get API keys
    const apiKeysData = await getSecret(`${NODE_ENV}/api-keys`);
    apiKeys = apiKeysData;

    logger.info('All secrets retrieved successfully');

    // Create Express app
    app = express();

    // Setup middleware and routes
    setupMiddleware();
    setupRoutes();
    setupErrorHandling();

    logger.info('Application initialized successfully');

    return app;
  } catch (error) {
    logger.error('Failed to initialize application', {
      error: error.message,
      stack: error.stack
    });
    process.exit(1);
  }
}

// ============================================================================
// MIDDLEWARE SETUP
// ============================================================================

function setupMiddleware() {
  app.use(helmet());
  app.use(cors({
    origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
    credentials: true
  }));
  app.use(express.json({ limit: '10kb' }));

  // Security headers
  app.use((req, res, next) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    next();
  });

  // HTTPS enforcement in production
  if (NODE_ENV === 'production') {
    app.use((req, res, next) => {
      if (req.header('x-forwarded-proto') !== 'https') {
        return res.redirect(`https://${req.header('host')}${req.url}`);
      }
      next();
    });
  }

  // Rate limiting
  const globalLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false
  });
  app.use(globalLimiter);

  // Request logging
  app.use((req, res, next) => {
    const start = Date.now();
    res.on('finish', () => {
      logger.info({
        method: req.method,
        path: req.path,
        status: res.statusCode,
        duration: `${Date.now() - start}ms`,
        ip: req.ip
      });
    });
    next();
  });
}

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn('Unauthorized access attempt - missing token', { path: req.path, ip: req.ip });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, jwtSecret, (err, user) => {
    if (err) {
      logger.warn('Invalid token attempt', { 
        path: req.path, 
        ip: req.ip, 
        error: err.message 
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    req.user = user;
    next();
  });
};

// ============================================================================
// ROUTES
// ============================================================================

function setupRoutes() {
  // Health check (public)
  app.get('/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  });

  // Protected endpoints
  app.get('/config', authenticateToken, async (req, res) => {
    try {
      // Example: get current config (secrets not exposed)
      res.json({
        user: req.user,
        apiKeysAvailable: Object.keys(apiKeys),
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      logger.error('Config endpoint error', { error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Secret rotation status (admin only)
  app.get('/admin/secret-status', authenticateToken, async (req, res) => {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    try {
      const status = Array.from(secretsCache.entries()).map(([name, data]) => ({
        name,
        cached: true,
        version: data.version,
        cachedAt: new Date(data.timestamp),
        ttlMs: SECRET_CACHE_TTL
      }));

      res.json({ secrets: status });
    } catch (error) {
      logger.error('Secret status error', { error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Invalidate secret cache (for manual rotation testing)
  app.post('/admin/invalidate-cache', authenticateToken, (req, res) => {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    const { secretName } = req.body;
    if (secretName) {
      secretsCache.delete(secretName);
      logger.info('Secret cache invalidated', { secret: secretName, admin: req.user.id });
      return res.json({ message: 'Cache invalidated' });
    }

    secretsCache.clear();
    logger.info('All secret caches invalidated', { admin: req.user.id });
    res.json({ message: 'All caches invalidated' });
  });
}

// ============================================================================
// ERROR HANDLING
// ============================================================================

function setupErrorHandling() {
  // 404 handler
  app.use((req, res) => {
    logger.warn('404 - Not found', { path: req.path, method: req.method });
    res.status(404).json({ error: 'Not found' });
  });

