# Quick Comparison: Original vs Secure Implementation

## Original Code

```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

### Issues in Original Code:
❌ No authentication - anyone can access user data
❌ No input validation
❌ Sensitive data (emails) exposed publicly
❌ No security headers
❌ No CORS configuration
❌ No rate limiting
❌ No error handling
❌ No logging
❌ Hardcoded port
❌ No HTTPS support

---

## Secure Implementation

### Key Improvements:

### 1. Authentication
```javascript
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'Token required' });

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([/* data */]);
});
```

### 2. Input Validation
```javascript
app.get('/users',
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: 'Invalid input', details: errors.array() });
    }
    // Process validated input
  }
);
```

### 3. Security Headers & CORS
```javascript
app.use(helmet()); // 15+ security headers
app.use(cors({ origin: ALLOWED_ORIGINS })); // Controlled CORS
app.use(helmet.contentSecurityPolicy({...})); // CSP protection
```

### 4. Rate Limiting
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests'
});
app.use(limiter);
```

### 5. Logging & Monitoring
```javascript
app.use(morgan('combined')); // Request logging
fs.appendFileSync('error.log', error); // Error logging
```

### 6. Proper Error Handling
```javascript
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.status || 500).json({ 
    error: 'Internal server error'
    // No stack traces in production
  });
});
```

### 7. Environment Configuration
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

