cat > SECURITY_REVIEW.md << 'EOF'
# Security Review: app.js

## Executive Summary
The current application demonstrates several **critical security vulnerabilities** that require immediate attention. This review identifies OWASP Top 10 risks and provides specific remediation steps.

---

## 🔴 CRITICAL VULNERABILITIES

### 1. **Missing Authentication & Authorization (OWASP A07:2021)**

**Vulnerability:** No authentication mechanism on `/users` endpoint. Any user can access sensitive user data.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Impact:** Unauthorized data access, privacy violation, compliance issues (GDPR, CCPA)

**Recommendation:** Add authentication middleware and role-based access control.

**Remediated Code:**
```javascript
const jwt = require('jsonwebtoken');

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Additional authorization check
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. **No Input Validation (OWASP A03:2021 - Injection)**

**Vulnerability:** No validation of query parameters or request bodies, opening doors to injection attacks.

**Risk Scenarios:**
- SQL injection if data is passed to database
- NoSQL injection
- Command injection

**Current Code:**
```javascript
// No query parameter validation
app.get('/users', (req, res) => {
  // If this connected to DB: SELECT * FROM users WHERE id = req.query.id
  // Attacker could pass: ?id=1 OR 1=1--
});
```

**Recommendation:** Implement comprehensive input validation.

**Remediated Code:**
```javascript
const { query, validationResult } = require('express-validator');

app.get(
  '/users',
  authenticateToken,
  // Validation middleware
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { id, limit } = req.query;

    // Proceed with validated inputs
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);
```

---

### 3. **Sensitive Data Exposure (OWASP A02:2021)**

**Vulnerability:** Exposing personally identifiable information (PII) without proper safeguards.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Issues:**
- Email addresses exposed to unauthorized users
- No HTTPS enforcement
- No rate limiting
- Sensitive data not encrypted in transit

**Recommendation:** 

**Remediated Code:**
```javascript
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

// Add security headers
app.use(helmet());

// Enable HTTPS redirect (in production)
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(`https://${req.headers.host}${req.url}`);
  }
  next();
});

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// Only expose necessary user data
app.get('/users', authenticateToken, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  // Return sanitized user data (exclude sensitive fields if not needed)
  const users = [
    { id: 1, name: 'Alice' }, // Email removed for privacy
    { id: 2, name: 'Bob' },
  ];

  res.json(users);
});
```

---

### 4. **Missing Security Headers (OWASP A01:2021 - Broken Access Control)**

**Vulnerability:** No security headers configured to prevent common attacks.

**Missing Headers:**
- `X-Frame-Options` - Prevents clickjacking
- `X-Content-Type-Options` - Prevents MIME type sniffing
- `Content-Security-Policy` - Prevents XSS
- `Strict-Transport-Security` - Enforces HTTPS

**Recommendation:** Use the `helmet` middleware.

**Remediated Code:**
```javascript
const helmet = require('helmet');

app.use(helmet());

// Additional custom headers if needed
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self'"
  );
  next();
});
```

---

### 5. **No CORS Configuration (OWASP A01:2021)**

**Vulnerability:** CORS (Cross-Origin Resource Sharing) not configured, leading to potential:
- Unauthorized cross-site requests
- Data theft via CSRF attacks
- Unauthorized API access from other domains

**Recommendation:** Implement strict CORS policy.

**Remediated Code:**
```javascript
const cors = require('cors');

// Configure CORS strictly
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com'];

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};

app.use(cors(corsOptions));
```

---

### 6. **No Error Handling & Information Disclosure**

**Vulnerability:** Default error messages may expose sensitive information.

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Issues:**
- No global error handler
- Stack traces exposed to clients
- Port number disclosed in logs

**Recommendation:** Implement proper error handling.

**Remediated Code:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  // Log error securely (not to client)
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Send generic error to client
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

app.listen(process.env.PORT || 3000, process.env.HOST || 'localhost', () => {
  if (process.env.NODE_ENV !== 'production') {
    console.log(`Server running on port ${process.env.PORT || 3000}`);
  }
});
```

---

### 7. **Logging & Monitoring Issues**

**Vulnerability:** No security logging for audit trails.

**Recommendation:** Implement comprehensive logging.

**Remediated Code:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Log authentication attempts
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });
  next();
});
```

---

### 8. **Environment Configuration Issues**

**Vulnerability:** Secrets and configuration may be hardcoded.

**Recommendation:** Use environment variables and .env files properly.

**.env (Add to .gitignore):**
```
JWT_SECRET=your-very-long-random-secret-key-here
NODE_ENV=production
PORT=3000
HOST=localhost
ALLOWED_ORIGINS=https://yourdomain.com
LOG_LEVEL=info
DATABASE_URL=your-database-url
```

**app.js:**
```javascript
require('dotenv').config();

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    console.error(`Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
});
```

---

## 📋 Summary Table

| Vulnerability | Severity | OWASP Category | Status |
|---|---|---|---|
| No Authentication | 🔴 CRITICAL | A07:2021 | ⚠️ Not Fixed |
