app.use(limiter);

// 6. Request Logging
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
    userAgent: req.get('user-agent')
  });
  next();
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

/**
 * Verify JWT token from Authorization header
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // "Bearer TOKEN"

  if (!token) {
    logger.warn(`Authentication attempt without token from IP: ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid/expired token from IP: ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

/**
 * Check if user has required role
 */
function authorize(requiredRole) {
  return (req, res, next) => {
    if (!req.user.role || req.user.role !== requiredRole) {
      logger.warn(`Unauthorized access attempt by user ${req.user.id} to admin resource`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// ============================================================================
// ROUTES - PUBLIC
// ============================================================================

/**
 * Health check endpoint (no auth required)
 * Input: None
 * Output: { status: 'ok', timestamp: ISO string }
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV
  });
});

/**
 * Login endpoint to get JWT token
 * Input: username, password
 * Output: JWT token
 */
app.post(
  '/login',
  // Input validation
  body('username')
    .trim()
    .isLength({ min: 3, max: 50 })
    .withMessage('Username must be between 3 and 50 characters')
    .matches(/^[a-zA-Z0-9_-]+$/)
    .withMessage('Username can only contain alphanumeric characters, hyphens, and underscores'),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters long'),
  (req, res) => {
    // Check validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn(`Login validation failed: ${JSON.stringify(errors.array())}`);
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, password } = req.body;

    // TODO: Verify against database with bcrypt
    // This is a placeholder - DO NOT use in production
    if (username === 'admin' && password === 'SecurePassword123') {
      const token = jwt.sign(
        { id: 1, username, role: 'admin' },
        process.env.JWT_SECRET,
        { expiresIn: '1h' }
      );

      logger.info(`Successful login for user: ${username}`);
      return res.json({ token });
    }

    logger.warn(`Failed login attempt for user: ${username}`);
    res.status(401).json({ error: 'Invalid credentials' });
  }
);

// ============================================================================
// ROUTES - PROTECTED
// ============================================================================

/**
 * Get users list (Admin only)
 * Requires: Authentication + Admin role
 * Input: limit (optional, 1-100, default 100), offset (optional)
 * Output: Array of users
 */
app.get(
  '/users',
  authenticateToken,
  authorize('admin'),
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .toInt()
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    // Check validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { limit = 100, offset = 0 } = req.query;

    // Note: In production, query database with parameterized queries
    // DO NOT concatenate user input into SQL queries
    const users = [
      { id: 1, name: 'Alice', role: 'user' },
      { id: 2, name: 'Bob', role: 'user' }
    ];

    // Paginate results
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit,
      offset
    });
  }
);

/**
 * Get single user by ID (Admin only, or own user)
 * Requires: Authentication
 * Input: id (positive integer)
 * Output: User object (without sensitive fields)
 */
app.get(
  '/users/:id',
  authenticateToken,
  // Input validation
  query('id')
    .isInt({ min: 1 })
    .toInt()
    .withMessage('Invalid user ID'),
  (req, res) => {
    // Check validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id, 10);

    // Authorization check: Users can only view their own profile
    if (req.user.role !== 'admin' && req.user.id !== userId) {
      logger.warn(`Unauthorized access attempt by user ${req.user.id} to user ${userId}`);
      return res.status(403).json({ error: 'Cannot access other users\' data' });
    }

    // Return sanitized user data (exclude passwords, tokens, etc.)
    const user = {
      id: userId,
      name: 'Alice',
      role: 'user'
    };

    res.json(user);
  }
);

/**
 * Create new user (Admin only)
 * Requires: Authentication + Admin role
 * Input: { username, email, password, role }
 * Output: Created user object
 */
app.post(
  '/users',
  authenticateToken,
  authorize('admin'),
  // Input validation
  body('username')
    .trim()
    .isLength({ min: 3, max: 50 })
    .withMessage('Username must be between 3 and 50 characters')
    .matches(/^[a-zA-Z0-9_-]+$/)
    .withMessage('Username can only contain alphanumeric characters, hyphens, and underscores'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email address'),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters long')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .withMessage('Password must contain lowercase, uppercase, and number'),
  body('role')
    .isIn(['user', 'admin', 'moderator'])
    .withMessage('Invalid role'),
  (req, res) => {
    // Check validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn(`User creation validation failed: ${JSON.stringify(errors.array())}`);
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, email, password, role } = req.body;

    // TODO: Hash password with bcrypt before storing
    // TODO: Check for duplicate usernames/emails
    // TODO: Store in database

    logger.info(`New user created by admin: ${username}`);

    res.status(201).json({
      id: 3,
      username,
      email,
      role
    });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * CORS error handler
 */
app.use((err, req, res, next) => {
  if (err.message === 'Not allowed by CORS policy') {
    logger.warn(`CORS error: ${err.message} from ${req.ip}`);
    return res.status(403).json({ error: 'CORS policy violation' });
  }
  next(err);
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  logger.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method
  });

  const statusCode = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({ error: message });
});

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  if (process.env.NODE_ENV !== 'production') {
    logger.info(`Server running on ${HOST}:${PORT}`);
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;
EOF

