# Security Code Snippets - Quick Reference

## 1. Authentication Middleware

### Generate JWT Token
```javascript
const jwt = require('jsonwebtoken');

function generateToken(user) {
  return jwt.sign(
    { id: user.id, username: user.username, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: '1h' }
  );
}
```

### Verify JWT Token
```javascript
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
}
```

---

## 2. Input Validation Examples

### Validate Email
```javascript
const { body, validationResult } = require('express-validator');

app.post('/register', 
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email address')
    .normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process valid email
  }
);
```

### Validate Password
```javascript
body('password')
  .isLength({ min: 8 })
  .withMessage('Password must be at least 8 characters')
  .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])/)
  .withMessage('Password must include uppercase, lowercase, number, and special character')
```

### Validate Integer Parameter
```javascript
const { query } = require('express-validator');

query('id')
  .isInt({ min: 1 })
  .toInt()
  .withMessage('ID must be a positive integer')
```

### Validate String with Regex
```javascript
body('username')
  .trim()
  .isLength({ min: 3, max: 50 })
  .withMessage('Username must be 3-50 characters')
  .matches(/^[a-zA-Z0-9_-]+$/)
  .withMessage('Username can only contain alphanumeric, hyphens, and underscores')
```

### Custom Validation
```javascript
body('newPassword')
  .custom(async (value) => {
    // Check if password was previously used
    const isPreviouslyUsed = await checkPasswordHistory(value);
    if (isPreviouslyUsed) {
      throw new Error('Cannot reuse previous passwords');
    }
  })
```

