  }

  async getSecret(path) {
    const cacheKey = path;

    // Check cache
    if (this.cache[cacheKey]) {
      const { data, timestamp } = this.cache[cacheKey];
      if (Date.now() - timestamp < this.cacheTTL) {
        return data;
      }
    }

    try {
      const response = await vault.read(path);
      const secretData = response.data.data;

      // Cache the result
      this.cache[cacheKey] = {
        data: secretData,
        timestamp: Date.now(),
      };

      return secretData;
    } catch (error) {
      console.error(`Failed to read secret at ${path}:`, error);
      throw new Error('Cannot retrieve secrets from Vault');
    }
  }
}

