/**
 * SECURE APP.JS - AWS SECRETS MANAGER IMPLEMENTATION
 * 
 * This version removes all hardcoded secrets and uses AWS Secrets Manager
 * for production-grade secret management with automatic rotation support.
 */

const express = require('express');
const AWS = require('aws-sdk');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Initialize AWS Secrets Manager client
const secretsClient = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Configure AWS SDK logging
AWS.config.logger = console;

/**
 * Secrets Manager with caching to reduce API calls
 * Implements TTL-based caching with automatic expiration
 */
class SecretsManager {
  constructor(cacheTTL = 5 * 60 * 1000) { // 5 minutes default
    this.cache = new Map();
    this.cacheTTL = cacheTTL;
    this.requestInProgress = new Map();
  }

  /**
   * Get secret with caching and request deduplication
   * Prevents multiple simultaneous requests for same secret
   */
  async getSecret(secretId) {
    // Check cache
    if (this.cache.has(secretId)) {
      const { data, timestamp } = this.cache.get(secretId);
      if (Date.now() - timestamp < this.cacheTTL) {
        console.log(`[SecretsManager] Cache hit for ${secretId}`);
        return data;
      }
      // Cache expired, remove it
      this.cache.delete(secretId);
    }

    // Prevent duplicate requests
    if (this.requestInProgress.has(secretId)) {
      console.log(`[SecretsManager] Waiting for in-progress request: ${secretId}`);
      return this.requestInProgress.get(secretId);
    }

    // Create fetch promise
    const fetchPromise = this._fetchSecretFromAWS(secretId);
    this.requestInProgress.set(secretId, fetchPromise);

    try {
      const data = await fetchPromise;

      // Cache the result
      this.cache.set(secretId, {
        data,
        timestamp: Date.now()
      });

      return data;
    } finally {
      this.requestInProgress.delete(secretId);
    }
  }

  /**
   * Internal method to fetch secret from AWS
   */
  async _fetchSecretFromAWS(secretId) {
    try {
      const params = { SecretId: secretId };
      const data = await secretsClient.getSecretValue(params).promise();

      console.log(`[SecretsManager] Retrieved secret: ${secretId}`);

      // Parse JSON if stored as JSON string
      if (data.SecretString) {
        try {
          return JSON.parse(data.SecretString);
        } catch {
          return { value: data.SecretString };
        }
      }

      return data.SecretBinary
        ? Buffer.from(data.SecretBinary, 'base64')
        : null;
    } catch (error) {
      console.error(`[SecretsManager] Failed to retrieve secret ${secretId}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretId}`);
    }
  }

  /**
   * Clear all cached secrets (useful for manual rotation)
   */
  clearCache() {
    this.cache.clear();
    console.log('[SecretsManager] Cache cleared');
  }
}

// Initialize secrets manager
const secretsManager = new SecretsManager();

/**
 * Initialize application with secrets
 */
let appSecrets = null;

async function initializeSecrets() {
  try {
    appSecrets = await secretsManager.getSecret(
      process.env.SECRETS_ARN || 'prod/app-secrets'
    );
    console.log('[App] Secrets initialized successfully');
  } catch (error) {
    console.error('[App] Failed to initialize secrets:', error);
    // Fail fast - don't start the app without secrets
    process.exit(1);
  }
}

/**
 * Middleware to ensure secrets are loaded
 */
function ensureSecretsLoaded(req, res, next) {
  if (!appSecrets) {
    return res.status(500).json({
      error: 'Service unavailable',
      errorId: req.id
    });
  }
  next();
}

/**
 * Create Express app with security middleware
 */
function createApp() {
  const app = express();

  // Security headers
  app.use(helmet());

  // CORS configuration
  const corsOptions = {
    origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    maxAge: 86400 // 24 hours
  };
  app.use(cors(corsOptions));

  // Rate limiting
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,
    message: 'Too many requests from this IP',
    standardHeaders: true,
    legacyHeaders: false,
    skip: (req) => process.env.NODE_ENV === 'test'
  });
  app.use(limiter);

  // Body parser with size limits
  app.use(express.json({ limit: '10kb' }));
  app.use(express.urlencoded({ limit: '10kb', extended: true }));

  // Ensure secrets are loaded
  app.use(ensureSecretsLoaded);

  // ==================== ROUTES ====================

  /**
   * Health check endpoint
   * Does not require authentication
   */
  app.get('/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV
    });
  });

  /**
   * Protected users endpoint
   * Requires authentication (in real app)
   */
  app.get('/users', (req, res) => {
    // In production, add authentication middleware here
    // app.get('/users', authenticateToken, (req, res) => {

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  /**
   * Secrets rotation endpoint
   * Allows manual rotation of cached secrets
   * In production, restrict this to admin only
   */
  app.post('/admin/rotate-secrets', (req, res) => {
    // TODO: Add authentication and authorization
    secretsManager.clearCache();
    appSecrets = null;
    res.json({ message: 'Secrets cache cleared, will reload on next request' });
  });

  // ==================== ERROR HANDLING ====================

  /**
   * 404 handler
   */
  app.use((req, res) => {
    res.status(404).json({
      error: 'Not found',
      path: req.path
    });
  });

  /**
   * Global error handler
   */
  app.use((err, req, res, next) => {
    console.error('[Error Handler]', err);

    if (process.env.NODE_ENV === 'production') {
      return res.status(err.status || 500).json({
        error: 'Internal server error',
        errorId: req.id
      });
    }

    res.status(err.status || 500).json({
      error: err.message,
      stack: err.stack,
      details: err
    });
  });

  return app;
}

/**
 * Start the server
 */
async function startServer() {
  try {
    // Initialize secrets before starting server
    await initializeSecrets();

    const app = createApp();
    const port = process.env.PORT || 3000;

    app.listen(port, () => {
      console.log(`[App] Server running on port ${port}`);
      console.log(`[App] Environment: ${process.env.NODE_ENV}`);
    });

  } catch (error) {
    console.error('[App] Failed to start server:', error);
    process.exit(1);
  }
}

// Start server if this is the main module
if (require.main === module) {
  startServer();
}

module.exports = { createApp, SecretsManager, startServer };
