class SecretsManager {
  constructor(cacheTTL = 5 * 60 * 1000) { // 5 minutes default
    this.cache = new Map();
    this.cacheTTL = cacheTTL;
    this.requestInProgress = new Map();
  }

  /**
   * Get secret with caching and request deduplication
   * Prevents multiple simultaneous requests for same secret
   */
  async getSecret(secretId) {
    // Check cache
    if (this.cache.has(secretId)) {
      const { data, timestamp } = this.cache.get(secretId);
      if (Date.now() - timestamp < this.cacheTTL) {
        console.log(`[SecretsManager] Cache hit for ${secretId}`);
        return data;
      }
      // Cache expired, remove it
      this.cache.delete(secretId);
    }

    // Prevent duplicate requests
    if (this.requestInProgress.has(secretId)) {
      console.log(`[SecretsManager] Waiting for in-progress request: ${secretId}`);
      return this.requestInProgress.get(secretId);
    }

    // Create fetch promise
    const fetchPromise = this._fetchSecretFromAWS(secretId);
    this.requestInProgress.set(secretId, fetchPromise);

    try {
      const data = await fetchPromise;

      // Cache the result
      this.cache.set(secretId, {
        data,
        timestamp: Date.now()
      });

      return data;
    } finally {
      this.requestInProgress.delete(secretId);
