/**
 * Secrets Manager Module
 * Handles secure retrieval of secrets from AWS Secrets Manager or local .env
 * 
 * USAGE:
 *   - Development: Reads from .env file (which is in .gitignore)
 *   - Production: Reads from AWS Secrets Manager
 */

const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");
require('dotenv').config();

// Determine environment
const isProduction = process.env.NODE_ENV === 'production';
const isDevlopment = process.env.NODE_ENV === 'development';

// Cache for secrets (to avoid repeated AWS calls)
const secretsCache = new Map();
const CACHE_TTL = 3600000; // 1 hour

// AWS Secrets Manager client
let secretsManagerClient = null;

if (isProduction) {
  secretsManagerClient = new SecretsManagerClient({ 
    region: process.env.AWS_REGION || 'us-east-1' 
  });
}

/**
 * Retrieve a secret from AWS Secrets Manager
 * Secrets should be stored as JSON in Secrets Manager
 * 
 * Example secret in AWS Secrets Manager:
 * {
 *   "DATABASE_URL": "postgres://user:pass@host/db",
 *   "API_KEY": "sk-..."
 * }
 */
async function getSecretFromAWS(secretName) {
  try {
    // Check cache first
    const cacheKey = `aws-${secretName}`;
    const cached = secretsCache.get(cacheKey);
    if (cached && cached.expiresAt > Date.now()) {
      console.log(`[CACHE HIT] Retrieved secret from cache: ${secretName}`);
      return cached.value;
    }

    console.log(`[AWS_SM] Fetching secret: ${secretName}`);

    const command = new GetSecretValueCommand({ 
      SecretId: secretName 
    });

    const response = await secretsManagerClient.send(command);

    let secret;
    if ('SecretString' in response) {
      secret = JSON.parse(response.SecretString);
    } else {
      // Handle binary secrets
      secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    // Cache the secret
    secretsCache.set(cacheKey, {
      value: secret,
      expiresAt: Date.now() + CACHE_TTL
    });

    console.log(`[AWS_SM] Successfully retrieved secret: ${secretName}`);
    return secret;
  } catch (error) {
    console.error(`[ERROR] Failed to retrieve secret ${secretName}:`, error.message);
    throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
  }
}

/**
 * Retrieve secrets from environment variables (.env file)
 * Used in development environment
 */
function getSecretsFromEnv() {
  const secrets = {
    DATABASE_URL: process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
  };

  // Validate that all required secrets are present
  const missing = Object.entries(secrets)
    .filter(([_, value]) => !value)
    .map(([key]) => key);

  if (missing.length > 0) {
    console.warn(`[WARNING] Missing secrets: ${missing.join(', ')}`);
  }

  return secrets;
}

/**
 * Initialize all application secrets
 * Call this function on application startup
 */
async function initializeSecrets() {
  try {
    console.log(`[INIT] Initializing secrets (${process.env.NODE_ENV})`);

    if (isProduction) {
      // In production, fetch from AWS Secrets Manager
      console.log('[INIT] Using AWS Secrets Manager');

      const dbSecrets = await getSecretFromAWS('app/database');
