        "secretsmanager:PutSecretValue",
        "secretsmanager:CreateSecret"
      ],
      "Resource": "*"
    }
  ]
}
```

3. Node.js implementation:
```javascript
// config/secrets-aws.js
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION });

class AwsSecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    const now = Date.now();
    const cached = this.cache.get(secretName);

    if (cached && now - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache with timestamp
      this.cache.set(secretName, { value: secret, timestamp: now });
      return secret;
    } catch (err) {
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  // Rotate secret (call this periodically)
  async rotateSecret(secretName) {
    try {
      await secretsManager.rotateSecret({ SecretId: secretName }).promise();
      this.cache.delete(secretName); // Clear cache
      console.log(`Secret rotated: ${secretName}`);
    } catch (err) {
      console.error(`Error rotating secret: ${secretName}`, err);
      throw err;
    }
  }
}

module.exports = new AwsSecretsManager();
