```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    try {
      // Check cache
      if (this.cache[secretName] && 
          Date.now() - this.cache[secretName].timestamp < this.cacheTTL) {
        logger.debug(`Cache hit for secret: ${secretName}`);
        return this.cache[secretName].value;
      }

      logger.info(`Fetching secret from AWS Secrets Manager: ${secretName}`);

      const result = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if ('SecretString' in result) {
        secret = JSON.parse(result.SecretString);
      } else {
        secret = Buffer.from(result.SecretBinary, 'base64').toString('ascii');
      }

      // Cache it
      this.cache[secretName] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (err) {
      logger.error(`Failed to retrieve secret ${secretName}: ${err.message}`);
      throw new Error(`Cannot access secret: ${secretName}`);
    }
  }

  async getDatabase() {
    return this.getSecret('app/database');
  }

  async getAwsCredentials() {
    return this.getSecret('app/aws-credentials');
  }

  async getApiKeys() {
    return this.getSecret('app/api-keys');
  }
}

module.exports = new SecretsManager();
```

