```javascript
// config/secrets.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

class SecretsProvider {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache[secretName] && 
        Date.now() - this.cache[secretName].timestamp < this.cacheTTL) {
      return this.cache[secretName].value;
    }

    try {
      const data = await secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secretValue;
      if (data.SecretString) {
        secretValue = JSON.parse(data.SecretString);
      } else {
        secretValue = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        timestamp: Date.now()
      };

      return secretValue;
    } catch (err) {
      console.error(`Failed to retrieve secret ${secretName}:`, err);
      throw new Error(`Cannot retrieve secret: ${secretName}`);
    }
  }

  async getAllSecrets() {
    return {
      database: await this.getSecret('prod/postgres/credentials'),
      aws: await this.getSecret('prod/aws/credentials'),
      stripe: await this.getSecret('prod/stripe/secret-key'),
      anthropic: await this.getSecret('prod/anthropic/api-key'),
      logfire: await this.getSecret('prod/logfire/token')
    };
  }
}

module.exports = new SecretsProvider();
```

