// config/gcp-secrets.js
const secretManager = require('@google-cloud/secret-manager');

class GCPSecretsProvider {
  constructor() {
    this.client = new secretManager.SecretManagerServiceClient();
    this.projectId = process.env.GCP_PROJECT_ID;
  }

  async getSecret(secretName) {
    const name = this.client.secretVersionPath(
      this.projectId,
      secretName,
      'latest'
    );

    const [version] = await this.client.accessSecretVersion({ name });
    const payload = version.payload.data.toString('utf8');

    try {
      return JSON.parse(payload);
    } catch {
      return payload;
    }
  }

  async createSecret(secretName, secretValue) {
    const parent = this.client.projectPath(this.projectId);

    const [secret] = await this.client.createSecret({
      parent: parent,
      secretId: secretName,
      secret: {}
    });

    await this.client.addSecretVersion({
      parent: secret.name,
      payload: {
        data: Buffer.from(JSON.stringify(secretValue), 'utf8')
      }
    });

    return secret;
  }
}

module.exports = new GCPSecretsProvider();
```

