// config/vault.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN
});

class VaultSecretsProvider {
  async getSecret(path) {
    try {
      const response = await vault.read(path);
      return response.data.data;
    } catch (err) {
      console.error(`Failed to read secret from ${path}:`, err);
      throw err;
    }
  }

  async getSecrets() {
    return {
      database: await this.getSecret('secret/data/prod/database'),
      aws: await this.getSecret('secret/data/prod/aws'),
      stripe: await this.getSecret('secret/data/prod/stripe'),
      anthropic: await this.getSecret('secret/data/prod/anthropic'),
      logfire: await this.getSecret('secret/data/prod/logfire')
    };
  }

  async rotateSecret(path, newValue) {
    try {
      const response = await vault.write(path, { data: newValue });
      console.log(`Secret rotated: ${path}`);
      return response;
    } catch (err) {
      console.error(`Failed to rotate secret: ${path}`, err);
      throw err;
    }
  }
}

