        return JSON.parse(secret.value);
      } catch {
        return secret.value;
      }
    } catch (err) {
      console.error(`Failed to retrieve secret ${secretName}:`, err);
      throw err;
    }
  }

  async setSecret(secretName, secretValue) {
    await this.client.setSecret(secretName, JSON.stringify(secretValue));
  }
}

