      const user = users.find(u => u.id === userId);
      res.json(user);
    }
  );


3. SECURITY HEADERS - BEFORE vs AFTER
======================================

BEFORE (Vulnerable):
  const express = require('express');
  const app = express();
  app.listen(3000);

AFTER (Secure):
  const express = require('express');
  const helmet = require('helmet');
  const app = express();

  app.use(helmet());
  app.use((req, res, next) => {
    res.setHeader('Strict-Transport-Security', 'max-age=31536000');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    next();
  });

  app.listen(3000);


4. RATE LIMITING - BEFORE vs AFTER
===================================

BEFORE (Vulnerable):
  app.post('/login', (req, res) => {
    // No rate limiting - unlimited login attempts
  });

AFTER (Secure):
  const rateLimit = require('express-rate-limit');

  const loginLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 5,
    message: 'Too many login attempts'
  });

  app.post('/login', loginLimiter, (req, res) => {
    // Protected from brute force
  });


5. CORS - BEFORE vs AFTER
==========================

BEFORE (Vulnerable):
  // No CORS setup - allows all origins
  app.get('/api/data', (req, res) => {
    res.json(data);
  });

AFTER (Secure):
  const cors = require('cors');

  app.use(cors({
    origin: ['https://trusted-domain.com'],
    credentials: true,
    methods: ['GET', 'POST'],
    allowedHeaders: ['Content-Type', 'Authorization']
  }));


6. ERROR HANDLING - BEFORE vs AFTER
====================================

BEFORE (Vulnerable):
  app.get('/users/:id', (req, res) => {
    try {
      // code
    } catch (err) {
      // Stack trace exposed to client
      res.status(500).json({ error: err.stack });
    }
  });

AFTER (Secure):
  app.get('/users/:id', (req, res, next) => {
    try {
      // code
    } catch (err) {
      next(err); // Pass to error handler
    }
  });

  app.use((err, req, res, next) => {
    console.error(err); // Log internally
    const message = process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message;
    res.status(500).json({ error: message });
  });


7. SECRETS - BEFORE vs AFTER
=============================

BEFORE (Vulnerable):
  // .env.test committed to git
  DATABASE_URL=postgres://admin:password@host:5432/db
  API_KEY=secret-key-123
  STRIPE_KEY=sk_live_secret

AFTER (Secure):
  // .env.example (no secrets)
  DATABASE_URL=postgresql://user:password@localhost:5432/dbname
  API_KEY=your-api-key-here
  STRIPE_KEY=your-stripe-key-here

  // .gitignore
  .env
  .env*.local
  *.key
  *.pem

  // Use environment variables in CI/CD
  export DATABASE_URL=actual-url-from-secrets-manager


8. DATA SANITIZATION - BEFORE vs AFTER
=======================================

BEFORE (Vulnerable):
  app.post('/search', (req, res) => {
    const query = req.body.query;
    const results = db.find({ name: { $regex: query } });
    res.json(results);
  });

AFTER (Secure):
  const mongoSanitize = require('express-mongo-sanitize');
  const xss = require('xss-clean');

  app.use(mongoSanitize()); // Removes $ and . from input
  app.use(xss()); // Removes malicious HTML

  app.post('/search', (req, res) => {
    const query = req.body.query;
    // Now sanitized
    const results = db.find({ name: { $regex: query } });
    res.json(results);
  });


9. REQUEST SIZE LIMITS - BEFORE vs AFTER
=========================================

BEFORE (Vulnerable):
  app.use(express.json());
  // Accepts unlimited size - DoS risk

AFTER (Secure):
  app.use(express.json({ limit: '10kb' }));
  app.use(express.urlencoded({ limit: '10kb', extended: true }));


10. LOGGING - BEFORE vs AFTER
==============================

BEFORE (Vulnerable):
  app.get('/users', (req, res) => {
    console.log('Getting users');
    res.json(users);
  });

AFTER (Secure):
  const logSecurityEvent = (req, level, message, metadata) => {
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      level,
      message,
      ip: req.ip,
      user: req.user?.id || 'anonymous',
      method: req.method,
      path: req.path,
      ...metadata
    }));
  };

  app.get('/users', validateApiKey, (req, res) => {
    try {
      logSecurityEvent(req, 'INFO', 'Users retrieved');
      res.json(users);
    } catch (error) {
      logSecurityEvent(req, 'ERROR', 'Error retrieving users', {
        error: error.message
      });
      res.status(500).json({ error: 'Internal server error' });
    }
  });


QUICK START - SECURE APP.JS
=============================

Step 1: Install dependencies
  npm install express helmet express-rate-limit \
    express-mongo-sanitize xss-clean cors validator dotenv

Step 2: Use the provided app_SECURE.js
  cp app_SECURE.js app.js

Step 3: Configure environment
