/**
 * Secure Express.js Application
 * Implements OWASP Top 10 protections and security best practices
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
  exceptionHandlers: [
    new winston.transports.File({ filename: 'exceptions.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// CONFIGURATION
// ============================================================================

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-this';

if (!process.env.JWT_SECRET && NODE_ENV === 'production') {
  logger.error('CRITICAL: JWT_SECRET not set in production environment');
  process.exit(1);
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers (Helmet.js)
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
  },
}));

app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true,
}));

// 2. CORS Configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));

// 3. Request Logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim()),
  },
  skip: (req, res) => res.statusCode < 400,
}));

// 4. Body Parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 5. Rate Limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn({
      event: 'rate_limit_exceeded',
      ip: req.ip,
      path: req.path,
      timestamp: new Date().toISOString(),
    });
    res.status(429).json({
      error: 'Too many requests, please try again later.',
    });
  },
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for auth endpoints
  skipSuccessfulRequests: true,
  message: 'Too many authentication attempts, please try again later.',
});

app.use(generalLimiter);

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      event: 'missing_auth_token',
      ip: req.ip,
      path: req.path,
      timestamp: new Date().toISOString(),
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({
        event: 'invalid_token',
        ip: req.ip,
        error: err.message,
        timestamp: new Date().toISOString(),
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

const validateGetUsersQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be an integer between 1 and 100'),
  query('sort')
    .optional()
    .isIn(['id', 'name'])
    .withMessage('Sort must be either "id" or "name"'),
];

// ============================================================================
// HEALTH CHECK ENDPOINT
// ============================================================================

/**
 * GET /health
 * Public endpoint for health checks (no auth required)
 * Rate limited but not authenticated
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      // Only expose environment in development
      ...(NODE_ENV === 'development' && { environment: NODE_ENV }),
    });
  } catch (error) {
    logger.error({
      event: 'health_check_error',
      error: error.message,
      timestamp: new Date().toISOString(),
    });
    res.status(500).json({ error: 'Health check failed' });
  }
});

// ============================================================================
// PROTECTED ENDPOINTS
// ============================================================================

/**
 * GET /api/v1/users
 * Retrieve list of users (paginated)
 * Requires authentication
 * Supports filtering and sorting
 */
app.get('/api/v1/users',
  authenticateToken,
  validateGetUsersQuery,
  (req, res, next) => {
    try {
      // Validate inputs
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn({
          event: 'invalid_input',
          userId: req.user?.id,
          errors: errors.array(),
          timestamp: new Date().toISOString(),
        });
        return res.status(400).json({
          error: 'Invalid input parameters',
          details: errors.array(),
        });
      }

      // Safe to use validated inputs
      const limit = req.query.limit || 10;
      const sort = req.query.sort || 'id';

      // Mock database
      let users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
        { id: 3, name: 'Charlie' },
      ];

      // Apply sorting
      if (sort === 'name') {
        users.sort((a, b) => a.name.localeCompare(b.name));
      }

      // Apply pagination
      const paginatedUsers = users.slice(0, limit);

      // Log successful access
      logger.info({
        event: 'users_retrieved',
        userId: req.user?.id,
        count: paginatedUsers.length,
        timestamp: new Date().toISOString(),
      });

      res.status(200).json({
        data: paginatedUsers,
        count: paginatedUsers.length,
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * GET /api/v1/users/:id
 * Retrieve a specific user
 * Requires authentication
 */
app.get('/api/v1/users/:id',
  authenticateToken,
  (req, res, next) => {
    try {
      const userId = parseInt(req.params.id);

      if (isNaN(userId) || userId < 1) {
        logger.warn({
          event: 'invalid_user_id',
          userId: req.user?.id,
          requestedId: req.params.id,
          timestamp: new Date().toISOString(),
        });
        return res.status(400).json({
          error: 'Invalid user ID',
        });
      }

      // Mock database lookup
      const users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
        { id: 3, name: 'Charlie' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      logger.info({
        event: 'user_retrieved',
        userId: req.user?.id,
        targetUserId: userId,
        timestamp: new Date().toISOString(),
      });

      res.status(200).json({
        data: user,
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * POST /api/v1/login
 * Login endpoint to get JWT token
 */
app.post('/api/v1/login',
  authLimiter,
  express.json(),
  (req, res, next) => {
    try {
      const { username, password } = req.body;

      // Validate input
      if (!username || !password) {
        logger.warn({
          event: 'login_attempt_missing_credentials',
          ip: req.ip,
          timestamp: new Date().toISOString(),
        });
        return res.status(400).json({
          error: 'Username and password are required',
        });
      }

      // In production, verify against database with bcrypt
      // This is a simplified example
      if (username === 'demo' && password === 'demo') {
        const token = jwt.sign(
          { id: 1, username: 'demo' },
          JWT_SECRET,
          { expiresIn: '1h' }
        );

        logger.info({
          event: 'successful_login',
          username: username,
          ip: req.ip,
          timestamp: new Date().toISOString(),
        });

        return res.status(200).json({
          token,
          expiresIn: '1h',
        });
      }

      logger.warn({
        event: 'failed_login',
        username: username,
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });

      res.status(401).json({
        error: 'Invalid credentials',
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * 404 Handler
 */
app.use((req, res) => {
  logger.warn({
    event: '404_not_found',
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  res.status(404).json({
    error: 'Endpoint not found',
    path: req.path,
  });
});

/**
 * Global Error Handler
 */
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    userId: req.user?.id,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  const isProduction = NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: isProduction
      ? 'Internal server error'
      : err.message,
    // Only expose stack in development
    ...(NODE_ENV === 'development' && {
      stack: err.stack,
    }),
    timestamp: new Date().toISOString(),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info({
    event: 'server_started',
    port: PORT,
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
  });
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info({
    event: 'sigterm_received',
    timestamp: new Date().toISOString(),
  });

  server.close(() => {
    logger.info({
      event: 'server_closed',
      timestamp: new Date().toISOString(),
    });
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    logger.error({
      event: 'forced_shutdown',
      timestamp: new Date().toISOString(),
    });
    process.exit(1);
  }, 10000);
});

process.on('SIGINT', () => {
  logger.info({
    event: 'sigint_received',
    timestamp: new Date().toISOString(),
  });
  process.exit(0);
});

module.exports = app;

