If you can't immediately migrate to a secrets manager, implement this safer .env approach:

```javascript
// config/secrets.js
require('dotenv').config();

const requiredSecrets = [
  'JWT_SECRET',
  'NODE_ENV',
  'PORT'
];

const productionSecrets = [
  'JWT_SECRET',
  'DB_HOST',
  'DB_PORT',
  'DB_NAME',
  'DB_USER',
  'DB_PASSWORD',
  'ALLOWED_ORIGINS'
];

function validateSecrets() {
  const isProduction = process.env.NODE_ENV === 'production';
  const secretsToCheck = isProduction ? productionSecrets : requiredSecrets;

  const missing = secretsToCheck.filter(secret => !process.env[secret]);

  if (missing.length > 0) {
    console.error(`CRITICAL: Missing required secrets: ${missing.join(', ')}`);
    process.exit(1);
  }

  // Validate secret strength
  const jwtSecret = process.env.JWT_SECRET;
  if (jwtSecret.length < 32) {
    console.error('CRITICAL: JWT_SECRET must be at least 32 characters');
    process.exit(1);
  }

  if (isProduction && jwtSecret === 'your-secret-key-change-this') {
    console.error('CRITICAL: Default JWT_SECRET used in production!');
    process.exit(1);
  }
}

// Validate on startup
validateSecrets();

module.exports = {
  jwtSecret: process.env.JWT_SECRET,
  dbHost: process.env.DB_HOST,
  dbPort: process.env.DB_PORT,
  dbName: process.env.DB_NAME,
  dbUser: process.env.DB_USER,
  dbPassword: process.env.DB_PASSWORD,
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(','),
