/**
 * Secure Express.js Application
 * 
 * This is an improved version of app.js with security best practices implemented.
 * For production use, ensure all environment variables are properly configured.
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security headers
app.use(helmet());

// 2. CORS configuration
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
    if (!origin || allowedOrigins.includes(origin.trim())) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// 3. Body parsing with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: false }));

// 4. Request logging
const morganFormat = process.env.NODE_ENV === 'production' ? 'combined' : 'dev';
app.use(morgan(morganFormat));

// 5. Rate limiting - global
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => process.env.NODE_ENV !== 'production',
});
app.use(globalLimiter);

// 6. Rate limiting - auth endpoint (stricter)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts',
  skipSuccessfulRequests: true,
});

// 7. Disable x-powered-by header
if (process.env.NODE_ENV === 'production') {
  app.disable('x-powered-by');
}

// ============================================================================
// SECURITY UTILITIES
// ============================================================================

/**
 * Verify JWT token
 */
const verifyToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logSecurityEvent('AUTH_FAILED', {
      reason: 'Missing token',
      ip: req.ip,
      path: req.path,
      method: req.method,
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      logSecurityEvent('AUTH_FAILED', {
        reason: 'Invalid/expired token',
        ip: req.ip,
        path: req.path,
        method: req.method,
        error: err.message,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

/**
 * Check user authorization (role-based)
 */
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logSecurityEvent('AUTHORIZATION_FAILED', {
        userId: req.user.id,
        requiredRole: allowedRoles,
        userRole: req.user.role,
        path: req.path,
        method: req.method,
        ip: req.ip,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

/**
 * Log security events
 */
const logSecurityEvent = (eventType, details) => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    level: 'SECURITY',
    eventType,
    ...details,
  };
  console.error(JSON.stringify(logEntry));
};

// ============================================================================
// PUBLIC ENDPOINTS (No Authentication Required)
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// ============================================================================
// PROTECTED ENDPOINTS (Authentication Required)
// ============================================================================

/**
 * Get list of users (admin only)
 * GET /users
 * Authorization: Bearer <token>
 */
app.get('/users', verifyToken, authorize('admin', 'user_manager'), (req, res) => {
  // Note: Sensitive data (email) is NOT exposed
  const users = [
    { id: 1, name: 'Alice', createdAt: '2024-01-15' },
    { id: 2, name: 'Bob', createdAt: '2024-01-16' },
  ];

  logSecurityEvent('USERS_LIST_ACCESSED', {
    userId: req.user.id,
    userRole: req.user.role,
    ip: req.ip,
  });

  res.status(200).json(users);
});

/**
 * Get current user profile (authenticated users)
 * GET /profile
 * Authorization: Bearer <token>
 */
app.get('/profile', verifyToken, (req, res) => {
  res.status(200).json({
    id: req.user.id,
    name: req.user.name,
    role: req.user.role,
  });
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * Handle CORS errors
 */
app.use((err, req, res, next) => {
  if (err.message === 'Not allowed by CORS') {
    logSecurityEvent('CORS_ERROR', {
      origin: req.get('origin'),
      path: req.path,
      method: req.method,
      ip: req.ip,
    });
    return res.status(403).json({ error: 'CORS policy violation' });
  }
  next(err);
});

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  logSecurityEvent('NOT_FOUND', {
    path: req.path,
    method: req.method,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not Found' });
});

/**
 * Global error handler (must be last)
 */
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';

  logSecurityEvent('ERROR', {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    stack: err.stack,
  });

  const statusCode = err.status || err.statusCode || 500;
  const response = {
    error: isDevelopment ? err.message : 'Internal Server Error',
  };

  // Only expose stack trace in development
  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER INITIALIZATION
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`✓ Server running on port ${PORT}`);
  console.log(`✓ Environment: ${NODE_ENV}`);
  console.log(`✓ Timestamp: ${new Date().toISOString()}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

