/**
 * Secrets Configuration Manager
 * 
 * This module handles loading secrets from various sources:
 * - Environment variables
 * - AWS Secrets Manager
 * - HashiCorp Vault
 * - Azure Key Vault
 * - Local .env files (development only)
 */

require('dotenv').config();
const path = require('path');

/**
 * Secret configuration interface
 */
class SecretsManager {
  constructor() {
    this.secrets = {};
    this.source = {};
    this.initialized = false;
  }

  /**
   * Initialize secrets from appropriate source based on environment
   */
  async initialize() {
    const nodeEnv = process.env.NODE_ENV || 'development';

    try {
      switch (nodeEnv) {
        case 'production':
          await this.loadFromAWSSecretsManager();
          break;
        case 'staging':
          await this.loadFromVault();
          break;
        case 'development':
          this.loadFromEnv();
          this.validateDevSecrets();
          break;
        default:
          this.loadFromEnv();
      }

      this.validateRequiredSecrets();
      this.initialized = true;
      console.log('✓ Secrets loaded successfully');
    } catch (error) {
      console.error('✗ Failed to load secrets:', error.message);
      throw error;
    }
  }

  /**
   * Load secrets from environment variables
   * ONLY for development - never use in production
   */
  loadFromEnv() {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('CRITICAL: Cannot load secrets from .env in production!');
    }

    this.secrets = {
      // JWT Configuration
      jwt: {
        secret: process.env.JWT_SECRET,
        algorithm: process.env.JWT_ALGORITHM || 'HS256',
        expiresIn: process.env.JWT_EXPIRES_IN || '1h',
        refreshExpiresIn: process.env.JWT_REFRESH_EXPIRES_IN || '7d',
      },

      // Database Credentials
      database: {
        host: process.env.DB_HOST,
        port: process.env.DB_PORT,
        username: process.env.DB_USER,
        password: process.env.DB_PASSWORD,
        database: process.env.DB_NAME,
        ssl: process.env.DB_SSL === 'true',
      },

      // API Keys
      api: {
        sendgridKey: process.env.SENDGRID_API_KEY,
        stripeKey: process.env.STRIPE_SECRET_KEY,
        twilioAccountSid: process.env.TWILIO_ACCOUNT_SID,
        twilioAuthToken: process.env.TWILIO_AUTH_TOKEN,
      },

      // OAuth Credentials
      oauth: {
        googleClientId: process.env.GOOGLE_CLIENT_ID,
        googleClientSecret: process.env.GOOGLE_CLIENT_SECRET,
        githubClientId: process.env.GITHUB_CLIENT_ID,
        githubClientSecret: process.env.GITHUB_CLIENT_SECRET,
      },

      // Application Configuration
      app: {
        corsOrigins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
        port: process.env.PORT || 3000,
        nodeEnv: process.env.NODE_ENV,
      },
    };

    this.source = {
      jwt: 'environment',
      database: 'environment',
      api: 'environment',
      oauth: 'environment',
      app: 'environment',
    };
  }

  /**
   * Load secrets from AWS Secrets Manager
   * Recommended for production AWS deployments
   */
  async loadFromAWSSecretsManager() {
    try {
      const AWS = require('aws-sdk');
      const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

      const secrets = await Promise.all([
        this.getAWSSecret(client, 'prod/app/jwt'),
        this.getAWSSecret(client, 'prod/app/database'),
        this.getAWSSecret(client, 'prod/app/api-keys'),
        this.getAWSSecret(client, 'prod/app/oauth'),
      ]);

      this.secrets = {
        jwt: secrets[0],
        database: secrets[1],
        api: secrets[2],
        oauth: secrets[3],
        app: {
          corsOrigins: (process.env.ALLOWED_ORIGINS || '').split(','),
          port: process.env.PORT || 3000,
          nodeEnv: 'production',
        },
      };

      this.source = {
        jwt: 'AWS Secrets Manager',
        database: 'AWS Secrets Manager',
        api: 'AWS Secrets Manager',
        oauth: 'AWS Secrets Manager',
        app: 'environment',
      };
    } catch (error) {
      throw new Error(`Failed to load from AWS Secrets Manager: ${error.message}`);
    }
  }

  /**
   * Load secrets from HashiCorp Vault
   * Recommended for on-premise deployments
   */
  async loadFromVault() {
    try {
      const vault = require('node-vault');
      const client = vault({
        endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
        token: process.env.VAULT_TOKEN,
      });

      const secrets = await Promise.all([
        client.read('secret/data/app/jwt'),
        client.read('secret/data/app/database'),
        client.read('secret/data/app/api-keys'),
        client.read('secret/data/app/oauth'),
      ]);

      this.secrets = {
        jwt: secrets[0].data.data,
        database: secrets[1].data.data,
        api: secrets[2].data.data,
        oauth: secrets[3].data.data,
        app: {
          corsOrigins: (process.env.ALLOWED_ORIGINS || '').split(','),
          port: process.env.PORT || 3000,
          nodeEnv: 'staging',
        },
      };

      this.source = {
        jwt: 'HashiCorp Vault',
        database: 'HashiCorp Vault',
        api: 'HashiCorp Vault',
        oauth: 'HashiCorp Vault',
        app: 'environment',
      };
    } catch (error) {
      throw new Error(`Failed to load from Vault: ${error.message}`);
    }
  }

  /**
   * Get secret from AWS Secrets Manager with caching and rotation
   */
  async getAWSSecret(client, secretId) {
    try {
      const response = await client.getSecretValue({ SecretId: secretId }).promise();

      if ('SecretString' in response) {
        return JSON.parse(response.SecretString);
      } else {
        return Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }
    } catch (error) {
      throw new Error(`Failed to retrieve secret ${secretId}: ${error.message}`);
    }
  }

  /**
   * Validate that all required secrets are present
   */
  validateRequiredSecrets() {
    const required = ['jwt', 'database', 'api', 'oauth'];

    for (const key of required) {
      if (!this.secrets[key]) {
        throw new Error(`CRITICAL: Missing required secret configuration: ${key}`);
      }
    }

    // JWT secret must be strong (minimum 32 characters)
    if (this.secrets.jwt.secret && this.secrets.jwt.secret.length < 32) {
      throw new Error('CRITICAL: JWT_SECRET must be at least 32 characters');
    }

    // Database credentials must be present
    if (!this.secrets.database.password || !this.secrets.database.username) {
      throw new Error('CRITICAL: Database credentials missing');
    }
  }

  /**
   * Validate development-only secrets
   */
  validateDevSecrets() {
    console.warn('⚠️  DEVELOPMENT MODE: Using secrets from .env file');
    console.warn('⚠️  NEVER use .env files in production');

    if (!this.secrets.jwt.secret) {
      throw new Error('Missing JWT_SECRET in .env');
    }

    if (this.secrets.jwt.secret === 'your-super-secret-key-change-this-to-a-strong-value') {
      throw new Error('CRITICAL: Using default JWT_SECRET - change it immediately!');
    }
  }

  /**
   * Get a specific secret value
   * @param {string} path - Path to secret (e.g., 'jwt.secret')
   * @returns {string|object} The secret value
   */
  get(path) {
    const keys = path.split('.');
    let value = this.secrets;

    for (const key of keys) {
      if (value[key] === undefined) {
        throw new Error(`Secret not found: ${path}`);
      }
      value = value[key];
    }

    return value;
  }

  /**
   * Get all secrets (for logging purposes - should only show sources, not values)
   */
  getMetadata() {
    return {
      initialized: this.initialized,
      sources: this.source,
      timestamp: new Date().toISOString(),
    };
  }

  /**
   * Rotate secrets (for services that support it)
   */
  async rotate() {
    if (process.env.NODE_ENV === 'production') {
      console.log('Rotating secrets from secrets manager...');
      await this.initialize();
      console.log('✓ Secrets rotated successfully');
    } else {
      console.warn('Secret rotation not performed in development mode');
    }
  }
}

