        userRole: req.user.role,
        path: req.path,
        method: req.method,
        ip: req.ip,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

/**
 * Log security events (NEVER log secret values)
 */
const logSecurityEvent = (eventType, details) => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    level: 'SECURITY',
    eventType,
    ...details,
  };
  console.error(JSON.stringify(logEntry));
};

// ============================================================================
// PUBLIC ENDPOINTS
// ============================================================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV,
  });
});

/**
 * Readiness check - verifies secrets are loaded
 */
app.get('/ready', (req, res) => {
  if (!secrets || !secrets.initialized) {
    return res.status(503).json({ status: 'not ready', error: 'Secrets not initialized' });
  }
  res.status(200).json({ status: 'ready', timestamp: new Date().toISOString() });
});

// ============================================================================
// PROTECTED ENDPOINTS
// ============================================================================

/**
 * Get list of users (admin only)
 */
app.get('/users', verifyToken, authorize('admin', 'user_manager'), (req, res) => {
  const users = [
    { id: 1, name: 'Alice', createdAt: '2024-01-15' },
    { id: 2, name: 'Bob', createdAt: '2024-01-16' },
  ];

  logSecurityEvent('USERS_LIST_ACCESSED', {
    userId: req.user.id,
    userRole: req.user.role,
    ip: req.ip,
  });

  res.status(200).json(users);
});

/**
 * Get current user profile
 */
app.get('/profile', verifyToken, (req, res) => {
  res.status(200).json({
    id: req.user.id,
    name: req.user.name,
    role: req.user.role,
  });
});

/**
 * Generate JWT token (for demonstration/testing only)
 * In production, use OAuth2 or similar
 */
app.post('/generate-token', (req, res) => {
  // This is for demonstration - in production, authenticate user first
  const user = {
    id: 1,
    name: 'Test User',
    role: 'admin',
  };

  const jwtSecret = secrets.get('jwt.secret');
  const jwtAlgorithm = secrets.get('jwt.algorithm');
  const expiresIn = secrets.get('jwt.expiresIn');

  const token = jwt.sign(user, jwtSecret, {
    algorithm: jwtAlgorithm,
    expiresIn: expiresIn,
  });

  res.status(200).json({ token });
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * Handle CORS errors
 */
app.use((err, req, res, next) => {
  if (err.message === 'Not allowed by CORS') {
    logSecurityEvent('CORS_ERROR', {
      origin: req.get('origin'),
      path: req.path,
      method: req.method,
      ip: req.ip,
    });
    return res.status(403).json({ error: 'CORS policy violation' });
  }
  next(err);
});

/**
 * 404 handler
 */
app.use((req, res) => {
  logSecurityEvent('NOT_FOUND', {
    path: req.path,
    method: req.method,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not Found' });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  const nodeEnv = secrets ? secrets.get('app.nodeEnv') : process.env.NODE_ENV;
  const isDevelopment = nodeEnv === 'development';

  logSecurityEvent('ERROR', {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    // Only log stack in development
    stack: isDevelopment ? err.stack : undefined,
  });

  const statusCode = err.status || err.statusCode || 500;
  const response = {
    error: isDevelopment ? err.message : 'Internal Server Error',
  };

  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

/**
 * Start the server
 */
async function startServer() {
  try {
    // Initialize secrets first
    await initializeApp();

    // Setup middleware after secrets are loaded
    setupSecurityMiddleware();

    // Start listening
    const port = secrets.get('app.port');
    const nodeEnv = secrets.get('app.nodeEnv');

    const server = app.listen(port, () => {
      console.log(`✓ Server running on port ${port}`);
      console.log(`✓ Environment: ${nodeEnv}`);
      console.log(`✓ Secrets initialized: Yes`);
      console.log(`✓ Timestamp: ${new Date().toISOString()}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('SIGTERM received. Shutting down gracefully...');
      server.close(() => {
        console.log('Server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    console.error('Failed to start server:', error.message);
    process.exit(1);
  }
}

// Start server if this is the main module
if (require.main === module) {
  startServer();
}

module.exports = app;

