/**
 * Secrets Management Module
 * Handles loading secrets from various sources with fallback to .env
 * 
 * Priority order:
 * 1. AWS Secrets Manager (production)
 * 2. HashiCorp Vault (multi-environment)
 * 3. GCP Secret Manager (GCP deployments)
 * 4. Azure Key Vault (Azure deployments)
 * 5. Environment variables from .env (development only)
 */

const path = require('path');

// Load .env only for development/fallback
if (process.env.NODE_ENV !== 'production' || !process.env.SECRETS_MANAGER_TYPE) {
  require('dotenv').config({ path: path.join(__dirname, '.env.local') });
}

const logger = require('./logger'); // Assuming you have a logger

class SecretsManager {
  constructor() {
    this.secrets = null;
    this.lastLoadTime = null;
    this.cacheExpiry = 3600000; // 1 hour in milliseconds
  }

  /**
   * Get secrets with intelligent caching and failover
   */
  async getSecrets(forceRefresh = false) {
    // Return cached secrets if still valid
    if (
      this.secrets &&
      !forceRefresh &&
      Date.now() - this.lastLoadTime < this.cacheExpiry
    ) {
      logger.debug('Returning cached secrets');
      return this.secrets;
    }

    try {
      const managerType = process.env.SECRETS_MANAGER_TYPE || 'env';

      logger.info(`Loading secrets from: ${managerType}`);

      switch (managerType) {
        case 'aws':
          this.secrets = await this.loadFromAWSSecretsManager();
          break;
        case 'vault':
          this.secrets = await this.loadFromVault();
          break;
        case 'gcp':
          this.secrets = await this.loadFromGCPSecretManager();
          break;
        case 'azure':
          this.secrets = await this.loadFromAzureKeyVault();
          break;
        case 'env':
        default:
          this.secrets = this.loadFromEnvironment();
          break;
      }

      this.lastLoadTime = Date.now();
      this.validateSecrets(this.secrets);

      logger.info('Secrets loaded successfully');
      return this.secrets;
    } catch (error) {
      logger.error('Failed to load secrets', { error: error.message });

      // Fallback to environment variables
      if (process.env.NODE_ENV !== 'production') {
        logger.warn('Falling back to environment variables');
        this.secrets = this.loadFromEnvironment();
        return this.secrets;
      }

      throw new Error('Critical: Unable to load secrets and not in development mode');
    }
  }

  /**
   * AWS Secrets Manager
   */
  async loadFromAWSSecretsManager() {
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const secretName = process.env.AWS_SECRETS_MANAGER_NAME || 'app/secrets';

    try {
      const data = await client.getSecretValue({ SecretId: secretName }).promise();

      if ('SecretString' in data) {
        return JSON.parse(data.SecretString);
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        return JSON.parse(buff.toString('ascii'));
      }
    } catch (error) {
      logger.error('AWS Secrets Manager error', { error: error.message });
      throw error;
    }
  }

  /**
   * HashiCorp Vault
   */
  async loadFromVault() {
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN
    });

    const vaultPath = process.env.VAULT_SECRET_PATH || 'secret/data/app/production';

    try {
      const result = await vault.read(vaultPath);

      // Handle Vault KV v2 format
      if (result.data.data) {
        return result.data.data;
      }

      return result.data;
    } catch (error) {
      logger.error('Vault error', { error: error.message });
      throw error;
    }
  }

  /**
   * Google Cloud Secret Manager
   */
  async loadFromGCPSecretManager() {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    const client = new SecretManagerServiceClient();

    const projectId = process.env.GCP_PROJECT_ID;
    const secretName = process.env.GCP_SECRET_NAME || 'app-secrets';

    try {
      const name = client.projectSecretVersionPath(projectId, secretName, 'latest');
      const [version] = await client.accessSecretVersion({ name });

      const secret = version.payload.data.toString('utf8');
      return JSON.parse(secret);
    } catch (error) {
      logger.error('GCP Secret Manager error', { error: error.message });
      throw error;
    }
  }

  /**
   * Azure Key Vault
   */
  async loadFromAzureKeyVault() {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const keyVaultUrl = process.env.KEYVAULT_VAULT_URL;

    if (!keyVaultUrl) {
      throw new Error('KEYVAULT_VAULT_URL environment variable is required');
    }

    try {
      const credential = new DefaultAzureCredential();
      const client = new SecretClient(keyVaultUrl, credential);

      const secretNames = [
        'DatabaseUrl',
        'JwtSecret',
        'AwsAccessKeyId',
        'AwsSecretAccessKey',
        'ApiKeys'
      ];

      const secrets = {};

      for (const secretName of secretNames) {
        try {
          const secret = await client.getSecret(secretName);
          secrets[this.camelToSnakeCase(secretName)] = secret.value;
        } catch (error) {
          logger.warn(`Secret not found in Azure: ${secretName}`);
        }
      }

      return secrets;
    } catch (error) {
      logger.error('Azure Key Vault error', { error: error.message });
      throw error;
    }
  }

  /**
   * Load from environment variables (development/fallback)
   */
  loadFromEnvironment() {
    return {
      DATABASE_URL: process.env.DATABASE_URL,
      JWT_SECRET: process.env.JWT_SECRET,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
    };
  }

  /**
   * Validate that all required secrets are present
   */
  validateSecrets(secrets) {
    const required = ['JWT_SECRET', 'DATABASE_URL'];

    for (const key of required) {
      if (!secrets[key]) {
        throw new Error(`Required secret missing: ${key}`);
      }
    }

    logger.debug('Secrets validation passed');
  }

  /**
   * Utility: Convert camelCase to SNAKE_CASE
   */
  camelToSnakeCase(str) {
    return str
      .replace(/([A-Z])/g, '_$1')
      .toUpperCase()
      .substring(1);
  }

  /**
   * Trigger secret refresh (useful for rotation)
   */
  async refreshSecrets() {
    logger.info('Refreshing secrets');
    return this.getSecrets(true);
  }

  /**
   * Get a specific secret
   */
  async get(key) {
    const secrets = await this.getSecrets();
    return secrets[key];
  }
}

