/**
 * Secure Logger Module
 * Ensures sensitive information is never logged
 */

const winston = require('winston');
const path = require('path');

// List of sensitive keys that should never be logged
const SENSITIVE_KEYS = [
  'password',
  'secret',
  'token',
  'api_key',
  'apikey',
  'access_key',
  'secret_key',
  'private_key',
  'jwt',
  'authorization',
  'cookie',
  'session',
  'credit_card',
  'ssn',
  'aws_secret',
  'stripe',
  'database_url'
];

/**
 * Redact sensitive information from objects
 */
function redactSensitiveData(obj, depth = 0) {
  if (depth > 10) return obj; // Prevent infinite recursion

  if (obj === null || typeof obj !== 'object') {
    return obj;
  }

  if (Array.isArray(obj)) {
    return obj.map(item => redactSensitiveData(item, depth + 1));
  }

  const redacted = { ...obj };

  for (const key in redacted) {
    if (redacted.hasOwnProperty(key)) {
      const lowerKey = key.toLowerCase();

      // Check if key is sensitive
      if (SENSITIVE_KEYS.some(sensitive => lowerKey.includes(sensitive))) {
        redacted[key] = '[REDACTED]';
      } else if (typeof redacted[key] === 'object') {
        redacted[key] = redactSensitiveData(redacted[key], depth + 1);
      }
    }
  }

  return redacted;
}

/**
 * Create Winston logger with secure formatting
 */
function createLogger() {
  const logLevel = process.env.LOG_LEVEL || 'info';

  const customFormat = winston.format.printf(({ level, message, timestamp, ...metadata }) => {
    // Redact sensitive data from metadata
    const safeMetadata = redactSensitiveData(metadata);

    let log = `${timestamp} [${level.toUpperCase()}] ${message}`;

    if (Object.keys(safeMetadata).length > 0) {
      log += ` ${JSON.stringify(safeMetadata)}`;
    }

    return log;
  });

  return winston.createLogger({
    level: logLevel,
    format: winston.format.combine(
      winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
      customFormat
    ),
    defaultMeta: { service: 'app' },
    transports: [
      // Error logs
      new winston.transports.File({
        filename: path.join(__dirname, 'logs', 'error.log'),
        level: 'error',
        maxsize: 10485760, // 10MB
        maxFiles: 5,
      }),
      // Combined logs
      new winston.transports.File({
        filename: path.join(__dirname, 'logs', 'combined.log'),
        maxsize: 10485760, // 10MB
        maxFiles: 5,
      }),
      // Security events
      new winston.transports.File({
        filename: path.join(__dirname, 'logs', 'security.log'),
        level: 'warn',
        maxsize: 10485760, // 10MB
        maxFiles: 10,
      }),
    ],
  });
}

// Add console transport for development
function createDevelopmentLogger() {
  const logger = createLogger();

  if (process.env.NODE_ENV !== 'production') {
    logger.add(new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      ),
    }));
  }

  return logger;
}

// Create singleton logger
const logger = createDevelopmentLogger();

module.exports = logger;

