require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const jwt = require('jsonwebtoken');

const logger = require('./logger');
const { getInstance: getSecretsManager } = require('./secrets-manager');

const app = express();

// ==================== CONFIGURATION ====================

const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;

// ==================== SECURITY MIDDLEWARE ====================

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};
app.use(cors(corsOptions));

// 3. Body Parser with Size Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data Sanitization
app.use(mongoSanitize());

// 5. Request Logging Middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info(`${req.method} ${req.path}`, {
      ip: req.ip,
      status: res.statusCode,
      duration: `${duration}ms`,
      userAgent: req.get('user-agent'),
    });
  });

  next();
});

// 6. HTTPS Enforcement (production)
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// ==================== RATE LIMITING ====================

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn('Rate limit exceeded', { ip: req.ip, path: req.path });
    res.status(429).json({ error: 'Too many requests' });
  },
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  handler: (req, res) => {
    logger.warn('Authentication rate limit exceeded', { ip: req.ip });
    res.status(429).json({ error: 'Too many authentication attempts' });
  },
});

app.use(generalLimiter);

// ==================== AUTHENTICATION ====================

let secrets = null;

/**
 * Load secrets at application startup
 */
async function initializeSecrets() {
  try {
    const secretsManager = getSecretsManager();
    secrets = await secretsManager.getSecrets();

    if (!secrets.JWT_SECRET) {
      throw new Error('JWT_SECRET is required but not found');
    }

    logger.info('Secrets loaded successfully');
  } catch (error) {
    logger.error('Failed to initialize secrets', { error: error.message });
    process.exit(1);
  }
}

/**
 * Authenticate JWT token
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn('Authentication attempt without token', { ip: req.ip });
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const user = jwt.verify(token, secrets.JWT_SECRET);
    req.user = user;
    next();
  } catch (error) {
    logger.warn('Invalid token attempt', {
      ip: req.ip,
      error: error.message,
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ==================== ROUTES ====================

/**
 * Health check endpoint (no auth required)
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
      uptime: process.uptime(),
    });
  } catch (error) {
    logger.error('Health check error', { error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Users endpoint (requires authentication)
 */
app.get('/users', authLimiter, authenticateToken, (req, res) => {
  try {
    // Filter data based on user role/permissions
    const isAdmin = req.user?.role === 'admin';

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Regular users see limited data, admins see everything
    const filteredUsers = users.map(user => {
      if (isAdmin) {
        return user;
      }
      return { id: user.id, name: user.name };
    });

    logger.info('Users retrieved', {
      userId: req.user?.id,
      count: filteredUsers.length,
    });

    res.json(filteredUsers);
  } catch (error) {
    logger.error('Error retrieving users', { error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Error handling middleware
 */
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't expose internal errors to client
  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ==================== STARTUP ====================

/**
 * Initialize and start server
 */
async function startServer() {
  try {
    // Load secrets first
    await initializeSecrets();

    // Start listening
    app.listen(PORT, () => {
      logger.info(`Server running`, {
        port: PORT,
        environment: NODE_ENV,
        timestamp: new Date().toISOString(),
      });
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM signal received: closing HTTP server');
      server.close(() => {
        logger.info('HTTP server closed');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      logger.info('SIGINT signal received: closing HTTP server');
      server.close(() => {
        logger.info('HTTP server closed');
        process.exit(0);
      });
    });
  } catch (error) {
    logger.error('Failed to start server', { error: error.message });
    process.exit(1);
  }
}

// Only start if this is the main module
if (require.main === module) {
  startServer();
}

module.exports = app;

