```javascript
require('dotenv').config(); // Only for non-secrets config
const express = require('express');
const helmet = require('helmet');
const AWS = require('aws-sdk');

const app = express();
const secretsClient = new AWS.SecretsManager();

let cachedSecrets = null;
const SECRET_CACHE_TTL = 3600000; // 1 hour
let secretsCachTime = 0;

/**
 * Retrieves secrets from AWS Secrets Manager with caching
 */
async function getSecrets() {
  const now = Date.now();

  // Return cached secrets if still valid
  if (cachedSecrets && (now - secretsCacheTime) < SECRET_CACHE_TTL) {
    return cachedSecrets;
  }

  try {
    const data = await secretsClient
      .getSecretValue({ SecretId: process.env.SECRETS_NAME })
      .promise();

    if ('SecretString' in data) {
      cachedSecrets = JSON.parse(data.SecretString);
      secretsCacheTime = now;
      return cachedSecrets;
    }
  } catch (error) {
    console.error('Failed to retrieve secrets from AWS:', error);
    // Fallback to cached secrets or throw
    if (cachedSecrets) {
      console.warn('Using cached secrets due to retrieval failure');
      return cachedSecrets;
    }
    throw new Error('Secrets unavailable');
  }
}

/**
 * Initialize application with secrets
 */
async function initializeApp() {
  const secrets = await getSecrets();

  // Validate required secrets
  const required = ['JWT_SECRET', 'DB_PASSWORD', 'API_KEY'];
  for (const secret of required) {
    if (!secrets[secret]) {
      throw new Error(`Missing required secret: ${secret}`);
    }
  }

  return secrets;
}

