// IMPLEMENTATION GUIDE - Step-by-step Security Fixes

// ============================================================
// STEP 1: Add Dependencies
// ============================================================

// Run in terminal:
// npm install express helmet cors express-rate-limit express-mongo-sanitize xss-clean validator jsonwebtoken dotenv

// Create .env file:
// PORT=3000
// NODE_ENV=development
// JWT_SECRET=your-secret-key-min-32-characters-long-!
// ALLOWED_ORIGINS=http://localhost:3000
// DATABASE_URL=mongodb://localhost/yourapp

// ============================================================
// STEP 2: Minimal Secure Implementation
// ============================================================

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const jwt = require('jsonwebtoken');
require('dotenv').config();

const app = express();

// Security Middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' }));
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000'
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use('/api/', limiter);

// ============================================================
// STEP 3: Authentication Helper
// ============================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'Token required' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

// ============================================================
// STEP 4: Validation Helper
// ============================================================

const validateUserId = (id) => {
  const num = parseInt(id, 10);
  return !isNaN(num) && num > 0;
};

// ============================================================
// STEP 5: Protected Routes
// ============================================================

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/api/users', authenticateToken, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

app.get('/api/users/:id', authenticateToken, (req, res) => {
  if (!validateUserId(req.params.id)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  const users = {
    '1': { id: 1, name: 'Alice', email: 'alice@example.com' },
    '2': { id: 2, name: 'Bob', email: 'bob@example.com' },
  };

  const user = users[req.params.id];
  if (!user) return res.status(404).json({ error: 'Not found' });

  res.json(user);
});

// ============================================================
// STEP 6: Error Handler
// ============================================================

app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' ? 
      'Internal error' : err.message
  });
});

app.listen(process.env.PORT, () => {
  console.log(`Server on port ${process.env.PORT}`);
});

module.exports = app;

// ============================================================
// TESTING: Use these commands to test
// ============================================================

