// 4. Create a valid token for testing
node -e "const jwt = require('jsonwebtoken'); console.log(jwt.sign({id:1}, 'test-secret-key-min-32-characters-long-!', {expiresIn:'1h'}))"

// 5. Use valid token
curl -H "Authorization: Bearer YOUR_TOKEN_HERE" http://localhost:3000/api/users

// 6. Test invalid user ID
curl -H "Authorization: Bearer YOUR_TOKEN_HERE" http://localhost:3000/api/users/abc
*/

