  // Normal query: { name: 'Alice' }

  $ curl 'http://localhost:3000/users?name[$ne]=null'
  // Malicious query: { name: { $ne: null } }
  // Returns ALL users regardless of name

  $ curl 'http://localhost:3000/users?name[$regex]=.*'
  // Returns all users matching any pattern

  $ curl 'http://localhost:3000/users?name[$gt]=-1&name[$lt]=z'
  // Returns all users with string names

IMPACT:
  ✓ Database bypass
  ✓ Unauthorized data access
  ✓ Data modification
  ✓ Authentication bypass

PREVENTION:
  const mongoSanitize = require('express-mongo-sanitize');
  app.use(mongoSanitize());

  // OR validate inputs
  if (typeof name !== 'string' || !/^[a-zA-Z\s]+$/.test(name)) {
    return res.status(400).json({ error: 'Invalid input' });
  }

