// ============================================================
// SECRETS MANAGER - Production-Ready Implementation
// ============================================================
// 
// This provides multiple strategies for managing secrets:
// 1. AWS Secrets Manager (Recommended for production)
// 2. HashiCorp Vault (Enterprise solution)
// 3. Secure .env fallback (Development only)
//
// ============================================================

const aws = require('aws-sdk');

// ============================================================
// SECRETS MANAGER CLASS
// ============================================================

class SecretsManager {
  constructor(environment = 'development') {
    this.environment = environment;
    this.cache = new Map();
    this.cacheExpiry = new Map();
    this.CACHE_TTL = 3600000; // 1 hour

    // Only initialize AWS for production/staging
    if (environment !== 'development') {
      this.secretsClient = new aws.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    }
  }

  /**
   * Get secret from configured store
   * Strategy: AWS Secrets Manager > Vault > .env > Error
   */
  async getSecret(secretName, options = {}) {
    const { 
      fallbackEnvVar = null,
      useCache = true,
      required = true 
    } = options;

    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const expiry = this.cacheExpiry.get(secretName);
      if (expiry > Date.now()) {
        return this.cache.get(secretName);
      } else {
        this.cache.delete(secretName);
        this.cacheExpiry.delete(secretName);
      }
    }

    let secret;

    try {
      // Strategy 1: AWS Secrets Manager (Production)
      if (this.environment !== 'development') {
        secret = await this._getFromAWS(secretName);
      } 
      // Strategy 2: Environment variable fallback
      else if (fallbackEnvVar || process.env[secretName]) {
        secret = process.env[fallbackEnvVar || secretName];
      }

      if (!secret && required) {
        throw new Error(
          `Secret '${secretName}' not found. ` +
          `Configure in AWS Secrets Manager or set ${fallbackEnvVar || secretName} ` +
          `environment variable.`
        );
      }

      // Cache the secret
      if (secret && useCache) {
        this.cache.set(secretName, secret);
        this.cacheExpiry.set(secretName, Date.now() + this.CACHE_TTL);
      }

      return secret;

    } catch (error) {
      console.error(`Failed to retrieve secret '${secretName}':`, error.message);

      if (required) {
        throw error;
      }
      return null;
    }
  }

  /**
   * Get secret from AWS Secrets Manager
   */
  async _getFromAWS(secretName) {
    try {
      const response = await this.secretsClient
        .getSecretValue({ SecretId: secretName })
        .promise();

      if (response.SecretString) {
        // If it's JSON, parse it
        try {
          return JSON.parse(response.SecretString);
        } catch {
          // Return as string if not JSON
          return response.SecretString;
        }
      }

      return response.SecretBinary;

    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret '${secretName}' not found in AWS Secrets Manager`);
      }
      throw error;
    }
  }

  /**
   * Get multiple secrets
   */
  async getSecrets(secretNames) {
    const secrets = {};

    for (const name of secretNames) {
      try {
        secrets[name] = await this.getSecret(name);
      } catch (error) {
        console.warn(`Warning: Failed to load secret '${name}'`);
      }
    }

    return secrets;
  }

  /**
   * Clear cache (useful for testing)
   */
  clearCache() {
    this.cache.clear();
    this.cacheExpiry.clear();
  }

  /**
   * Invalidate specific secret cache
   */
  invalidateCache(secretName) {
    this.cache.delete(secretName);
    this.cacheExpiry.delete(secretName);
  }
}

// ============================================================
// CONFIGURATION LOADER
// ============================================================

class SecureConfig {
  constructor(environment = process.env.NODE_ENV || 'development') {
    this.environment = environment;
    this.secretsManager = new SecretsManager(environment);
    this.config = {};
  }

  /**
   * Load all application secrets
   */
  async load() {
    // Critical secrets - must be present
    const criticalSecrets = [
      'JWT_SECRET',
      'SESSION_SECRET',
    ];

    // Optional secrets - may not be present
    const optionalSecrets = [
      'DATABASE_PASSWORD',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'SENDGRID_API_KEY',
      'SENTRY_DSN',
    ];

    // Load critical secrets
    for (const secretName of criticalSecrets) {
      try {
        this.config[secretName] = await this.secretsManager.getSecret(
          secretName,
          { 
            fallbackEnvVar: secretName,
            required: true 
          }
        );
      } catch (error) {
        throw new Error(`Failed to load critical secret '${secretName}': ${error.message}`);
      }
    }

    // Load optional secrets
    for (const secretName of optionalSecrets) {
      try {
        this.config[secretName] = await this.secretsManager.getSecret(
          secretName,
          { 
            fallbackEnvVar: secretName,
            required: false 
          }
        );
      } catch (error) {
        console.warn(`Optional secret '${secretName}' not loaded: ${error.message}`);
      }
    }

    // Validate secrets
    this._validateSecrets();

    return this.config;
  }

  /**
   * Validate secret strength and format
   */
  _validateSecrets() {
    // JWT_SECRET should be at least 32 characters
    if (this.config.JWT_SECRET) {
      if (this.config.JWT_SECRET.length < 32) {
        throw new Error(
          'JWT_SECRET must be at least 32 characters long. ' +
          'Generate with: node -e "console.log(require(\'crypto\').randomBytes(32).toString(\'hex\'))"'
        );
      }

      // Check if using default/placeholder value
      if (this.config.JWT_SECRET.includes('your-super-secret') ||
          this.config.JWT_SECRET === 'secret') {
        throw new Error(
          'JWT_SECRET contains placeholder value. Set a strong random secret.'
        );
      }
    }

    // Same for SESSION_SECRET
    if (this.config.SESSION_SECRET) {
      if (this.config.SESSION_SECRET.length < 32) {
        throw new Error('SESSION_SECRET must be at least 32 characters');
      }
      if (this.config.SESSION_SECRET.includes('your-super-secret')) {
        throw new Error('SESSION_SECRET contains placeholder value');
      }
    }
  }

  /**
   * Get config value safely (won't expose secrets)
   */
  get(key) {
    return this.config[key];
  }

  /**
   * Get all non-sensitive config (safe to log)
   */
  getSafeConfig() {
    const safe = { ...this.config };

    // Remove sensitive fields before logging
    const sensitiveFields = [
      'JWT_SECRET',
      'SESSION_SECRET',
      'DATABASE_PASSWORD',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'SENDGRID_API_KEY',
    ];

    sensitiveFields.forEach(field => {
      if (safe[field]) {
        safe[field] = '***REDACTED***';
      }
    });

    return safe;
  }

  /**
   * Validate environment is production-ready
   */
  validateProduction() {
    if (this.environment === 'production') {
      // Must use AWS Secrets Manager in production
      if (!process.env.AWS_REGION) {
        throw new Error(
          'AWS_REGION must be set for production. ' +
          'Secrets Manager cannot be used without AWS credentials.'
        );
      }

      // Must not use .env files
      if (require('fs').existsSync('.env')) {
        console.warn(
          'WARNING: .env file found in production environment. ' +
          'This is a security risk. Use AWS Secrets Manager instead.'
        );
      }
    }
  }
}

module.exports = {
  SecretsManager,
  SecureConfig
};

// ============================================================
// USAGE EXAMPLE
// ============================================================

