    // Safe to log the config (sensitive fields redacted)
    console.log('Configuration loaded:', config.getSafeConfig());

    // Use secrets in your application
    const jwtSecret = config.get('JWT_SECRET');
    const dbPassword = config.get('DATABASE_PASSWORD');

