// ✗ console.log(process.env) - Exposes all secrets
// ✗ console.log(config.JWT_SECRET) - May be logged in production
// ✗ Pass secrets as query parameters

// DO THIS (Secure):
// ✓ console.log(config.getSafeConfig()) - Redacted output
