*/

// ============================================================
// AWS SECRETS MANAGER SETUP GUIDE
// ============================================================

const aws = require('aws-sdk');

// ============================================================
// STEP 1: CREATE SECRETS IN AWS SECRETS MANAGER
// ============================================================

class AWSSecretsSetup {
  constructor() {
    this.client = new aws.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  /**
   * Create a new secret in AWS Secrets Manager
   * 
   * Usage in AWS Console:
   * 1. Go to AWS Secrets Manager
   * 2. Click "Store a new secret"
   * 3. Choose secret type (Other type of secrets)
   * 4. Paste the JSON:
   *    {
   *      "JWT_SECRET": "your-generated-secret-here",
   *      "SESSION_SECRET": "your-generated-secret-here"
   *    }
   * 5. Name it: prod/app/secrets
   * 6. Add tags, enable rotation if needed
   */
  async createSecretProgrammatically(secretName, secretValue) {
    try {
      const params = {
        Name: secretName,
        Description: `Application secrets for ${secretName}`,
        SecretString: JSON.stringify(secretValue),
        Tags: [
          { Key: 'Environment', Value: process.env.NODE_ENV },
          { Key: 'Application', Value: 'secure-app' },
          { Key: 'ManagedBy', Value: 'Terraform' }
        ]
      };

      const result = await this.client.createSecret(params).promise();
      console.log(`✓ Secret created: ${result.ARN}`);
      return result;

    } catch (error) {
      if (error.code === 'ResourceExistsException') {
        console.warn(`Secret ${secretName} already exists`);
      } else {
        throw error;
      }
    }
  }

  /**
   * Update an existing secret
   */
  async updateSecret(secretName, secretValue) {
    try {
      const result = await this.client.updateSecret({
        SecretId: secretName,
        SecretString: JSON.stringify(secretValue)
      }).promise();

      console.log(`✓ Secret updated: ${result.ARN}`);
      return result;

    } catch (error) {
      throw error;
    }
  }

  /**
   * Enable automatic rotation
   */
  async enableRotation(secretName, rotationDays = 30) {
    try {
      const result = await this.client.rotateSecret({
        SecretId: secretName,
        RotationRules: {
          AutomaticallyAfterDays: rotationDays
        },
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN
      }).promise();

      console.log(`✓ Rotation enabled for ${secretName}`);
      return result;

    } catch (error) {
      console.error('Failed to enable rotation:', error);
