const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const validator = require('validator');
const jwt = require('jsonwebtoken');

const { SecureConfig } = require('./secrets-manager');

// ============================================================
// GLOBAL CONFIGURATION
// ============================================================

let secureConfig;
let app;

// ============================================================
// INITIALIZE APPLICATION
// ============================================================

async function initializeApp() {
  try {
    // Load secrets from AWS Secrets Manager or environment
    console.log('Loading configuration...');
    secureConfig = new SecureConfig(process.env.NODE_ENV || 'development');
    await secureConfig.load();

    // Validate production configuration
    if (process.env.NODE_ENV === 'production') {
      secureConfig.validateProduction();
    }

    console.log('✓ Configuration loaded successfully');
    console.log('✓ Secrets loaded:', {
      ...secureConfig.getSafeConfig(),
      nodeEnv: process.env.NODE_ENV
    });

    // Create Express app
    app = createExpressApp();

    return app;

  } catch (error) {
    console.error('✗ Failed to initialize application:', error.message);
    console.error('Application will not start due to configuration errors.');
    process.exit(1);
  }
}

// ============================================================
// CREATE EXPRESS APP
// ============================================================

function createExpressApp() {
  const app = express();

  // ============================================================
  // SECURITY MIDDLEWARE
  // ============================================================

  // Helmet - Security headers
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", 'data:', 'https:'],
      }
    },
    hsts: {
      maxAge: 31536000, // 1 year
      includeSubDomains: true,
      preload: true
    }
  }));

  // CORS - Controlled cross-origin access
  app.use(cors({
    origin: (origin, callback) => {
      const allowedOrigins = (
        process.env.ALLOWED_ORIGINS || 'http://localhost:3000'
      ).split(',');

      if (!origin || allowedOrigins.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    optionsSuccessStatus: 200
  }));

  // Body parser with size limits
  app.use(express.json({ limit: '10kb' }));
  app.use(express.urlencoded({ limit: '10kb', extended: true }));

  // Data sanitization
  app.use(mongoSanitize());
  app.use(xss());

  // Rate limiting
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,
    message: 'Too many requests',
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use('/api/', limiter);

  // Stricter rate limiting for auth endpoints
  const authLimiter = rateLimit({
    windowMs: 1 * 60 * 1000, // 1 minute
    max: 5,
    skipSuccessfulRequests: false,
  });

  // ============================================================
  // AUTHENTICATION MIDDLEWARE
  // ============================================================

  const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
      return res.status(401).json({ error: 'Access token required' });
    }

    try {
      const jwtSecret = secureConfig.get('JWT_SECRET');

      // Verify JWT signature and expiration
      const decoded = jwt.verify(token, jwtSecret);
      req.user = decoded;
      next();

    } catch (error) {
      const message = error.name === 'TokenExpiredError' ? 
        'Token expired' : 'Invalid token';

      return res.status(403).json({ error: message });
    }
  };

  // ============================================================
  // INPUT VALIDATION
  // ============================================================

  const validateInput = {
    email: (email) => {
      if (!email || typeof email !== 'string') return false;
      return validator.isEmail(email);
    },

    userId: (id) => {
      const parsed = parseInt(id, 10);
      return !isNaN(parsed) && parsed > 0 && parsed <= 999999;
    },

    string: (str, minLength = 1, maxLength = 500) => {
      if (typeof str !== 'string') return false;
      return str.length >= minLength && str.length <= maxLength;
    },

    searchQuery: (query) => {
      if (!query || typeof query !== 'string') return false;
      if (query.length > 100) return false;
      return /^[a-zA-Z0-9\s\-_.@]+$/.test(query);
    }
  };

  // ============================================================
  // API ROUTES
  // ============================================================

  // Health check
  app.get('/api/health', (req, res) => {
    res.json({
      status: 'healthy',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
      version: '2.0.0'
    });
  });

  // Login endpoint - PROTECTED BY RATE LIMITING
  app.post('/api/auth/login', authLimiter, (req, res) => {
    try {
      const { username, password } = req.body;

      // Input validation
      if (!validateInput.string(username, 2, 50)) {
        return res.status(400).json({ error: 'Invalid username' });
      }
      if (!validateInput.string(password, 8, 100)) {
        return res.status(400).json({ error: 'Invalid password' });
      }

      // In production: Verify against bcrypt hash in database
      // This is a simplified example
      if (username === 'admin' && password === 'securepassword') {

        const jwtSecret = secureConfig.get('JWT_SECRET');

        // Create JWT token with expiration
        const token = jwt.sign(
          { 
            userId: 1, 
            username: username,
            iat: Math.floor(Date.now() / 1000)
          },
          jwtSecret,
          { expiresIn: '1h' }
        );

        return res.json({
          token,
          expiresIn: 3600,
          type: 'Bearer'
        });
      }

      res.status(401).json({ error: 'Invalid credentials' });

    } catch (error) {
      console.error('Login error:', error);
      res.status(500).json({ error: 'Authentication failed' });
    }
  });

  // Get users - PROTECTED
  app.get('/api/users', authenticateToken, (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Sanitize output
      const safeUsers = users.map(({ id, name, email }) => ({
        id, name, email
      }));

      res.json(safeUsers);

    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({ error: 'Server error' });
    }
  });

  // Get user by ID - PROTECTED WITH VALIDATION
  app.get('/api/users/:id', authenticateToken, (req, res) => {
    try {
      const userId = req.params.id;

      if (!validateInput.userId(userId)) {
        return res.status(400).json({ 
          error: 'Invalid user ID format' 
        });
      }

      const users = {
        '1': { id: 1, name: 'Alice', email: 'alice@example.com' },
        '2': { id: 2, name: 'Bob', email: 'bob@example.com' },
      };

      const user = users[userId];

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.json(user);

    } catch (error) {
      console.error('Error fetching user:', error);
      res.status(500).json({ error: 'Server error' });
    }
  });

  // Search users - PROTECTED WITH RATE LIMIT
  app.get('/api/search', authLimiter, authenticateToken, (req, res) => {
    try {
      const query = req.query.q;

      if (!validateInput.searchQuery(query)) {
        return res.status(400).json({ 
          error: 'Invalid search query' 
        });
      }

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const results = users.filter(user =>
        user.name.toLowerCase().includes(query.toLowerCase()) ||
        user.email.toLowerCase().includes(query.toLowerCase())
      );

      res.json(results);

    } catch (error) {
      console.error('Search error:', error);
      res.status(500).json({ error: 'Search failed' });
    }
  });

  // Create user - PROTECTED WITH VALIDATION
  app.post('/api/users', authenticateToken, (req, res) => {
    try {
      const { name, email } = req.body;

      if (!validateInput.string(name, 2, 50)) {
        return res.status(400).json({ error: 'Invalid name' });
      }

      if (!validateInput.email(email)) {
        return res.status(400).json({ error: 'Invalid email' });
      }

      // In production: Check for duplicate, hash password, save to DB
      const newUser = {
        id: 3,
        name: name.trim(),
        email: email.toLowerCase().trim()
      };

      res.status(201).json(newUser);

    } catch (error) {
      console.error('User creation error:', error);
      res.status(500).json({ error: 'Failed to create user' });
    }
  });

  // ============================================================
  // ERROR HANDLING
  // ============================================================

  // 404 handler
  app.use((req, res) => {
    res.status(404).json({
      error: 'Not found',
      path: req.path,
      method: req.method
    });
  });

  // Global error handler
  app.use((err, req, res, next) => {
    console.error('Unhandled error:', {
      message: err.message,
      status: err.status,
      path: req.path
    });

    const isProduction = process.env.NODE_ENV === 'production';
    const statusCode = err.statusCode || 500;

    const response = {
      error: isProduction ? 
        'Internal server error' : err.message
    };

    if (!isProduction && err.stack) {
      response.details = err.stack;
    }

    res.status(statusCode).json(response);
  });

  return app;
}

// ============================================================
// SERVER STARTUP
// ============================================================

async function startServer() {
  try {
    const expressApp = await initializeApp();

    const PORT = process.env.PORT || 3000;
    const HOST = process.env.HOST || 'localhost';

    expressApp.listen(PORT, HOST, () => {
      console.log(`
╔════════════════════════════════════════╗
║  Secure Express Application Started    ║
╚════════════════════════════════════════╝

  Server:      ${HOST}:${PORT}
  Environment: ${process.env.NODE_ENV || 'development'}
  Secrets:     ${process.env.NODE_ENV === 'production' ? 'AWS Secrets Manager' : 'Environment Variables'}

