// vault-client.js
const axios = require('axios');

class VaultClient {
  constructor(vaultAddr, roleId, secretId) {
    this.vaultAddr = vaultAddr;
    this.roleId = roleId;
    this.secretId = secretId;
    this.token = null;
  }

  async authenticate() {
    const response = await axios.post(`${this.vaultAddr}/v1/auth/approle/login`, {
      role_id: this.roleId,
      secret_id: this.secretId,
    });
    this.token = response.data.auth.client_token;
  }

  async getSecret(path) {
    if (!this.token) await this.authenticate();

    try {
      const response = await axios.get(`${this.vaultAddr}/v1/${path}`, {
        headers: { 'X-Vault-Token': this.token },
      });
      return response.data.data.data;
    } catch (error) {
      if (error.response?.status === 403) {
        this.token = null; // Re-authenticate on permission error
        return this.getSecret(path);
      }
      throw error;
    }
  }
}

module.exports = VaultClient;
