    }

    secretsCache = secrets;
    secretsCacheExpiry = now + CACHE_TTL;

    return secrets;
  } catch (error) {
    console.error('Failed to retrieve secrets:', error);
    throw new Error('Unable to retrieve application secrets');
  }
}

