**Risk:** Application can be overwhelmed by malicious requests.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter limit for login attempts
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.',
});

app.post('/login', loginLimiter, (req, res) => {
  // Login logic here
});
```

---

#### **6. ❌ MEDIUM: Missing CORS Configuration (OWASP A01:2021 - Broken Access Control)**
**Issue:** No CORS headers configured.

**Risk:** If used in browser context, either too permissive or unnecessarily restrictive.

**Recommendation:**
```javascript
const cors = require('cors');

// Configure CORS properly
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};

app.use(cors(corsOptions));
```

---

#### **7. ❌ MEDIUM: No Logging/Monitoring (OWASP A09:2021 - Logging and Monitoring Failures)**
**Issue:** No security event logging for auditing or incident response.

**Risk:** Cannot detect or investigate security incidents.

**Recommendation:**
```javascript
const morgan = require('morgan');
const fs = require('fs');

// Create a write stream (in append mode)
const accessLogStream = fs.createWriteStream('access.log', { flags: 'a' });

// Log all requests (security-focused format)
app.use(morgan(
  ':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent"',
  { stream: accessLogStream }
));

// Log security events
function logSecurityEvent(level, event, details) {
  console.error(`[${level}] ${event}:`, details);
  // In production, send to centralized logging service
}
```

---

#### **8. ❌ MEDIUM: No Error Handling (OWASP A01:2021 - Broken Access Control)**
**Issue:** Unhandled errors could leak sensitive information.

**Risk:** Stack traces and internal details exposed to attackers.

**Recommendation:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  // Log the error internally
  console.error('Error:', err);

  // Don't expose internal error details to client
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    requestId: req.id, // For support tickets
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

#### **9. ❌ MEDIUM: No Content-Type Validation**
**Issue:** POST/PUT endpoints don't validate incoming content.

**Risk:** Large payloads, malformed data, or unexpected formats could cause issues.

**Recommendation:**
```javascript
// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Validate Content-Type header
app.use((req, res, next) => {
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    if (!req.is('application/json')) {
      return res.status(400).json({ error: 'Content-Type must be application/json' });
    }
  }
  next();
});
```

---

#### **10. ❌ LOW: Hardcoded Port & Missing Environment Configuration**
**Issue:** Port hardcoded; no environment variable support.

**Risk:** Inflexible deployment, potential credential exposure if configuration is in code.

**Recommendation:**
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

