/**
 * SECURE SECRETS MANAGEMENT CONFIGURATION
 * 
 * Implements multiple strategies for loading secrets from different providers
 * Priority: Secrets Manager > Environment > Local (dev only)
 */

const AWS = require('aws-sdk');
const { SecretManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");

class SecretsManager {
  constructor() {
    this.environment = process.env.NODE_ENV || 'development';
    this.secrets = {};
    this.provider = this.detectProvider();
  }

  /**
   * Detect which secrets provider to use based on environment
   */
  detectProvider() {
    if (process.env.VAULT_ADDR) {
      return 'vault'; // HashiCorp Vault
    }
    if (process.env.AZURE_KEY_VAULT_NAME) {
      return 'azure'; // Azure Key Vault
    }
    if (process.env.GCP_PROJECT_ID) {
      return 'gcp'; // Google Secret Manager
    }
    if (process.env.AWS_REGION) {
      return 'aws'; // AWS Secrets Manager
    }
    if (this.environment === 'development') {
      return 'local'; // .env file (dev only!)
    }
    throw new Error('No secrets provider configured');
  }

  /**
   * Load all secrets asynchronously
   */
  async initialize() {
    console.log(`[SecretsManager] Initializing with provider: ${this.provider}`);

    switch (this.provider) {
      case 'aws':
        await this.loadFromAWSSecretsManager();
        break;
      case 'azure':
        await this.loadFromAzureKeyVault();
        break;
      case 'gcp':
        await this.loadFromGCPSecretManager();
        break;
      case 'vault':
        await this.loadFromHashiCorpVault();
        break;
      case 'local':
        this.loadFromLocalEnv();
        break;
      default:
        throw new Error(`Unknown provider: ${this.provider}`);
    }

    this.validateRequiredSecrets();
    console.log('[SecretsManager] Secrets loaded successfully');
  }

  /**
   * OPTION 1: AWS Secrets Manager
   * Best for: AWS-hosted applications
   */
  async loadFromAWSSecretsManager() {
    const client = new SecretManagerClient({ region: process.env.AWS_REGION });

    const secretNames = [
      'app/db-credentials',
      'app/jwt-secret',
      'app/api-keys',
      'app/aws-credentials',
    ];

    for (const secretName of secretNames) {
      try {
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const data = await client.send(command);

        const secretValue = data.SecretString 
          ? JSON.parse(data.SecretString)
          : Buffer.from(data.SecretBinary, 'base64').toString('ascii');

        Object.assign(this.secrets, secretValue);
        console.log(`[AWS Secrets Manager] Loaded: ${secretName}`);
      } catch (error) {
        console.error(`[AWS Secrets Manager] Failed to load ${secretName}:`, error.message);
        if (this.environment === 'production') throw error;
      }
    }
  }

  /**
   * OPTION 2: Azure Key Vault
   * Best for: Azure-hosted applications
   */
  async loadFromAzureKeyVault() {
    const { SecretClient } = require("@azure/keyvault-secrets");
    const { DefaultAzureCredential } = require("@azure/identity");

    const vaultUrl = `https://${process.env.AZURE_KEY_VAULT_NAME}.vault.azure.net/`;
    const client = new SecretClient(vaultUrl, new DefaultAzureCredential());

    const secretNames = [
      'DATABASE-URL',
      'JWT-SECRET',
      'STRIPE-SECRET-KEY',
      'AWS-ACCESS-KEY-ID',
      'AWS-SECRET-ACCESS-KEY',
    ];

    for (const secretName of secretNames) {
      try {
        const secret = await client.getSecret(secretName);
        this.secrets[secretName] = secret.value;
        console.log(`[Azure Key Vault] Loaded: ${secretName}`);
      } catch (error) {
        console.error(`[Azure Key Vault] Failed to load ${secretName}:`, error.message);
        if (this.environment === 'production') throw error;
      }
    }
  }

  /**
   * OPTION 3: Google Secret Manager
   * Best for: GCP-hosted applications
   */
  async loadFromGCPSecretManager() {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

    const client = new SecretManagerServiceClient();
    const projectId = process.env.GCP_PROJECT_ID;

    const secretNames = [
      'database-url',
      'jwt-secret',
      'stripe-secret-key',
      'aws-access-key-id',
      'aws-secret-access-key',
    ];

    for (const secretName of secretNames) {
      try {
        const name = client.secretVersionPath(projectId, secretName, 'latest');
        const [version] = await client.accessSecretVersion({ name });
        const secretValue = version.payload.data.toString('utf8');

        this.secrets[secretName.toUpperCase().replace(/-/g, '_')] = secretValue;
        console.log(`[GCP Secret Manager] Loaded: ${secretName}`);
      } catch (error) {
        console.error(`[GCP Secret Manager] Failed to load ${secretName}:`, error.message);
        if (this.environment === 'production') throw error;
      }
    }
  }

  /**
   * OPTION 4: HashiCorp Vault
   * Best for: On-premise and complex enterprise environments
   */
  async loadFromHashiCorpVault() {
    const vault = require('node-vault');

    const vaultClient = vault({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN,
    });

    const secretPath = process.env.VAULT_SECRET_PATH || 'secret/data/app/prod';

    try {
      const secrets = await vaultClient.read(secretPath);
      Object.assign(this.secrets, secrets.data.data);
      console.log(`[Vault] Loaded secrets from: ${secretPath}`);
    } catch (error) {
      console.error(`[Vault] Failed to load secrets:`, error.message);
      if (this.environment === 'production') throw error;
    }
  }

  /**
   * OPTION 5: Local .env (Development Only)
   * ⚠️  NEVER use in production!
   */
  loadFromLocalEnv() {
    require('dotenv').config();

    if (this.environment !== 'development') {
      throw new Error(
        'Local .env file loading is only permitted in development environment. ' +
        'Configure a proper secrets manager (AWS, Azure, GCP, Vault) for production.'
      );
    }

    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'STRIPE_SECRET_KEY',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
    ];

    for (const secret of requiredSecrets) {
      if (process.env[secret]) {
        this.secrets[secret] = process.env[secret];
      }
    }

    console.warn('[⚠️  WARNING] Using local .env file for secrets. NEVER use this in production!');
  }

  /**
   * Validate that all required secrets are loaded
   */
  validateRequiredSecrets() {
    const required = [
      'DATABASE_URL',
      'JWT_SECRET',
      'STRIPE_SECRET_KEY',
    ];

    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      const error = `Missing required secrets: ${missing.join(', ')}`;
      if (this.environment === 'production') {
        throw new Error(error);
      } else {
        console.warn(`[⚠️  WARNING] ${error}`);
      }
    }
  }

  /**
   * Get a secret value safely
   */
  get(key, defaultValue = null) {
    if (!this.secrets[key]) {
      console.warn(`[⚠️  WARNING] Secret not found: ${key}`);
      if (this.environment === 'production' && !defaultValue) {
        throw new Error(`Required secret not found: ${key}`);
      }
      return defaultValue;
    }
    return this.secrets[key];
  }

  /**
   * Check if secret exists
   */
  has(key) {
    return key in this.secrets;
  }

  /**
   * Get all secrets (use carefully - mainly for debugging)
   */
  getAll() {
    if (this.environment === 'production') {
      throw new Error('Cannot export all secrets in production');
    }
    return { ...this.secrets };
  }

  /**
   * Get secrets count (safe for logging)
   */
  count() {
    return Object.keys(this.secrets).length;
  }
}

// Export singleton instance
module.exports = new SecretsManager();

