/**
 * SECRETS SCANNER
 * 
 * Detects exposed secrets in code, configs, and environment files
 * Usage: node scan-secrets.js [path]
 */

const fs = require('fs');
const path = require('path');
const readline = require('readline');

// Secret patterns to detect
const SECRET_PATTERNS = {
  // API Keys
  'api_key': /api[_-]?key\s*[:=]\s*['"]?([a-zA-Z0-9_\-]{20,})/gi,
  'aws_access_key': /AKIA[0-9A-Z]{16}/g,
  'aws_secret_key': /aws_secret_access_key\s*[:=]\s*['"]([a-zA-Z0-9/+=]{40})/gi,
  'stripe_key': /(sk_live|pk_live|sk_test|pk_test)_[a-zA-Z0-9_]{20,}/g,
  'jwt': /jwt\s*[:=]\s*['"]?(eyJ[A-Za-z0-9_-]{20,})/gi,
  'db_password': /password\s*[:=]\s*['"]([^'"]+)['"]/gi,
  'db_connection': /postgres:\/\/[^:]+:([^@]+)@/gi,
  'private_key': /-----BEGIN (RSA|DSA|EC|OPENSSH|PGP) PRIVATE KEY/g,
  'github_token': /gh[pousr]{1}_[a-zA-Z0-9_]{36,255}/g,
  'anthropic_api': /sk-ant-[a-zA-Z0-9-]{50,}/g,
  'oauth_token': /oauth[_-]?token\s*[:=]\s*['"]([a-zA-Z0-9_\-]{40,})/gi,
  'env_password': /^(DATABASE_PASSWORD|APP_PASSWORD|DB_PASS)\s*[:=]\s*['"]([^'"]+)/gmi,
};

// Files to skip
const SKIP_PATTERNS = [
  /node_modules/,
  /\.git/,
  /\.next/,
  /dist/,
  /build/,
  /\.log$/,
  /package-lock\.json$/,
  /yarn\.lock$/,
];

class SecretsScanner {
  constructor(targetPath = '.') {
    this.targetPath = targetPath;
    this.findings = [];
    this.scannedFiles = 0;
    this.skippedFiles = 0;
  }

  shouldSkip(filePath) {
    return SKIP_PATTERNS.some(pattern => pattern.test(filePath));
  }

  scanFile(filePath) {
    try {
      if (this.shouldSkip(filePath)) {
        this.skippedFiles++;
        return;
      }

      const content = fs.readFileSync(filePath, 'utf8');
      let lineNumber = 0;

      const lines = content.split('\n');

      for (const line of lines) {
        lineNumber++;

        // Skip comments and common false positives
        if (line.trim().startsWith('//') || 
            line.trim().startsWith('#') ||
            line.includes('example') ||
            line.includes('TODO')) {
          continue;
        }

        for (const [patternName, regex] of Object.entries(SECRET_PATTERNS)) {
          const matches = line.matchAll(regex);

          for (const match of matches) {
            // Filter out false positives
            if (this.isFalsePositive(match[0], patternName)) {
              continue;
            }

            this.findings.push({
              severity: this.getSeverity(patternName),
              type: patternName,
              file: filePath,
              line: lineNumber,
              preview: this.maskSecret(line),
              matched: match[0],
            });
          }
        }
      }

      this.scannedFiles++;
    } catch (error) {
      // Ignore binary files and read errors
      if (error.code !== 'EISDIR' && !error.message.includes('binary')) {
        // console.warn(`[⚠️] Failed to scan ${filePath}: ${error.message}`);
      }
    }
  }

  scanDirectory(dir) {
    try {
      const entries = fs.readdirSync(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);

        if (entry.isDirectory()) {
