/**
 * GIT PRE-COMMIT HOOK: Prevent secrets from being committed
 * 
 * Installation:
 *   cp git-pre-commit-hook.js .git/hooks/pre-commit
 *   chmod +x .git/hooks/pre-commit
 * 
 * Or use husky:
 *   npx husky install
 *   npx husky add .husky/pre-commit "node git-pre-commit-hook.js"
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// Patterns that indicate secrets
const SECRET_PATTERNS = [
  /password\s*[:=]/i,
  /secret[_-]?key\s*[:=]/i,
  /api[_-]?key\s*[:=]/i,
  /token\s*[:=]/i,
  /aws[_-]?secret/i,
  /AKIA[0-9A-Z]{16}/,  // AWS Access Keys
  /sk_live_|sk_test_/,  // Stripe Keys
  /sk-ant-/,  // Anthropic Keys
  /-----BEGIN.*PRIVATE KEY/,
  /oauth[_-]?token/i,
  /[a-zA-Z0-9]{40,}/,  // Generic long keys
];

const ALLOWED_PATTERNS = [
  /example/i,
  /localhost/,
  /127\.0\.0\.1/,
  /0\.0\.0\.0/,
  /placeholder/i,
  /demo/i,
  /test/i,
  /sample/i,
  /REPLACE_ME/,
  /YOUR_/,
  /change_me/i,
  /CANARY-/,  // Allow canary tokens for testing
];

const SKIP_FILES = [
  /node_modules/,
  /\.git/,
  /package-lock\.json/,
  /yarn\.lock/,
  /\.md$/,
];

function getChangedFiles() {
  try {
    const output = execSync('git diff --cached --name-only --diff-filter=ACM', {
      encoding: 'utf-8',
    });
    return output.split('\n').filter(line => line.trim());
  } catch (error) {
    console.error('Failed to get changed files:', error.message);
    return [];
  }
}

function getStagedChanges(filePath) {
  try {
    const output = execSync(`git diff --cached "${filePath}"`, {
      encoding: 'utf-8',
    });
    return output;
  } catch (error) {
    return '';
  }
}

function shouldSkipFile(filePath) {
  return SKIP_FILES.some(pattern => pattern.test(filePath));
}

function isAllowedPattern(text) {
  return ALLOWED_PATTERNS.some(pattern => pattern.test(text));
}

function checkForSecrets(text, filePath) {
  const lines = text.split('\n');
  const findings = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Skip comments and documentation
    if (line.trim().startsWith('#') || 
        line.trim().startsWith('//') ||
        line.trim().startsWith('*')) {
      continue;
    }

    for (const pattern of SECRET_PATTERNS) {
      if (pattern.test(line)) {
        // Check if it's a false positive
        if (isAllowedPattern(line)) {
          continue;
        }

        findings.push({
          file: filePath,
          line: i + 1,
          content: line.substring(0, 80),
        });
      }
    }
  }

  return findings;
}

function main() {
  const files = getChangedFiles();
  let hasSecrets = false;
  const allFindings = [];

  console.log('🔍 Scanning staged changes for secrets...\n');

  for (const file of files) {
    if (shouldSkipFile(file)) {
      continue;
    }

    const changes = getStagedChanges(file);
    const findings = checkForSecrets(changes, file);

    if (findings.length > 0) {
      hasSecrets = true;
      allFindings.push(...findings);

      console.log(`\n⚠️  Potential secrets detected in: ${file}`);
      for (const finding of findings) {
        console.log(`   Line ${finding.line}: ${finding.content}...`);
      }
    }
  }

  if (hasSecrets) {
    console.log('\n' + '='.repeat(70));
    console.log('🚨 SECRETS DETECTED IN STAGED CHANGES');
    console.log('='.repeat(70));
    console.log('\nCommit BLOCKED to prevent secret leakage.\n');
    console.log('To fix:');
    console.log('  1. Remove secrets from the file');
    console.log('  2. Use a secrets manager (AWS, Azure, GCP, Vault)');
    console.log('  3. Re-stage changes: git add <file>');
    console.log('  4. Commit again\n');
    console.log('If you believe this is a false positive:');
    console.log('  - Mark it with CANARY- prefix for canary tokens');
    console.log('  - Mark it with example/demo/test/sample for samples');
    console.log('  - Add exception to ALLOWED_PATTERNS in this script\n');
    console.log('Learn more: https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html');
    console.log('='.repeat(70) + '\n');
    process.exit(1);
  }

  console.log('✅ No secrets detected in staged changes');
  process.exit(0);
}

main();

