// Secure secrets management for Node.js application
// Supports both local development and AWS Secrets Manager for production

const AWS = require('aws-sdk');
const fs = require('fs');
const path = require('path');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.isLocal = process.env.NODE_ENV !== 'production';
    this.useLocalFiles = process.env.USE_LOCAL_SECRETS === 'true';
    this.initialized = false;
  }

  /**
   * Initialize secrets from appropriate source
   * Local dev: .env.local file
   * Production: AWS Secrets Manager via IAM role
   */
  async initialize() {
    if (this.initialized) {
      console.log('ℹ️  Secrets already initialized');
      return;
    }

    try {
      if (this.isLocal && this.useLocalFiles) {
        await this.loadFromLocalFile();
      } else {
        await this.loadFromAWSSecretsManager();
      }

      this.validateRequiredSecrets();
      this.initialized = true;
      console.log('✓ Secrets initialized successfully');
    } catch (error) {
      console.error('❌ Failed to initialize secrets:', error.message);
      process.exit(1);
    }
  }

  /**
   * Load secrets from local .env.local file
   * ONLY for local development
   */
  async loadFromLocalFile() {
    const envPath = path.join(process.cwd(), '.env.local');

    if (!fs.existsSync(envPath)) {
      throw new Error(
        'Missing .env.local file for local development.\n' +
        'Steps:\n' +
        '1. Copy .env.example to .env.local\n' +
        '2. Fill in your local development secrets\n' +
        '3. NEVER commit .env.local to version control!'
      );
    }

    // Verify .env.local is in .gitignore
    const gitignorePath = path.join(process.cwd(), '.gitignore');
    if (fs.existsSync(gitignorePath)) {
      const gitignoreContent = fs.readFileSync(gitignorePath, 'utf8');
      if (!gitignoreContent.includes('.env.local')) {
        console.warn('⚠️  WARNING: .env.local is not in .gitignore!');
        console.warn('Add this line to .gitignore immediately:');
        console.warn('.env.local');
      }
    }

    require('dotenv').config({ path: envPath });

    this.secrets = {
      DATABASE_URL: this.getEnv('DATABASE_URL', ''),
      AWS_ACCESS_KEY_ID: this.getEnv('AWS_ACCESS_KEY_ID', ''),
      AWS_SECRET_ACCESS_KEY: this.getEnv('AWS_SECRET_ACCESS_KEY', ''),
      AWS_REGION: this.getEnv('AWS_REGION', 'us-east-1'),
      ANTHROPIC_API_KEY: this.getEnv('ANTHROPIC_API_KEY', ''),
      STRIPE_SECRET_KEY: this.getEnv('STRIPE_SECRET_KEY', ''),
      LOGFIRE_TOKEN: this.getEnv('LOGFIRE_TOKEN', ''),
      JWT_SECRET: this.getEnv('JWT_SECRET', ''),
    };

    console.log('⚠️  Using local .env.local file - LOCAL DEVELOPMENT ONLY');
  }

  /**
   * Load secrets from AWS Secrets Manager
   * For production/staging environments
   * Requires IAM role with secretsmanager:GetSecretValue permission
   */
  async loadFromAWSSecretsManager() {
    const region = process.env.AWS_REGION || 'us-east-1';
    const secretName = process.env.SECRETS_NAME || 'app/secrets/production';

    const secretsManager = new AWS.SecretsManager({ region });

    try {
      console.log(`📡 Loading secrets from AWS Secrets Manager: ${secretName} (region: ${region})`);

      const data = await secretsManager.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      // Handle both JSON and plaintext secrets
      if (data.SecretString) {
        this.secrets = JSON.parse(data.SecretString);
      } else if (data.SecretBinary) {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        this.secrets = JSON.parse(buff.toString('ascii'));
      }

      console.log('✓ Successfully loaded secrets from AWS Secrets Manager');
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(
          `Secret "${secretName}" not found in AWS Secrets Manager.\n` +
          `Create it first using: aws secretsmanager create-secret --name ${secretName} --secret-string '{...}'`
        );
      } else if (error.code === 'AccessDenied') {
        throw new Error(
          `Access denied to AWS Secrets Manager.\n` +
          `Ensure your IAM role has secretsmanager:GetSecretValue permission for: ${secretName}`
        );
      }
      throw error;
    }
  }

  /**
   * Get environment variable with optional default
   */
  getEnv(key, defaultValue = undefined) {
    const value = process.env[key];
    if (!value && defaultValue === undefined) {
      throw new Error(`Environment variable ${key} is not set`);
    }
    return value || defaultValue;
  }

  /**
   * Validate that all required secrets are present
   */
  validateRequiredSecrets() {
    const required = ['DATABASE_URL', 'STRIPE_SECRET_KEY', 'JWT_SECRET'];
    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}`
      );
    }
  }

  /**
   * Get a secret value
   * Throws error if secret not found
   */
  get(key) {
    if (!(key in this.secrets)) {
      throw new Error(
        `Secret "${key}" not found.\n` +
        `Available secrets: ${Object.keys(this.secrets).join(', ')}`
      );
    }
    return this.secrets[key];
  }

  /**
   * Check if a secret exists
   */
  has(key) {
    return key in this.secrets;
  }

  /**
   * Get secret with default value if not found
   */
  getOrDefault(key, defaultValue) {
    return this.has(key) ? this.get(key) : defaultValue;
  }

  /**
   * Get all secrets (CAREFUL - for debugging only)
   * Never log in production!
   */
  getAll() {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Cannot dump all secrets in production environment');
    }
    return { ...this.secrets };
  }

  /**
   * Rotate secrets by fetching fresh copy from AWS Secrets Manager
   * Useful for periodic rotation
   */
  async rotateSecrets() {
    if (this.useLocalFiles) {
      throw new Error('Secret rotation not supported for local files');
    }

    console.log('🔄 Rotating secrets...');
    this.initialized = false;
    await this.initialize();
    console.log('✓ Secrets rotated successfully');
  }
}

// Export singleton instance
module.exports = new SecretsManager();

// app-with-secrets.js
