/**
 * Secure Express Application
 * Implements security best practices and OWASP Top 10 protections
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const winston = require('winston');

// ============================================================================
// 1. CONFIGURE LOGGING (A09 - Logging and Monitoring)
// ============================================================================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Also log to console in development
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const app = express();

// ============================================================================
// 2. SECURITY HEADERS (A05 - Security Misconfiguration)
// ============================================================================
app.use(helmet());
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));
app.use(helmet.frameguard({ action: 'deny' }));
app.use(helmet.xssFilter());
app.use(helmet.noSniff());
app.use(helmet.referrerPolicy({ policy: 'strict-origin-when-cross-origin' }));
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  }
}));

// ============================================================================
// 3. CORS CONFIGURATION (A05 - Security Misconfiguration)
// ============================================================================
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Total-Count', 'RateLimit-Remaining'],
  maxAge: 3600,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// ============================================================================
// 4. BODY PARSER WITH SIZE LIMITS (A05 - Security Misconfiguration)
// ============================================================================
app.use(express.json({ limit: '1kb' }));
app.use(express.urlencoded({ extended: false, limit: '1kb' }));

// ============================================================================
// 5. RATE LIMITING (A01, A04, A05 - Multiple protections)
// ============================================================================
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Don't rate limit health checks
    return req.path === '/health';
  }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for auth attempts
  message: 'Too many authentication attempts, please try again later',
  skipSuccessfulRequests: true
});

app.use(generalLimiter);

// ============================================================================
// 6. REQUEST ID MIDDLEWARE (For security monitoring)
// ============================================================================
app.use((req, res, next) => {
  req.id = require('crypto').randomUUID();
  res.setHeader('X-Request-ID', req.id);
  logger.info(`Incoming request: ${req.method} ${req.path}`, {
    requestId: req.id,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });
  next();
});

// ============================================================================
// 7. AUTHENTICATION MIDDLEWARE (A01, A07 - Access Control & Authentication)
// ============================================================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer token

  if (!token) {
    logger.warn('Unauthorized access attempt - no token', { requestId: req.id });
    return res.status(401).json({
      error: 'Access token required',
      requestId: req.id
    });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      logger.warn('Invalid or expired token attempt', { 
        requestId: req.id,
        error: err.message 
      });
      return res.status(403).json({
        error: 'Invalid or expired token',
        requestId: req.id
      });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// 8. INPUT VALIDATION MIDDLEWARE (A03 - Injection)
// ============================================================================
const validateUserQuery = [
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt()
];

// ============================================================================
// 9. REQUEST VALIDATION HANDLER
// ============================================================================
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation error', {
      requestId: req.id,
      errors: errors.array()
    });
    return res.status(400).json({
      error: 'Invalid request parameters',
      details: errors.array(),
      requestId: req.id
    });
  }
  next();
};

// ============================================================================
// 10. ROUTES (with security measures)
// ============================================================================

/**
 * Health check endpoint (public, no auth required)
 */
app.get('/health', (req, res) => {
  try {
    logger.debug('Health check', { requestId: req.id });
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      requestId: req.id
    });
  } catch (error) {
    logger.error('Health check error', {
      requestId: req.id,
      error: error.message
    });
    res.status(500).json({
      error: 'Internal server error',
      requestId: req.id
    });
  }
});

/**
 * Get users endpoint (protected, requires authentication)
 * Supports filtering and pagination
 */
app.get('/users',
  authenticateToken,
  validateUserQuery,
  handleValidationErrors,
  (req, res) => {
    try {
      const { id, limit = 10, offset = 0 } = req.query;

      // Mock user database
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters (safe because input is validated)
      if (id) {
        users = users.filter(u => u.id === id);
      }

      // Apply pagination (safe because input is validated)
      const total = users.length;
      users = users.slice(offset, offset + limit);

      logger.info('Users retrieved', {
        requestId: req.id,
        userId: req.user.id,
        count: users.length
      });

      res.json({
        data: users,
        pagination: {
          offset,
          limit,
          total
        },
        requestId: req.id
      });
    } catch (error) {
      logger.error('Error retrieving users', {
        requestId: req.id,
        error: error.message,
        stack: error.stack
      });
      res.status(500).json({
        error: process.env.NODE_ENV === 'production'
          ? 'Internal server error'
          : error.message,
        requestId: req.id
      });
    }
  }
);

/**
 * Mock authentication endpoint (for demonstration)
 * In production, use proper OAuth2/OIDC providers
 */
app.post('/login', authLimiter, express.json(), (req, res) => {
  try {
    const { username, password } = req.body;

    // WARNING: This is a mock. NEVER store passwords like this in production.
    // Use bcrypt for password hashing and proper authentication.
    if (!username || !password) {
      logger.warn('Login attempt with missing credentials', {
        requestId: req.id
      });
      return res.status(400).json({
        error: 'Username and password required',
        requestId: req.id
      });
    }

    // Mock user (in production, query secure database with hashed password)
    if (username === 'demo' && password === 'demo123') {
      const token = jwt.sign(
        { id: 1, username },
        process.env.JWT_SECRET || 'your-secret-key',
        { expiresIn: '1h' }
      );

      logger.info('Successful login', {
        requestId: req.id,
        username
      });

      return res.json({
        token,
        expiresIn: 3600,
        requestId: req.id
      });
    }

    logger.warn('Failed login attempt', {
      requestId: req.id,
      username
    });
    res.status(401).json({
      error: 'Invalid credentials',
      requestId: req.id
    });
  } catch (error) {
    logger.error('Login error', {
      requestId: req.id,
      error: error.message
    });
    res.status(500).json({
      error: 'Internal server error',
      requestId: req.id
    });
  }
});

// ============================================================================
// 11. 404 HANDLER
// ============================================================================
app.use((req, res) => {
  logger.warn('404 Not Found', {
    requestId: req.id,
    path: req.path,
    method: req.method
  });
  res.status(404).json({
    error: 'Not found',
    requestId: req.id
  });
});

// ============================================================================
// 12. GLOBAL ERROR HANDLER (A09 - Logging and Monitoring)
// ============================================================================
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    requestId: req.id,
    error: err.message,
    stack: err.stack,
    path: req.path
  });

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const response = {
    error: isDevelopment ? err.message : 'Internal server error',
    requestId: req.id
  };

  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// ============================================================================
// 13. START SERVER
// ============================================================================
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`, {
    nodeEnv: process.env.NODE_ENV,
    port: PORT
  });
});

// ============================================================================
// 14. GRACEFUL SHUTDOWN
// ============================================================================
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

