const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN
});

class VaultManager {
  async getSecret(path) {
    try {
      const result = await vault.read(`secret/data/${path}`);
      return result.data.data;
    } catch (error) {
      console.error(`Failed to read secret from Vault: ${path}`, error);
      throw error;
    }
  }

  async rotateSecret(path, newSecret) {
    try {
      await vault.write(`secret/data/${path}`, { data: newSecret });
      console.log(`Secret rotated: ${path}`);
    } catch (error) {
      console.error(`Failed to rotate secret: ${path}`, error);
      throw error;
    }
  }
}

module.exports = new VaultManager();
```

