/**
 * SECURE EXPRESS.JS APPLICATION
 * This is a hardened version implementing all security best practices
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');

// ============================================================================
// CONFIGURATION
// ============================================================================

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

// Validate required environment variables
if (!JWT_SECRET) {
  throw new Error('CRITICAL: JWT_SECRET environment variable must be set');
}

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'express-app' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

// Console logging in development
if (NODE_ENV === 'development') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    ),
  }));
}

// Request logging
app.use(morgan('combined', { stream: { write: (msg) => logger.info(msg) } }));

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet - Set HTTP security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// 2. CORS Configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// 3. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 4. Rate Limiting
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({ error: 'Too many requests' });
  },
});

const sensitiveDataLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  skipSuccessfulRequests: false,
  handler: (req, res) => {
    logger.warn(`Sensitive endpoint rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({ error: 'Too many requests to sensitive endpoint' });
  },
});

app.use(globalLimiter);

// ============================================================================
// AUTHENTICATION & AUTHORIZATION
// ============================================================================

/**
 * Middleware to verify JWT token
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Missing token from IP: ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    logger.debug(`Token verified for user: ${decoded.userId}`);
    next();
  } catch (err) {
    logger.warn(`Invalid token from IP: ${req.ip}, Error: ${err.message}`);
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

/**
 * Middleware to check user role
 */
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      logger.warn(`Unauthorized access attempt - User: ${req.user?.userId}, IP: ${req.ip}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// ============================================================================
// INPUT VALIDATION
// ============================================================================

/**
 * Custom validators for common fields
 */
const validators = {
  userId: query('userId').optional().isInt().toInt(),
  name: query('name').optional().trim().isLength({ min: 1, max: 100 }).escape(),
  email: query('email').optional().isEmail().normalizeEmail(),
  role: query('role').optional().isIn(['user', 'admin', 'moderator']),
};

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn(`Validation error from IP: ${req.ip}`, { errors: errors.array() });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint - No authentication required
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

/**
 * Get users - Protected endpoint
 * Requires: Valid JWT token with admin role
 */
app.get(
  '/users',
  sensitiveDataLimiter,
  validators.userId,
  validators.role,
  handleValidationErrors,
  authenticateToken,
  authorize('admin'),
  (req, res) => {
    try {
      logger.info(`User ${req.user.userId} retrieved user list`);

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      ];

      // Filter if query parameters provided
      let filteredUsers = users;
      if (req.query.userId) {
        filteredUsers = filteredUsers.filter(u => u.id === req.query.userId);
      }
      if (req.query.role) {
        filteredUsers = filteredUsers.filter(u => u.role === req.query.role);
      }

      // Log the action
      logger.debug(`Returned ${filteredUsers.length} users to user ${req.user.userId}`);

      res.json({
        success: true,
        data: filteredUsers,
        count: filteredUsers.length,
      });
    } catch (err) {
      logger.error('Error retrieving users', { error: err.message, stack: err.stack });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

/**
 * Get current user info - Protected endpoint
 */
app.get('/me', authenticateToken, (req, res) => {
  try {
    logger.info(`User ${req.user.userId} retrieved their profile`);
    res.json({
      success: true,
      data: {
        userId: req.user.userId,
        role: req.user.role,
        // Don't expose sensitive internal fields
      },
    });
  } catch (err) {
    logger.error('Error retrieving user profile', { error: err.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Login endpoint - For testing/demo purposes only
 * In production, use OAuth2, SAML, or dedicated auth service
 */
app.post('/login', express.json(), (req, res) => {
  try {
    const { userId, password } = req.body;

    // Input validation
    if (!userId || !password) {
      logger.warn(`Login attempt with missing credentials from IP: ${req.ip}`);
      return res.status(400).json({ error: 'userId and password required' });
    }

    // WARNING: This is a demo only. Never check passwords in plain text!
    // Use bcrypt or similar in production
    if (userId !== 'admin' || password !== 'demo123') {
      logger.warn(`Failed login attempt for user: ${userId} from IP: ${req.ip}`);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = jwt.sign(
      { userId, role: 'admin', iat: Math.floor(Date.now() / 1000) },
      JWT_SECRET,
      { expiresIn: '1h' }
    );

    logger.info(`Successful login for user: ${userId}`);
    res.json({ success: true, token });
  } catch (err) {
    logger.error('Error during login', { error: err.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// 404 HANDLER
// ============================================================================

app.use((req, res) => {
  logger.warn(`Not found: ${req.method} ${req.path}`);
  res.status(404).json({ error: 'Endpoint not found' });
});

// ============================================================================
// GLOBAL ERROR HANDLER
// ============================================================================

app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  const isDevelopment = NODE_ENV === 'development';
  const statusCode = err.status || 500;

  const response = {
    error: isDevelopment ? err.message : 'Internal Server Error',
  };

  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info(`Server started on port ${PORT} in ${NODE_ENV} mode`);
  logger.info(`Environment: ${NODE_ENV}`);
  logger.info(`JWT_SECRET configured: ${!!JWT_SECRET}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully...');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

