  const envContent = decryptEnv('.env.encrypted', process.env.ENV_PASSWORD);
  const lines = envContent.split('\n');
  lines.forEach(line => {
    const [key, value] = line.split('=');
    process.env[key.trim()] = value.trim();
  });
} catch (error) {
  logger.error('Failed to decrypt .env file');
  process.exit(1);
}
