// ===== PATTERN 1: Secure Environment Variables with Validation =====

class SecureConfig {
  constructor() {
    this.config = {};
    this.loadAndValidateSecrets();
  }

  loadAndValidateSecrets() {
    // Define required secrets with validation rules
    const requiredSecrets = {
      NODE_ENV: { required: true, type: 'string', values: ['development', 'staging', 'production'] },
      DATABASE_URL: { required: true, type: 'string', pattern: /^postgres:\/\// },
      JWT_SECRET: { required: true, type: 'string', minLength: 32 },
      API_SECRET: { required: true, type: 'string', minLength: 32 },
      AWS_REGION: { required: false, type: 'string', default: 'us-east-1' },
      LOG_LEVEL: { required: false, type: 'string', default: 'info' },
    };

    const errors = [];
    const warnings = [];

    for (const [key, rules] of Object.entries(requiredSecrets)) {
      const value = process.env[key];

      // Check if required
      if (rules.required && !value) {
        errors.push(`Missing required secret: ${key}`);
        continue;
      }

      if (!value) {
        if (rules.default !== undefined) {
          this.config[key] = rules.default;
        }
        continue;
      }

      // Validate type
      if (rules.type === 'string' && typeof value !== 'string') {
        errors.push(`${key} must be a string`);
      }

      // Validate allowed values
      if (rules.values && !rules.values.includes(value)) {
        errors.push(`${key} must be one of: ${rules.values.join(', ')}`);
      }

      // Validate pattern
      if (rules.pattern && !rules.pattern.test(value)) {
        errors.push(`${key} does not match required pattern`);
      }

      // Validate minimum length
      if (rules.minLength && value.length < rules.minLength) {
        errors.push(`${key} must be at least ${rules.minLength} characters`);
      }

      // Security warnings
      if (key.includes('SECRET') && value === 'dev-secret' || value === 'test-secret') {
        warnings.push(`⚠️  ${key} uses a weak secret value`);
      }

      this.config[key] = value;
    }

    // Throw on errors
    if (errors.length > 0) {
      throw new Error(`Configuration errors:\n${errors.join('\n')}`);
    }

    // Log warnings
    if (warnings.length > 0) {
      console.warn('Configuration warnings:\n' + warnings.join('\n'));
    }

    // Prevent modification
    Object.freeze(this.config);
  }

  get(key) {
    return this.config[key];
  }

  has(key) {
    return key in this.config;
  }

  // Never log secrets
  toString() {
    return '[SecureConfig]';
  }

  toJSON() {
    return '[SecureConfig]';
  }
}

// ===== PATTERN 2: Secrets Manager Interface =====

class SecretsManager {
  constructor(provider) {
    this.provider = provider;
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName, options = {}) {
    const { useCache = true, ttl = this.cacheTTL } = options;

    // Check cache
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < ttl) {
        return cached.value;
      }
    }

    // Fetch from provider
    let secret;
    try {
      secret = await this.provider.getSecret(secretName);
    } catch (error) {
      this.logSecretAccessError(secretName, error);
      throw error;
    }

    // Cache result
    if (useCache) {
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });
    }

    // Log access
    this.logSecretAccess(secretName);

    return secret;
  }

  logSecretAccess(secretName) {
    const log = {
      timestamp: new Date().toISOString(),
      secretName,
      service: process.env.SERVICE_NAME || 'unknown',
      environment: process.env.NODE_ENV,
      caller: this.getCallerInfo()
    };
    console.info('SECRET_ACCESS', log);
  }

  logSecretAccessError(secretName, error) {
    const log = {
      timestamp: new Date().toISOString(),
      secretName,
      error: error.message,
      service: process.env.SERVICE_NAME || 'unknown',
      environment: process.env.NODE_ENV,
    };
    console.error('SECRET_ACCESS_ERROR', log);
  }

  getCallerInfo() {
    const stack = new Error().stack.split('\n')[3];
    return stack ? stack.trim() : 'unknown';
  }

  clearCache() {
    this.cache.clear();
  }
}

// ===== PATTERN 3: AWS Secrets Manager Provider =====

class AWSSecretsProvider {
  constructor() {
    const AWS = require('aws-sdk');
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      if ('SecretString' in data) {
        try {
          return JSON.parse(data.SecretString);
        } catch {
          // If not JSON, return as string
          return data.SecretString;
        }
      } else if ('SecretBinary' in data) {
        return data.SecretBinary;
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      } else if (error.code === 'InvalidRequestException') {
        throw new Error(`Invalid secret request for: ${secretName}`);
      } else if (error.code === 'InvalidClientTokenId') {
        throw new Error('AWS credentials are invalid or expired');
      } else if (error.code === 'AccessDenied') {
        throw new Error(`Access denied to secret: ${secretName}`);
      }
      throw error;
    }
  }
}

// ===== PATTERN 4: Environment Variables Provider (Dev Only) =====

