  logSecretAccessError(secretName, error) {
    const log = {
      timestamp: new Date().toISOString(),
      secretName,
      error: error.message,
      service: process.env.SERVICE_NAME || 'unknown',
      environment: process.env.NODE_ENV,
    };
    console.error('SECRET_ACCESS_ERROR', log);
  }

  getCallerInfo() {
    const stack = new Error().stack.split('\n')[3];
    return stack ? stack.trim() : 'unknown';
  }

  clearCache() {
    this.cache.clear();
  }
}

// ===== PATTERN 3: AWS Secrets Manager Provider =====

class AWSSecretsProvider {
  constructor() {
    const AWS = require('aws-sdk');
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      if ('SecretString' in data) {
        try {
          return JSON.parse(data.SecretString);
        } catch {
          // If not JSON, return as string
          return data.SecretString;
        }
      } else if ('SecretBinary' in data) {
        return data.SecretBinary;
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      } else if (error.code === 'InvalidRequestException') {
        throw new Error(`Invalid secret request for: ${secretName}`);
      } else if (error.code === 'InvalidClientTokenId') {
        throw new Error('AWS credentials are invalid or expired');
      } else if (error.code === 'AccessDenied') {
        throw new Error(`Access denied to secret: ${secretName}`);
      }
      throw error;
    }
  }
}

// ===== PATTERN 4: Environment Variables Provider (Dev Only) =====

class EnvProvider {
  async getSecret(secretName) {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Secret not found in environment: ${secretName}`);
    }
    try {
      return JSON.parse(value);
    } catch {
      return value;
    }
  }
}

// ===== PATTERN 5: Secure App Initialization =====

async function initializeSecureApp() {
  // Load and validate configuration
  const config = new SecureConfig();

  // Select secrets provider based on environment
  let secretsProvider;
  if (config.get('NODE_ENV') === 'production') {
    secretsProvider = new AWSSecretsProvider();
  } else {
    secretsProvider = new EnvProvider();
  }

  const secretsManager = new SecretsManager(secretsProvider);

  // Initialize app with secrets
  const express = require('express');
  const app = express();

  // Middleware
  app.use(require('helmet')());
  app.use(express.json({ limit: '10kb' }));

  // Routes
  app.get('/health', (req, res) => {
    res.json({ status: 'ok' });
  });

  app.get('/config-test', async (req, res) => {
    try {
      const dbSecret = await secretsManager.getSecret('prod/database');
      res.json({
        database: typeof dbSecret === 'object' ? 'Connected' : 'Error',
        message: 'Secrets loaded successfully'
      });
    } catch (error) {
      res.status(500).json({ error: error.message });
    }
  });

  return { app, config, secretsManager };
}

// ===== PATTERN 6: Graceful Shutdown =====

async function startApp() {
  try {
    const { app, config, secretsManager } = await initializeSecureApp();

    const server = app.listen(process.env.PORT || 3000, () => {
      console.log(`Server running on port ${process.env.PORT || 3000}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', async () => {
      console.log('SIGTERM signal received: closing HTTP server');
      server.close(async () => {
        console.log('HTTP server closed');
        // Clear secrets on shutdown
        secretsManager.clearCache();
        process.exit(0);
      });
    });

    process.on('SIGINT', async () => {
      console.log('SIGINT signal received: closing HTTP server');
      server.close(async () => {
        console.log('HTTP server closed');
        secretsManager.clearCache();
        process.exit(0);
      });
    });

  } catch (error) {
    console.error('Failed to start app:', error.message);
    process.exit(1);
  }
}

module.exports = {
  SecureConfig,
  SecretsManager,
  AWSSecretsProvider,
  EnvProvider,
  initializeSecureApp,
  startApp
};

// Start if run directly
if (require.main === module) {
  startApp();
}

