## Step-by-Step: AWS Secrets Manager Migration

### Step 1: Install AWS SDK

```bash
npm install aws-sdk
```

### Step 2: Create Secrets in AWS

```bash
# Store database credentials
aws secretsmanager create-secret \
  --name prod/database \
  --description "Production database credentials" \
  --secret-string '{
    "host": "db.internal",
    "port": 5432,
    "username": "prod-user",
    "password": "GENERATED_SECURE_PASSWORD",
    "database": "production"
  }' \
  --region us-east-1 \
  --tags Key=Environment,Value=production Key=Application,Value=app

# Store API keys
aws secretsmanager create-secret \
  --name prod/api-keys \
  --description "Third-party API keys" \
  --secret-string '{
    "stripe_key": "sk_live_...",
    "anthropic_key": "sk-ant-...",
    "logfire_token": "..."
  }' \
  --region us-east-1

# Store JWT secrets
aws secretsmanager create-secret \
  --name prod/jwt \
  --description "JWT signing secrets" \
  --secret-string '{
    "JWT_SECRET": "GENERATED_STRONG_SECRET_MIN_32_CHARS",
    "JWT_REFRESH_SECRET": "GENERATED_STRONG_SECRET_MIN_32_CHARS"
  }' \
  --region us-east-1
```

### Step 3: Set IAM Permissions

```bash
# Create inline policy for your app's service role
aws iam put-role-policy \
  --role-name YourAppServiceRole \
  --policy-name SecretsManagerAccess \
  --policy-document '{
    "Version": "2012-10-17",
    "Statement": [
      {
        "Effect": "Allow",
        "Action": [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ],
        "Resource": "arn:aws:secretsmanager:us-east-1:ACCOUNT_ID:secret:prod/*"
      }
    ]
  }'
```

### Step 4: Update Application Code

```javascript
// app.js - Updated
const express = require('express');
const helmet = require('helmet');
const AWS = require('aws-sdk');

const app = express();
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache for secrets (optional but recommended)
const secretsCache = new Map();
const CACHE_TTL = 3600000; // 1 hour

async function getSecret(secretName) {
  // Check cache
  if (secretsCache.has(secretName)) {
    const cached = secretsCache.get(secretName);
    if (Date.now() - cached.timestamp < CACHE_TTL) {
      return cached.value;
    }
  }

  // Fetch from Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    const secretValue = JSON.parse(data.SecretString);

    // Cache it
    secretsCache.set(secretName, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw error;
  }
}

// Initialize app
(async () => {
  try {
    // Load secrets
    const dbSecret = await getSecret('prod/database');
    const apiKeys = await getSecret('prod/api-keys');
    const jwtSecret = await getSecret('prod/jwt');

    // Security middleware
    app.use(helmet());
    app.use(express.json({ limit: '10kb' }));

    // Routes
    app.get('/health', (req, res) => {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString() 
      });
    });

    app.get('/users', (req, res) => {
      // Protected endpoint would use jwtSecret for verification
      res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]);
    });

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('SIGTERM received, shutting down gracefully');
      secretsCache.clear();
      process.exit(0);
    });

  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
})();

module.exports = app;
```

---

## Step-by-Step: HashiCorp Vault Migration

### Step 1: Install Vault Client

```bash
npm install node-vault
```

### Step 2: Set Up Vault Service

```bash
# Start Vault dev server (development only)
vault server -dev

# In production, use enterprise or self-hosted
# See: https://www.vaultproject.io/docs/deployment
```

### Step 3: Create Secrets in Vault

```bash
# Enable KV secrets engine (if not already enabled)
vault secrets enable -version=2 kv

# Create secrets
vault kv put secret/prod/database \
  host="db.internal" \
  port="5432" \
  username="prod-user" \
  password="SECURE_PASSWORD"

vault kv put secret/prod/api-keys \
  stripe_key="sk_live_..." \
  anthropic_key="sk-ant-..."

# Create access policy
vault policy write app-policy - <<EOF
path "secret/data/prod/*" {
  capabilities = ["read", "list"]
}
EOF

# Create app role for authentication
vault auth enable approle
vault write auth/approle/role/app-role \
  token_ttl=1h \
  token_max_ttl=4h \
  policies="app-policy"

# Generate credentials
vault read auth/approle/role/app-role/role-id
vault write -f auth/approle/role/app-role/secret-id
```

### Step 4: Configure Vault Access

```bash
# Set environment variables
export VAULT_ADDR="https://vault.example.com"
export VAULT_ROLE_ID="YOUR_ROLE_ID"
export VAULT_SECRET_ID="YOUR_SECRET_ID"
```

### Step 5: Update Application Code

```javascript
// app.js - Vault version
const express = require('express');
const vault = require('node-vault');

const vaultClient = vault({
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN
});

async function authenticateWithVault() {
  try {
    const result = await vaultClient.auth.approle({
      role_id: process.env.VAULT_ROLE_ID,
      secret_id: process.env.VAULT_SECRET_ID
    });
    return result.auth.client_token;
  } catch (error) {
    console.error('Vault authentication failed:', error);
    throw error;
  }
}

async function getVaultSecret(secretPath) {
  try {
    const secret = await vaultClient.read(`secret/data/${secretPath}`);
    return secret.data.data; // Vault v2 kv response structure
  } catch (error) {
    console.error(`Error reading Vault secret at ${secretPath}:`, error);
    throw error;
  }
}

// Initialize
(async () => {
  try {
    // Authenticate with Vault
    await authenticateWithVault();

    // Load secrets
    const dbSecret = await getVaultSecret('prod/database');
    const apiKeys = await getVaultSecret('prod/api-keys');

    const app = express();

    app.get('/health', (req, res) => {
      res.json({ status: 'ok' });
    });

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });

  } catch (error) {
    console.error('Startup error:', error);
    process.exit(1);
  }
})();
```

