    volumes:
      - db-data:/var/lib/postgresql/data
    networks:
      - app-network

networks:
  app-network:
    driver: bridge

volumes:
  db-data:
```

---

## Kubernetes Secrets

### Create Secrets

```bash
# Create from files
kubectl create secret generic app-secrets \
  --from-file=database.json \
  --from-file=api-keys.json \
  -n production

# Create from literals
kubectl create secret generic app-secrets \
  --from-literal=JWT_SECRET=your-secret \
  --from-literal=DATABASE_URL=postgres://... \
  -n production

# Using external secret operators (recommended)
# See: https://external-secrets.io/
```

### Pod Configuration

```yaml
apiVersion: v1
kind: Pod
metadata:
  name: app-pod
  namespace: production
spec:
  containers:
  - name: app
    image: app:latest
    env:
    # Method 1: Direct environment variable
    - name: JWT_SECRET
      valueFrom:
        secretKeyRef:
          name: app-secrets
          key: JWT_SECRET

    # Method 2: Mount as volume
    volumeMounts:
    - name: secrets
      mountPath: /app/secrets
      readOnly: true

  volumes:
  - name: secrets
    secret:
      secretName: app-secrets
      defaultMode: 0400  # Read-only

  # Security context
  securityContext:
    runAsNonRoot: true
    runAsUser: 1001
    fsReadOnlyRootFilesystem: true
```

### External Secrets Operator

```yaml
# Install: helm install external-secrets external-secrets/external-secrets
apiVersion: external-secrets.io/v1beta1
kind: SecretStore
metadata:
  name: aws-secrets-store
  namespace: production
spec:
  provider:
    aws:
      service: SecretsManager
      region: us-east-1
      auth:
        jwt:
          serviceAccountRef:
            name: external-secrets-sa
---
apiVersion: external-secrets.io/v1beta1
kind: ExternalSecret
metadata:
  name: app-secrets
  namespace: production
spec:
  refreshInterval: 1h
  secretStoreRef:
    name: aws-secrets-store
    kind: SecretStore
  target:
    name: app-secrets
    creationPolicy: Owner
  data:
  - secretKey: database
    remoteRef:
      key: prod/database
  - secretKey: api-keys
    remoteRef:
      key: prod/api-keys
```

---

## Monitoring & Alerting

### CloudWatch Alarms

```bash
# Alert on failed secret access
aws cloudwatch put-metric-alarm \
  --alarm-name SecretAccessFailures \
  --alarm-description "Alert on Secrets Manager access failures" \
  --metric-name UserErrorCount \
  --namespace AWS/SecretsManager \
  --statistic Sum \
  --period 300 \
  --threshold 5 \
  --comparison-operator GreaterThanThreshold \
  --alarm-actions arn:aws:sns:us-east-1:ACCOUNT_ID:alert-topic
```

### Application Logging

```javascript
// Log secret access (without exposing secrets)
const logger = require('winston');

async function getSecretWithLogging(secretName) {
  const startTime = Date.now();

  try {
    const secret = await getSecret(secretName);

    logger.info('Secret accessed successfully', {
      secretName,
      duration: Date.now() - startTime,
      service: process.env.SERVICE_NAME,
      timestamp: new Date().toISOString()
    });

    return secret;
  } catch (error) {
    logger.error('Secret access failed', {
      secretName,
      error: error.message,
      duration: Date.now() - startTime,
      service: process.env.SERVICE_NAME,
      timestamp: new Date().toISOString()
    });

    throw error;
  }
}
```

---

## Compliance Checklist

- [ ] All secrets removed from version control
- [ ] Git history cleaned
- [ ] Secrets manager implemented
- [ ] IAM policies configured
- [ ] Secret rotation enabled
- [ ] Access logging enabled
- [ ] Monitoring alerts configured
- [ ] Disaster recovery plan documented
- [ ] Team trained on secret management
- [ ] Regular security audits scheduled

