```javascript
/**
 * secrets-manager.js
 * Unified secrets management with support for multiple backends
 */

const AWS = require('aws-sdk');
const fs = require('fs');

class SecretsManager {
  constructor(options = {}) {
    this.backend = options.backend || process.env.SECRETS_BACKEND || 'env';
    this.cache = new Map();
    this.ttl = options.ttl || 3600000; // 1 hour
    this.lastRefresh = new Map();

    if (this.backend === 'aws') {
      this.awsSecrets = new AWS.SecretsManager({
        region: options.region || process.env.AWS_REGION || 'us-east-1',
      });
    }
  }

  /**
   * Get a secret with caching and rotation support
   */
  async get(secretName, options = {}) {
    const cacheKey = secretName;
    const now = Date.now();

    // Check cache
    if (
      this.cache.has(cacheKey) &&
      (now - this.lastRefresh.get(cacheKey)) < this.ttl
    ) {
      return this.cache.get(cacheKey);
    }

    // Fetch from backend
    let secretValue;

    switch (this.backend) {
      case 'aws':
        secretValue = await this._getFromAWS(secretName);
        break;
      case 'env':
        secretValue = this._getFromEnv(secretName);
        break;
      case 'kubernetes':
        secretValue = this._getFromKubernetes(secretName);
        break;
      default:
        throw new Error(`Unknown secrets backend: ${this.backend}`);
    }

    // Cache the result
    this.cache.set(cacheKey, secretValue);
    this.lastRefresh.set(cacheKey, now);

    return secretValue;
  }

  /**
   * Get multiple secrets
   */
  async getMultiple(secretNames) {
    const results = {};
    for (const name of secretNames) {
      results[name] = await this.get(name);
    }
    return results;
  }

  /**
   * Validate that all required secrets exist
   */
  async validate(requiredSecrets) {
    const missing = [];

    for (const secret of requiredSecrets) {
      try {
        await this.get(secret);
      } catch (error) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    console.log(`✓ All ${requiredSecrets.length} required secrets validated`);
  }

  /**
   * Rotate secrets (invalidate cache)
   */
  rotate(secretName) {
    this.cache.delete(secretName);
    this.lastRefresh.delete(secretName);
    console.log(`Rotated secret: ${secretName}`);
  }

  // Private methods

  async _getFromAWS(secretName) {
    try {
      const data = await this.awsSecrets.getSecretValue({
        SecretId: secretName,
      }).promise();

      if ('SecretString' in data) {
        return data.SecretString;
      }
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    } catch (error) {
      throw new Error(`Failed to retrieve secret ${secretName} from AWS: ${error.message}`);
    }
  }

  _getFromEnv(secretName) {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Environment variable ${secretName} not found`);
    }
    return value;
  }

  _getFromKubernetes(secretName) {
    try {
      const path = `/var/run/secrets/kubernetes.io/serviceaccount/${secretName}`;
      return fs.readFileSync(path, 'utf8');
    } catch (error) {
      throw new Error(`Failed to read Kubernetes secret ${secretName}: ${error.message}`);
    }
  }
}

module.exports = SecretsManager;
```

