const SecretsManager = require('aws-sdk').SecretsManager;

class AutomatedRotationService {
  constructor() {
    this.secretsManager = new SecretsManager();
  }

  /**
   * Rotate credentials automatically
   * Returns only rotation status, not actual values
   */
  async rotateCredentials(secretId, rotationType = 'full') {
    try {
      const response = await this.secretsManager.rotateSecret({
        SecretId: secretId,
        RotationRules: {
          AutomaticallyAfterDays: 30,
          Duration: '3h',
          ScheduleExpression: 'rate(30 days)',
        },
      }).promise();

      return {
        status: 'success',
        rotatedAt: new Date().toISOString(),
        secretArn: response.ARN,
        rotationEnabled: true,
        // ⚠️ Never include actual credential values
      };
    } catch (error) {
      throw new Error(`Rotation failed: ${error.message}`);
    }
  }

  /**
   * Verify rotation without exposing credentials
   */
  async verifyRotation(secretId) {
    try {
      const metadata = await this.secretsManager.describeSecret({
        SecretId: secretId,
      }).promise();

      return {
        lastRotatedDate: metadata.LastRotatedDate,
        rotationEnabled: metadata.RotationEnabled,
        rotationRules: metadata.RotationRules,
        versions: metadata.VersionIdsToStages,
      };
    } catch (error) {
      throw new Error(`Verification failed: ${error.message}`);
    }
  }
}

module.exports = AutomatedRotationService;
