```javascript
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GCPSecretManager {
  constructor(projectId) {
    this.projectId = projectId;
    this.client = new SecretManagerServiceClient();
  }

  async getSecret(secretId, version = 'latest') {
    try {
      const name = this.client.secretVersionPath(
        this.projectId,
        secretId,
        version
      );
      const [version_] = await this.client.accessSecretVersion({ name });
      return version_.payload.data.toString('utf8');
    } catch (err) {
      console.error(`Failed to retrieve secret: ${secretId}`, err);
      throw err;
    }
  }
}

