// app-with-secrets-manager.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const AWS = require('aws-sdk');

const app = express();
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

// Cache for secrets (with TTL)
const secretsCache = new Map();
const CACHE_TTL = 3600000; // 1 hour

async function getSecret(secretName) {
  // Check cache first
  if (secretsCache.has(secretName)) {
    const cached = secretsCache.get(secretName);
    if (Date.now() - cached.timestamp < CACHE_TTL) {
      return cached.value;
    }
  }

  try {
    const data = await secretsManager
      .getSecretValue({ SecretId: secretName })
      .promise();

    const secretValue = JSON.parse(data.SecretString);

    // Cache the secret
    secretsCache.set(secretName, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  } catch (err) {
    console.error(`Failed to retrieve secret: ${secretName}`, err);
    throw new Error('Failed to initialize application secrets');
  }
}

// Lazy-load secrets on first request
let appSecrets = null;

async function initializeSecrets() {
  if (!appSecrets) {
    appSecrets = await getSecret('prod/app-secrets');
  }
  return appSecrets;
}

// Security middleware
