/**
 * Secure Secrets Management Module
 * Handles secrets loading from multiple sources
 * 
 * Features:
 * - AWS Secrets Manager integration
 * - Environment variable validation
 * - Secret rotation support
 * - Audit logging
 */

require('dotenv').config();
const winston = require('winston');

// ===== LOGGING =====
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// ===== SECRET PATTERNS FOR SCRUBBING =====
const SECRET_PATTERNS = [
  /sk_live_[a-zA-Z0-9]{24}/g,        // Stripe live keys
  /sk_test_[a-zA-Z0-9]{24}/g,        // Stripe test keys
  /sk-ant-[a-zA-Z0-9_-]{32,}/g,      // Anthropic keys
  /AKIA[0-9A-Z]{16}/g,               // AWS access keys
  /aws_secret_access_key[^&\n]*/gi,  // AWS secret keys
  /Bearer\s+[a-zA-Z0-9_.-]+/g,       // Bearer tokens
  /postgres:\/\/[^@]+@/g,            // Database connection strings
  /mongo\+srv:\/\/[^@]+@/g,          // MongoDB connection strings
];

/**
 * Scrub secrets from text
 * @param {string} text - Text that may contain secrets
 * @returns {string} - Scrubbed text with secrets replaced by [REDACTED]
 */
function scrubSecrets(text) {
  if (!text) return text;

  let scrubbed = String(text);
  SECRET_PATTERNS.forEach(pattern => {
    scrubbed = scrubbed.replace(pattern, '[REDACTED]');
  });
  return scrubbed;
}

/**
 * Validate required secrets are present
 * @param {array} requiredSecrets - List of required secret names
 * @throws Error if any required secret is missing
 */
function validateSecrets(requiredSecrets) {
  const missing = [];

  requiredSecrets.forEach(secretName => {
    if (!process.env[secretName]) {
      missing.push(secretName);
    }
  });

  if (missing.length > 0) {
    const error = `Missing required secrets: ${missing.join(', ')}`;
    logger.error(error);
    throw new Error(error);
  }

  logger.info('All required secrets validated successfully');
}

/**
 * Load secrets from AWS Secrets Manager
 * Requires AWS credentials configured
 */
async function loadFromAWSSecretsManager() {
  try {
    const { SecretsManagerClient, GetSecretValueCommand } = 
      require("@aws-sdk/client-secrets-manager");

    const client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });

    const secretPrefix = process.env.AWS_SECRETS_PREFIX || '';
    const secretsToLoad = [
      'database',
      'anthropic-api-key',
      'stripe-secret-key',
      'aws-credentials',
    ];

    logger.info('Loading secrets from AWS Secrets Manager', { 
      region: process.env.AWS_REGION,
      prefix: secretPrefix 
    });

    for (const secretName of secretsToLoad) {
      try {
        const command = new GetSecretValueCommand({ 
          SecretId: `${secretPrefix}${secretName}` 
        });

        const data = await client.send(command);

        if ('SecretString' in data) {
          const secretValue = JSON.parse(data.SecretString);

          // Map secret names to environment variables
          const envMapping = {
            'database': 'DATABASE_URL',
            'anthropic-api-key': 'ANTHROPIC_API_KEY',
            'stripe-secret-key': 'STRIPE_SECRET_KEY',
            'aws-credentials': ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY'],
          };

          const envVar = envMapping[secretName];

          if (Array.isArray(envVar)) {
            // Multiple env vars from one secret
            Object.keys(secretValue).forEach(key => {
              process.env[key] = secretValue[key];
            });
          } else {
            process.env[envVar] = typeof secretValue === 'object' 
              ? JSON.stringify(secretValue) 
              : secretValue;
          }

          logger.info('Secret loaded successfully', { 
            secret: secretName,
            // Don't log the actual value
          });
        }
      } catch (error) {
        logger.warn(`Secret not found or inaccessible: ${secretName}`, {
          error: error.code
        });
      }
    }
  } catch (error) {
    logger.error('Failed to initialize AWS Secrets Manager', {
      error: scrubSecrets(error.message)
    });
    throw error;
  }
}

/**
 * Load secrets from Doppler
 * Requires DOPPLER_TOKEN environment variable
 */
async function loadFromDoppler() {
  try {
    const { config } = require('doppler-sdk');

    logger.info('Loading secrets from Doppler');

    // Doppler automatically populates process.env
    // No additional loading needed if using doppler CLI

    logger.info('Doppler secrets loaded');
  } catch (error) {
    logger.error('Failed to load secrets from Doppler', {
      error: error.message
    });
    throw error;
  }
}

/**
 * Load secrets from HashiCorp Vault
 * Requires VAULT_ADDR and VAULT_TOKEN
 */
async function loadFromVault() {
  try {
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    logger.info('Loading secrets from HashiCorp Vault', {
      endpoint: process.env.VAULT_ADDR
    });

    const secrets = await vault.read('secret/data/app');

    if (secrets && secrets.data && secrets.data.data) {
      Object.assign(process.env, secrets.data.data);
      logger.info('Vault secrets loaded successfully');
    }
  } catch (error) {
    logger.error('Failed to load secrets from Vault', {
      error: scrubSecrets(error.message)
    });
    throw error;
  }
}

/**
 * Initialize secrets based on configuration
 */
async function initializeSecrets() {
  try {
    const secretsSource = process.env.SECRETS_SOURCE || 'env';

    logger.info('Initializing secrets', { source: secretsSource });

    switch (secretsSource.toLowerCase()) {
      case 'aws':
        await loadFromAWSSecretsManager();
        break;

      case 'doppler':
        await loadFromDoppler();
        break;

      case 'vault':
        await loadFromVault();
        break;

      case 'env':
      default:
        logger.info('Using environment variables directly (development mode)');
        break;
    }

    // Validate that all required secrets are present
    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'NODE_ENV',
    ];

    validateSecrets(requiredSecrets);

    logger.info('Secrets initialization complete');
  } catch (error) {
    logger.error('Secrets initialization failed', {
      error: scrubSecrets(error.message)
    });
    throw error;
  }
}

/**
 * Audit log secrets access
 */
function auditSecretAccess(secretName, success = true) {
  logger.info('Secret access audit', {
    event: success ? 'SECRET_ACCESS_SUCCESS' : 'SECRET_ACCESS_FAILED',
    secret: secretName,
    timestamp: new Date().toISOString(),
    // Could include: userId, service, ip, etc.
  });
}

/**
 * Get secret safely with audit logging
 */
function getSecret(secretName, defaultValue = null) {
  const value = process.env[secretName];

  if (value) {
    auditSecretAccess(secretName, true);
    return value;
  }

  if (defaultValue !== null) {
    logger.warn(`Secret not found, using default`, { secret: secretName });
    return defaultValue;
  }

  auditSecretAccess(secretName, false);
  const error = `Required secret not found: ${secretName}`;
  logger.error(error);
  throw new Error(error);
}

module.exports = {
  initializeSecrets,
  getSecret,
  scrubSecrets,
  validateSecrets,
  logger,
};

/**
 * Secured Express Application
 * 
 * Security Features:
 * - Secrets management integration
 * - Secret scrubbing in logs
 * - Audit logging for sensitive operations
 * - Secure configuration
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const winston = require('winston');
const jwt = require('jsonwebtoken');

// Import secure secrets manager
const secretsManager = require('./secrets-manager');

// ===== CONFIGURATION =====
const app = express();

// ===== LOGGING =====
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.splat(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    ...(process.env.NODE_ENV !== 'production' 
      ? [new winston.transports.Console({ 
          format: winston.format.combine(
            winston.format.colorize(),
            winston.format.simple()
          )
        })]
      : [])
  ],
  // Hook to scrub secrets from logs
  exceptionHandlers: [
    new winston.transports.File({ filename: 'exceptions.log' })
  ]
});

// Custom log formatter to scrub secrets
const originalLog = logger.log;
logger.log = function(...args) {
  if (args.length > 0 && typeof args[0] === 'object') {
    args[0].message = secretsManager.scrubSecrets(
      JSON.stringify(args[0].message || '')
    );
  }
  return originalLog.apply(logger, args);
};

// ===== SECURITY MIDDLEWARE =====

// Security headers
app.use(helmet());

// CORS configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// HTTPS enforcement
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && 
      !req.secure && 
      req.get('x-forwarded-proto') !== 'https') {
    logger.warn('Non-HTTPS request in production', { 
      path: req.path,
      ip: req.ip 
    });
    return res.status(403).json({ error: 'HTTPS required' });
  }
  next();
});

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ===== REQUEST LOGGING =====
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info('HTTP Request', {
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    });
  });

  next();
});

// ===== AUTHENTICATION MIDDLEWARE =====
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn('Authentication attempt without token', { 
      ip: req.ip,
      path: req.path 
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const jwtSecret = secretsManager.getSecret('JWT_SECRET');
    const decoded = jwt.verify(token, jwtSecret);
    req.user = decoded;

    logger.debug('Token verified successfully', { 
      userId: decoded.id,
      path: req.path
    });

    next();
  } catch (err) {
    logger.warn('Token verification failed', { 
      error: err.message,
      ip: req.ip 
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// ===== AUTHORIZATION MIDDLEWARE =====
function authorizeRole(requiredRole) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (req.user.role !== requiredRole) {
      logger.warn('Unauthorized role access attempt', { 
        userId: req.user.id,
        requiredRole,
        userRole: req.user.role,
        path: req.path
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

// ===== PUBLIC ROUTES =====

/**
 * Health check endpoint
 * Used for monitoring, no authentication required
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV 
  });
});

// ===== PROTECTED ROUTES =====

/**
 * Get users endpoint
 * Requires authentication and admin role
 * Returns sanitized user data (no emails)
 */
app.get('/users', authenticateToken, authorizeRole('admin'), (req, res) => {
  try {
    logger.info('Users list requested', { 
      userId: req.user.id,
      timestamp: new Date().toISOString()
    });

    // Only return safe fields, never expose sensitive data
    const users = [
      { id: 1, name: 'Alice', role: 'user' },
      { id: 2, name: 'Bob', role: 'user' },
    ];

    res.json(users);
  } catch (error) {
    logger.error('Error retrieving users', { 
      error: secretsManager.scrubSecrets(error.message),
      userId: req.user.id 
    });
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get current user info
 * Requires authentication
 */
app.get('/users/me', authenticateToken, (req, res) => {
  try {
    logger.info('User profile requested', { userId: req.user.id });

    res.json({
      id: req.user.id,
      email: req.user.email,
      role: req.user.role,
    });
  } catch (error) {
    logger.error('Error retrieving user profile', { 
      error: secretsManager.scrubSecrets(error.message),
      userId: req.user.id 
    });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ===== ERROR HANDLING =====

/**
 * 404 handler
 */
app.use((req, res) => {
  logger.debug('404 not found', { path: req.path, method: req.method });
  res.status(404).json({ error: 'Not found' });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: secretsManager.scrubSecrets(err.message),
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ 
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// ===== SERVER STARTUP =====

/**
 * Initialize and start server
 */
async function startServer() {
  try {
    // Initialize secrets
    await secretsManager.initializeSecrets();

    const PORT = process.env.PORT || 3000;
    const NODE_ENV = process.env.NODE_ENV || 'development';

    app.listen(PORT, () => {
      logger.info('Server started successfully', {
        port: PORT,
        environment: NODE_ENV,
        timestamp: new Date().toISOString(),
      });
    });
  } catch (error) {
    logger.error('Failed to start server', {
      error: secretsManager.scrubSecrets(error.message),
      stack: error.stack,
    });
    process.exit(1);
  }
}

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught exception', {
    message: secretsManager.scrubSecrets(error.message),
    stack: error.stack,
  });
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled rejection', {
    reason: secretsManager.scrubSecrets(JSON.stringify(reason)),
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

// Start the server
if (require.main === module) {
  startServer();
}

module.exports = app;

