## Common Vulnerability Patterns & Fixes

### SQL Injection
```javascript
// ❌ WRONG - Concatenating user input
const query = `SELECT * FROM users WHERE name = '${req.query.name}'`;
db.query(query);

// ✅ RIGHT - Use parameterized queries
const query = 'SELECT * FROM users WHERE name = ?';
db.query(query, [req.query.name]);
```

### Cross-Site Scripting (XSS)
```javascript
// ❌ WRONG - Rendering user input directly
res.send(`<h1>${req.query.title}</h1>`);

// ✅ RIGHT - Escape or use templating
res.json({ title: req.query.title }); // JSON is safe
// Or use Express template engines with auto-escape
```

### Command Injection
```javascript
// ❌ WRONG - Executing user input
const exec = require('child_process').exec;
exec(`convert ${req.body.filename}`);

// ✅ RIGHT - Use parameterized commands
const { execFile } = require('child_process');
execFile('convert', [req.body.filename]);
```

### Path Traversal
```javascript
// ❌ WRONG - Direct path manipulation
const file = req.query.file;
res.sendFile(`./uploads/${file}`);

// ✅ RIGHT - Validate and normalize paths
const path = require('path');
const file = req.query.file;
const safePath = path.join(
  path.resolve('./uploads'),
  path.normalize(file)
);
if (!safePath.startsWith(path.resolve('./uploads'))) {
  return res.status(400).json({ error: 'Invalid path' });
}
res.sendFile(safePath);
```

