require('dotenv').config();

const secretsManager = require('./secrets');
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');

/**
 * Initialize application with security hardening
 */
async function initializeApp() {
  try {
    // Step 1: Load and validate secrets
    console.log('[App] Loading secrets...');
    await secretsManager.loadSecrets();
    console.log('[App] Secrets loaded successfully');

    // Step 2: Create Express app
    const app = express();

    // Step 3: Apply security middleware
    console.log('[App] Applying security middleware...');

    // Helmet helps secure Express apps by setting various HTTP headers
    app.use(helmet({
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          scriptSrc: ["'self'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          imgSrc: ["'self'", 'data:', 'https:'],
        }
      },
      hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
      },
      frameguard: { action: 'deny' },
      noSniff: true,
      xssFilter: true,
      referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
    }));

    // CORS configuration
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
    app.use(cors({
      origin: allowedOrigins,
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
      allowedHeaders: ['Content-Type', 'Authorization'],
      maxAge: 3600,
      optionsSuccessStatus: 200
    }));

    // Rate limiting middleware
    const rateLimit = require('express-rate-limit');
    const limiter = rateLimit({
      windowMs: 15 * 60 * 1000, // 15 minutes
      max: 100, // Limit each IP to 100 requests per windowMs
      message: 'Too many requests, please try again later',
      standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
      legacyHeaders: false // Disable the `X-RateLimit-*` headers
    });

    app.use(limiter);

    // Body parser with size limits
    app.use(express.json({ limit: '1mb' }));
    app.use(express.urlencoded({ limit: '1mb', extended: true }));

    // Request logging middleware
    app.use((req, res, next) => {
      const start = Date.now();
      res.on('finish', () => {
        const duration = Date.now() - start;
        console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
      });
      next();
    });

    // Step 4: Security headers middleware
    app.use((req, res, next) => {
      res.setHeader('X-Content-Type-Options', 'nosniff');
      res.setHeader('X-Frame-Options', 'DENY');
      res.setHeader('X-XSS-Protection', '1; mode=block');
      res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
      res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
      next();
    });

    // Step 5: Error handling middleware
    app.use((err, req, res, next) => {
      console.error('[App] Error:', secretsManager.sanitizeError(err));

      if (process.env.NODE_ENV === 'production') {
        res.status(err.status || 500).json({
          error: 'Internal server error',
          timestamp: new Date().toISOString()
        });
      } else {
        res.status(err.status || 500).json({
          error: err.message,
          stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
        });
      }
    });

    console.log('[App] Security middleware applied');

    return app;
  } catch (error) {
    console.error('[App] Initialization failed:', error.message);
    process.exit(1);
  }
}

module.exports = { initializeApp, secretsManager };

