/**
 * SECRETS MANAGEMENT IMPLEMENTATIONS
 * Multiple providers for different environments
 */

// ============================================================================
// OPTION 1: AWS SECRETS MANAGER PROVIDER
// ============================================================================

class AWSSecretsProvider {
  constructor() {
    const AWS = require('aws-sdk');
    this.secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheExpiry = 3600000; // 1 hour
    this.cacheTimes = {};
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName] && !this.isCacheExpired(secretName)) {
      console.log(`[CACHE HIT] Retrieved ${secretName} from cache`);
      return this.cache[secretName];
    }

    try {
      const data = await this.secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the result
      this.cache[secretName] = secret;
      this.cacheTimes[secretName] = Date.now();

      console.log(`[AWS SECRETS MANAGER] Retrieved ${secretName}`);
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve ${secretName} from AWS:`, error);
      throw error;
    }
  }

  isCacheExpired(secretName) {
    const cacheTime = this.cacheTimes[secretName];
    return !cacheTime || (Date.now() - cacheTime > this.cacheExpiry);
  }

  async loadSecrets() {
    // Load all required secrets at startup
    const secretsToLoad = [
      'prod/database/url',
      'prod/stripe/secret_key',
      'prod/aws/access_key',
      'prod/anthropic/api_key',
      'prod/logfire/token'
    ];

    const secrets = {};
    for (const secretName of secretsToLoad) {
      secrets[secretName] = await this.getSecret(secretName);
    }
    return secrets;
  }

  // Validate secret rotation
  async validateSecretRotation(secretName, expectedVersion) {
    const data = await this.secretsManager.describeSecret({
      SecretId: secretName
    }).promise();

    if (data.VersionIdsToStages && data.VersionIdsToStages[expectedVersion]) {
      return true;
    }
    throw new Error(`Secret ${secretName} has not been rotated to expected version`);
  }
}

// ============================================================================
// OPTION 2: HASHICORP VAULT PROVIDER
// ============================================================================

class VaultProvider {
  constructor() {
    const vault = require('node-vault');
    this.vault = vault({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN,
      apiVersion: 'v1'
    });
    this.cache = {};
    this.cacheExpiry = 3600000;
    this.cacheTimes = {};
  }

  async getSecret(path) {
    // Check cache first
    if (this.cache[path] && !this.isCacheExpired(path)) {
      console.log(`[CACHE HIT] Retrieved ${path} from cache`);
      return this.cache[path];
    }

    try {
      const response = await this.vault.read(path);
      const secret = response.data.data; // Vault v2 API

      // Cache the result
      this.cache[path] = secret;
      this.cacheTimes[path] = Date.now();

      console.log(`[VAULT] Retrieved ${path}`);
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve ${path} from Vault:`, error);
      throw error;
    }
  }

  isCacheExpired(path) {
    const cacheTime = this.cacheTimes[path];
    return !cacheTime || (Date.now() - cacheTime > this.cacheExpiry);
  }

  async loadSecrets() {
    const secretPaths = [
      'secret/prod/database',
      'secret/prod/stripe',
      'secret/prod/aws',
      'secret/prod/anthropic',
      'secret/prod/logfire'
    ];

    const secrets = {};
    for (const path of secretPaths) {
      secrets[path] = await this.getSecret(path);
    }
    return secrets;
  }

  // Vault-specific: Setup automatic secret rotation
  async enableSecretRotation(secretPath, rotationInterval) {
    console.log(`Vault rotation policy can be set via Vault UI or API`);
    console.log(`Path: ${secretPath}, Interval: ${rotationInterval}`);
  }

  // List secret versions for audit
  async auditSecretAccess(path) {
    try {
      const response = await this.vault.list(`metadata/${path}`);
      return response;
    } catch (error) {
      console.error(`Audit failed for ${path}:`, error);
      throw error;
    }
  }
}

// ============================================================================
// OPTION 3: 1PASSWORD PROVIDER (CLI-based)
// ============================================================================

class OnePasswordProvider {
  constructor() {
    this.cache = {};
    this.cacheExpiry = 3600000;
    this.cacheTimes = {};
  }

  async getSecret(itemPath) {
    // Check cache first
    if (this.cache[itemPath] && !this.isCacheExpired(itemPath)) {
      console.log(`[CACHE HIT] Retrieved ${itemPath} from cache`);
      return this.cache[itemPath];
    }

    try {
      const { exec } = require('child_process');
      const { promisify } = require('util');
      const execAsync = promisify(exec);

      // Requires 1Password CLI and sign-in
      const { stdout } = await execAsync(
        `op read "${itemPath}"`
      );

      const secret = stdout.trim();
      this.cache[itemPath] = secret;
      this.cacheTimes[itemPath] = Date.now();

      console.log(`[1PASSWORD] Retrieved ${itemPath}`);
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve ${itemPath} from 1Password:`, error);
      throw error;
    }
  }

  isCacheExpired(itemPath) {
    const cacheTime = this.cacheTimes[itemPath];
    return !cacheTime || (Date.now() - cacheTime > this.cacheExpiry);
  }

  async loadSecrets() {
    const secretItems = [
      'op://production/database/url',
      'op://production/stripe/secret_key',
      'op://production/aws/access_key_id',
      'op://production/anthropic/api_key',
      'op://production/logfire/token'
    ];

    const secrets = {};
    for (const itemPath of secretItems) {
      secrets[itemPath] = await this.getSecret(itemPath);
    }
    return secrets;
  }
}

// ============================================================================
// OPTION 4: KUBERNETES SECRETS PROVIDER
// ============================================================================

class KubernetesSecretsProvider {
  constructor() {
    const k8s = require('@kubernetes/client-node');
    const kc = new k8s.KubeConfig();
    kc.loadFromDefault();
    this.v1 = kc.makeApiClient(k8s.CoreV1Api);
    this.namespace = process.env.NAMESPACE || 'default';
    this.cache = {};
    this.cacheExpiry = 3600000;
    this.cacheTimes = {};
  }

  async getSecret(secretName, key) {
    const cacheKey = `${secretName}:${key}`;

    // Check cache first
    if (this.cache[cacheKey] && !this.isCacheExpired(cacheKey)) {
      console.log(`[CACHE HIT] Retrieved ${cacheKey} from cache`);
      return this.cache[cacheKey];
    }

    try {
      const response = await this.v1.readNamespacedSecret(
        secretName,
        this.namespace
      );

      const secretValue = Buffer.from(
        response.body.data[key],
        'base64'
      ).toString('utf-8');

      this.cache[cacheKey] = secretValue;
      this.cacheTimes[cacheKey] = Date.now();

      console.log(`[K8S SECRETS] Retrieved ${cacheKey}`);
      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve ${cacheKey} from Kubernetes:`, error);
      throw error;
    }
  }

  isCacheExpired(cacheKey) {
    const cacheTime = this.cacheTimes[cacheKey];
    return !cacheTime || (Date.now() - cacheTime > this.cacheExpiry);
  }

  async loadSecrets() {
    const secretsMap = {
      'app-secrets:database_url': 'database_url',
      'app-secrets:stripe_key': 'stripe_key',
      'app-secrets:aws_access_key': 'aws_access_key',
      'app-secrets:anthropic_key': 'anthropic_key',
      'app-secrets:logfire_token': 'logfire_token'
    };

    const secrets = {};
    for (const [secretName, key] of Object.entries(secretsMap)) {
      secrets[secretName] = await this.getSecret(secretName, key);
    }
    return secrets;
  }

  // Watch for secret updates
  watchSecrets(secretName, callback) {
    const watch = new k8s.Watch(require('@kubernetes/client-node'));
    watch.watch(
      `/api/v1/namespaces/${this.namespace}/secrets`,
      { fieldSelector: `metadata.name=${secretName}` },
      (type, obj) => {
        console.log(`[K8S WATCH] Secret ${secretName} changed:`, type);
        this.cache = {}; // Invalidate cache
        callback(type, obj);
      },
      (err) => console.error('Watch error:', err)
    );
  }
}

// ============================================================================
// ENVIRONMENT-BASED PROVIDER (Development only)
// ============================================================================

class EnvProvider {
  constructor() {
    require('dotenv').config();
    this.cache = {};
  }

  async getSecret(key) {
    // Only use env provider in development
    if (process.env.NODE_ENV === 'production') {
      throw new Error(
        'EnvProvider cannot be used in production. Use a proper secrets manager.'
      );
    }

    if (this.cache[key]) {
      return this.cache[key];
    }

    const secret = process.env[key];
    if (!secret) {
      throw new Error(`Secret ${key} not found in environment variables`);
    }

    this.cache[key] = secret;
    console.log(`[ENV] Retrieved ${key}`);
    return secret;
  }

  async loadSecrets() {
    const requiredSecrets = [
      'DATABASE_URL',
      'STRIPE_SECRET_KEY',
      'AWS_ACCESS_KEY_ID',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];

    const secrets = {};
    for (const secretName of requiredSecrets) {
      secrets[secretName] = await this.getSecret(secretName);
    }
    return secrets;
  }
}

// ============================================================================
// FACTORY: SELECT PROVIDER BASED ON ENVIRONMENT
// ============================================================================

function getSecretsProvider() {
  const env = process.env.NODE_ENV || 'development';
  const secretsManager = process.env.SECRETS_MANAGER || 'env';

  console.log(`Initializing secrets provider: ${secretsManager} (${env})`);

  switch (secretsManager) {
    case 'aws':
      return new AWSSecretsProvider();
    case 'vault':
      return new VaultProvider();
    case '1password':
      return new OnePasswordProvider();
    case 'kubernetes':
      return new KubernetesSecretsProvider();
    case 'env':
    default:
      if (env === 'production') {
        throw new Error(
          'Environment provider cannot be used in production. Set SECRETS_MANAGER.'
        );
      }
      return new EnvProvider();
  }
}

// ============================================================================
// USAGE EXAMPLE IN APPLICATION
// ============================================================================

async function initializeApp() {
  const provider = getSecretsProvider();

  try {
    const secrets = await provider.loadSecrets();
    console.log('All secrets loaded successfully');
    return secrets;
  } catch (error) {
    console.error('Failed to load secrets at startup:', error);
    process.exit(1);
  }
}

// ============================================================================
// EXPORTS
// ============================================================================

module.exports = {
  AWSSecretsProvider,
  VaultProvider,
  OnePasswordProvider,
  KubernetesSecretsProvider,
  EnvProvider,
  getSecretsProvider,
  initializeApp
};

/**
 * SECURE APPLICATION WITH SECRETS MANAGEMENT
 * This version uses a proper secrets manager and follows security best practices
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const winston = require('winston');
const { initializeApp, getSecretsProvider } = require('./secrets-manager-implementations');

// ============================================================================
// CONFIGURATION
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const SECRETS_MANAGER = process.env.SECRETS_MANAGER || 'env';

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { 
    service: 'express-app',
    environment: NODE_ENV 
  },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    ),
  }));
}

// ============================================================================
// GLOBALS & STATE
// ============================================================================

const app = express();
let secretsCache = null;
let isShuttingDown = false;

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// CORS configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn({
      type: 'RATE_LIMIT_EXCEEDED',
      ip: req.ip,
      path: req.path,
      method: req.method,
    });
    res.status(429).json({ error: 'Too many requests' });
  },
});

app.use(generalLimiter);

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      type: 'HTTP_REQUEST',
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });
  });

  next();
});

// ============================================================================
// HEALTH CHECK ENDPOINT (No auth required)
// ============================================================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime(),
  });
});

// ============================================================================
// PUBLIC ENDPOINTS
// ============================================================================

app.get('/users', (req, res) => {
  try {
    // Return public data only (no email for unauthenticated users)
    const publicUsers = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.json(publicUsers);
  } catch (error) {
    logger.error({
      type: 'ENDPOINT_ERROR',
      path: '/users',
      error: error.message,
    });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn({
    type: 'NOT_FOUND',
    method: req.method,
    path: req.path,
    ip: req.ip,
  });
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const errorId = require('crypto').randomUUID();

  logger.error({
    type: 'UNHANDLED_ERROR',
    errorId,
    message: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  // Don't expose internal details in production
  const response = {
    error: NODE_ENV === 'production' 
      ? 'Internal server error'
      : err.message,
    errorId, // For debugging
  };

  if (NODE_ENV === 'development' && err.stack) {
    response.stack = err.stack;
  }

  res.status(err.statusCode || 500).json(response);
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

function gracefulShutdown(signal) {
  logger.info(`${signal} received, starting graceful shutdown...`);
  isShuttingDown = true;

  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 30 seconds
  setTimeout(() => {
    logger.error('Forced shutdown due to timeout');
    process.exit(1);
  }, 30000);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// ============================================================================
// SECRETS LOADING
// ============================================================================

async function loadSecrets() {
  try {
    logger.info(`Loading secrets from: ${SECRETS_MANAGER}`);

    const provider = getSecretsProvider();
    secretsCache = await provider.loadSecrets();

    logger.info('Secrets loaded successfully');
    return secretsCache;
  } catch (error) {
    logger.error({
      type: 'SECRETS_LOAD_FAILED',
      message: error.message,
      secrelsManager: SECRETS_MANAGER,
    });
    throw error;
  }
}

// ============================================================================
// STARTUP
// ============================================================================

let server;

async function start() {
  try {
    // Load secrets before starting server
    await loadSecrets();

    server = app.listen(PORT, () => {
      logger.info({
        type: 'SERVER_STARTED',
        port: PORT,
        environment: NODE_ENV,
        secretsManager: SECRETS_MANAGER,
        timestamp: new Date().toISOString(),
      });
    });

  } catch (error) {
    logger.error({
      type: 'STARTUP_FAILED',
      message: error.message,
      stack: error.stack,
    });
    process.exit(1);
  }
}

// Start the application
if (require.main === module) {
  start();
}

// ============================================================================
// EXPORTS
// ============================================================================

module.exports = app;

/**
 * ENVIRONMENT-SPECIFIC SECRETS CONFIGURATION
 * Shows how to properly structure and load secrets in different environments
 */

// ============================================================================
// CONFIGURATION STRUCTURE
// ============================================================================

const developmentSecrets = {
  database: {
    url: 'sqlite://./dev.db',
    // Use local database, never production credentials
  },
  api: {
    stripe: 'sk_test_[REDACTED-EXAMPLE]',  // Test key
    anthropic: 'sk-ant-test-key',
    logfire: 'test-token',
  },
  aws: {
    accessKeyId: null,  // Use local mocking instead
    secretAccessKey: null,
    region: 'us-east-1',
  },
