  },
};

const testSecrets = {
  database: {
    url: 'sqlite://./test.db',
    // Isolated test database
  },
  api: {
    stripe: 'sk_test_[REDACTED-EXAMPLE]',
    anthropic: 'sk-ant-test-key',
    logfire: 'test-token',
  },
  aws: {
    accessKeyId: 'AKIA_TEST_ONLY',
    secretAccessKey: 'test-only-key',
    region: 'us-east-1',
  },
  auth: {
    jwtSecret: 'test-secret-never-use-in-production',
    sessionTimeout: 300,  // Shorter for testing
  },
};

// Production: Load from secrets manager
const productionSecrets = {
  database: {
    // Loaded from AWS Secrets Manager or similar
    // Structure: { url: 'postgresql://...' }
  },
  api: {
    // Loaded from secrets manager
    // Structure: { stripe: 'sk_live_...', anthropic: '...', etc }
  },
  aws: {
