    // Structure: { jwtSecret: '...', sessionTimeout: 3600 }
  },
};

// ============================================================================
// CONFIGURATION LOADER
// ============================================================================

const fs = require('fs');
const path = require('path');

class ConfigurationManager {
  constructor(environment = process.env.NODE_ENV || 'development') {
    this.environment = environment;
    this.config = {};
    this.loadedSecrets = {};
  }

  async loadConfiguration() {
    console.log(`Loading configuration for: ${this.environment}`);

    switch (this.environment) {
      case 'production':
        return await this.loadProductionConfig();
      case 'staging':
        return await this.loadStagingConfig();
      case 'test':
        return this.loadTestConfig();
      case 'development':
      default:
        return this.loadDevelopmentConfig();
    }
  }

  loadDevelopmentConfig() {
    console.log('Using development secrets (local .env file)');

    // In development, use .env file but validate it doesn't have production secrets
    require('dotenv').config({ path: '.env.development.local' });

    this.validateDevelopmentSecrets();

    return {
      ...developmentSecrets,
      // Override with .env values if present
      database: {
        url: process.env.DATABASE_URL || developmentSecrets.database.url,
      },
