        logfire: process.env.LOGFIRE_TOKEN || testSecrets.api.logfire,
      },
    };
  }

  async loadProductionConfig() {
    console.log('Using production secrets (AWS Secrets Manager)');

    const AWS = require('aws-sdk');
    const secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    try {
      const secrets = await this.getSecretFromAWS(secretsManager, 'prod/app-secrets');
      return this.validateProductionSecrets(secrets);
    } catch (error) {
