    }

    console.log('✓ Production secrets validated');
    return secrets;
  }

  validateStagingSecrets(secrets) {
    // Validate staging secrets
    const requiredSecrets = ['database', 'api', 'auth'];

    for (const key of requiredSecrets) {
      if (!secrets[key]) {
