      }
    }

    console.log('✓ Staging secrets validated');
    return secrets;
  }

  getNestedValue(obj, path) {
    return path.split('.').reduce((current, prop) => current?.[prop], obj);
  }

  validateEnvironmentSeparation() {
    const env = process.env.NODE_ENV;

    // Ensure clear separation between environments
    if (env === 'production') {
      // Production must use secrets manager
      if (!process.env.SECRETS_MANAGER || process.env.SECRETS_MANAGER === 'env') {
