      }
    }

    if (env === 'test') {
      // Test must use isolated test credentials
      if (fs.existsSync('.env.production.local')) {
        const content = fs.readFileSync('.env.production.local', 'utf8');
        if (content.includes('sk_live') || content.includes('@prod.')) {
          throw new Error('Production credentials detected in test environment');
        }
      }
    }

    console.log('✓ Environment separation validated');
  }

  // Create environment-specific .env template
  static createTemplate(environment) {
    const templates = {
      development: `# Development Configuration
NODE_ENV=development
SECRETS_MANAGER=env
LOG_LEVEL=debug

# Use LOCAL test credentials ONLY
DATABASE_URL=sqlite://./dev.db
STRIPE_SECRET_KEY=sk_test_[REDACTED-EXAMPLE]
ANTHROPIC_API_KEY=sk-ant-local-testing
JWT_SECRET=dev-secret-do-not-use-production

# Features
DEBUG_MODE=true
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:5173
`,
      test: `# Test Configuration  
NODE_ENV=test
SECRETS_MANAGER=env
LOG_LEVEL=error

# Isolated test database
DATABASE_URL=sqlite://./test.db
STRIPE_SECRET_KEY=sk_test_[REDACTED-EXAMPLE]
ANTHROPIC_API_KEY=sk-ant-test-key
JWT_SECRET=test-secret-12345

# Quick sessions for tests
SESSION_TIMEOUT=300
`,
      staging: `# Staging Configuration
NODE_ENV=staging
SECRETS_MANAGER=vault
LOG_LEVEL=info

# Vault configuration
VAULT_ADDR=https://vault.staging.internal
VAULT_TOKEN=s.VAULT_TOKEN_FROM_K8S

# AWS configuration
AWS_REGION=us-east-1

# Other services load from Vault
`,
      production: `# Production Configuration
NODE_ENV=production
SECRETS_MANAGER=aws

# AWS Secrets Manager configuration
AWS_REGION=us-east-1

# All secrets loaded from AWS Secrets Manager
# Never commit actual secrets to this file
# See app-secure.js for implementation

# Features
DEBUG_MODE=false
LOG_LEVEL=warn
`,
    };

    return templates[environment] || '';
  }
}

// ============================================================================
// USAGE EXAMPLES
// ============================================================================

// Example 1: Load configuration in application startup
async function exampleApplicationStartup() {
  const configManager = new ConfigurationManager();

  try {
    configManager.validateEnvironmentSeparation();
    const config = await configManager.loadConfiguration();
    console.log('Configuration loaded successfully');
    return config;
  } catch (error) {
    console.error('Configuration load failed:', error.message);
    process.exit(1);
  }
}

// Example 2: Create template for environment
function exampleCreateTemplate() {
  const env = process.env.NODE_ENV || 'development';
  const template = ConfigurationManager.createTemplate(env);

  console.log(`Template for ${env}:`);
  console.log(template);
}

// ============================================================================
// EXPORTS
// ============================================================================

module.exports = {
  ConfigurationManager,
  developmentSecrets,
  testSecrets,
  exampleApplicationStartup,
  exampleCreateTemplate,
};

