// Secure version of app.js with security best practices implemented
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ============================================================================
// ENVIRONMENT VARIABLES & VALIDATION
// ============================================================================
const JWT_SECRET = process.env.JWT_SECRET;
const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;
const CORS_ORIGIN = process.env.CORS_ORIGIN || 'http://localhost:3000';

if (!JWT_SECRET && NODE_ENV === 'production') {
  throw new Error('JWT_SECRET environment variable is required in production');
}

// ============================================================================
// LOGGING CONFIGURATION
// ============================================================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5
    }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet - Set various HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS - Restrict cross-origin requests
const corsOptions = {
  origin: function(origin, callback) {
    const whitelist = CORS_ORIGIN.split(',').map(o => o.trim());

    if (!origin || whitelist.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn(`Blocked CORS request from ${origin}`);
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
};

app.use(cors(corsOptions));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks (but log them)
    return req.path === '/health';
  }
});

app.use(limiter);

// 4. Strict transport security redirect
app.use((req, res, next) => {
  if (NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
    res.redirect(`https://${req.header('host')}${req.url}`);
  } else {
    next();
  }
});

// Body parser middleware
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn(`Authentication failed: No token provided from ${req.ip}`);
    return res.status(401).json({ 
      error: 'Access token required',
      message: 'Please provide a valid JWT token'
    });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Authentication failed: Invalid token from ${req.ip}`);
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        message: NODE_ENV === 'development' ? err.message : undefined
      });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// REQUEST LOGGING MIDDLEWARE
// ============================================================================

app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      userId: req.user?.id || 'anonymous'
    });
  });

  next();
});

// ============================================================================
// ROUTE HANDLERS
// ============================================================================

/**
 * Health check endpoint
 * Public endpoint for monitoring
 */
app.get('/health', (req, res) => {
  res.status(200).json({ 
    status: 'ok'
    // Don't expose sensitive information like timestamps or version
  });
});

/**
 * Login endpoint - Generates JWT token
 */
app.post('/login', express.json(), (req, res) => {
  try {
    const { username, password } = req.body;

    // Input validation
    if (!username || !password) {
      return res.status(400).json({ 
        error: 'Username and password are required' 
      });
    }

    // Validate input format
    if (typeof username !== 'string' || username.length > 100) {
      return res.status(400).json({ 
        error: 'Invalid username format' 
      });
    }

    if (typeof password !== 'string' || password.length > 255) {
      return res.status(400).json({ 
        error: 'Invalid password format' 
      });
    }

    // TODO: In production, verify against database with bcrypt
    // This is a simplified example
    const user = {
      id: 1,
      username: username,
      admin: false
    };

    // Generate JWT token
    const token = jwt.sign(user, JWT_SECRET, { 
      expiresIn: '1h',
      algorithm: 'HS256'
    });

    logger.info(`User ${username} logged in successfully from ${req.ip}`);
    res.json({ token });
  } catch (error) {
    logger.error('Login error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

/**
 * Get users endpoint
 * Protected endpoint - requires authentication
 */
app.get('/users', 
  authenticateToken,
  [
    query('search').optional().isString().trim().isLength({ max: 100 }),
    query('limit').optional().isInt({ min: 1, max: 100 }),
    query('offset').optional().isInt({ min: 0 })
  ],
  (req, res) => {
    try {
      // Validation error handling
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn(`Validation error for /users from ${req.ip}:`, errors.array());
        return res.status(400).json({ 
          errors: errors.array().map(e => ({
            field: e.param,
            message: e.msg
          }))
        });
      }

      // Check authorization
      if (!req.user.admin) {
        logger.warn(`Unauthorized access to /users by user ${req.user.id}`);
        return res.status(403).json({ 
          error: 'Insufficient permissions',
          message: 'Only administrators can access this resource'
        });
      }

      const { search, limit = 10, offset = 0 } = req.query;

      // Mock data
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter by search term
      if (search) {
        const searchLower = search.toLowerCase();
        users = users.filter(u => 
          u.name.toLowerCase().includes(searchLower) ||
          u.email.toLowerCase().includes(searchLower)
        );
      }

      // Pagination
      const total = users.length;
      users = users.slice(offset, offset + limit);

      logger.info(`User ${req.user.id} retrieved ${users.length} users`);
      res.json({ 
        data: users,
        pagination: {
          offset,
          limit,
          total
        }
      });
    } catch (error) {
      logger.error('Get users error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

/**
 * Get single user endpoint
 * Protected endpoint with ID validation
 */
app.get('/users/:id',
  authenticateToken,
  [
    query('id').isInt({ min: 1 })
  ],
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const userId = parseInt(req.params.id);

      // Mock data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found' 
        });
      }

      logger.info(`User ${req.user.id} retrieved user ${userId}`);
      res.json(user);
    } catch (error) {
      logger.error('Get user error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// Handle 404 - Not Found
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({ 
    error: 'Endpoint not found',
    message: `${req.method} ${req.path} does not exist`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const status = err.status || 500;
  const isDevelopment = NODE_ENV === 'development';

  res.status(status).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      status: status,
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Original vs Secure Version - Vulnerability Comparison

## Side-by-Side Code Comparison

### Vulnerability 1: Authentication

#### ❌ ORIGINAL (VULNERABLE)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Problems:**
- Anyone can access this endpoint
- No authentication check
- Sensitive data (emails) exposed
- No authorization control

**Attack:**
```bash
curl http://attacker.com:3000/users
# Returns all user data without auth
```

#### ✅ SECURE VERSION
```javascript
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Auth failed: No token from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Auth failed: Invalid token from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

app.get('/users', 
  authenticateToken,
  (req, res) => {
    if (!req.user.admin) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    res.json([
      { id: 1, name: 'Alice' },  // Email removed
      { id: 2, name: 'Bob' },
    ]);
  }
);
```

**Solutions:**
- JWT authentication required
- Authorization checks
- Data minimization (emails removed)
- Logging of failed attempts

