#### 4. Rotate Secrets (Add to your ops/devops)

```bash
#!/bin/bash
# rotate-secrets.sh - Run monthly

AWS_REGION="us-east-1"
SECRET_ID="app/production/secrets"

# Get current secret
CURRENT=$(aws secretsmanager get-secret-value \
  --secret-id $SECRET_ID \
  --region $AWS_REGION \
  --query SecretString \
  --output text)

# Update passwords/keys here
NEW_DB_PASS=$(openssl rand -base64 32)
NEW_API_KEY=$(openssl rand -base64 32)

# Parse and update
UPDATED=$(echo $CURRENT | jq \
  --arg dbpass "$NEW_DB_PASS" \
  --arg apikey "$NEW_API_KEY" \
  '.DATABASE_PASSWORD = $dbpass | .API_KEY = $apikey')

# Update secret
aws secretsmanager update-secret \
  --secret-id $SECRET_ID \
  --secret-string "$UPDATED" \
  --region $AWS_REGION

echo "✓ Secrets rotated"
```

