/**
 * HARDENED APP.JS with Secrets Management
 * Implements AWS Secrets Manager with fallback to environment variables
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const AWS = require('aws-sdk');

const app = express();
app.use(helmet());

// ============================================================================
// SECRETS MANAGEMENT
// ============================================================================

class SecretsManager {
  constructor() {
    this.secrets = null;
    this.lastFetch = 0;
    this.cacheTTL = 60 * 60 * 1000; // 1 hour cache

    // Initialize AWS Secrets Manager only in production
    if (process.env.NODE_ENV === 'production') {
      this.awsSecretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    }
  }

  async load() {
    // Check cache validity
    if (this.secrets && Date.now() - this.lastFetch < this.cacheTTL) {
      console.log('[SECRETS] Using cached secrets');
      return this.secrets;
    }

    try {
      if (process.env.NODE_ENV === 'production') {
        await this._loadFromAWS();
      } else {
        await this._loadFromEnvironment();
      }

      this.lastFetch = Date.now();
      return this.secrets;
    } catch (err) {
      console.error('[SECRETS] Failed to load secrets:', err.message);
      throw err;
    }
  }

  async _loadFromAWS() {
    try {
      const response = await this.awsSecretsManager.getSecretValue({
        SecretId: process.env.SECRETS_MANAGER_NAME || 'app/production/secrets'
      }).promise();

      // Parse secret
      let secretString;
      if ('SecretString' in response) {
        secretString = response.SecretString;
      } else {
        secretString = Buffer.from(
          response.SecretBinary,
          'base64'
        ).toString('ascii');
      }

      this.secrets = JSON.parse(secretString);
      console.log('[SECRETS] Loaded from AWS Secrets Manager');

      // Validate required secrets are present
      this._validateSecrets();

    } catch (err) {
      throw new Error(`AWS Secrets Manager error: ${err.message}`);
    }
  }

  async _loadFromEnvironment() {
    // Development: load from environment variables
    this.secrets = {
      DATABASE_URL: process.env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
    };

    console.log('[SECRETS] Loaded from environment variables (DEV MODE)');

    if (Object.values(this.secrets).some(v => !v)) {
      console.warn('[SECRETS] WARNING: Some secrets are missing');
    }
  }

  _validateSecrets() {
    const required = [
      'DATABASE_URL',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
    ];

    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  get(key) {
    if (!this.secrets) {
      throw new Error('Secrets not loaded. Call load() first.');
    }

    if (!this.secrets[key]) {
      throw new Error(`Secret "${key}" not found`);
    }

    return this.secrets[key];
  }

  has(key) {
    return this.secrets && key in this.secrets;
  }
}

// ============================================================================
// APPLICATION INITIALIZATION
// ============================================================================

const secretsManager = new SecretsManager();
let appReady = false;

/**
 * Initialize application with secrets
 */
async function initializeApp() {
  try {
    // Load secrets first
    await secretsManager.load();

    // Setup routes
    setupRoutes();

    // Start server
    const port = process.env.PORT || 3000;
    app.listen(port, () => {
      console.log(`[APP] Server running on port ${port}`);
      console.log(`[APP] Environment: ${process.env.NODE_ENV || 'development'}`);
      appReady = true;
    });

  } catch (err) {
    console.error('[APP] Failed to initialize:', err.message);
    process.exit(1);
  }
}

/**
 * Health check endpoint (no secrets required)
 */
function setupRoutes() {
  app.get('/health', (req, res) => {
    if (!appReady) {
      return res.status(503).json({ 
        status: 'initializing',
        error: 'Application is still starting up'
      });
    }

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
      uptime: process.uptime()
    });
  });

  app.get('/api/protected', (req, res) => {
    // Example protected endpoint that would use secrets
    // In real app: add authentication/authorization middleware

    res.json({
      message: 'This endpoint uses secrets internally'
    });
  });

  // 404 handler
  app.use((req, res) => {
    res.status(404).json({ error: 'Not found' });
  });

  // Error handler
  app.use((err, req, res, next) => {
    console.error('[ERROR]', err.message);

    const isDev = process.env.NODE_ENV === 'development';
    res.status(err.statusCode || 500).json({
      error: isDev ? err.message : 'Internal server error',
      ...(isDev && { stack: err.stack })
    });
  });
}

// ============================================================================
// STARTUP
// ============================================================================

// Initialize app when this module is loaded
initializeApp().catch(err => {
  console.error('[FATAL]', err);
  process.exit(1);
});

module.exports = app;
EOF

