#!/usr/bin/env node

/**
 * SECURE SECRETS MANAGEMENT GUIDE
 * 
 * This module demonstrates how to properly manage secrets
 * using industry best practices and cloud-native solutions
 */

// ============================================================================
// OPTION 1: AWS SECRETS MANAGER (Recommended for AWS deployments)
// ============================================================================

const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

/**
 * Retrieve secrets from AWS Secrets Manager
 * - Secrets are encrypted at rest
 * - Secrets are not stored in files
 * - Access controlled via IAM policies
 * - Audit trail of access
 */
async function getAWSSecret(secretName) {
  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    } else {
      const buff = Buffer.from(data.SecretBinary, 'base64');
      return buff.toString('ascii');
    }
  } catch (error) {
    console.error(`Failed to retrieve secret: ${secretName}`, error);
    throw error;
  }
}

// Usage example:
async function initializeWithAWSSecrets() {
  const dbSecret = await getAWSSecret('prod/database/credentials');
  const apiKeys = await getAWSSecret('prod/api/keys');

  return {
    database: dbSecret,
    apis: apiKeys
  };
}

// ============================================================================
// OPTION 2: Azure Key Vault (Recommended for Azure deployments)
// ============================================================================

const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

const credential = new DefaultAzureCredential();
const client = new SecretClient(
  `https://${process.env.AZURE_VAULT_NAME}.vault.azure.net/`,
  credential
);

/**
 * Retrieve secrets from Azure Key Vault
 * - Managed by Azure
 * - Automatic rotation support
 * - RBAC integration
 * - Audit logging included
 */
async function getAzureSecret(secretName) {
  try {
    const secret = await client.getSecret(secretName);
    return secret.value;
  } catch (error) {
    console.error(`Failed to retrieve secret from Azure Key Vault: ${secretName}`, error);
    throw error;
  }
}

// Usage example:
async function initializeWithAzureSecrets() {
  const dbUrl = await getAzureSecret('database-url');
  const apiKey = await getAzureSecret('api-key');

  return {
    databaseUrl: dbUrl,
    apiKey: apiKey
  };
}

// ============================================================================
// OPTION 3: HashiCorp Vault (Recommended for hybrid/on-prem)
// ============================================================================

const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN
});

/**
 * Retrieve secrets from HashiCorp Vault
 * - Multi-cloud support
 * - Dynamic secrets generation
 * - Encryption as a service
 * - Policy-based access control
 */
async function getVaultSecret(path) {
  try {
    const secret = await vault.read(path);
    return secret.data.data;
  } catch (error) {
    console.error(`Failed to retrieve secret from Vault: ${path}`, error);
    throw error;
  }
}

// Usage example:
async function initializeWithVault() {
  const dbCreds = await getVaultSecret('secret/data/database');
  const apiKeys = await getVaultSecret('secret/data/api-keys');

  return {
    database: dbCreds,
    apis: apiKeys
  };
}

// ============================================================================
// OPTION 4: Google Cloud Secret Manager (For GCP)
// ============================================================================

const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

const gcpClient = new SecretManagerServiceClient();

/**
 * Retrieve secrets from Google Cloud Secret Manager
 * - Native GCP integration
 * - Automatic encryption
 * - Fine-grained access control
 * - Rotation policies
 */
async function getGCPSecret(secretId, version = 'latest') {
  try {
    const projectId = process.env.GCP_PROJECT_ID;
    const name = gcpClient.secretVersionPath(projectId, secretId, version);
    const [version_] = await gcpClient.accessSecretVersion({ name });
    return version_.payload.data.toString('utf-8');
  } catch (error) {
    console.error(`Failed to retrieve secret from GCP: ${secretId}`, error);
    throw error;
  }
}

// Usage example:
async function initializeWithGCPSecrets() {
  const dbUrl = await getGCPSecret('database-url');
  const apiKey = await getGCPSecret('api-key');

  return {
    databaseUrl: dbUrl,
    apiKey: apiKey
  };
}

// ============================================================================
// OPTION 5: Fallback - Secure .env handling (For development ONLY)
// ============================================================================

const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

/**
 * Load secrets from .env file with strict security checks
 * WARNING: Only use in development environment
 */
function loadEnvSecurely(envPath = '.env') {
  const stats = fs.statSync(envPath);

  // Check file permissions - should be 0o600 (rw-------)
  const mode = stats.mode & parseInt('777', 8);
  if (mode !== parseInt('600', 8)) {
    throw new Error(
      `SECURITY ERROR: .env file has insecure permissions (${mode.toString(8)}). ` +
      `Expected 0o600 (rw-------). Run: chmod 600 ${envPath}`
    );
  }

  // Load and parse
  const envConfig = dotenv.parse(fs.readFileSync(envPath));
  return envConfig;
}

// Usage:
async function initializeWithEnvFile() {
  if (process.env.NODE_ENV === 'production') {
    throw new Error('Cannot load secrets from .env file in production. Use a secrets manager.');
  }

  return loadEnvSecurely();
}

// ============================================================================
// UNIFIED SECRETS LOADER
// ============================================================================

/**
 * Unified interface that selects appropriate secrets backend
 * based on deployment environment
 */
class SecretsManager {
  constructor() {
    this.backend = null;
    this.secrets = {};
  }

  async initialize() {
    const environment = process.env.NODE_ENV;
    const secretsBackend = process.env.SECRETS_BACKEND;

    try {
      switch (secretsBackend || 'auto-detect') {
        case 'aws':
          this.backend = 'aws-secrets-manager';
          this.secrets = await initializeWithAWSSecrets();
          break;

        case 'azure':
          this.backend = 'azure-key-vault';
          this.secrets = await initializeWithAzureSecrets();
          break;

        case 'vault':
          this.backend = 'hashicorp-vault';
          this.secrets = await initializeWithVault();
          break;

        case 'gcp':
          this.backend = 'gcp-secret-manager';
          this.secrets = await initializeWithGCPSecrets();
          break;

        case 'env':
          if (environment !== 'development') {
            throw new Error('Env file backend only allowed in development');
          }
          this.backend = 'env-file';
          this.secrets = await initializeWithEnvFile();
          break;

        case 'auto-detect':
        default:
          // Auto-detect based on environment
          if (process.env.AWS_REGION) {
            this.backend = 'aws-secrets-manager';
            this.secrets = await initializeWithAWSSecrets();
          } else if (process.env.AZURE_VAULT_NAME) {
            this.backend = 'azure-key-vault';
            this.secrets = await initializeWithAzureSecrets();
          } else if (process.env.VAULT_ADDR) {
            this.backend = 'hashicorp-vault';
            this.secrets = await initializeWithVault();
          } else if (process.env.GCP_PROJECT_ID) {
            this.backend = 'gcp-secret-manager';
            this.secrets = await initializeWithGCPSecrets();
          } else if (environment === 'development') {
            this.backend = 'env-file';
            this.secrets = await initializeWithEnvFile();
          } else {
            throw new Error(
              'No secrets backend configured. Set SECRETS_BACKEND environment variable ' +
              'or provide cloud provider credentials'
            );
          }
      }

      console.log(`✓ Secrets loaded from: ${this.backend}`);
      return this.secrets;
    } catch (error) {
      console.error('Failed to initialize secrets manager:', error.message);
      throw error;
    }
  }

  get(key, defaultValue = null) {
    return this.secrets[key] ?? defaultValue;
  }

  require(key) {
    if (!this.secrets[key]) {
      throw new Error(`Required secret not found: ${key}`);
    }
    return this.secrets[key];
  }
}

// ============================================================================
// INTEGRATION EXAMPLE
// ============================================================================

const secretsManager = new SecretsManager();

async function startApplication() {
  // Initialize secrets
  await secretsManager.initialize();

  // Access secrets
  const databaseUrl = secretsManager.require('DATABASE_URL');
  const jwtSecret = secretsManager.require('JWT_SECRET');
  const apiKey = secretsManager.get('THIRD_PARTY_API_KEY');

  // Use in application
  const app = require('./app');
  app.configure({
    database: databaseUrl,
    auth: { secret: jwtSecret },
    api: { key: apiKey }
  });

  app.listen(process.env.PORT || 3000);
}

// Export for use
module.exports = {
  SecretsManager,
  getAWSSecret,
  getAzureSecret,
  getVaultSecret,
  getGCPSecret,
  startApplication
};

// Start if run directly
if (require.main === module) {
  startApplication().catch(err => {
    console.error('Fatal error:', err);
    process.exit(1);
  });
}

