// Secure version of app.js with security improvements
// See SECURITY_AUDIT.txt for detailed vulnerability analysis

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const csrf = require('csurf');
const cookieParser = require('cookie-parser');
const { v4: uuidv4 } = require('uuid');

// ============================================================
// SECURITY MIDDLEWARE
// ============================================================

// 1. HELMET - Sets secure HTTP headers (prevents XSS, Clickjacking, etc.)
app.use(helmet());

// 2. Cookie Parser - Required for CSRF protection
app.use(cookieParser(process.env.COOKIE_SECRET || 'your-secret-key'));

// 3. Body Parser with size limits - Prevents payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data sanitization - Prevents NoSQL injection
app.use(mongoSanitize());

// 5. Rate Limiting - Prevents brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 requests per 15 minutes for auth
  skipSuccessfulRequests: true,
});

// CSRF Protection
const csrfProtection = csrf({ cookie: true });

// ============================================================
// ROUTES WITH SECURITY
// ============================================================

// Health check endpoint - No sensitive data exposed
app.get('/health', (req, res) => {
  // Generate request ID for logging/tracking
  const requestId = uuidv4();

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    requestId: requestId
  });
});

// Users endpoint - With authentication, validation, and authorization
app.get('/users', 
  authLimiter, // Stricter rate limit
  authenticateToken, // Authentication middleware
  authorizeAdmin, // Authorization middleware
  (req, res) => {
    try {
      // Sanitize and validate any query parameters
      const limit = sanitizeInteger(req.query.limit, 10, 1, 100);
      const offset = sanitizeInteger(req.query.offset, 0, 0, 1000);

      // Database query would go here (with parameterized queries)
      // const users = await db.query(
      //   'SELECT id, name, email FROM users LIMIT $1 OFFSET $2',
      //   [limit, offset]
      // );

      // Mock data (in real app, fetch from database with parameterized queries)
      const mockUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      res.json({
        success: true,
        data: mockUsers,
        meta: {
          limit: limit,
          offset: offset,
          requestId: req.id
        }
      });
    } catch (error) {
      logSecurityEvent('Error fetching users', {
        userId: req.user.id,
        error: error.message
      });
      res.status(500).json({
        success: false,
        message: 'Internal server error',
        requestId: req.id
      });
    }
  }
);

// Create user endpoint - With input validation
app.post('/users',
  authLimiter,
  authenticateToken,
  csrfProtection,
  (req, res) => {
    try {
      // Validate input
      const { name, email, password } = req.body;

      // 1. Check required fields
      if (!name || !email || !password) {
        return res.status(400).json({
          success: false,
          message: 'Missing required fields: name, email, password'
        });
      }

      // 2. Validate email format
      if (!validator.isEmail(email)) {
        return res.status(400).json({
          success: false,
          message: 'Invalid email format'
        });
      }

      // 3. Validate name (alphanumeric and spaces only, max 100 chars)
      if (!validator.isLength(name, { min: 1, max: 100 }) || 
          !validator.matches(name, /^[a-zA-Z0-9\s'-]+$/)) {
        return res.status(400).json({
          success: false,
          message: 'Invalid name format'
        });
      }

      // 4. Validate password strength
      if (!validator.isLength(password, { min: 12 })) {
        return res.status(400).json({
          success: false,
          message: 'Password must be at least 12 characters'
        });
      }

      // 5. Sanitize inputs
      const sanitizedName = validator.escape(name);
      const sanitizedEmail = validator.normalizeEmail(email);

      // Password should be hashed with bcrypt
      // const hashedPassword = await bcrypt.hash(password, 12);

      // Database insert with parameterized query
      // await db.query(
      //   'INSERT INTO users (name, email, password) VALUES ($1, $2, $3)',
      //   [sanitizedName, sanitizedEmail, hashedPassword]
      // );

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: {
          name: sanitizedName,
          email: sanitizedEmail
        }
      });

    } catch (error) {
      logSecurityEvent('Error creating user', {
        userId: req.user.id,
        error: error.message
      });
      res.status(500).json({
        success: false,
        message: 'Internal server error'
      });
    }
  }
);

// ============================================================
// SECURITY MIDDLEWARE FUNCTIONS
// ============================================================

/**
 * Authentication middleware - Verify JWT or session
 */
function authenticateToken(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({
      success: false,
      message: 'Access token required'
    });
  }

  // In production, verify JWT token
  // try {
  //   const decoded = jwt.verify(token, process.env.JWT_SECRET);
  //   req.user = decoded;
  //   next();
  // } catch (err) {
  //   return res.status(403).json({ message: 'Invalid token' });
  // }

  // Mock implementation for this example
  req.user = { id: 1, role: 'admin' };
  req.id = uuidv4();
  next();
}

/**
 * Authorization middleware - Check user role/permissions
 */
function authorizeAdmin(req, res, next) {
  if (req.user.role !== 'admin') {
    logSecurityEvent('Unauthorized access attempt', {
      userId: req.user.id,
      endpoint: req.path,
      requiredRole: 'admin',
      userRole: req.user.role
    });

    return res.status(403).json({
      success: false,
      message: 'Insufficient permissions'
    });
  }

  next();
}

/**
 * Sanitize integer input
 * @param {*} value - Input value
 * @param {number} defaultValue - Default if invalid
 * @param {number} min - Minimum allowed value
 * @param {number} max - Maximum allowed value
 * @returns {number} Validated integer
 */
function sanitizeInteger(value, defaultValue, min, max) {
  const parsed = parseInt(value, 10);

  if (isNaN(parsed)) {
    return defaultValue;
  }

  if (parsed < min) return min;
  if (parsed > max) return max;

  return parsed;
}

/**
 * Log security events to monitoring system
 * @param {string} event - Event description
 * @param {object} details - Additional event details
 */
function logSecurityEvent(event, details) {
  // In production, send to SIEM/logging system
  console.warn(`[SECURITY] ${event}`, JSON.stringify(details, null, 2));
}

// ============================================================
// ERROR HANDLING
// ============================================================

// Global error handler - Don't expose stack traces to clients
app.use((err, req, res, next) => {
  const requestId = req.id || uuidv4();

  // Log full error details server-side only
  console.error(`[ERROR] Request ${requestId}:`, err);

  // Don't expose internal error details to client
  res.status(err.status || 500).json({
    success: false,
    message: 'Internal server error',
    requestId: requestId
    // Never include: err.stack, err.message, database details, etc.
  });
});

// ============================================================
// STARTUP
// ============================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

