/**
 * Secure Secrets Management Module
 * Handles loading secrets from different sources based on environment
 * Supports: AWS Secrets Manager, HashiCorp Vault, Environment Variables
 */

const fs = require('fs');
const path = require('path');

/**
 * Secrets Manager Factory
 * Returns appropriate secrets provider based on environment
 */
class SecretsManager {
  constructor() {
    this.env = process.env.NODE_ENV || 'development';
    this.secrets = {};
    this.provider = this.selectProvider();
  }

  /**
   * Select the appropriate secrets provider
   */
  selectProvider() {
    switch (this.env) {
      case 'production':
        return new AWSSecretsManagerProvider();
      case 'staging':
        return new VaultSecretsProvider();
      case 'development':
        return new DotenvProvider();
      default:
        return new DotenvProvider();
    }
  }

  /**
   * Initialize and load secrets
   */
  async initialize() {
    try {
      console.log(`[Secrets] Loading secrets from: ${this.provider.constructor.name}`);
      this.secrets = await this.provider.loadSecrets();
      this.validateSecrets();
      console.log('[Secrets] ✓ Secrets loaded successfully');
      return this.secrets;
    } catch (error) {
      console.error('[Secrets] ✗ Failed to load secrets:', error.message);
      throw error;
    }
  }

  /**
   * Validate that all required secrets are present
   */
  validateSecrets() {
    const required = [
      'DATABASE_URL',
      'JWT_SECRET',
      'API_KEY_STRIPE',
      'API_KEY_ANTHROPIC',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  /**
   * Get a secret value
   */
  get(key) {
    const value = this.secrets[key];
    if (!value) {
      throw new Error(`Secret not found: ${key}`);
    }
    return value;
  }

  /**
   * Check if secret exists
   */
  has(key) {
    return key in this.secrets;
  }

  /**
   * Get all secrets (for debugging only - never expose in logs)
   */
  getAll() {
    return { ...this.secrets };
  }
}

/**
 * AWS Secrets Manager Provider
 * Recommended for production environments
 */
class AWSSecretsManagerProvider {
  async loadSecrets() {
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager({ region: 'us-east-1' });

    try {
      const data = await client
        .getSecretValue({ SecretId: 'app/production/secrets' })
        .promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        // Handle binary secrets if needed
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      console.log('[Secrets] Loaded from AWS Secrets Manager');
      return secret;
    } catch (error) {
      throw new Error(`Failed to load from AWS Secrets Manager: ${error.message}`);
    }
  }
}

/**
 * HashiCorp Vault Provider
 * Recommended for enterprise/staging environments
 */
class VaultSecretsProvider {
  async loadSecrets() {
    const axios = require('axios');

    const vaultAddr = process.env.VAULT_ADDR || 'http://vault:8200';
    const vaultToken = process.env.VAULT_TOKEN;
    const vaultPath = process.env.VAULT_PATH || 'secret/app/staging';

    if (!vaultToken) {
      throw new Error('VAULT_TOKEN environment variable not set');
    }

    try {
      const response = await axios.get(`${vaultAddr}/v1/${vaultPath}`, {
        headers: {
          'X-Vault-Token': vaultToken
        }
      });

      console.log('[Secrets] Loaded from HashiCorp Vault');
      return response.data.data.data;
    } catch (error) {
      throw new Error(`Failed to load from Vault: ${error.message}`);
    }
  }
}

/**
 * Dotenv Provider (Development Only)
 * Should NEVER be used in production
 */
class DotenvProvider {
  async loadSecrets() {
    require('dotenv').config({
      path: process.env.ENV_FILE || '.env.local'
    });

    console.log('[Secrets] ⚠️  Loaded from .env file (DEVELOPMENT ONLY)');

    return {
      DATABASE_URL: process.env.DATABASE_URL,
      JWT_SECRET: process.env.JWT_SECRET,
      API_KEY_STRIPE: process.env.API_KEY_STRIPE,
      API_KEY_ANTHROPIC: process.env.API_KEY_ANTHROPIC,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      COOKIE_SECRET: process.env.COOKIE_SECRET,
      LOG_LEVEL: process.env.LOG_LEVEL || 'info'
    };
  }
}

/**
 * Singleton instance
 */
let instance = null;

/**
 * Get or create SecretsManager instance
 */
function getSecretsManager() {
  if (!instance) {
    instance = new SecretsManager();
  }
  return instance;
}

module.exports = {
  SecretsManager,
  getSecretsManager,
  AWSSecretsManagerProvider,
  VaultSecretsProvider,
  DotenvProvider
};

