/**
 * Secure Express Application with Proper Secrets Management
 * 
 * Key Security Features:
 * - AWS Secrets Manager integration
 * - No hardcoded secrets
 * - Secure initialization
 * - Audit logging for secret access
 */

require('dotenv').config({ path: process.env.ENV_FILE || '.env.local' });

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const AWS = require('aws-sdk');

// ============ LOGGER CONFIGURATION ============
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============ SECRETS MANAGER CLASS ============
class SecretsManager {
  constructor() {
    if (process.env.NODE_ENV === 'production') {
      this.client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
      this.mode = 'aws';
    } else {
      // Development: use environment variables
      this.mode = 'env';
      logger.warn('[SECURITY] Running in development mode - using environment variables');
    }

    this.cache = {};
    this.cacheTimestamp = Date.now();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    const now = Date.now();
    if (this.cache[secretName] && (now - this.cacheTimestamp) < this.cacheTTL) {
      logger.debug(`[SECRETS] Cache hit for ${secretName}`);
      return this.cache[secretName];
    }

    try {
      let secret;

      if (this.mode === 'aws') {
        logger.info(`[SECRETS] Fetching ${secretName} from AWS Secrets Manager`);

        const data = await this.client.getSecretValue({
          SecretId: secretName
        }).promise();

        if ('SecretString' in data) {
          secret = JSON.parse(data.SecretString);
        } else {
          secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
        }

        logger.info(`[AUDIT] Retrieved secret: ${secretName}`);
      } else {
        // Development mode - get from environment
        const envKey = secretName.toUpperCase().replace(/-/g, '_').replace(/\//g, '_');
        secret = process.env[envKey];

        if (!secret) {
          throw new Error(`Secret ${envKey} not found in environment`);
        }

        logger.info(`[SECRETS] Loaded ${secretName} from environment variable`);
      }

      // Cache the secret
      this.cache[secretName] = secret;
      this.cacheTimestamp = now;

      return secret;
    } catch (error) {
      logger.error(`[SECRETS] Error fetching ${secretName}:`, {
        error: error.message,
        mode: this.mode
      });
      throw error;
    }
  }

  async getDbCredentials() {
    if (this.mode === 'aws') {
      const secret = await this.getSecret(process.env.DB_SECRET_NAME || 'prod/database');
      return typeof secret === 'string' ? JSON.parse(secret) : secret;
    } else {
      return {
        username: process.env.DB_USERNAME,
        password: process.env.DB_PASSWORD,
        host: process.env.DB_HOST,
        port: process.env.DB_PORT,
        database: process.env.DB_NAME,
      };
    }
  }

  async getApiKey(keyName) {
    const secretPath = `prod/api-keys/${keyName}`;
    return this.getSecret(secretPath);
  }
}

// ============ INITIALIZE APPLICATION ============
const app = express();
const secretsManager = new SecretsManager();

let appSecrets = {};

async function initializeApp() {
  try {
    logger.info('[INIT] Initializing application...');

    // Load required secrets
    appSecrets.jwtSecret = await secretsManager.getSecret(
      process.env.JWT_SECRET_NAME || 'prod/jwt-secret'
    );

    appSecrets.dbCredentials = await secretsManager.getDbCredentials();

    logger.info('[INIT] Application initialized successfully');
    return true;
  } catch (error) {
    logger.error('[INIT] Failed to initialize application:', error);

    // In production, fail hard if we can't load secrets
    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    }

    return false;
  }
}

// ============ SECURITY MIDDLEWARE ============
app.use(helmet());
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
}));

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

app.use(morgan('combined', {
  stream: { write: msg => logger.info(msg.trim()) }
}));

app.use(express.json({ limit: '10kb' }));

// ============ AUTHENTICATION MIDDLEWARE ============
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`[SECURITY] Unauthorized access attempt to ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, appSecrets.jwtSecret, (err, user) => {
    if (err) {
      logger.warn(`[SECURITY] Invalid token from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    req.user = user;
    logger.debug(`[AUDIT] User ${user.id} accessed ${req.path}`);
    next();
  });
};

// ============ ROUTES ============
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
  });
});

// Public endpoint
app.get('/users/public', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Database name from secrets (not the password!)
  const dbName = appSecrets.dbCredentials.database;

  res.json({
    users: [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ],
    database: dbName, // Only non-sensitive info
  });
});

// ============ ERROR HANDLING ============
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  logger.error('[ERROR]', err);

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ============ STARTUP ============
async function start() {
  const initialized = await initializeApp();

  if (initialized || process.env.NODE_ENV !== 'production') {
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      logger.info(`[STARTUP] Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
    });
  }
}

// Only start if this is the main module
if (require.main === module) {
  start().catch(error => {
    logger.error('[FATAL] Failed to start server:', error);
    process.exit(1);
  });
}

module.exports = { app, secretsManager, initializeApp };
