```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');

const app = express();

// ============ SECRETS LOADING (Single Source of Truth) ============
let secrets = null;

async function initializeSecrets() {
  // Choose based on environment
  if (process.env.ENVIRONMENT === 'aws') {
    const { getSecret } = require('./secrets-manager-aws');
    secrets = {
      database: await getSecret('prod/database'),
      aws: await getSecret('prod/aws'),
      stripe: await getSecret('prod/stripe'),
      anthropic: await getSecret('prod/anthropic'),
      logfire: await getSecret('prod/logfire')
    };
  } else if (process.env.ENVIRONMENT === 'vault') {
    const { getSecret } = require('./vault-manager');
    secrets = {
      database: await getSecret('secret/data/prod/database'),
      aws: await getSecret('secret/data/prod/aws'),
      stripe: await getSecret('secret/data/prod/stripe'),
      anthropic: await getSecret('secret/data/prod/anthropic'),
      logfire: await getSecret('secret/data/prod/logfire')
    };
  } else if (process.env.NODE_ENV === 'development') {
    // Development only - use .env.development (never .env.test in Git!)
    secrets = {
      database: process.env.DATABASE_URL,
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
      },
      stripe: process.env.STRIPE_SECRET_KEY,
      anthropic: process.env.ANTHROPIC_API_KEY,
      logfire: process.env.LOGFIRE_TOKEN
    };
  }

  return secrets;
}

// ============ STARTUP ============
app.use(helmet());

// Protected route - example
const jwt = require('jsonwebtoken');
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  jwt.verify(token, secrets.jwt_secret, (err, user) => {
    if (err) return res.status(403).json({ error: 'Forbidden' });
    req.user = user;
    next();
  });
};

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============ START SERVER ============
const PORT = process.env.PORT || 3000;

async function start() {
  try {
    // Load secrets before starting server
    await initializeSecrets();

    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV}`);
    });
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

start();

module.exports = app;
```

