// secrets-audit.js
const logger = require('winston');

function validateSecretsLoaded() {
  const requiredSecrets = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY'
  ];

  const missing = requiredSecrets.filter(s => !process.env[s]);

  if (missing.length > 0) {
    logger.error('CRITICAL: Missing secrets on startup', { missing });
    process.exit(1);
  }

  logger.info('All required secrets loaded successfully');
}

function auditSecretAccess(secretName, action) {
  logger.info('Secret accessed', {
    secret: secretName,
    action,
    timestamp: new Date().toISOString(),
    user: process.env.USER,
    pid: process.pid
  });
}

