const CACHE_TTL = 3600000; // 1 hour

async function getSecret(secretName) {
  const cached = secretsCache.get(secretName);

  // Return cached if still valid
  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    return cached.value;
  }

  try {
    const result = await client.getSecretValue({
      SecretId: secretName
    }).promise();

    const secret = result.SecretString ? 
      JSON.parse(result.SecretString) : 
      result.SecretBinary;

    // Cache the secret
    secretsCache.set(secretName, {
      value: secret,
      timestamp: Date.now()
    });

    return secret;
  } catch (error) {
    console.error(`Failed to retrieve secret: ${secretName}`, error);
    throw error;
  }
}

// Usage in app.js
const express = require('express');
const app = express();

let dbUrl, awsAccessKey, awsSecretKey, apiKeys;

// Load secrets on startup
async function initializeSecrets() {
  try {
    const dbSecret = await getSecret('prod/database');
    const awsSecret = await getSecret('prod/aws-credentials');
    const apiSecret = await getSecret('prod/api-keys');

    dbUrl = dbSecret.DATABASE_URL;
    awsAccessKey = awsSecret.AWS_ACCESS_KEY_ID;
    awsSecretKey = awsSecret.AWS_SECRET_ACCESS_KEY;
    apiKeys = apiSecret;

    console.log('Secrets loaded successfully');
  } catch (error) {
    console.error('Failed to load secrets - cannot start application');
    process.exit(1);
  }
}

app.listen(3000, async () => {
  await initializeSecrets();
  console.log('Server initialized with secrets');
});
