let cachedSecrets = {};
const CACHE_TTL = 3600000; // 1 hour

async function loadSecret(secretName) {
  // Return cached if valid
  if (cachedSecrets[secretName] && 
      Date.now() - cachedSecrets[secretName].loadedAt < CACHE_TTL) {
    return cachedSecrets[secretName].value;
  }

  try {
    const result = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    const secret = JSON.parse(result.SecretString);

    // Cache it
    cachedSecrets[secretName] = {
      value: secret,
      loadedAt: Date.now()
    };

    return secret;
  } catch (error) {
    console.error('Failed to load secret:', secretName, error.message);
    throw new Error('Cannot start: secrets unavailable');
  }
}

