// SECURE VERSION - Using AWS Secrets Manager
const express = require('express');
const AWS = require('aws-sdk');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Initialize AWS Secrets Manager client
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Secret cache with TTL
const secretCache = new Map();
const CACHE_TTL = 3600000; // 1 hour

/**
 * Load secret from Secrets Manager with caching
 * @param {string} secretName - Name of secret
 * @returns {Promise<Object>} - Secret value
 */
async function getSecret(secretName) {
  const cached = secretCache.get(secretName);

  // Return cached secret if still valid
  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    console.log(`[CACHE HIT] Retrieved ${secretName} from cache`);
    return cached.value;
  }

  try {
    console.log(`[SECRETS_MANAGER] Retrieving ${secretName}...`);
    const result = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    const secret = result.SecretString 
      ? JSON.parse(result.SecretString) 
      : Buffer.from(result.SecretBinary, 'base64').toString('ascii');

    // Cache the secret
    secretCache.set(secretName, {
      value: secret,
      timestamp: Date.now()
    });

    console.log(`[SECRETS_MANAGER] Successfully loaded ${secretName}`);
    return secret;
  } catch (error) {
    console.error(`[ERROR] Failed to load secret ${secretName}:`, error.message);
    throw new Error(`Cannot load secret: ${secretName}`);
  }
}

// Security middleware
app.use(helmet()); // Add security headers

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP'
});
app.use(limiter);

// Custom security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});

// Health check endpoint (no secrets needed)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Protected users endpoint
app.get('/users', (req, res) => {
  // In production, add authentication middleware here
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('[ERROR]', {
    message: err.message,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal Server Error',
      status: err.status || 500
    }
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

/**
 * Initialize application and load secrets
 */
async function initialize() {
  try {
    console.log('[INIT] Starting application initialization...');

    // Verify secrets are accessible
    // (In production, these would be used to configure database, APIs, etc.)
    const appSecrets = await getSecret('prod/app-secrets');

    console.log('[INIT] Secrets loaded successfully');

    const PORT = process.env.PORT || 3000;
    const NODE_ENV = process.env.NODE_ENV || 'development';

    app.listen(PORT, () => {
      console.log(`[INFO] Server running on port ${PORT} in ${NODE_ENV} mode`);
    });
  } catch (error) {
    console.error('[FATAL] Failed to initialize application:', error.message);
    process.exit(1);
  }
}

// Only initialize if this is the main module
if (require.main === module) {
  initialize();
}

module.exports = app;
