## PROPER SECRETS MANAGEMENT SOLUTION

### **RECOMMENDED APPROACH: Use a Secrets Manager**

#### **Option 1: AWS Secrets Manager (for AWS environments)**

```javascript
// secrets.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

let secretsCache = {};

async function getSecret(secretName) {
  // Check cache first (expires after 1 hour in production)
  if (secretsCache[secretName] && secretsCache[secretName].expires > Date.now()) {
    return secretsCache[secretName].value;
  }

  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    let secret;
    if ('SecretString' in data) {
      secret = JSON.parse(data.SecretString);
    } else {
      secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    // Cache for 1 hour
    secretsCache[secretName] = {
      value: secret,
      expires: Date.now() + 3600000
    };

    return secret;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw new Error('Failed to load configuration');
  }
}

module.exports = { getSecret };
```

**Usage in app.js:**
```javascript
const { getSecret } = require('./secrets');

app.get('/initialize', async (req, res) => {
  try {
    const dbSecret = await getSecret('prod/database');
    const awsSecret = await getSecret('prod/aws');

    // Connect using retrieved secrets
    // Secrets never stored in environment variables

    res.json({ status: 'initialized' });
  } catch (error) {
    res.status(500).json({ error: 'Initialization failed' });
  }
});
```

