```javascript
// vault-client.js
const vault = require('node-vault');

const client = vault({
  endpoint: process.env.VAULT_ADDR || 'https://vault.example.com',
  token: process.env.VAULT_TOKEN // obtained from CI/CD system, not developer laptop
});

async function getVaultSecret(path, key) {
  try {
    const response = await client.read(path);
    return response.data.data[key];
  } catch (error) {
    console.error(`Failed to retrieve vault secret ${path}/${key}:`, error);
    throw error;
  }
}

// Renew token periodically
async function renewVaultToken() {
  try {
    await client.tokenRenewSelf();
  } catch (error) {
    console.error('Token renewal failed:', error);
    process.exit(1); // Force restart if token can't be renewed
  }
}

// Renew every 30 minutes
setInterval(renewVaultToken, 30 * 60 * 1000);

module.exports = { getVaultSecret };
```

