// gcp-secrets.js
const secretManager = require('@google-cloud/secret-manager');

const client = new secretManager.SecretManagerServiceClient();

async function getGCPSecret(projectId, secretId, version = 'latest') {
  try {
    const name = client.secretVersionPath(projectId, secretId, version);
    const [version_] = await client.accessSecretVersion({ name });

    const secretString = version_.payload.data.toString('utf8');

    // Try to parse as JSON, otherwise return as string
    try {
      return JSON.parse(secretString);
    } catch {
      return secretString;
    }
  } catch (error) {
