// audit-logger.js
const fs = require('fs');
const path = require('path');

function logSecretAccess(secretName, accessor, timestamp = new Date()) {
  const logEntry = {
    timestamp,
    secretName,
    accessor, // user/service that accessed it
    action: 'SECRET_ACCESS',
    success: true
  };

  const logPath = path.join(__dirname, 'logs', 'secret-access.jsonl');
  fs.appendFileSync(logPath, JSON.stringify(logEntry) + '\n');
}

function logSecretRotation(secretName, oldVersion, newVersion) {
  const logEntry = {
    timestamp: new Date(),
    secretName,
    action: 'SECRET_ROTATION',
    oldVersion,
    newVersion
  };

  const logPath = path.join(__dirname, 'logs', 'secret-rotation.jsonl');
  fs.appendFileSync(logPath, JSON.stringify(logEntry) + '\n');
}

module.exports = { logSecretAccess, logSecretRotation };
```

