// ============================================================================
// HASHICORP VAULT IMPLEMENTATION
// For most secure, platform-agnostic secret management
// ============================================================================

const vault = require('node-vault');

class VaultSecretsManager {
  constructor(options = {}) {
    this.endpoint = options.endpoint || process.env.VAULT_ADDR;
    this.token = options.token || process.env.VAULT_TOKEN;
    this.namespace = options.namespace || 'secret';

    if (!this.endpoint || !this.token) {
      throw new Error('VAULT_ADDR and VAULT_TOKEN environment variables required');
    }

    this.client = vault({
      endpoint: this.endpoint,
      token: this.token,
      apiVersion: 'v1'
    });

    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour

    // Start token renewal
    this.startTokenRenewal();
  }

  /**
   * Retrieve a secret from Vault
   */
  async getSecret(path, key = null) {
    const cacheKey = key ? `${path}:${key}` : path;
    const cached = this.cache.get(cacheKey);

    if (cached && cached.expiresAt > Date.now()) {
      console.log(`[Cache HIT] ${cacheKey}`);
      return cached.value;
    }

    try {
      console.log(`[Fetching] ${cacheKey} from Vault`);
      const response = await this.client.read(`${this.namespace}/${path}`);

      const value = key ? response.data.data[key] : response.data.data;

      this.cache.set(cacheKey, {
        value,
        expiresAt: Date.now() + this.cacheTTL
      });

      console.log(`[Cached] ${cacheKey}`);
      return value;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve ${cacheKey}:`, error.message);

      // Return cached value if available
      if (cached) {
        console.warn(`[FALLBACK] Using expired cache for ${cacheKey}`);
        return cached.value;
      }

      throw error;
    }
  }

  /**
   * List available secrets
   */
  async listSecrets(path) {
    try {
      const response = await this.client.list(`${this.namespace}/${path}`);
      return response.data.keys;
    } catch (error) {
      console.error(`Failed to list secrets at ${path}:`, error);
      throw error;
    }
  }

  /**
   * Write a secret (use carefully, usually done outside app)
   */
  async setSecret(path, data) {
    try {
      await this.client.write(`${this.namespace}/${path}`, { data });
      this.cache.delete(path);
      console.log(`[SET] Secret written to ${path}`);
    } catch (error) {
      console.error(`Failed to write secret to ${path}:`, error);
      throw error;
    }
  }

  /**
   * Renew Vault token automatically
   * Vault tokens expire and need periodic renewal
   */
  startTokenRenewal() {
    // Renew every 30 minutes (adjust based on token TTL)
    setInterval(async () => {
      try {
        console.log('[Token] Renewing Vault token...');
        const response = await this.client.tokenRenewSelf();
        const newTTL = response.auth.lease_duration;
        console.log(`[Token] Renewed successfully, new TTL: ${newTTL}s`);
      } catch (error) {
        console.error('[Token] Renewal failed:', error.message);
        // If we can't renew, we should exit and restart
        console.error('[CRITICAL] Cannot renew Vault token, exiting...');
        process.exit(1);
      }
    }, 30 * 60 * 1000);
  }

  /**
   * Get token info
   */
  async getTokenInfo() {
    try {
      return await this.client.tokenLookupSelf();
    } catch (error) {
      console.error('Failed to get token info:', error);
      throw error;
    }
  }

  /**
   * Clear cache
   */
  clearCache() {
    this.cache.clear();
    console.log('[Cache] Cleared');
  }
}

// Usage in Express app
