cat > scripts/scan-secrets.js << 'SCANNER'
#!/usr/bin/env node

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const secretPatterns = [
  /AKIA[0-9A-Z]{16}/,                    // AWS Access Key
  /aws_secret_access_key\s*=\s*(.+)/i,   // AWS Secret Key
  /sk_live_[a-zA-Z0-9]{20,}/,             // Stripe Live Key
  /sk_test_[a-zA-Z0-9]{20,}/,             // Stripe Test Key
  /ghp_[a-zA-Z0-9]{36}/,                  // GitHub Token
  /django-insecure-[a-zA-Z0-9]{50,}/,    // Django Secret
  /password\s*=\s*(.+)/i,                // Password
  /api[_-]?key\s*[:=]\s*(.+)/i,          // API Key
];

function scanDirectory(dir) {
  const excludePaths = ['.git', 'node_modules', '.next', 'dist', 'build'];
  let foundSecrets = false;

  function scan(currentPath) {
    try {
      const items = fs.readdirSync(currentPath);

      items.forEach(item => {
        const fullPath = path.join(currentPath, item);
        const stat = fs.statSync(fullPath);

        if (excludePaths.includes(item)) return;

        if (stat.isDirectory()) {
          scan(fullPath);
        } else if (stat.isFile() && !item.startsWith('.')) {
          const content = fs.readFileSync(fullPath, 'utf8');

          secretPatterns.forEach((pattern, idx) => {
            if (pattern.test(content)) {
              console.log(`❌ Potential secret found in ${fullPath}`);
              foundSecrets = true;
            }
          });
        }
      });
    } catch (error) {
      // Skip permission errors
    }
  }

  scan(dir);
  return foundSecrets;
}

console.log('🔍 Scanning for secrets...');
const found = scanDirectory(process.cwd());

if (found) {
  console.log('❌ Secrets detected!');
  process.exit(1);
} else {
  console.log('✅ No secrets detected');
  process.exit(0);
}
SCANNER

chmod +x scripts/scan-secrets.js

# 6. Update package.json scripts
echo "📝 Adding npm scripts..."
npm pkg set scripts.scan-secrets="node scripts/scan-secrets.js"
npm pkg set scripts.check-secrets="gitleaks detect --verbose"

echo ""
echo "✅ Secret scanning setup complete!"
echo ""
echo "📝 Next steps:"
echo "   1. Review your git history: git log --all"
echo "   2. If secrets found, clean with: git filter-branch"
echo "   3. Run: npm run check-secrets"
echo "   4. Commit these changes"
echo "   5. Your pre-commit hook will now block secrets"
echo ""

EOF

