});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

---

### **2. No Authentication/Authorization (OWASP A01:2021 - Broken Access Control)**

**Issue:** The `/users` endpoint exposes sensitive user data without any authentication or authorization checks.

**Risk:** Any attacker can access all user information including emails.

**Recommended Fix:**
```javascript
const jwt = require('jsonwebtoken');
const SECRET_KEY = process.env.JWT_SECRET || 'your-secret-key';

// Middleware for authentication
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Verify user has permission to access user data
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### **3. No Input Validation (OWASP A03:2021 - Injection)**

**Issue:** The application doesn't validate or sanitize any input parameters. Although the current endpoints don't accept parameters, this is a pattern issue.

**Recommended Fix - Add validation middleware:**
```javascript
const { query, validationResult } = require('express-validator');

// Example protected endpoint with validation
app.get('/user/:id', 
  authenticateToken,
  query('id').isInt({ min: 1 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = req.params.id;
    // Fetch user safely
    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  }
);
```

---

### **4. No Rate Limiting (OWASP A04:2021 - Insecure Design)**

**Issue:** Endpoints are unprotected against brute force, DDoS, and abuse attacks.

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Strict rate limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: false,
});

// Apply limiters
app.use('/api/', limiter);
app.post('/login', strictLimiter, (req, res) => {
  // Login logic
});
```

---

### **5. No CORS Configuration (OWASP A01:2021 - Broken Access Control)**

**Issue:** Missing explicit CORS policy allows requests from any origin, which could facilitate CSRF attacks.

**Recommended Fix:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));

// CSRF protection for state-changing operations
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

app.use(cookieParser());
app.use(csrf({ cookie: true }));

