## **SECURE SECRETS MANAGEMENT SOLUTION**

### **Option 1: AWS Secrets Manager (Recommended for Production)**

```javascript
// ✅ GOOD: Using AWS Secrets Manager
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

async function getSecrets() {
  try {
    const secretName = process.env.NODE_ENV === 'production' 
      ? 'prod/app-secrets' 
      : 'dev/app-secrets';

    const data = await secretsManager.getSecretValue({
      SecretId: secretName,
      VersionStage: 'AWSCURRENT'
    }).promise();

    let secrets;
    if ('SecretString' in data) {
      secrets = JSON.parse(data.SecretString);
    } else {
      const buff = Buffer.from(data.SecretBinary, 'base64');
      secrets = JSON.parse(buff.toString('ascii'));
    }

    return secrets;
  } catch (error) {
    console.error('Error retrieving secrets:', error);
    throw error;
  }
}

// Usage in app.js
(async () => {
  const secrets = await getSecrets();
  const app = require('express')();

  const JWT_SECRET = secrets.JWT_SECRET;
  const DB_URL = secrets.DATABASE_URL;
  // ... rest of app
})();
```

