```javascript
// ✅ GOOD: Using encrypted secrets for local development
const fs = require('fs');
const crypto = require('crypto');

const ENCRYPTION_KEY = Buffer.from(
  process.env.LOCAL_ENCRYPTION_KEY || 
  '0'.repeat(64), 
  'hex'
);

function decryptSecrets(encryptedFile) {
  const encrypted = fs.readFileSync(encryptedFile);

  const iv = encrypted.slice(0, 16);
  const decipher = crypto.createDecipheriv(
    'aes-256-cbc',
    ENCRYPTION_KEY,
    iv
  );

  let decrypted = decipher.update(encrypted.slice(16));
  decrypted = Buffer.concat([decrypted, decipher.final()]);

  return JSON.parse(decrypted.toString('utf8'));
}

// Usage
const secrets = decryptSecrets('.secrets.encrypted');
const JWT_SECRET = secrets.JWT_SECRET;
