```javascript
const express = require('express');
const helmet = require('helmet');
require('dotenv').config(); // Only for non-secret config

const app = express();

// In production, use AWS Secrets Manager, Vault, etc.
// For local dev, use encrypted secrets
let secrets;

async function initializeApp() {
  // Production: Use secrets manager
  if (process.env.NODE_ENV === 'production') {
    secrets = await getSecretsFromAWSSecretsManager();
  } 
  // Development: Use encrypted file or local vault
  else if (process.env.NODE_ENV === 'development') {
    secrets = require('node-vault')({
      endpoint: process.env.VAULT_ADDR
    });
  }
  // Testing: Use test secrets from memory (never from .env)
  else {
    secrets = {
      JWT_SECRET: 'test-secret-change-me',
      DATABASE_URL: 'postgres://test:test@localhost/test',
    };
  }

  // Validate secrets are loaded
  if (!secrets.JWT_SECRET || !secrets.DATABASE_URL) {
    throw new Error('Critical secrets not loaded');
  }

  setupRoutes();
  return app;
}

function setupRoutes() {
  app.use(helmet());

  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // Protected endpoint using secret
  app.get('/users', authenticateWithSecret, (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });
}

function authenticateWithSecret(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  try {
    const jwt = require('jsonwebtoken');
    jwt.verify(token, secrets.JWT_SECRET); // Use loaded secret
    next();
  } catch (error) {
    res.status(403).json({ error: 'Invalid token' });
  }
}

// Start only if not imported as module
if (require.main === module) {
  initializeApp()
    .then(() => {
      const PORT = process.env.PORT || 3000;
      app.listen(PORT, () => {
        console.log(`Server running on port ${PORT}`);
      });
    })
    .catch(error => {
      console.error('Failed to initialize app:', error);
      process.exit(1);
    });
}

module.exports = { app, initializeApp };
```

