```javascript
// Automated secret rotation (using AWS Secrets Manager)
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function rotateSecrets() {
  const secretsToRotate = [
    'prod/app-secrets',
    'prod/jwt-secret',
    'prod/api-keys'
  ];

  for (const secretName of secretsToRotate) {
    try {
      await secretsManager.rotateSecret({
        SecretId: secretName,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN,
        RotationRules: {
