      const token = jwt.sign(
        { id: 1, username: 'testuser', role: 'user' },
        process.env.JWT_SECRET || 'test-secret'
      );

      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`);

      // First request should succeed
      expect([200, 429]).toContain(response.status);
    });
  });

  // ============================================
  // SENSITIVE DATA EXPOSURE TESTS (A01 + A02)
  // ============================================

  describe('Sensitive Data Handling', () => {
    test('Response should not expose sensitive stack traces in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(response.body.error).not.toContain('stack');
      expect(response.body.error).not.toContain('at ');

      process.env.NODE_ENV = originalEnv;
    });

    test('Response should have consistent timestamps', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.body.timestamp).toBeDefined();
      // Should be valid ISO string
      expect(() => new Date(response.body.timestamp)).not.toThrow();
    });
  });

  // ============================================
  // CORS TESTS (A07: Cross-Origin Issues)
  // ============================================

  describe('CORS Configuration - A07: Cross-Origin Issues', () => {
    test('Valid origin should be allowed', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });

    test('Credentials should be allowed for valid origins', async () => {
      const response = await request(app)
        .options('/users')
        .set('Origin', 'http://localhost:3000')
        .set('Access-Control-Request-Method', 'GET');

      // Should include CORS headers
      expect(response.status).toBeLessThan(500);
    });
  });

  // ============================================
  // ERROR HANDLING TESTS
  // ============================================

  describe('Error Handling & Logging', () => {
    test('404 errors should return proper response', async () => {
      const response = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(response.body.error).toBeDefined();
    });

    test('POST with invalid body should handle gracefully', async () => {
      const response = await request(app)
        .post('/login')
        .send({ invalid: 'data' });

      expect(response.status).toBe(400);
      expect(response.body.error).toBeDefined();
    });
  });

  // ============================================
  // INJECTION ATTACK PREVENTION TESTS
  // ============================================

  describe('Injection Prevention', () => {
    test('SQL-like injection in query should be rejected', async () => {
      const response = await request(app)
        .get('/users?id=1; DROP TABLE users;--')
        .set('Authorization', `Bearer ${validToken}`)
        .expect(400);

      expect(response.body.errors).toBeDefined();
    });

    test('NoSQL injection attempts should be rejected', async () => {
      const response = await request(app)
        .get('/users?id={"$gt":""}')
        .set('Authorization', `Bearer ${validToken}`)
        .expect(400);

      expect(response.body.errors).toBeDefined();
    });

    test('XSS-like parameters should be validated', async () => {
      const response = await request(app)
        .get('/users?name=<script>alert("xss")</script>')
        .set('Authorization', `Bearer ${validToken}`);

      // Should either reject or sanitize
      expect([400, 200]).toContain(response.status);
    });
  });

  // ============================================
  // PUBLIC ENDPOINTS TESTS
  // ============================================

  describe('Public Endpoints', () => {
    test('Health endpoint should be public', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.body.status).toBe('ok');
      expect(response.body.timestamp).toBeDefined();
    });

    test('Health endpoint should not require authentication', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.status).toBe(200);
    });
  });
});

