/**
 * Secrets Manager
 * 
 * Loads secrets from AWS Secrets Manager in production
 * or from .env.local in development
 * 
 * NEVER hardcode secrets or store them in version control!
 */

const AWS = require('aws-sdk');

const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

let cachedSecrets = null;
let cacheTimestamp = null;
const CACHE_TTL = 5 * 60 * 1000; // Cache for 5 minutes

/**
 * Retrieve secrets from AWS Secrets Manager
 * Implements caching to avoid rate limiting
 * 
 * @param {string} secretName - Name of the secret in Secrets Manager
 * @returns {Promise<Object>} Parsed secret object
 * @throws {Error} If secret retrieval fails
 */
async function getSecretsFromAWS(secretName) {
  try {
    // Check cache
    if (cachedSecrets && cacheTimestamp && Date.now() - cacheTimestamp < CACHE_TTL) {
      console.log('[Secrets] Using cached secrets');
      return cachedSecrets;
    }

    console.log(`[Secrets] Retrieving secret: ${secretName}`);

    const data = await client.getSecretValue({ 
      SecretId: secretName 
    }).promise();

    let secretValue;
    if ('SecretString' in data) {
      secretValue = JSON.parse(data.SecretString);
    } else if ('SecretBinary' in data) {
      throw new Error('Binary secrets not supported');
    } else {
      throw new Error('Invalid secret format');
    }

    // Cache the secrets
    cachedSecrets = secretValue;
    cacheTimestamp = Date.now();

    console.log('[Secrets] Successfully retrieved and cached secrets');
    return secretValue;
  } catch (error) {
    console.error('[Secrets] Error retrieving from AWS:', error.message);
    throw new Error(`Failed to retrieve secrets from AWS: ${error.message}`);
  }
}

/**
 * Retrieve secrets from environment variables (development)
 * 
 * @returns {Object} Secrets object
 * @throws {Error} If required secrets are missing
 */
function getSecretsFromEnvironment() {
  const requiredSecrets = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
  ];

  const secrets = {};
  const missing = [];

  for (const key of requiredSecrets) {
    if (process.env[key]) {
      secrets[key] = process.env[key];
    } else {
      missing.push(key);
    }
  }

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}\n` +
      `Copy .env.example to .env.local and fill in the values`
    );
  }

  return secrets;
}

/**
 * Main function to get secrets
 * Uses AWS Secrets Manager in production, environment variables in development
 * 
 * @param {string} secretName - AWS secret name (production only)
 * @returns {Promise<Object>} Secrets object
 * @throws {Error} If secrets cannot be retrieved
 */
async function getSecrets(secretName = null) {
  try {
    if (process.env.NODE_ENV === 'production') {
      if (!secretName) {
        secretName = process.env.SECRET_NAME || 'prod/app/secrets';
      }

      return await getSecretsFromAWS(secretName);
    } else {
      // Development
      return getSecretsFromEnvironment();
    }
  } catch (error) {
    console.error('[Secrets] Failed to load secrets:', error);
    throw error;
  }
}

/**
 * Validate that all required secrets are present
 * 
 * @param {Object} secrets - Secrets object
 * @throws {Error} If validation fails
 */
function validateSecrets(secrets) {
  const requiredKeys = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
  ];

  for (const key of requiredKeys) {
    if (!secrets[key]) {
      throw new Error(`Missing required secret: ${key}`);
    }

    if (typeof secrets[key] !== 'string' || secrets[key].trim() === '') {
      throw new Error(`Invalid or empty secret: ${key}`);
    }
  }

  console.log('[Secrets] All required secrets validated successfully');
}

/**
 * Clear the secrets cache (useful for testing or forced refresh)
 */
function clearCache() {
  cachedSecrets = null;
  cacheTimestamp = null;
  console.log('[Secrets] Cache cleared');
}

module.exports = {
  getSecrets,
  validateSecrets,
  clearCache,
};

