### **4. No Input Validation** ⚠️ HIGH
**Severity:** MEDIUM-HIGH  
**Issue:** Query parameters and request bodies are not validated (when added).

**Recommended Fix:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  authenticateToken,
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    // Validate and sanitize
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ]);
  }
);
```

---

### **5. No HTTPS Enforcement** ⚠️ HIGH
**Severity:** HIGH  
**Issue:** Application doesn't enforce HTTPS in production.

**Recommended Fix:**
```javascript
// Middleware to enforce HTTPS
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production') {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  } else {
    next();
  }
});

// Or use express-enforce-https
const enforceHttps = require('express-enforce-https');
if (process.env.NODE_ENV === 'production') {
  app.use(enforceHttps.HTTPS({ trustProtoHeader: true }));
}
```

