## RECOMMENDED SOLUTION: AWS Secrets Manager

### Why AWS Secrets Manager?
- Encrypts secrets at rest with AWS KMS
- Manages encryption keys automatically
- Fine-grained IAM access control
- Automatic credential rotation
- Audit trail via CloudTrail
- No code restart needed for updates
- Cost: ~$0.40/month per secret

### Implementation Steps

#### Step 1: Create Secrets in AWS

```bash
# Create database secret
aws secretsmanager create-secret \
  --name prod/database/main \
  --description "Production database credentials" \
  --secret-string '{
    "username": "admin",
    "password": "secure-random-password",
    "host": "db.internal",
    "port": 5432,
    "dbname": "production"
  }' \
  --kms-key-id alias/aws/secretsmanager

# Create API keys secret
aws secretsmanager create-secret \
  --name prod/api/keys \
  --description "Production API keys" \
  --secret-string '{
    "anthropic_api_key": "sk-ant-xxxxxxxx",
    "stripe_secret_key": "sk_live_[REDACTED-EXAMPLE]",
    "logfire_token": "xxxxxxxx"
  }' \
  --kms-key-id alias/aws/secretsmanager

# Create AWS credentials secret
aws secretsmanager create-secret \
  --name prod/aws/credentials \
  --description "AWS API credentials" \
  --secret-string '{
    "access_key_id": "AKIA...",
    "secret_access_key": "..."
  }' \
  --kms-key-id alias/aws/secretsmanager
```

#### Step 2: Update Node.js Application

```javascript
// secrets-manager.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let secretCache = {};

async function getSecret(secretName) {
  // Return cached secret if available
  if (secretCache[secretName]) {
    return secretCache[secretName];
  }

  try {
    const data = await client.getSecretValue({ 
      SecretId: secretName 
    }).promise();

    let secret;
    if ('SecretString' in data) {
      secret = JSON.parse(data.SecretString);
    } else {
      secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    // Cache for performance (optional: add TTL)
    secretCache[secretName] = secret;

    return secret;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw error;
  }
}

// Clear cache periodically (optional)
setInterval(() => {
  secretCache = {};
}, 3600000); // 1 hour

module.exports = { getSecret };
```

```javascript
