require('dotenv').config(); // For development only
const express = require('express');
const { getSecret } = require('./secrets-manager');

const app = express();

// Load secrets on startup
async function initializeApp() {
  try {
    // Get all secrets we need
    const dbSecret = await getSecret('prod/database/main');
    const apiKeysSecret = await getSecret('prod/api/keys');

    // Configure application with secrets
    app.set('dbSecret', dbSecret);
    app.set('apiKeys', apiKeysSecret);

    // Now start server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });
  } catch (error) {
    console.error('Failed to initialize app:', error);
    process.exit(1);
  }
}

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

initializeApp();

module.exports = app;
```

