### Environment Variable Monitoring

```javascript
// middleware/secret-monitor.js
const SENSITIVE_PATTERNS = [
  'PASSWORD',
  'SECRET',
  'TOKEN',
  'KEY',
  'CREDENTIAL',
  'AUTH'
];

function checkForSecrets() {
  const env = process.env;
  const suspiciousVars = {};

  Object.keys(env).forEach(key => {
    if (SENSITIVE_PATTERNS.some(pattern => key.includes(pattern))) {
      // Log the key name (not value) for auditing
      suspiciousVars[key] = '[REDACTED]';
    }
  });

  if (Object.keys(suspiciousVars).length > 0) {
    console.warn('⚠️  Sensitive environment variables detected:');
    console.warn(JSON.stringify(Object.keys(suspiciousVars), null, 2));
  }

  return suspiciousVars;
}

module.exports = { checkForSecrets };
```

### Error Message Sanitization

```javascript
// middleware/error-sanitizer.js
function sanitizeError(err) {
  const sensitivePatterns = [
    /password[=:]\s*['"]?([^'"&\s]+)/gi,
    /api[_-]?key[=:]\s*['"]?([^'"&\s]+)/gi,
    /(AKIA[0-9A-Z]{16})/g,
    /(sk_live_[0-9a-zA-Z]{20,})/g
  ];

  let message = err.message || '';
  let stack = err.stack || '';

  sensitivePatterns.forEach(pattern => {
    message = message.replace(pattern, '[REDACTED]');
    stack = stack.replace(pattern, '[REDACTED]');
  });

  return {
    message,
    stack: process.env.NODE_ENV === 'production' ? undefined : stack,
    code: err.code
  };
}

module.exports = { sanitizeError };
```

