```javascript
// logger/audit.js
const fs = require('fs');
const path = require('path');

class AuditLogger {
  constructor() {
    this.logFile = path.join(process.cwd(), 'logs', 'audit.log');
    this.ensureLogDirectory();
  }

  ensureLogDirectory() {
    const dir = path.dirname(this.logFile);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
  }

  logSecretAccess(secretName, userId, action, success, reason) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      event: 'SECRET_ACCESS',
      secret: secretName,
      userId: userId || 'SYSTEM',
      action: action,
      success: success,
      reason: reason,
      userAgent: process.env.HTTP_USER_AGENT,
      remoteIp: process.env.REMOTE_IP
    };

    fs.appendFileSync(
      this.logFile,
      JSON.stringify(logEntry) + '\n'
    );

    // Also send to centralized logging if configured
    if (process.env.SENTRY_DSN) {
      this.sendToSentry(logEntry);
    }
  }

  sendToSentry(logEntry) {
    // Implementation would send to Sentry or similar
  }
}

module.exports = new AuditLogger();
