// scripts/scan-secrets.js
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const SECRETS_PATTERNS = [
  {
    name: 'AWS Access Key',
    pattern: /AKIA[0-9A-Z]{16}/g
  },
  {
    name: 'AWS Secret Key',
    pattern: /(aws_secret_access_key|CANARY-aws-secret)/g
  },
  {
    name: 'Stripe API Key',
    pattern: /sk_live_[0-9a-zA-Z]{20,}/g
  },
  {
    name: 'Database URL',
    pattern: /(postgres|mysql|mongodb):\/\/.+:.+@/g
  },
  {
    name: 'API Keys',
    pattern: /(api[_-]?key|API[_-]?KEY)\s*[=:]\s*["\']([^"\']+)["\']?/g
  },
  {
    name: 'JWT Token',
    pattern: /eyJ[a-zA-Z0-9_\-]+\.eyJ[a-zA-Z0-9_\-]+\.[a-zA-Z0-9_\-]+/g
  },
  {
    name: 'Private Key',
    pattern: /-----BEGIN (RSA|DSA|EC|PGP) PRIVATE KEY/g
  }
];

const EXCLUDED_DIRS = ['node_modules', '.git', 'dist', 'build', '.env'];

function scanFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const findings = [];

    SECRETS_PATTERNS.forEach(secretPattern => {
      const matches = content.match(secretPattern.pattern);
      if (matches) {
        matches.forEach(match => {
          findings.push({
            file: filePath,
            pattern: secretPattern.name,
            match: match.substring(0, 20) + '***',
            line: content.substring(0, content.indexOf(match)).split('\n').length
          });
        });
      }
    });

    return findings;
  } catch (error) {
    return [];
  }
}

function scanDirectory(dir) {
  let findings = [];
  const files = fs.readdirSync(dir);

  files.forEach(file => {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    // Skip excluded directories
    if (stat.isDirectory()) {
      if (!EXCLUDED_DIRS.includes(file)) {
        findings = findings.concat(scanDirectory(filePath));
      }
    } else {
      findings = findings.concat(scanFile(filePath));
    }
  });

  return findings;
}

const findings = scanDirectory('.');

if (findings.length > 0) {
  console.error('\n🚨 SECRETS DETECTED:\n');
  findings.forEach(finding => {
    console.error(`${finding.file}:${finding.line}`);
    console.error(`  Type: ${finding.pattern}`);
    console.error(`  Match: ${finding.match}\n`);
  });
  process.exit(1);
} else {
  console.log('✓ No secrets detected');
  process.exit(0);
}
