  ];

  let message = err.message || '';
  let stack = err.stack || '';

  sensitivePatterns.forEach(pattern => {
    message = message.replace(pattern, '[REDACTED]');
    stack = stack.replace(pattern, '[REDACTED]');
  });

  return {
    message,
    stack: process.env.NODE_ENV === 'production' ? undefined : stack,
    code: err.code
  };
}

