// ✅ SECURE APPROACH - AWS Secrets Manager
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

class SecretsProvider {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      const secret = data.SecretString 
        ? JSON.parse(data.SecretString) 
        : data.SecretBinary;

      // Cache the secret
      this.cache.set(secretName, { value: secret, timestamp: Date.now() });
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secret retrieval failed for ${secretName}`);
    }
  }

  // Clear cache on demand
  clearCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

const secretsProvider = new SecretsProvider();

