# Security Review: app.js

## Executive Summary
The current application is a minimal Express.js server with two endpoints. While the code is relatively simple, it contains several security vulnerabilities and missing best practices that should be addressed before production deployment.

---

## CRITICAL FINDINGS

### 1. **Missing Authentication & Authorization** (OWASP A07:2021)
**Severity:** HIGH

**Issue:** Both endpoints are completely unauthenticated. Any user can access sensitive user data.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:** Implement authentication middleware
```javascript
const jwt = require('jsonwebtoken');

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. **Sensitive Data Exposure** (OWASP A02:2021)
**Severity:** HIGH

**Issues:**
- Exposing email addresses and user information without need-to-know basis
- No HTTPS enforcement
- No data classification strategy
- Email addresses are typically PII (Personally Identifiable Information)

**Recommendations:**

```javascript
// Only return necessary data based on user role
app.get('/users', authenticateToken, (req, res) => {
  // Check authorization - admin only
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  // Return limited data set
  const users = [
    { id: 1, name: 'Alice' },  // No email unless needed
    { id: 2, name: 'Bob' },
  ];

  res.json(users);
});

// Add HTTPS requirement
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync('path/to/private-key.pem'),
  cert: fs.readFileSync('path/to/certificate.pem')
};

https.createServer(options, app).listen(3000);
```

---

### 3. **Missing Input Validation** (OWASP A03:2021)
**Severity:** MEDIUM

**Issue:** No query parameter validation or sanitization. An attacker could inject malicious parameters.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  // query parameters are not validated
  res.json([...]);
});
```

**Recommendation:** Add input validation
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  authenticateToken,
  // Validate query parameters
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('search')
    .optional()
    .trim()
    .isLength({ max: 50 })
    .withMessage('Search term too long'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { page = 1, limit = 10, search } = req.query;

    // Continue with validated parameters
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ]);
  }
);
```

---

### 4. **Missing Security Headers** (OWASP)
**Severity:** MEDIUM

**Issue:** No HTTP security headers implemented. Application is vulnerable to various header-based attacks.

**Recommendation:** Use helmet.js middleware
```javascript
const helmet = require('helmet');

app.use(helmet());

// Or configure specific headers:
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
  }
}));

app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));

app.use(helmet.frameguard({ action: 'deny' }));
app.use(helmet.noSniff());
app.use(helmet.xssFilter());
```

---

### 5. **No Rate Limiting** (OWASP A04:2021 - Insecure Design)
**Severity:** MEDIUM

**Issue:** API endpoints are unprotected against brute force and DoS attacks.

**Recommendation:** Implement rate limiting
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter for auth attempts
  skipSuccessfulRequests: true,
});

app.use('/api/', limiter); // Apply to all API routes
app.post('/login', strictLimiter, (req, res) => {
  // login logic
});
```

---

### 6. **Hardcoded Server Port** (OWASP A05:2021)
**Severity:** LOW

**Issue:** Configuration is hardcoded instead of environment-based.

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Recommendation:** Use environment variables
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

---

### 7. **Missing CORS Configuration** (OWASP A07:2021)
**Severity:** MEDIUM

**Issue:** No CORS policy defined, allowing any origin to make requests.

**Recommendation:** Configure CORS properly
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));
```

---

### 8. **Missing Logging & Monitoring** (OWASP A09:2021)
**Severity:** MEDIUM

**Issue:** No request logging or security event tracking for audit purposes.

**Recommendation:** Add structured logging
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

app.use((req, res, next) => {
  logger.info({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
  });
  next();
});
```

---

### 9. **Missing Error Handling** (OWASP A01:2021)
**Severity:** MEDIUM

**Issue:** No centralized error handling. Stack traces could be exposed to users.

**Recommendation:** Implement global error handler
```javascript
// Endpoint not found
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource does not exist.'
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose stack trace in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});
```

---

### 10. **Missing Input Encoding/Output Encoding** (OWASP A03:2021)
**Severity:** MEDIUM

**Issue:** JSON responses aren't explicitly protected against injection attacks.

**Recommendation:** Validate and sanitize all data
```javascript
const { body, validationResult } = require('express-validator');

// When accepting user input:
app.post('/users',
  authenticateToken,
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape() // Escape special characters
    .withMessage('Invalid name'),
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Process validated data
    res.json({ success: true });
  }
);
```

