    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================
// 2. MIDDLEWARE - SECURITY HEADERS (A07:2021)
// ============================================
app.use(helmet());

// ============================================
// 3. MIDDLEWARE - CORS (A07:2021)
// ============================================
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};

app.use(cors(corsOptions));

// ============================================
// 4. MIDDLEWARE - BODY PARSING
// ============================================
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// ============================================
// 5. MIDDLEWARE - REQUEST LOGGING
// ============================================
app.use((req, res, next) => {
  logger.info({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
  });
  next();
});

// ============================================
// 6. MIDDLEWARE - RATE LIMITING (A04:2021)
// ============================================
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req, res) => {
    // Use X-Forwarded-For if behind a proxy
    return req.ip || req.connection.remoteAddress;
  },
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

app.use('/api/', globalLimiter);

// ============================================
// 7. AUTHENTICATION MIDDLEWARE (A07:2021)
// ============================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      message: 'Missing authentication token',
      path: req.path,
      ip: req.ip,
    });
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Access token required',
    });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      logger.warn({
        message: 'Invalid token',
        path: req.path,
        ip: req.ip,
        error: err.message,
      });
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Invalid or expired token',
      });
    }
    req.user = user;
    next();
  });
};

// ============================================
// 8. AUTHORIZATION MIDDLEWARE
// ============================================
const authorizeRole = (requiredRole) => {
  return (req, res, next) => {
    if (req.user.role !== requiredRole) {
      logger.warn({
        message: 'Unauthorized access attempt',
        requiredRole,
        userRole: req.user.role,
        userId: req.user.id,
        path: req.path,
        ip: req.ip,
      });
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Insufficient permissions',
      });
    }
    next();
  };
};

// ============================================
// 9. ROUTES - HEALTH CHECK (No auth needed)
// ============================================
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

// ============================================
// 10. ROUTES - LOGIN (for demo purposes)
// ============================================
app.post('/api/login', strictLimiter, (req, res) => {
  try {
    // In production, validate credentials against database
    const user = {
      id: 1,
      role: 'admin',
    };

    const token = jwt.sign(user, process.env.ACCESS_TOKEN_SECRET || 'dev-secret', {
      expiresIn: '1h',
    });

    logger.info({
      message: 'User login successful',
      userId: user.id,
      ip: req.ip,
    });

    res.json({ token });
  } catch (error) {
    logger.error({
      message: 'Login error',
      error: error.message,
      ip: req.ip,
    });

    res.status(500).json({
      error: 'Internal Server Error',
      message: process.env.NODE_ENV === 'production'
        ? 'An error occurred during login'
        : error.message,
    });
  }
});

// ============================================
// 11. ROUTES - GET USERS (Protected)
// ============================================
app.get('/api/users',
  authenticateToken,
  authorizeRole('admin'),
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('search')
    .optional()
    .trim()
    .isLength({ max: 50 })
    .withMessage('Search term too long'),
  (req, res) => {
    try {
      // Validate query parameters
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const { page = 1, limit = 10 } = req.query;

      // Return minimal user data (no sensitive info by default)
      const users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      logger.info({
        message: 'Users list accessed',
        userId: req.user.id,
        page,
        limit,
      });

      res.json({
        success: true,
        data: users,
        pagination: {
          page,
          limit,
          total: users.length,
        },
      });
    } catch (error) {
      logger.error({
        message: 'Error fetching users',
        error: error.message,
        userId: req.user.id,
      });

      res.status(500).json({
        error: 'Internal Server Error',
        message: process.env.NODE_ENV === 'production'
          ? 'Failed to fetch users'
          : error.message,
      });
    }
  }
);

// ============================================
// 12. ERROR HANDLING - 404
// ============================================
app.use((req, res) => {
  logger.warn({
    message: 'Route not found',
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist.',
    path: req.path,
  });
});

// ============================================
// 13. ERROR HANDLING - GLOBAL HANDLER
// ============================================
app.use((err, req, res, next) => {
  logger.error({
    message: 'Unhandled error',
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;

  res.status(statusCode).json({
    error: 'Internal Server Error',
    message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ============================================
// 14. SERVER STARTUP
// ============================================
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  logger.info({
    message: 'Server started',
    host: HOST,
    port: PORT,
    environment: process.env.NODE_ENV || 'development',
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Quick Reference Guide

## 🔴 CRITICAL - Fix Immediately

### 1. Add Authentication
```javascript
// BEFORE (Vulnerable)
