## Common Injection Attacks & Prevention

### SQL Injection
```javascript
// VULNERABLE
const query = `SELECT * FROM users WHERE name = '${req.query.name}'`;

// SECURE (Parameterized)
const query = 'SELECT * FROM users WHERE name = $1';
db.query(query, [req.query.name]);
```

### NoSQL Injection
```javascript
// VULNERABLE
User.find({ name: req.query.name });

// SECURE
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize());
User.find({ name: req.query.name });
```

### Command Injection
```javascript
// VULNERABLE
const output = exec(`ls ${req.query.path}`);

// SECURE
const { spawn } = require('child_process');
const child = spawn('ls', [req.query.path]);
```

### XSS Prevention
```javascript
// In responses - sanitize
const sanitizeHtml = require('sanitize-html');
const clean = sanitizeHtml(userInput);

// In input validation
const { escape } = require('express-validator');
app.post('/comment', body('text').escape());
```

