```

**Fixed code (SECURE):**
```javascript
// ✅ SECURE - Require secret, fail fast in production
const getJWTSecret = () => {
  const secret = process.env.ACCESS_TOKEN_SECRET;

  if (!secret) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('CRITICAL: ACCESS_TOKEN_SECRET must be set in production');
    }
    // Development only
    console.warn('WARNING: Using development JWT secret - NEVER use in production');
    return 'dev-secret-never-in-production';
  }

  // Validate secret strength in production
  if (process.env.NODE_ENV === 'production' && secret.length < 32) {
    throw new Error('CRITICAL: ACCESS_TOKEN_SECRET must be at least 32 characters');
  }

  return secret;
};

const JWT_SECRET = getJWTSecret();

// Usage:
jwt.verify(token, JWT_SECRET, (err, user) => {
  // ...
});
