### 4. Add Startup Validation
**Add to app-secure.js (at startup):**
```javascript
// ============================================
// SECRETS VALIDATION (Add at very beginning)
// ============================================
const validateSecrets = () => {
  const requiredSecrets = [
    'ACCESS_TOKEN_SECRET',
    'REFRESH_TOKEN_SECRET',
  ];

  const missingSecrets = requiredSecrets.filter(secret => !process.env[secret]);

  if (missingSecrets.length > 0) {
    const message = `CRITICAL: Missing required secrets: ${missingSecrets.join(', ')}`;
    console.error(message);

    if (process.env.NODE_ENV === 'production') {
      process.exit(1); // Fail fast in production
    }
  }

  // Validate secret strength in production
  if (process.env.NODE_ENV === 'production') {
    const weakSecrets = requiredSecrets.filter(secret => {
      const value = process.env[secret];
      return value && value.length < 32;
    });

    if (weakSecrets.length > 0) {
      console.error(`CRITICAL: Weak secrets detected: ${weakSecrets.join(', ')}`);
      process.exit(1);
    }
  }
};

// Call at startup
validateSecrets();
```

